    }

    /// Build a fixture descriptor with the given id. The injector
    /// only reads `id`, `description`, `parameters`, and
    /// `output_schema`; the rest are filled with neutral defaults.
    fn descriptor(id: &str) -> ToolDescriptor {
        ToolDescriptor {
