    // ── Receipt-stamp migration + semantics (v12, commons-fluency fix 3) ──

    #[tokio::test]
    async fn migration_v11_to_v12_adds_receipt_columns_null_for_old_rows() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("notes.db");

        // Build a REAL v11 database by running the actual ladder,
        // then write one pre-v12 row — its receipts must come up
        // NULL, never fabricated.
        {
            let conn = Connection::open(&db_path).unwrap();
            conn.execute_batch("PRAGMA journal_mode=WAL;").unwrap();
            conn.execute_batch(SCHEMA_NEW).unwrap();
            for m in [
                MIGRATION_V2,
                MIGRATION_V3,
                MIGRATION_V4,
                MIGRATION_V5,
                MIGRATION_V6,
                MIGRATION_V7,
                MIGRATION_V8,
                MIGRATION_V9,
                MIGRATION_V10,
                MIGRATION_V11,
            ] {
                conn.execute_batch(m).unwrap();
            }
            let v: i64 = conn
                .query_row("PRAGMA user_version", [], |r| r.get(0))
                .unwrap();
            assert_eq!(v, 11, "handcrafted DB must sit at v11");
            conn.execute_batch(
                "INSERT INTO notes (id, kind, content, session_id, created_at, updated_at)
                 VALUES ('pre-v12', 'todo', 'old note', 's0', 1000, 1000);",
            )
            .unwrap();
        }

        // Open with NoteStore — the v12 migration runs.
        let store = NoteStore::open(&db_path).unwrap();

        // New writes still carry NULL receipts until the sink
        // publishes or a peer delivers — the negative arm (§18.3:
        // absence is reported, never defaulted).
        let id = store
            .write_note("decision", "no sink yet", vec![], vec![], "s1")
            .await
            .unwrap();
        let row = store.read_note_by_id(&id).await.unwrap().unwrap();
        assert_eq!(
            row.sent_at, None,
            "unpublished note must report sent_at null"
        );
        assert_eq!(
            row.received_at, None,
            "locally-authored note must report received_at null"
        );

        drop(store);

        // Columns exist, chain head is 12, and the pre-v12 row's
        // receipts stayed NULL through the migration.
        let conn = Connection::open(&db_path).unwrap();
        let v: i64 = conn
            .query_row("PRAGMA user_version", [], |r| r.get(0))
            .unwrap();
        assert_eq!(v, 12);
        let cols: Vec<String> = conn
            .prepare("PRAGMA table_info(notes)")
            .unwrap()
            .query_map([], |r| r.get::<_, String>(1))
            .unwrap()
            .map(|r| r.unwrap())
            .collect();
        assert!(
            cols.contains(&"sent_at".to_string()),
            "sent_at column missing"
        );
        assert!(
            cols.contains(&"received_at".to_string()),
            "received_at column missing"
        );
        let (sent, recv): (Option<i64>, Option<i64>) = conn
            .query_row(
                "SELECT sent_at, received_at FROM notes WHERE id = 'pre-v12'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(sent, None, "pre-v12 row must report sent_at null");
        assert_eq!(recv, None, "pre-v12 row must report received_at null");
    }

    // ── TEACHABLE lesson-kind migration + payload tests (v11) ────────────

    #[tokio::test]
    async fn migration_v10_to_v11_preserves_children_and_admits_lesson() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("notes.db");

        // Build a REAL v10 database by running the actual ladder, then
        // populate the v9/v10 child tables so the v11 rebuild has live
        // `REFERENCES notes(id)` rows to preserve — the exact hazard the
        // create-copy-drop-rename order exists to avoid.
        {
            let conn = Connection::open(&db_path).unwrap();
            conn.execute_batch("PRAGMA journal_mode=WAL;").unwrap();
            conn.execute_batch(SCHEMA_NEW).unwrap();
            for m in [
                MIGRATION_V2,
                MIGRATION_V3,
                MIGRATION_V4,
                MIGRATION_V5,
                MIGRATION_V6,
                MIGRATION_V7,
                MIGRATION_V8,
                MIGRATION_V9,
                MIGRATION_V10,
            ] {
                conn.execute_batch(m).unwrap();
            }
            let v: i64 = conn
                .query_row("PRAGMA user_version", [], |r| r.get(0))
                .unwrap();
            assert_eq!(v, 10, "handcrafted DB must sit at v10");

            conn.execute_batch(
                "INSERT INTO notes (id, kind, content, session_id, created_at, updated_at)
                 VALUES ('id-1', 'todo', 'old prelesson note', 's0', 1000, 1000);
                 INSERT INTO note_embeddings (note_id, embedding, model_id, dim, created_at)
                 VALUES ('id-1', X'00000000', 'test-model', 1, 1000);
                 INSERT INTO note_entities (note_id, entity, kind, salience, created_at)
                 VALUES ('id-1', 'Rust', 'Tech', 1.0, 1000);",
            )
            .unwrap();
        }

        // Open with NoteStore — the v11 migration runs.
        let store = NoteStore::open(&db_path).unwrap();

        // Old note preserved and readable.
        let notes = store
            .read_notes(None, &[], &[], &[], 10, false)
            .await
            .unwrap();
        assert_eq!(notes.len(), 1);
        assert_eq!(notes[0].content, "old prelesson note");

        // The new kind is admitted…
        let lesson_id = store
            .write_note("lesson", "Keep answers short.", vec![], vec![], "s1")
            .await
            .unwrap();
        assert!(!lesson_id.is_empty());
        // …and a bogus kind still fails the CHECK.
        assert!(store
            .write_note("bogus_kind", "nope", vec![], vec![], "s1")
            .await
            .is_err());

        drop(store);

        // Child tables, FK integrity, and FTS survived the rebuild.
        // The open stepped the chain to the CURRENT head — v12 since
        // the receipt-stamp migration landed (commons-fluency fix 3).
        let conn = Connection::open(&db_path).unwrap();
        let v: i64 = conn
            .query_row("PRAGMA user_version", [], |r| r.get(0))
            .unwrap();
        assert_eq!(v, 12);
        let emb: i64 = conn
            .query_row("SELECT COUNT(*) FROM note_embeddings", [], |r| r.get(0))
            .unwrap();
        assert_eq!(emb, 1, "note_embeddings rows must survive the rebuild");
        let ent: i64 = conn
            .query_row("SELECT COUNT(*) FROM note_entities", [], |r| r.get(0))
            .unwrap();
        assert_eq!(ent, 1, "note_entities rows must survive the rebuild");
        let fk_violations: i64 = conn
            .query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |r| {
                r.get(0)
            })
            .unwrap();
        assert_eq!(
            fk_violations, 0,
            "v11 rebuild must not orphan child FKs (rename-rewrite hazard)"
        );
        let fts_hits: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM notes_fts WHERE notes_fts MATCH 'prelesson'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(fts_hits, 1, "FTS must be rebuilt over the copied rows");
    }

