        // corpus_id="wikipedia".
        std::fs::create_dir_all(idx_dir.join("wikipedia")).unwrap();
        std::fs::write(
            idx_dir.join("wikipedia/_corpus_meta.json"),
            r#"{"corpus_id":"wikipedia"}"#,
