            ),
        ];
        write_edges_csr(dir, 3, &by_id, &edges).unwrap();

        let csr = CsrEdges::open(&dir.join(EDGES_CSR_FILENAME)).unwrap();
        assert_eq!(csr.n_atoms(), 3);
        assert_eq!(csr.n_edges(), 2);

        // out-edges: local 0 → local 2 (Involves, 0.9, scip); local 2 has none.
        let o0 = csr.out_edges(0);
        assert_eq!(o0.len(), 1);
        assert_eq!(o0[0].0, 2);
        assert_eq!(o0[0].1, edge_type_u8(ArchEdgeType::Involves));
        assert!((o0[0].2 - 0.9).abs() < 1e-6);
        assert_eq!(o0[0].3, prov_u8(EdgeProvenance::ScipStructural));
        assert_eq!(csr.out_edges(2).len(), 0);

        // in-edges of local 2: from local 0 (scip) and local 1 (containment).
        let i2 = csr.in_edges(2);
        assert_eq!(i2.len(), 2);
        let nbrs: std::collections::HashSet<u32> = i2.iter().map(|e| e.0).collect();
        assert!(nbrs.contains(&0) && nbrs.contains(&1));
        // Provenance survives the in-CSR direction too, keyed by source neighbor.
        let prov_of = |from: u32| i2.iter().find(|e| e.0 == from).map(|e| e.3).unwrap();
        assert_eq!(prov_of(0), prov_u8(EdgeProvenance::ScipStructural));
        assert_eq!(prov_of(1), prov_u8(EdgeProvenance::ContainmentStructural));
        assert_eq!(csr.in_edges(0).len(), 0);

        // out-of-range local id → empty, not a panic.
        assert_eq!(csr.out_edges(99).len(), 0);
    }

    #[test]
    fn store_needs_build_flags_a_stale_csr_version() {
        // A freshly written v2 store (atoms.lance + a CSR v2 edges.csr) is current.
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path();
        let atoms = vec![entity(1, "Alice"), entity(2, "Bob")];
        let edges = vec![Edge {
            id: EdgeId::from_raw("e1"),
            edge_type: EdgeType::Involves,
            source: AtomId::entity(1),
            target: AtomId::entity(2),
            evidence: vec![],
            trigger_event: None,
            sub_question: None,
            confidence: 0.9,
            provenance: EdgeProvenance::ScipStructural,
        }];
        write_store_blocking(dir, "c1", &atoms, &edges).unwrap();
        assert!(!store_needs_build(dir), "a fresh CSR v2 store is current");

        // Flipping the edges.csr header version byte to a superseded value makes
        // the store unreadable (CsrEdges::open rejects it), so a rebuild is
        // required even though atoms.lance is present. The mtime check alone
        // can't see this; the version guard must.
        let csr = dir.join(EDGES_CSR_FILENAME);
        let mut bytes = std::fs::read(&csr).unwrap();
        bytes[4] = 1; // CSR_VERSION 2 → the pre-provenance v1 format
        std::fs::write(&csr, &bytes).unwrap();
        assert_eq!(edges_csr_version(&csr), Some(1));
        assert!(
            store_needs_build(dir),
            "a v1 edges.csr must force a rebuild"
        );
    }

    #[tokio::test]
    async fn lance_preload_reads_back_parity_atoms_and_edges() {
        // Reader-parity: LancePreload reads the v2 store back into resident
        // records identical to the canonical projection, and the CSR edge
        // endpoints resolve to the right atom-id strings — so the daemon's
        // `AtlasGraph` hands out views straight from resident data.
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path();
        let atoms = vec![entity(1, "Alice"), entity(2, "Bob"), entity(3, "Carol")];
        let mk =
            |src: usize, tgt: usize, ty: EdgeType, conf: f32, prov: EdgeProvenance, id: &str| {
                Edge {
                    id: EdgeId::from_raw(id),
                    edge_type: ty,
                    source: AtomId::entity(src),
                    target: AtomId::entity(tgt),
                    evidence: vec![],
                    trigger_event: None,
                    sub_question: None,
                    confidence: conf,
                    provenance: prov,
                }
            };
        let edges = vec![
            mk(
                1,
                3,
                EdgeType::Involves,
                0.9,
                EdgeProvenance::ScipStructural,
                "e1",
            ),
            mk(
                2,
                3,
                EdgeType::Causes,
                0.5,
                EdgeProvenance::ContainmentStructural,
                "e2",
            ),
        ];
        write_store(dir, "frozen", &atoms, &edges).await.unwrap();

        let pre = LancePreload::open(dir).await.unwrap();
        assert_eq!(pre.atom_count(), 3);
        assert_eq!(pre.edge_count(), 2);

        // PARITY: each resident record == the canonical projection of the
        // original — including aliases/evidence, which live only in the payload
        // (the scalar columns drop them), proving the payload round-trips them.
        for atom in &atoms {
            let got = pre.atom(atom.id().as_str()).expect("atom present");
            assert_eq!(
                *got,
                project(atom),
                "preload record != canonical projection"
            );
        }
        let alice = pre.atom(AtomId::entity(1).as_str()).unwrap();
        assert_eq!(alice.aliases, vec!["Alice-alias".to_string()]);
        assert_eq!(alice.evidence.len(), 1); // Entity first_appearance sec_0001
        assert_eq!(alice.evidence[0].chunk_id, "sec_0001");

        // Edges resolve to atom-id strings, directionally.
        let (e1, e2, e3) = (
            AtomId::entity(1).as_str().to_string(),
            AtomId::entity(2).as_str().to_string(),
            AtomId::entity(3).as_str().to_string(),
        );
        let out1 = pre.out_edges(&e1);
        assert_eq!(out1.len(), 1);
        assert_eq!(out1[0].0, e1); // source
        assert_eq!(out1[0].1, e3); // target
        assert_eq!(out1[0].2, EdgeType::Involves);
        assert!((out1[0].3 - 0.9).abs() < 1e-6);
        assert_eq!(out1[0].4, EdgeProvenance::ScipStructural); // provenance preserved

        // entity3: two in-edges (from 1 and 2), zero out.
        assert_eq!(pre.out_edges(&e3).len(), 0);
        let in3 = pre.in_edges(&e3);
        assert_eq!(in3.len(), 2);
        assert!(in3.iter().all(|e| e.1 == e3)); // all target entity3
        let srcs: std::collections::HashSet<&str> = in3.iter().map(|e| e.0).collect();
        assert!(srcs.contains(e1.as_str()) && srcs.contains(e2.as_str()));

        // Degree = in + out, no tuple alloc.
        assert_eq!(pre.edge_degree(&e3), 2);
        assert_eq!(pre.edge_degree(&e1), 1);

        // Absent atom → empty / zero / None, never a panic.
        assert!(pre.atom("nope").is_none());
        assert_eq!(pre.out_edges("nope").len(), 0);
        assert_eq!(pre.edge_degree("nope"), 0);
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Event-sourced governance oplog + active-set fold.
//!
//! The governance layer treats a community's normative state as a
//! *query over an append-only log of governance acts*, not as stored
//! mutable state. Rules are atlas `Claim` atoms (extracted by a
//! recipe's custom-ontology atlas pipeline); tensions are atlas
//! `EdgeType::Tension` edges. This module owns the **acts on top of
//! that graph** — assert / supersede / retract a rule, resolve / accept
//! a tension — and the pure fold ([`derive_active`]) that derives the
//! *current active rule set* from the act log.
//!
//! Why event-sourced (the design conceit, "common law"):
//!   - the current law is a [`derive_active`] query, not a row you mutate;
//!   - history is preserved — "what was the guest policy in March, and
//!     why did it change?" is answerable because nothing is destroyed;
//!   - every act is reversible via a single general [`GovernanceOpKind::Revert`]
//!     that tomb-stones prior ops during the fold (INV-3) and is itself
//!     revertible (reverting a `Revert` re-applies the original ops);
//!   - [`GovernanceOpKind::AcceptTension`] makes a known, tolerated
//!     contradiction a *first-class state*, not a bug to be force-resolved —
//!     which is how real common law actually works.
//!
//! Division of labour with the atlas: the atlas graph supplies *which
//! rules exist* (Claim atoms) and *which tensions were surfaced* (Tension
//! edges). This log supplies *what was decided about them*. The fold is
//! therefore pure over the ops alone; the set of currently-**open**
//! tensions is `(atlas tension edges) − (adjudicated edges)`, computed by
//! [`ActiveSet::open_tensions`] which takes the edge universe as input.
//!
//! This is the load-bearing contract everything else writes through, so
//! the fold does no IO and never calls inference, and the invariants
//! below (replay determinism, reversibility, attribution) are pinned by
//! the module tests.

use std::collections::{BTreeMap, BTreeSet};
use std::fs::{self, OpenOptions};
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::enrichment::atlas::atoms::AtomId;
use crate::enrichment::atlas::edges::EdgeId;
use crate::error::{Error, Result};

/// Current oplog line format version. Bumped only when the reader must
/// opt in to new semantics (the schema-back-compat convention: a reader
/// refuses lines declaring a `v` it doesn't understand rather than
/// silently misinterpreting them).
pub const GOVERNANCE_OPLOG_VERSION: u32 = 1;

// ── Op identity ──────────────────────────────────────────────

/// Stable, content-addressed id for a governance op. Derived from the
/// op's (kind, timestamp, actor) triple, so the id a [`GovernanceOpKind::Revert`]
/// targets is reproducible from the log bytes alone — no positional or
/// external counter to drift.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct OpId(String);

impl OpId {
    pub fn from_raw(s: impl Into<String>) -> Self {
        Self(s.into())
    }
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

// ── The acts ─────────────────────────────────────────────────

/// The six governance acts (spec §6.3) plus the one general reversal op.
///
/// Internally tagged on `"op"` so each line is self-describing and each
/// variant carries exactly its own fields — illegal field combinations
/// are unrepresentable (SOLID/"make illegal states unrepresentable",
/// versus the all-fields-optional shape of the reconciliation oplog).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum GovernanceOpKind {
    /// A rule (Claim atom) enters the governed set. Emitted idempotently
    /// by ingest for every freshly-extracted rule; re-asserting a rule id
    /// already present is a no-op for the active set.
    AssertRule {
        rule: AtomId,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        source_doc: Option<String>,
    },
    /// One or more old rules are replaced by a new rule. The new rule is
    /// asserted active; each old rule becomes [`RuleStatus::Superseded`].
    Supersede {
        new_rule: AtomId,
        old_rules: Vec<AtomId>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// A rule is withdrawn from active law with no replacement.
    RetractRule {
        rule: AtomId,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// A surfaced tension is adjudicated as resolved. `via` names the act
    /// that resolved it (a [`GovernanceOpKind::Supersede`]), so the audit
    /// trail links the tension to its fix.
    ///
    /// `endpoints` records the tension's two rule ids at adjudication
    /// time. Edge ids are re-minted sequentially on every atlas rebuild,
    /// but content-hash rule ids are stable — so the endpoint pair is the
    /// adjudication's durable identity across rebuilds (see
    /// [`ActiveSet::tension_pairs`]). Optional for back-compat with logs
    /// written before the field existed.
    ResolveTension {
        tension: EdgeId,
        via: OpId,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        endpoints: Option<(AtomId, AtomId)>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// A surfaced tension is adjudicated as known-and-tolerated. The
    /// rationale is required: an accepted contradiction must say why.
    /// `endpoints` as on [`GovernanceOpKind::ResolveTension`].
    AcceptTension {
        tension: EdgeId,
        rationale: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        endpoints: Option<(AtomId, AtomId)>,
    },
    /// A surfaced tension is adjudicated as not-a-conflict: the detector
    /// was wrong (a decoy), not a contradiction the community tolerates —
    /// that distinct state is [`GovernanceOpKind::AcceptTension`].
    /// Deliberately light-ceremony (rationale optional): dismissing
    /// detector noise is the steward's call, and it is revertible like
    /// every act. `endpoints` as on [`GovernanceOpKind::ResolveTension`].
    DismissTension {
        tension: EdgeId,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        endpoints: Option<(AtomId, AtomId)>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// Tomb-stone prior op(s). The fold skips each target *and its
    /// effects* as if it had never been recorded. A human adjudication is
    /// usually a small bundle (AssertRule + Supersede + ResolveTension);
    /// naming the whole bundle makes the undo atomic. Revertible: a
    /// `Revert` of a `Revert` re-applies the originals.
    Revert {
        targets: Vec<OpId>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
}

/// One line in `governance_oplog.jsonl` — an act plus its provenance.
///
/// The `kind` is flattened, so a line reads
/// `{"id":"gov-…","v":1,"ts_unix":…,"actor":"human:alex","op":"supersede",…}`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GovernanceOp {
    /// Content-addressed op id (see [`OpId`]). Stable across replays.
    pub id: OpId,
    /// Line format version. Always written; read-side gate skips lines
    /// declaring a higher version than this reader understands.
    #[serde(default = "default_version")]
    pub v: u32,
    /// Op timestamp (Unix seconds).
    pub ts_unix: i64,
    /// Who performed the act. INV-2: every act except [`GovernanceOpKind::AssertRule`]
    /// (which ingest may author as `actor = "ingest"`) MUST be attributed
    /// to a `human:<name>`. The CLI verbs pass this; [`first_unattended_act`]
    /// is the guard against an unattended write.
    pub actor: String,
    #[serde(flatten)]
    pub kind: GovernanceOpKind,
}

fn default_version() -> u32 {
    GOVERNANCE_OPLOG_VERSION
}

impl GovernanceOp {
    /// Build an op, deriving its content-addressed [`OpId`] from the
    /// (kind, ts, actor) triple. Two byte-identical acts at the same
    /// second by the same actor would collide by design — callers append
    /// in real time, so this does not arise in practice (the same
    /// birthday-bound caveat the atom content-hash ids carry).
    pub fn new(kind: GovernanceOpKind, ts_unix: i64, actor: impl Into<String>) -> Self {
        let actor = actor.into();
        // serde_json field order is the declaration order, so the body
        // string — and therefore the id — is deterministic across runs.
        let body = serde_json::to_string(&kind).unwrap_or_default();
        let input = format!("gov|{ts_unix}|{actor}|{body}");
        Self {
            id: OpId(format!("gov-{}", short_hash(&input))),
            v: GOVERNANCE_OPLOG_VERSION,
            ts_unix,
            actor,
            kind,
        }
    }
}

/// INV-2 guard: the first op that is neither an `AssertRule` nor authored
/// by a `human:<name>` actor — i.e. an adjudication a code path tried to
/// write unattended. `None` means the log honours the attribution
/// invariant. The CLI's human verbs always pass `human:<name>`; this
/// catches a regression where some automated path forges a decision.
pub fn first_unattended_act(ops: &[GovernanceOp]) -> Option<&GovernanceOp> {
    ops.iter().find(|op| {
        !matches!(op.kind, GovernanceOpKind::AssertRule { .. }) && !op.actor.starts_with("human:")
    })
}

// ── Derived state ────────────────────────────────────────────

/// Status of a rule in the derived active set.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
pub enum RuleStatus {
    /// In force.
    Active,
    /// Replaced by `by_rules`, via op `by`.
    Superseded { by: OpId, by_rules: Vec<AtomId> },
    /// Withdrawn without replacement, via op `by`.
    Retracted { by: OpId },
}

/// Adjudication outcome of a tension. Only adjudicated tensions appear in
/// the fold output — an *open* tension is one the atlas surfaced that the
/// log has not yet touched (see [`ActiveSet::open_tensions`]).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
pub enum TensionStatus {
    /// Resolved by op `by` (which references the resolving Supersede).
    Resolved { by: OpId },
    /// Accepted as known-and-tolerated, via op `by`.
    Accepted { by: OpId },
    /// Dismissed as not-a-conflict (detector noise), via op `by`.
    Dismissed { by: OpId },
}

impl TensionStatus {
    /// The op that produced this status. Every adjudication carries the
    /// id of the act that decided it — used to identify the *live,
    /// winning* adjudication for an edge (last-write-wins in the fold).
    pub fn by(&self) -> &OpId {
        match self {
            TensionStatus::Resolved { by }
            | TensionStatus::Accepted { by }
            | TensionStatus::Dismissed { by } => by,
        }
    }
}

/// Canonical, order-independent key for a tension's endpoint rule pair —
/// `"<lo-id>|<hi-id>"`. String-backed so [`ActiveSet`] stays
/// JSON-serializable (JSON map keys must be strings); constructed only
/// through [`PairKey::new`], which normalizes the order.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(transparent)]
pub struct PairKey(String);

impl PairKey {
    pub fn new(a: &AtomId, b: &AtomId) -> Self {
        let (lo, hi) = if a.as_str() <= b.as_str() {
            (a, b)
        } else {
            (b, a)
        };
        Self(format!("{}|{}", lo.as_str(), hi.as_str()))
    }
}

/// The folded current state: every rule the log has touched with its
/// status, and every tension the log has adjudicated with its outcome.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ActiveSet {
    /// Rule id → status. Sorted (BTreeMap) for deterministic iteration.
    pub rules: BTreeMap<AtomId, RuleStatus>,
    /// Adjudicated tension id → outcome.
    pub tensions: BTreeMap<EdgeId, TensionStatus>,
    /// Adjudicated endpoint-pair → outcome, for adjudication ops that
    /// carried `endpoints`. Edge ids are re-minted on every atlas
    /// rebuild; the (content-hash) rule-id pair is the identity that
    /// survives, so a re-detected tension between the same two rules
    /// inherits its adjudication (see the view join in
    /// `governance_view::build_view`).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub tension_pairs: BTreeMap<PairKey, TensionStatus>,
}

impl ActiveSet {
    /// The rules currently in force, in deterministic id order.
    pub fn active_rules(&self) -> Vec<&AtomId> {
        self.rules
            .iter()
            .filter(|(_, s)| matches!(s, RuleStatus::Active))
            .map(|(id, _)| id)
            .collect()
    }

    /// Whether a specific rule is currently in force.
    pub fn is_active(&self, rule: &AtomId) -> bool {
        matches!(self.rules.get(rule), Some(RuleStatus::Active))
    }

    /// Open tensions = surfaced-by-the-atlas minus adjudicated-by-the-log.
    /// `all` is the tension-edge universe from the atlas graph; this
    /// returns those with no adjudication, in input order.
    pub fn open_tensions<'a>(&self, all: &'a [EdgeId]) -> Vec<&'a EdgeId> {
        all.iter()
            .filter(|e| !self.tensions.contains_key(*e))
            .collect()
    }
}

/// Derive the current active set by folding the act log.
///
/// Two passes, both pure:
///
/// **Pass 1 (backward) — liveness.** Walk newest→oldest computing which
/// ops are *live*, honouring [`GovernanceOpKind::Revert`] chains. A
/// `Revert` targets only earlier ops, so walking backward means every op
/// already knows the verdict of any op that could revert it. A live
/// `Revert` cancels its targets; a *cancelled* `Revert` does not (so
/// reverting a `Revert` re-applies the originals). See tests
/// `revert_supersede_reactivates_old_rule` and `revert_of_revert_reapplies`.
///
/// **Pass 2 (forward) — apply.** Fold the live ops in log order; later
/// ops overwrite earlier status for the same rule. Because the supersede
/// of a reverted bundle is skipped in pass 2, the old rule's earlier
/// `Active` status (from its ingest `AssertRule`) stands.
pub fn derive_active(ops: &[GovernanceOp]) -> ActiveSet {
    let n = ops.len();

    // Pass 1: liveness.
    let mut live = vec![true; n];
    let mut cancelled: BTreeSet<&str> = BTreeSet::new();
    for i in (0..n).rev() {
        let op = &ops[i];
        if cancelled.contains(op.id.as_str()) {
            // This op was tomb-stoned by a later live Revert. If it is
            // itself a Revert, skipping it here means its targets are
            // NOT added to `cancelled` — that is the revert-of-revert
            // re-application.
            live[i] = false;
            continue;
        }
        if let GovernanceOpKind::Revert { targets, .. } = &op.kind {
            for t in targets {
                cancelled.insert(t.as_str());
            }
        }
    }

    // Pass 2: apply live ops forward.
    let mut set = ActiveSet::default();
    for (i, op) in ops.iter().enumerate() {
        if !live[i] {
            continue;
        }
        match &op.kind {
            GovernanceOpKind::AssertRule { rule, .. } => {
                set.rules.insert(rule.clone(), RuleStatus::Active);
            }
            GovernanceOpKind::Supersede {
                new_rule,
                old_rules,
                ..
            } => {
                set.rules.insert(new_rule.clone(), RuleStatus::Active);
                for old in old_rules {
                    set.rules.insert(
                        old.clone(),
                        RuleStatus::Superseded {
                            by: op.id.clone(),
                            by_rules: vec![new_rule.clone()],
                        },
                    );
                }
            }
            GovernanceOpKind::RetractRule { rule, .. } => {
                set.rules
                    .insert(rule.clone(), RuleStatus::Retracted { by: op.id.clone() });
            }
            GovernanceOpKind::ResolveTension {
                tension, endpoints, ..
            } => {
                let status = TensionStatus::Resolved { by: op.id.clone() };
                if let Some((a, b)) = endpoints {
                    set.tension_pairs.insert(PairKey::new(a, b), status.clone());
                }
                set.tensions.insert(tension.clone(), status);
            }
            GovernanceOpKind::AcceptTension {
                tension, endpoints, ..
            } => {
                let status = TensionStatus::Accepted { by: op.id.clone() };
                if let Some((a, b)) = endpoints {
                    set.tension_pairs.insert(PairKey::new(a, b), status.clone());
                }
                set.tensions.insert(tension.clone(), status);
            }
            GovernanceOpKind::DismissTension {
                tension, endpoints, ..
            } => {
                let status = TensionStatus::Dismissed { by: op.id.clone() };
                if let Some((a, b)) = endpoints {
                    set.tension_pairs.insert(PairKey::new(a, b), status.clone());
                }
                set.tensions.insert(tension.clone(), status);
            }
            // Revert has no forward effect; its work was done in pass 1.
            GovernanceOpKind::Revert { .. } => {}
        }
    }
    set
}

// ── Persistence (mirrors reconciliation/oplog.rs conventions) ─

/// Append-only JSONL store at `<atlas_dir>/governance_oplog.jsonl`.
/// One [`GovernanceOp`] per line; the file is the bytes-level record of
/// every governance decision, and [`GovernanceOplog::derive`] replays it.
pub struct GovernanceOplog {
    pub path: PathBuf,
}

impl GovernanceOplog {
    pub fn new(atlas_dir: impl Into<PathBuf>) -> Self {
        Self {
            path: atlas_dir.into().join("governance_oplog.jsonl"),
        }
    }

    /// Append one op. Creates the atlas dir lazily on first write.
    pub fn append(&self, op: &GovernanceOp) -> Result<()> {
        if let Some(parent) = self.path.parent() {
            fs::create_dir_all(parent).map_err(Error::Io)?;
        }
        let line = serde_json::to_string(op)
            .map_err(|e| Error::Extraction(format!("governance_oplog: serialise: {e}")))?;
        let mut f = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)
            .map_err(Error::Io)?;
        f.write_all(line.as_bytes()).map_err(Error::Io)?;
        f.write_all(b"\n").map_err(Error::Io)?;
        tracing::debug!(
            id = %op.id.as_str(),
            actor = %op.actor,
            "governance_oplog: append"
        );
        Ok(())
    }

    /// Read every op in append order. Malformed lines and lines declaring
    /// a future `v` are skipped with a warning (forward-compat: an older
    /// reader must not crash on a newer log, nor silently misread it).
    pub fn read_all(&self) -> Result<Vec<GovernanceOp>> {
        if !self.path.exists() {
            return Ok(Vec::new());
        }
        let file = fs::File::open(&self.path).map_err(Error::Io)?;
        let reader = BufReader::new(file);
        let mut out = Vec::new();
        for (lineno, line) in reader.lines().enumerate() {
            let line = line.map_err(Error::Io)?;
            if line.trim().is_empty() {
                continue;
            }
            match serde_json::from_str::<GovernanceOp>(&line) {
                Ok(op) if op.v > GOVERNANCE_OPLOG_VERSION => {
                    tracing::warn!(
                        path = %self.path.display(),
                        line = lineno + 1,
                        v = op.v,
                        "governance_oplog: skipping op from a newer format version"
                    );
                }
                Ok(op) => out.push(op),
                Err(err) => {
                    tracing::warn!(
                        path = %self.path.display(),
                        line = lineno + 1,
                        "governance_oplog: malformed line skipped ({err})"
                    );
                }
            }
        }
        Ok(out)
    }

    /// Read + fold in one step: the current active set for this corpus.
    pub fn derive(&self) -> Result<ActiveSet> {
        Ok(derive_active(&self.read_all()?))
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}

/// 16-char prefix of a blake3 hex digest (64-bit truncation). Mirrors the
/// atom-id `short_hash`; kept local so the governance module doesn't widen
/// the atoms module's private API.
fn short_hash(input: &str) -> String {
    blake3::hash(input.as_bytes()).to_hex().to_string()[..16].to_string()
}

pub use corpus_engine_yield::time::unix_now as now_secs;

#[cfg(test)]
mod tests {
    use super::*;

    fn rule(n: usize) -> AtomId {
        AtomId::claim(n)
    }
    fn tension(n: usize) -> EdgeId {
        EdgeId::new(n)
    }

    /// Build an op at a monotonic, explicit timestamp so ids are
    /// deterministic and distinct within a test.
    fn op(kind: GovernanceOpKind, ts: i64, actor: &str) -> GovernanceOp {
        Op::new(kind, ts, actor)
    }

    #[test]
    fn assert_then_supersede() {
        let old = rule(1);
        let new = rule(2);
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: old.clone(),
                    source_doc: Some("charter.md".into()),
                },
                1000,
                "ingest",
            ),
            op(
                GovernanceOpKind::Supersede {
                    new_rule: new.clone(),
                    old_rules: vec![old.clone()],
                    rationale: "May 12 house meeting".into(),
                },
                1001,
                "human:alex",
            ),
        ];
        let set = derive_active(&ops);
        assert!(set.is_active(&new));
        assert!(matches!(
            set.rules.get(&old),
            Some(RuleStatus::Superseded { by_rules, .. }) if by_rules == &vec![new.clone()]
        ));
        assert_eq!(set.active_rules(), vec![&new]);
    }

    #[test]
    fn retract_rule_drops_it() {
        let r = rule(1);
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: r.clone(),
                    source_doc: None,
                },
                1000,
                "ingest",
            ),
            op(
                GovernanceOpKind::RetractRule {
                    rule: r.clone(),
                    rationale: "no longer applies".into(),
                },
                1001,
                "human:sam",
            ),
        ];
        let set = derive_active(&ops);
        assert!(!set.is_active(&r));
        assert!(matches!(
            set.rules.get(&r),
            Some(RuleStatus::Retracted { .. })
        ));
        assert!(set.active_rules().is_empty());
    }

    #[test]
    fn accept_tension_is_first_class_and_closes_open() {
        let t = tension(1);
        let other = tension(2);
        let ops = vec![op(
            GovernanceOpKind::AcceptTension {
                tension: t.clone(),
                rationale: "quiet-hours vs private-room is intentional".into(),
                endpoints: None,
            },
            1000,
            "human:alex",
        )];
        let set = derive_active(&ops);
        assert!(matches!(
            set.tensions.get(&t),
            Some(TensionStatus::Accepted { .. })
        ));
        // The unadjudicated tension is still open; the accepted one is not.
        assert_eq!(set.open_tensions(&[t.clone(), other.clone()]), vec![&other]);
    }

    #[test]
    fn dismiss_tension_closes_open_and_is_revertible() {
        let t = tension(1);
        let other = tension(2);
        let dismiss = op(
            GovernanceOpKind::DismissTension {
                tension: t.clone(),
                endpoints: None,
                rationale: String::new(),
            },
            1000,
            "human:alex",
        );
        let set = derive_active(std::slice::from_ref(&dismiss));
        assert!(matches!(
            set.tensions.get(&t),
            Some(TensionStatus::Dismissed { .. })
        ));
        // Dismissed leaves the open set; the untouched tension stays open.
        assert_eq!(set.open_tensions(&[t.clone(), other.clone()]), vec![&other]);

        // Reverting the dismissal reopens the tension.
        let revert = op(
            GovernanceOpKind::Revert {
                targets: vec![dismiss.id.clone()],
                rationale: "mis-click".into(),
            },
            1001,
            "human:alex",
        );
        let set = derive_active(&[dismiss, revert]);
        assert!(set.tensions.is_empty());
        assert_eq!(
            set.open_tensions(&[t.clone(), other.clone()]),
            vec![&t, &other]
        );
    }

    #[test]
    fn adjudication_by_endpoint_pair_survives_edge_renumbering() {
        // Adjudicate edge-0001 carrying its endpoint rule pair. After a
        // rebuild the same conceptual tension is re-minted as a NEW edge
        // id — the pair map is what lets the view still see it settled.
        let (a, b) = (rule(1), rule(2));
        let ops = vec![op(
            GovernanceOpKind::AcceptTension {
                tension: tension(1),
                rationale: "both can stand".into(),
                endpoints: Some((b.clone(), a.clone())), // reversed on purpose
            },
            1000,
            "human:alex",
        )];
        let set = derive_active(&ops);
        // Pair lookup is order-independent (normalized key).
        assert!(matches!(
            set.tension_pairs.get(&PairKey::new(&a, &b)),
            Some(TensionStatus::Accepted { .. })
        ));
        assert!(matches!(
            set.tension_pairs.get(&PairKey::new(&b, &a)),
            Some(TensionStatus::Accepted { .. })
        ));
        // The renumbered edge id itself is unknown to the edge-id map…
        assert!(set.tensions.get(&tension(99)).is_none());
        // …and an op without endpoints populates no pair entry.
        let bare = derive_active(&[op(
            GovernanceOpKind::AcceptTension {
                tension: tension(3),
                rationale: "legacy".into(),
                endpoints: None,
            },
            1001,
            "human:alex",
        )]);
        assert!(bare.tension_pairs.is_empty());
    }

    #[test]
    fn resolve_tension_links_to_supersede() {
        let old = rule(1);
        let new = rule(2);
        let t = tension(1);
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: String::new(),
            },
            1001,
            "human:alex",
        );
        let supersede_id = supersede.id.clone();
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: old.clone(),
                    source_doc: None,
                },
                1000,
                "ingest",
            ),
            supersede,
            op(
                GovernanceOpKind::ResolveTension {
                    tension: t.clone(),
                    via: supersede_id.clone(),
                    endpoints: None,
                    rationale: String::new(),
                },
                1002,
                "human:alex",
            ),
        ];
        let set = derive_active(&ops);
        assert!(matches!(
            set.tensions.get(&t),
            Some(TensionStatus::Resolved { .. })
        ));
        assert!(matches!(
            set.rules.get(&old),
            Some(RuleStatus::Superseded { .. })
        ));
        assert!(set.is_active(&new));
    }

    #[test]
    fn revert_supersede_reactivates_old_rule() {
        // Realistic resolution bundle: draft the new rule (AssertRule),
        // supersede the old, resolve the tension — then a human reverts
        // the whole bundle. The old rule must come back to force and the
        // tension must reopen.
        let old = rule(1);
        let new = rule(2);
        let t = tension(1);

        let assert_old = op(
            GovernanceOpKind::AssertRule {
                rule: old.clone(),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        let assert_new = op(
            GovernanceOpKind::AssertRule {
                rule: new.clone(),
                source_doc: None,
            },
            1001,
            "human:alex",
        );
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: String::new(),
            },
            1002,
            "human:alex",
        );
        let resolve = op(
            GovernanceOpKind::ResolveTension {
                tension: t.clone(),
                via: supersede.id.clone(),
                endpoints: None,
                rationale: String::new(),
            },
            1003,
            "human:alex",
        );
        let revert = op(
            GovernanceOpKind::Revert {
                targets: vec![
                    assert_new.id.clone(),
                    supersede.id.clone(),
                    resolve.id.clone(),
                ],
                rationale: "decision reversed at next meeting".into(),
            },
            1004,
            "human:sam",
        );

        let ops = vec![assert_old, assert_new, supersede, resolve, revert];
        let set = derive_active(&ops);

        // Old rule is active again; the orphan new rule and the tension
        // adjudication are gone.
        assert!(set.is_active(&old));
        assert!(
            !set.rules.contains_key(&new),
            "reverted draft rule should not exist"
        );
        assert_eq!(set.active_rules(), vec![&old]);
        assert_eq!(set.open_tensions(&[t.clone()]), vec![&t]);
    }

    #[test]
    fn revert_of_revert_reapplies() {
        let old = rule(1);
        let new = rule(2);

        let assert_old = op(
            GovernanceOpKind::AssertRule {
                rule: old.clone(),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: String::new(),
            },
            1001,
            "human:alex",
        );
        let revert1 = op(
            GovernanceOpKind::Revert {
                targets: vec![supersede.id.clone()],
                rationale: "undo".into(),
            },
            1002,
            "human:sam",
        );
        let revert2 = op(
            GovernanceOpKind::Revert {
                targets: vec![revert1.id.clone()],
                rationale: "actually, keep the supersession".into(),
            },
            1003,
            "human:alex",
        );

        // After revert1 alone: old active.
        let after_one = derive_active(&[assert_old.clone(), supersede.clone(), revert1.clone()]);
        assert!(after_one.is_active(&old));

        // After revert2 (revert of the revert): supersession restored.
        let after_two = derive_active(&[assert_old, supersede, revert1, revert2]);
        assert!(after_two.is_active(&new));
        assert!(matches!(
            after_two.rules.get(&old),
            Some(RuleStatus::Superseded { .. })
        ));
    }

    #[test]
    fn reassert_is_idempotent() {
        let r = rule(1);
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: r.clone(),
                    source_doc: None,
                },
                1000,
                "ingest",
            ),
            op(
                GovernanceOpKind::AssertRule {
                    rule: r.clone(),
                    source_doc: None,
                },
                1001,
                "ingest",
            ),
        ];
        let set = derive_active(&ops);
        assert_eq!(set.active_rules(), vec![&r]);
        assert_eq!(set.rules.len(), 1);
    }

    #[test]
    fn op_ids_are_deterministic_and_distinct() {
        let kind = GovernanceOpKind::AcceptTension {
            tension: tension(1),
            rationale: "ok".into(),
            endpoints: None,
        };
        // Same (kind, ts, actor) → same id.
        let a = Op::new(kind.clone(), 5, "human:alex");
        let b = GovernanceOp::new(kind.clone(), 5, "human:alex");
        assert_eq!(a.id, b.id);
        // Different ts → different id.
        let c = GovernanceOp::new(kind, 6, "human:alex");
        assert_ne!(a.id, c.id);
        // Id is a content-hash shape.
        assert!(a.id.as_str().starts_with("gov-"));
        assert_eq!(a.id.as_str().len(), "gov-".len() + 16);
    }

    #[test]
    fn unattended_adjudication_is_detected() {
        // An AssertRule by ingest is allowed.
        let assert = op(
            GovernanceOpKind::AssertRule {
                rule: rule(1),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        assert!(first_unattended_act(std::slice::from_ref(&assert)).is_none());

        // A Supersede must be human-authored.
        let forged = op(
            GovernanceOpKind::Supersede {
                new_rule: rule(2),
                old_rules: vec![rule(1)],
                rationale: String::new(),
            },
            1001,
            "ingest",
        );
        assert!(first_unattended_act(&[assert.clone(), forged.clone()]).is_some());

        let proper = op(
            GovernanceOpKind::Supersede {
                new_rule: rule(2),
                old_rules: vec![rule(1)],
                rationale: String::new(),
            },
            1001,
            "human:alex",
        );
        assert!(first_unattended_act(&[assert, proper]).is_none());
    }

    #[test]
    fn replay_round_trips_through_disk_byte_for_byte() {
        // INV-1: write → read → fold reproduces the in-memory fold, and
        // the read-back ops equal what was written.
        let dir = tempfile::tempdir().unwrap();
        let log = GovernanceOplog::new(dir.path());

        let old = rule(1);
        let new = rule(2);
        let t = tension(1);
        let assert_old = op(
            GovernanceOpKind::AssertRule {
                rule: old.clone(),
                source_doc: Some("charter.md".into()),
            },
            1000,
            "ingest",
        );
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: "meeting".into(),
            },
            1001,
            "human:alex",
        );
        let resolve = op(
            GovernanceOpKind::ResolveTension {
                tension: t.clone(),
                via: supersede.id.clone(),
                endpoints: Some((old.clone(), new.clone())),
                rationale: String::new(),
            },
            1002,
            "human:alex",
        );
        let dismiss = op(
            GovernanceOpKind::DismissTension {
                tension: tension(2),
                endpoints: Some((rule(3), rule(4))),
                rationale: "parking vs stays — not a conflict".into(),
            },
            1003,
            "human:alex",
        );
        let written = vec![assert_old, supersede, resolve, dismiss];
        for o in &written {
            log.append(o).unwrap();
        }

        let read_back = log.read_all().unwrap();
        assert_eq!(read_back, written, "ops must survive a disk round-trip");
        assert_eq!(
            log.derive().unwrap(),
            derive_active(&written),
            "fold over disk == fold over memory"
        );
    }

    #[test]
    fn read_skips_future_version_lines() {
        // Forward-compat: a line declaring a newer `v` is skipped, not
        // misinterpreted (schema-back-compat rule).
        let dir = tempfile::tempdir().unwrap();
        let log = GovernanceOplog::new(dir.path());
        let good = op(
            GovernanceOpKind::AssertRule {
                rule: rule(1),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        log.append(&good).unwrap();
        // Hand-write a structurally-valid line from a future version.
        let future = format!(
            r#"{{"id":"gov-future00000000","v":{},"ts_unix":1001,"actor":"human:x","op":"assert_rule","rule":"claim-9999"}}"#,
            GOVERNANCE_OPLOG_VERSION + 1
        );
        let mut f = OpenOptions::new().append(true).open(log.path()).unwrap();
        f.write_all(future.as_bytes()).unwrap();
        f.write_all(b"\n").unwrap();

        let read = log.read_all().unwrap();
        assert_eq!(read.len(), 1, "future-version line should be skipped");
        assert_eq!(read[0].id, good.id);
    }

    #[test]
    fn missing_log_folds_to_empty() {
        let dir = tempfile::tempdir().unwrap();
        let set = GovernanceOplog::new(dir.path()).derive().unwrap();
        assert!(set.rules.is_empty());
        assert!(set.tensions.is_empty());
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Event-sourced governance oplog + active-set fold.
//!
//! The governance layer treats a community's normative state as a
//! *query over an append-only log of governance acts*, not as stored
//! mutable state. Rules are atlas `Claim` atoms (extracted by a
//! recipe's custom-ontology atlas pipeline); tensions are atlas
//! `EdgeType::Tension` edges. This module owns the **acts on top of
//! that graph** — assert / supersede / retract a rule, resolve / accept
//! a tension — and the pure fold ([`derive_active`]) that derives the
//! *current active rule set* from the act log.
//!
//! Why event-sourced (the design conceit, "common law"):
//!   - the current law is a [`derive_active`] query, not a row you mutate;
//!   - history is preserved — "what was the guest policy in March, and
//!     why did it change?" is answerable because nothing is destroyed;
//!   - every act is reversible via a single general [`GovernanceOpKind::Revert`]
//!     that tomb-stones prior ops during the fold (INV-3) and is itself
//!     revertible (reverting a `Revert` re-applies the original ops);
//!   - [`GovernanceOpKind::AcceptTension`] makes a known, tolerated
//!     contradiction a *first-class state*, not a bug to be force-resolved —
//!     which is how real common law actually works.
//!
//! Division of labour with the atlas: the atlas graph supplies *which
//! rules exist* (Claim atoms) and *which tensions were surfaced* (Tension
//! edges). This log supplies *what was decided about them*. The fold is
//! therefore pure over the ops alone; the set of currently-**open**
//! tensions is `(atlas tension edges) − (adjudicated edges)`, computed by
//! [`ActiveSet::open_tensions`] which takes the edge universe as input.
//!
//! This is the load-bearing contract everything else writes through, so
//! the fold does no IO and never calls inference, and the invariants
//! below (replay determinism, reversibility, attribution) are pinned by
//! the module tests.

use std::collections::{BTreeMap, BTreeSet};
use std::fs::{self, OpenOptions};
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::enrichment::atlas::atoms::AtomId;
use crate::enrichment::atlas::edges::EdgeId;
use crate::error::{Error, Result};

/// Current oplog line format version. Bumped only when the reader must
/// opt in to new semantics (the schema-back-compat convention: a reader
/// refuses lines declaring a `v` it doesn't understand rather than
/// silently misinterpreting them).
pub const GOVERNANCE_OPLOG_VERSION: u32 = 1;

// ── Op identity ──────────────────────────────────────────────

/// Stable, content-addressed id for a governance op. Derived from the
/// op's (kind, timestamp, actor) triple, so the id a [`GovernanceOpKind::Revert`]
/// targets is reproducible from the log bytes alone — no positional or
/// external counter to drift.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct OpId(String);

impl OpId {
    pub fn from_raw(s: impl Into<String>) -> Self {
        Self(s.into())
    }
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

// ── The acts ─────────────────────────────────────────────────

/// The six governance acts (spec §6.3) plus the one general reversal op.
///
/// Internally tagged on `"op"` so each line is self-describing and each
/// variant carries exactly its own fields — illegal field combinations
/// are unrepresentable (SOLID/"make illegal states unrepresentable",
/// versus the all-fields-optional shape of the reconciliation oplog).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum GovernanceOpKind {
    /// A rule (Claim atom) enters the governed set. Emitted idempotently
    /// by ingest for every freshly-extracted rule; re-asserting a rule id
    /// already present is a no-op for the active set.
    AssertRule {
        rule: AtomId,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        source_doc: Option<String>,
    },
    /// One or more old rules are replaced by a new rule. The new rule is
    /// asserted active; each old rule becomes [`RuleStatus::Superseded`].
    Supersede {
        new_rule: AtomId,
        old_rules: Vec<AtomId>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// A rule is withdrawn from active law with no replacement.
    RetractRule {
        rule: AtomId,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// A surfaced tension is adjudicated as resolved. `via` names the act
    /// that resolved it (a [`GovernanceOpKind::Supersede`]), so the audit
    /// trail links the tension to its fix.
    ///
    /// `endpoints` records the tension's two rule ids at adjudication
    /// time. Edge ids are re-minted sequentially on every atlas rebuild,
    /// but content-hash rule ids are stable — so the endpoint pair is the
    /// adjudication's durable identity across rebuilds (see
    /// [`ActiveSet::tension_pairs`]). Optional for back-compat with logs
    /// written before the field existed.
    ResolveTension {
        tension: EdgeId,
        via: OpId,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        endpoints: Option<(AtomId, AtomId)>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// A surfaced tension is adjudicated as known-and-tolerated. The
    /// rationale is required: an accepted contradiction must say why.
    /// `endpoints` as on [`GovernanceOpKind::ResolveTension`].
    AcceptTension {
        tension: EdgeId,
        rationale: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        endpoints: Option<(AtomId, AtomId)>,
    },
    /// A surfaced tension is adjudicated as not-a-conflict: the detector
    /// was wrong (a decoy), not a contradiction the community tolerates —
    /// that distinct state is [`GovernanceOpKind::AcceptTension`].
    /// Deliberately light-ceremony (rationale optional): dismissing
    /// detector noise is the steward's call, and it is revertible like
    /// every act. `endpoints` as on [`GovernanceOpKind::ResolveTension`].
    DismissTension {
        tension: EdgeId,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        endpoints: Option<(AtomId, AtomId)>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
    /// Tomb-stone prior op(s). The fold skips each target *and its
    /// effects* as if it had never been recorded. A human adjudication is
    /// usually a small bundle (AssertRule + Supersede + ResolveTension);
    /// naming the whole bundle makes the undo atomic. Revertible: a
    /// `Revert` of a `Revert` re-applies the originals.
    Revert {
        targets: Vec<OpId>,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        rationale: String,
    },
}

/// One line in `governance_oplog.jsonl` — an act plus its provenance.
///
/// The `kind` is flattened, so a line reads
/// `{"id":"gov-…","v":1,"ts_unix":…,"actor":"human:alex","op":"supersede",…}`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GovernanceOp {
    /// Content-addressed op id (see [`OpId`]). Stable across replays.
    pub id: OpId,
    /// Line format version. Always written; read-side gate skips lines
    /// declaring a higher version than this reader understands.
    #[serde(default = "default_version")]
    pub v: u32,
    /// Op timestamp (Unix seconds).
    pub ts_unix: i64,
    /// Who performed the act. INV-2: every act except [`GovernanceOpKind::AssertRule`]
    /// (which ingest may author as `actor = "ingest"`) MUST be attributed
    /// to a `human:<name>`. The CLI verbs pass this; [`first_unattended_act`]
    /// is the guard against an unattended write.
    pub actor: String,
    #[serde(flatten)]
    pub kind: GovernanceOpKind,
}

fn default_version() -> u32 {
    GOVERNANCE_OPLOG_VERSION
}

impl GovernanceOp {
    /// Build an op, deriving its content-addressed [`OpId`] from the
    /// (kind, ts, actor) triple. Two byte-identical acts at the same
    /// second by the same actor would collide by design — callers append
    /// in real time, so this does not arise in practice (the same
    /// birthday-bound caveat the atom content-hash ids carry).
    pub fn new(kind: GovernanceOpKind, ts_unix: i64, actor: impl Into<String>) -> Self {
        let actor = actor.into();
        // serde_json field order is the declaration order, so the body
        // string — and therefore the id — is deterministic across runs.
        let body = serde_json::to_string(&kind).unwrap_or_default();
        let input = format!("gov|{ts_unix}|{actor}|{body}");
        Self {
            id: OpId(format!("gov-{}", short_hash(&input))),
            v: GOVERNANCE_OPLOG_VERSION,
            ts_unix,
            actor,
            kind,
        }
    }
}

/// INV-2 guard: the first op that is neither an `AssertRule` nor authored
/// by a `human:<name>` actor — i.e. an adjudication a code path tried to
/// write unattended. `None` means the log honours the attribution
/// invariant. The CLI's human verbs always pass `human:<name>`; this
/// catches a regression where some automated path forges a decision.
pub fn first_unattended_act(ops: &[GovernanceOp]) -> Option<&GovernanceOp> {
    ops.iter().find(|op| {
        !matches!(op.kind, GovernanceOpKind::AssertRule { .. }) && !op.actor.starts_with("human:")
    })
}

// ── Derived state ────────────────────────────────────────────

/// Status of a rule in the derived active set.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
pub enum RuleStatus {
    /// In force.
    Active,
    /// Replaced by `by_rules`, via op `by`.
    Superseded { by: OpId, by_rules: Vec<AtomId> },
    /// Withdrawn without replacement, via op `by`.
    Retracted { by: OpId },
}

/// Adjudication outcome of a tension. Only adjudicated tensions appear in
/// the fold output — an *open* tension is one the atlas surfaced that the
/// log has not yet touched (see [`ActiveSet::open_tensions`]).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
pub enum TensionStatus {
    /// Resolved by op `by` (which references the resolving Supersede).
    Resolved { by: OpId },
    /// Accepted as known-and-tolerated, via op `by`.
    Accepted { by: OpId },
    /// Dismissed as not-a-conflict (detector noise), via op `by`.
    Dismissed { by: OpId },
}

impl TensionStatus {
    /// The op that produced this status. Every adjudication carries the
    /// id of the act that decided it — used to identify the *live,
    /// winning* adjudication for an edge (last-write-wins in the fold).
    pub fn by(&self) -> &OpId {
        match self {
            TensionStatus::Resolved { by }
            | TensionStatus::Accepted { by }
            | TensionStatus::Dismissed { by } => by,
        }
    }
}

/// Canonical, order-independent key for a tension's endpoint rule pair —
/// `"<lo-id>|<hi-id>"`. String-backed so [`ActiveSet`] stays
/// JSON-serializable (JSON map keys must be strings); constructed only
/// through [`PairKey::new`], which normalizes the order.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(transparent)]
pub struct PairKey(String);

impl PairKey {
    pub fn new(a: &AtomId, b: &AtomId) -> Self {
        let (lo, hi) = if a.as_str() <= b.as_str() {
            (a, b)
        } else {
            (b, a)
        };
        Self(format!("{}|{}", lo.as_str(), hi.as_str()))
    }
}

/// The folded current state: every rule the log has touched with its
/// status, and every tension the log has adjudicated with its outcome.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ActiveSet {
    /// Rule id → status. Sorted (BTreeMap) for deterministic iteration.
    pub rules: BTreeMap<AtomId, RuleStatus>,
    /// Adjudicated tension id → outcome.
    pub tensions: BTreeMap<EdgeId, TensionStatus>,
    /// Adjudicated endpoint-pair → outcome, for adjudication ops that
    /// carried `endpoints`. Edge ids are re-minted on every atlas
    /// rebuild; the (content-hash) rule-id pair is the identity that
    /// survives, so a re-detected tension between the same two rules
    /// inherits its adjudication (see the view join in
    /// `governance_view::build_view`).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub tension_pairs: BTreeMap<PairKey, TensionStatus>,
}

impl ActiveSet {
    /// The rules currently in force, in deterministic id order.
    pub fn active_rules(&self) -> Vec<&AtomId> {
        self.rules
            .iter()
            .filter(|(_, s)| matches!(s, RuleStatus::Active))
            .map(|(id, _)| id)
            .collect()
    }

    /// Whether a specific rule is currently in force.
    pub fn is_active(&self, rule: &AtomId) -> bool {
        matches!(self.rules.get(rule), Some(RuleStatus::Active))
    }

    /// Open tensions = surfaced-by-the-atlas minus adjudicated-by-the-log.
    /// `all` is the tension-edge universe from the atlas graph; this
    /// returns those with no adjudication, in input order.
    pub fn open_tensions<'a>(&self, all: &'a [EdgeId]) -> Vec<&'a EdgeId> {
        all.iter()
            .filter(|e| !self.tensions.contains_key(*e))
            .collect()
    }
}

/// Derive the current active set by folding the act log.
///
/// Two passes, both pure:
///
/// **Pass 1 (backward) — liveness.** Walk newest→oldest computing which
/// ops are *live*, honouring [`GovernanceOpKind::Revert`] chains. A
/// `Revert` targets only earlier ops, so walking backward means every op
/// already knows the verdict of any op that could revert it. A live
/// `Revert` cancels its targets; a *cancelled* `Revert` does not (so
/// reverting a `Revert` re-applies the originals). See tests
/// `revert_supersede_reactivates_old_rule` and `revert_of_revert_reapplies`.
///
/// **Pass 2 (forward) — apply.** Fold the live ops in log order; later
/// ops overwrite earlier status for the same rule. Because the supersede
/// of a reverted bundle is skipped in pass 2, the old rule's earlier
/// `Active` status (from its ingest `AssertRule`) stands.
pub fn derive_active(ops: &[GovernanceOp]) -> ActiveSet {
    let n = ops.len();

    // Pass 1: liveness.
    let mut live = vec![true; n];
    let mut cancelled: BTreeSet<&str> = BTreeSet::new();
    for i in (0..n).rev() {
        let op = &ops[i];
        if cancelled.contains(op.id.as_str()) {
            // This op was tomb-stoned by a later live Revert. If it is
            // itself a Revert, skipping it here means its targets are
            // NOT added to `cancelled` — that is the revert-of-revert
            // re-application.
            live[i] = false;
            continue;
        }
        if let GovernanceOpKind::Revert { targets, .. } = &op.kind {
            for t in targets {
                cancelled.insert(t.as_str());
            }
        }
    }

    // Pass 2: apply live ops forward.
    let mut set = ActiveSet::default();
    for (i, op) in ops.iter().enumerate() {
        if !live[i] {
            continue;
        }
        match &op.kind {
            GovernanceOpKind::AssertRule { rule, .. } => {
                set.rules.insert(rule.clone(), RuleStatus::Active);
            }
            GovernanceOpKind::Supersede {
                new_rule,
                old_rules,
                ..
            } => {
                set.rules.insert(new_rule.clone(), RuleStatus::Active);
                for old in old_rules {
                    set.rules.insert(
                        old.clone(),
                        RuleStatus::Superseded {
                            by: op.id.clone(),
                            by_rules: vec![new_rule.clone()],
                        },
                    );
                }
            }
            GovernanceOpKind::RetractRule { rule, .. } => {
                set.rules
                    .insert(rule.clone(), RuleStatus::Retracted { by: op.id.clone() });
            }
            GovernanceOpKind::ResolveTension {
                tension, endpoints, ..
            } => {
                let status = TensionStatus::Resolved { by: op.id.clone() };
                if let Some((a, b)) = endpoints {
                    set.tension_pairs.insert(PairKey::new(a, b), status.clone());
                }
                set.tensions.insert(tension.clone(), status);
            }
            GovernanceOpKind::AcceptTension {
                tension, endpoints, ..
            } => {
                let status = TensionStatus::Accepted { by: op.id.clone() };
                if let Some((a, b)) = endpoints {
                    set.tension_pairs.insert(PairKey::new(a, b), status.clone());
                }
                set.tensions.insert(tension.clone(), status);
            }
            GovernanceOpKind::DismissTension {
                tension, endpoints, ..
            } => {
                let status = TensionStatus::Dismissed { by: op.id.clone() };
                if let Some((a, b)) = endpoints {
                    set.tension_pairs.insert(PairKey::new(a, b), status.clone());
                }
                set.tensions.insert(tension.clone(), status);
            }
            // Revert has no forward effect; its work was done in pass 1.
            GovernanceOpKind::Revert { .. } => {}
        }
    }
    set
}

// ── Persistence (mirrors reconciliation/oplog.rs conventions) ─

/// Append-only JSONL store at `<atlas_dir>/governance_oplog.jsonl`.
/// One [`GovernanceOp`] per line; the file is the bytes-level record of
/// every governance decision, and [`GovernanceOplog::derive`] replays it.
pub struct GovernanceOplog {
    pub path: PathBuf,
}

impl GovernanceOplog {
    pub fn new(atlas_dir: impl Into<PathBuf>) -> Self {
        Self {
            path: atlas_dir.into().join("governance_oplog.jsonl"),
        }
    }

    /// Append one op. Creates the atlas dir lazily on first write.
    pub fn append(&self, op: &GovernanceOp) -> Result<()> {
        if let Some(parent) = self.path.parent() {
            fs::create_dir_all(parent).map_err(Error::Io)?;
        }
        let line = serde_json::to_string(op)
            .map_err(|e| Error::Extraction(format!("governance_oplog: serialise: {e}")))?;
        let mut f = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)
            .map_err(Error::Io)?;
        f.write_all(line.as_bytes()).map_err(Error::Io)?;
        f.write_all(b"\n").map_err(Error::Io)?;
        tracing::debug!(
            id = %op.id.as_str(),
            actor = %op.actor,
            "governance_oplog: append"
        );
        Ok(())
    }

    /// Read every op in append order. Malformed lines and lines declaring
    /// a future `v` are skipped with a warning (forward-compat: an older
    /// reader must not crash on a newer log, nor silently misread it).
    pub fn read_all(&self) -> Result<Vec<GovernanceOp>> {
        if !self.path.exists() {
            return Ok(Vec::new());
        }
        let file = fs::File::open(&self.path).map_err(Error::Io)?;
        let reader = BufReader::new(file);
        let mut out = Vec::new();
        for (lineno, line) in reader.lines().enumerate() {
            let line = line.map_err(Error::Io)?;
            if line.trim().is_empty() {
                continue;
            }
            match serde_json::from_str::<GovernanceOp>(&line) {
                Ok(op) if op.v > GOVERNANCE_OPLOG_VERSION => {
                    tracing::warn!(
                        path = %self.path.display(),
                        line = lineno + 1,
                        v = op.v,
                        "governance_oplog: skipping op from a newer format version"
                    );
                }
                Ok(op) => out.push(op),
                Err(err) => {
                    tracing::warn!(
                        path = %self.path.display(),
                        line = lineno + 1,
                        "governance_oplog: malformed line skipped ({err})"
                    );
                }
            }
        }
        Ok(out)
    }

    /// Read + fold in one step: the current active set for this corpus.
    pub fn derive(&self) -> Result<ActiveSet> {
        Ok(derive_active(&self.read_all()?))
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}

/// 16-char prefix of a blake3 hex digest (64-bit truncation). Mirrors the
/// atom-id `short_hash`; kept local so the governance module doesn't widen
/// the atoms module's private API.
fn short_hash(input: &str) -> String {
    blake3::hash(input.as_bytes()).to_hex().to_string()[..16].to_string()
}

pub use corpus_engine_yield::time::unix_now as now_secs;

#[cfg(test)]
mod tests {
    use super::*;

    fn rule(n: usize) -> AtomId {
        AtomId::claim(n)
    }
    fn tension(n: usize) -> EdgeId {
        EdgeId::new(n)
    }

    /// Build an op at a monotonic, explicit timestamp so ids are
    /// deterministic and distinct within a test.
    fn op(kind: GovernanceOpKind, ts: i64, actor: &str) -> GovernanceOp {
        GovernanceOp::new(kind, ts, actor)
    }

    #[test]
    fn assert_then_supersede() {
        let old = rule(1);
        let new = rule(2);
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: old.clone(),
                    source_doc: Some("charter.md".into()),
                },
                1000,
                "ingest",
            ),
            op(
                GovernanceOpKind::Supersede {
                    new_rule: new.clone(),
                    old_rules: vec![old.clone()],
                    rationale: "May 12 house meeting".into(),
                },
                1001,
                "human:alex",
            ),
        ];
        let set = derive_active(&ops);
        assert!(set.is_active(&new));
        assert!(matches!(
            set.rules.get(&old),
            Some(RuleStatus::Superseded { by_rules, .. }) if by_rules == &vec![new.clone()]
        ));
        assert_eq!(set.active_rules(), vec![&new]);
    }

    #[test]
    fn retract_rule_drops_it() {
        let r = rule(1);
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: r.clone(),
                    source_doc: None,
                },
                1000,
                "ingest",
            ),
            op(
                GovernanceOpKind::RetractRule {
                    rule: r.clone(),
                    rationale: "no longer applies".into(),
                },
                1001,
                "human:sam",
            ),
        ];
        let set = derive_active(&ops);
        assert!(!set.is_active(&r));
        assert!(matches!(
            set.rules.get(&r),
            Some(RuleStatus::Retracted { .. })
        ));
        assert!(set.active_rules().is_empty());
    }

    #[test]
    fn accept_tension_is_first_class_and_closes_open() {
        let t = tension(1);
        let other = tension(2);
        let ops = vec![op(
            GovernanceOpKind::AcceptTension {
                tension: t.clone(),
                rationale: "quiet-hours vs private-room is intentional".into(),
                endpoints: None,
            },
            1000,
            "human:alex",
        )];
        let set = derive_active(&ops);
        assert!(matches!(
            set.tensions.get(&t),
            Some(TensionStatus::Accepted { .. })
        ));
        // The unadjudicated tension is still open; the accepted one is not.
        assert_eq!(set.open_tensions(&[t.clone(), other.clone()]), vec![&other]);
    }

    #[test]
    fn dismiss_tension_closes_open_and_is_revertible() {
        let t = tension(1);
        let other = tension(2);
        let dismiss = op(
            GovernanceOpKind::DismissTension {
                tension: t.clone(),
                endpoints: None,
                rationale: String::new(),
            },
            1000,
            "human:alex",
        );
        let set = derive_active(std::slice::from_ref(&dismiss));
        assert!(matches!(
            set.tensions.get(&t),
            Some(TensionStatus::Dismissed { .. })
        ));
        // Dismissed leaves the open set; the untouched tension stays open.
        assert_eq!(set.open_tensions(&[t.clone(), other.clone()]), vec![&other]);

        // Reverting the dismissal reopens the tension.
        let revert = op(
            GovernanceOpKind::Revert {
                targets: vec![dismiss.id.clone()],
                rationale: "mis-click".into(),
            },
            1001,
            "human:alex",
        );
        let set = derive_active(&[dismiss, revert]);
        assert!(set.tensions.is_empty());
        assert_eq!(
            set.open_tensions(&[t.clone(), other.clone()]),
            vec![&t, &other]
        );
    }

    #[test]
    fn adjudication_by_endpoint_pair_survives_edge_renumbering() {
        // Adjudicate edge-0001 carrying its endpoint rule pair. After a
        // rebuild the same conceptual tension is re-minted as a NEW edge
        // id — the pair map is what lets the view still see it settled.
        let (a, b) = (rule(1), rule(2));
        let ops = vec![op(
            GovernanceOpKind::AcceptTension {
                tension: tension(1),
                rationale: "both can stand".into(),
                endpoints: Some((b.clone(), a.clone())), // reversed on purpose
            },
            1000,
            "human:alex",
        )];
        let set = derive_active(&ops);
        // Pair lookup is order-independent (normalized key).
        assert!(matches!(
            set.tension_pairs.get(&PairKey::new(&a, &b)),
            Some(TensionStatus::Accepted { .. })
        ));
        assert!(matches!(
            set.tension_pairs.get(&PairKey::new(&b, &a)),
            Some(TensionStatus::Accepted { .. })
        ));
        // The renumbered edge id itself is unknown to the edge-id map…
        assert!(set.tensions.get(&tension(99)).is_none());
        // …and an op without endpoints populates no pair entry.
        let bare = derive_active(&[op(
            GovernanceOpKind::AcceptTension {
                tension: tension(3),
                rationale: "legacy".into(),
                endpoints: None,
            },
            1001,
            "human:alex",
        )]);
        assert!(bare.tension_pairs.is_empty());
    }

    #[test]
    fn resolve_tension_links_to_supersede() {
        let old = rule(1);
        let new = rule(2);
        let t = tension(1);
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: String::new(),
            },
            1001,
            "human:alex",
        );
        let supersede_id = supersede.id.clone();
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: old.clone(),
                    source_doc: None,
                },
                1000,
                "ingest",
            ),
            supersede,
            op(
                GovernanceOpKind::ResolveTension {
                    tension: t.clone(),
                    via: supersede_id.clone(),
                    endpoints: None,
                    rationale: String::new(),
                },
                1002,
                "human:alex",
            ),
        ];
        let set = derive_active(&ops);
        assert!(matches!(
            set.tensions.get(&t),
            Some(TensionStatus::Resolved { .. })
        ));
        assert!(matches!(
            set.rules.get(&old),
            Some(RuleStatus::Superseded { .. })
        ));
        assert!(set.is_active(&new));
    }

    #[test]
    fn revert_supersede_reactivates_old_rule() {
        // Realistic resolution bundle: draft the new rule (AssertRule),
        // supersede the old, resolve the tension — then a human reverts
        // the whole bundle. The old rule must come back to force and the
        // tension must reopen.
        let old = rule(1);
        let new = rule(2);
        let t = tension(1);

        let assert_old = op(
            GovernanceOpKind::AssertRule {
                rule: old.clone(),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        let assert_new = op(
            GovernanceOpKind::AssertRule {
                rule: new.clone(),
                source_doc: None,
            },
            1001,
            "human:alex",
        );
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: String::new(),
            },
            1002,
            "human:alex",
        );
        let resolve = op(
            GovernanceOpKind::ResolveTension {
                tension: t.clone(),
                via: supersede.id.clone(),
                endpoints: None,
                rationale: String::new(),
            },
            1003,
            "human:alex",
        );
        let revert = op(
            GovernanceOpKind::Revert {
                targets: vec![
                    assert_new.id.clone(),
                    supersede.id.clone(),
                    resolve.id.clone(),
                ],
                rationale: "decision reversed at next meeting".into(),
            },
            1004,
            "human:sam",
        );

        let ops = vec![assert_old, assert_new, supersede, resolve, revert];
        let set = derive_active(&ops);

        // Old rule is active again; the orphan new rule and the tension
        // adjudication are gone.
        assert!(set.is_active(&old));
        assert!(
            !set.rules.contains_key(&new),
            "reverted draft rule should not exist"
        );
        assert_eq!(set.active_rules(), vec![&old]);
        assert_eq!(set.open_tensions(&[t.clone()]), vec![&t]);
    }

    #[test]
    fn revert_of_revert_reapplies() {
        let old = rule(1);
        let new = rule(2);

        let assert_old = op(
            GovernanceOpKind::AssertRule {
                rule: old.clone(),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: String::new(),
            },
            1001,
            "human:alex",
        );
        let revert1 = op(
            GovernanceOpKind::Revert {
                targets: vec![supersede.id.clone()],
                rationale: "undo".into(),
            },
            1002,
            "human:sam",
        );
        let revert2 = op(
            GovernanceOpKind::Revert {
                targets: vec![revert1.id.clone()],
                rationale: "actually, keep the supersession".into(),
            },
            1003,
            "human:alex",
        );

        // After revert1 alone: old active.
        let after_one = derive_active(&[assert_old.clone(), supersede.clone(), revert1.clone()]);
        assert!(after_one.is_active(&old));

        // After revert2 (revert of the revert): supersession restored.
        let after_two = derive_active(&[assert_old, supersede, revert1, revert2]);
        assert!(after_two.is_active(&new));
        assert!(matches!(
            after_two.rules.get(&old),
            Some(RuleStatus::Superseded { .. })
        ));
    }

    #[test]
    fn reassert_is_idempotent() {
        let r = rule(1);
        let ops = vec![
            op(
                GovernanceOpKind::AssertRule {
                    rule: r.clone(),
                    source_doc: None,
                },
                1000,
                "ingest",
            ),
            op(
                GovernanceOpKind::AssertRule {
                    rule: r.clone(),
                    source_doc: None,
                },
                1001,
                "ingest",
            ),
        ];
        let set = derive_active(&ops);
        assert_eq!(set.active_rules(), vec![&r]);
        assert_eq!(set.rules.len(), 1);
    }

    #[test]
    fn op_ids_are_deterministic_and_distinct() {
        let kind = GovernanceOpKind::AcceptTension {
            tension: tension(1),
            rationale: "ok".into(),
            endpoints: None,
        };
        // Same (kind, ts, actor) → same id.
        let a = GovernanceOp::new(kind.clone(), 5, "human:alex");
        let b = GovernanceOp::new(kind.clone(), 5, "human:alex");
        assert_eq!(a.id, b.id);
        // Different ts → different id.
        let c = GovernanceOp::new(kind, 6, "human:alex");
        assert_ne!(a.id, c.id);
        // Id is a content-hash shape.
        assert!(a.id.as_str().starts_with("gov-"));
        assert_eq!(a.id.as_str().len(), "gov-".len() + 16);
    }

    #[test]
    fn unattended_adjudication_is_detected() {
        // An AssertRule by ingest is allowed.
        let assert = op(
            GovernanceOpKind::AssertRule {
                rule: rule(1),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        assert!(first_unattended_act(std::slice::from_ref(&assert)).is_none());

        // A Supersede must be human-authored.
        let forged = op(
            GovernanceOpKind::Supersede {
                new_rule: rule(2),
                old_rules: vec![rule(1)],
                rationale: String::new(),
            },
            1001,
            "ingest",
        );
        assert!(first_unattended_act(&[assert.clone(), forged.clone()]).is_some());

        let proper = op(
            GovernanceOpKind::Supersede {
                new_rule: rule(2),
                old_rules: vec![rule(1)],
                rationale: String::new(),
            },
            1001,
            "human:alex",
        );
        assert!(first_unattended_act(&[assert, proper]).is_none());
    }

    #[test]
    fn replay_round_trips_through_disk_byte_for_byte() {
        // INV-1: write → read → fold reproduces the in-memory fold, and
        // the read-back ops equal what was written.
        let dir = tempfile::tempdir().unwrap();
        let log = Oplog::<GovernanceOpKind>::new(dir.path());

        let old = rule(1);
        let new = rule(2);
        let t = tension(1);
        let assert_old = op(
            GovernanceOpKind::AssertRule {
                rule: old.clone(),
                source_doc: Some("charter.md".into()),
            },
            1000,
            "ingest",
        );
        let supersede = op(
            GovernanceOpKind::Supersede {
                new_rule: new.clone(),
                old_rules: vec![old.clone()],
                rationale: "meeting".into(),
            },
            1001,
            "human:alex",
        );
        let resolve = op(
            GovernanceOpKind::ResolveTension {
                tension: t.clone(),
                via: supersede.id.clone(),
                endpoints: Some((old.clone(), new.clone())),
                rationale: String::new(),
            },
            1002,
            "human:alex",
        );
        let dismiss = op(
            GovernanceOpKind::DismissTension {
                tension: tension(2),
                endpoints: Some((rule(3), rule(4))),
                rationale: "parking vs stays — not a conflict".into(),
            },
            1003,
            "human:alex",
        );
        let written = vec![assert_old, supersede, resolve, dismiss];
        for o in &written {
            log.append(o).unwrap();
        }

        let read_back = log.read_all().unwrap();
        assert_eq!(read_back, written, "ops must survive a disk round-trip");
        assert_eq!(
            log.derive().unwrap(),
            derive_active(&written),
            "fold over disk == fold over memory"
        );
    }

    #[test]
    fn read_skips_future_version_lines() {
        // Forward-compat: a line declaring a newer `v` is skipped, not
        // misinterpreted (schema-back-compat rule).
        let dir = tempfile::tempdir().unwrap();
        let log = Oplog::<GovernanceOpKind>::new(dir.path());
        let good = op(
            GovernanceOpKind::AssertRule {
                rule: rule(1),
                source_doc: None,
            },
            1000,
            "ingest",
        );
        log.append(&good).unwrap();
        // Hand-write a structurally-valid line from a future version.
        let future = format!(
            r#"{{"id":"gov-future00000000","v":{},"ts_unix":1001,"actor":"human:x","op":"assert_rule","rule":"claim-9999"}}"#,
            GOVERNANCE_OPLOG_VERSION + 1
        );
        let mut f = OpenOptions::new().append(true).open(log.path()).unwrap();
        f.write_all(future.as_bytes()).unwrap();
        f.write_all(b"\n").unwrap();

        let read = log.read_all().unwrap();
        assert_eq!(read.len(), 1, "future-version line should be skipped");
        assert_eq!(read[0].id, good.id);
    }

    #[test]
    fn missing_log_folds_to_empty() {
        let dir = tempfile::tempdir().unwrap();
        let set = GovernanceOplog::new(dir.path()).derive().unwrap();
        assert!(set.rules.is_empty());
        assert!(set.tensions.is_empty());
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Governance read-model — the join that turns the atlas graph + the
//! governance oplog into a human-facing view of *current law*.
//!
//! This is the single read surface the `govern tensions`/`govern ask`
//! CLI verbs, the desktop Tensions panel, and the detector bench all
//! consume. It answers three questions for a governance corpus:
//!   - which rules are currently in force (and which were superseded /
//!     retracted, for history)?
//!   - which surfaced tensions are still open (ranked for a meeting
//!     agenda), and which were adjudicated (resolved / accepted)?
//!   - what doesn't line up (glass-box data-integrity findings)?
//!
//! Division of labour (see [`super::governance`]): the atlas graph
//! supplies rule *content* (Claim atoms) and the *surfaced* tensions
//! (`EdgeType::Tension` edges); the oplog supplies *decisions*
//! ([`super::governance::derive_active`]). This module joins them.
//!
//! The view core ([`build_view`]) is pure and depends only on minimal
//! projections ([`RuleAtom`], [`RuleTension`]) — not on the full atlas
//! atom schema — so the read-model logic stays testable without the
//! atom graph. The [`GovernanceView::from_atlas_dir`] adapter is the
//! only part coupled to `atoms.json` / `edges.json`, and it reuses the
//! canonical [`AtomsFile`] / [`EdgesFile`] shapes.
//!
//! Glass-box principle (ARCH): the view never silently drops a broken
//! reference. A rule the log governs but no atom backs, a tension whose
//! endpoint is missing, an adjudication of a tension no edge surfaces,
//! an adjudication authored unattended — each is reported as a
//! [`GovernanceIssue`] the operator can see and fix.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::path::Path;

use serde::{Deserialize, Serialize};

use super::governance::{
    derive_active, ActiveSet, GovernanceOp, GovernanceOpKind, GovernanceOplog, OpId, PairKey,
    RuleStatus, TensionStatus,
};
use crate::enrichment::atlas::atoms::{AtomEnvelope, AtomId, AtomsFile, ChunkRef, Claim};
use crate::enrichment::atlas::edges::{Edge, EdgeId, EdgeType, EdgesFile};
use crate::error::{Error, Result};

// ── Inputs: minimal projections of the atlas graph ───────────

/// A governed rule's content, projected from a Claim atom. The read
/// model depends on this shape, not on `Claim`, so view logic is
/// decoupled from atom-graph internals.
#[derive(Debug, Clone, PartialEq)]
pub struct RuleAtom {
    pub id: AtomId,
    /// The normative statement (Claim `content`).
    pub text: String,
    /// Deontic force — `requires` | `forbids` | `permits` — carried on
    /// the Claim's `claim_kind`. `None` until the recipe ontology and
    /// extraction populate it.
    pub deontic: Option<String>,
    /// The scope-entity the rule attaches to (Claim `attributed_to`).
    /// Two rules sharing a scope-entity are what atlas Phase-6 pairs for
    /// tension, so this is the load-bearing modeling field.
    pub scope: Option<AtomId>,
    /// First evidence chunk — the rule's source citation.
    pub citation: Option<ChunkRef>,
}

/// A surfaced tension, projected from an `EdgeType::Tension` edge.
#[derive(Debug, Clone, PartialEq)]
pub struct RuleTension {
    pub id: EdgeId,
    pub rule_a: AtomId,
    pub rule_b: AtomId,
    /// The sub-question the tension turns on (edge `sub_question`).
    pub why: Option<String>,
    /// Detector confidence in `[0,1]` — ranks the meeting agenda.
    pub confidence: f32,
}

// ── Outputs: the view ────────────────────────────────────────

/// A rule with its derived status, ready to render.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RuleView {
    pub id: AtomId,
    pub text: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub deontic: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub scope: Option<AtomId>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub citation: Option<ChunkRef>,
    pub status: RuleStatus,
}

/// Whether a surfaced tension is open or how it was adjudicated. Like
/// [`TensionStatus`] but with the `Open` arm the fold can't know on its
/// own (it needs the edge universe this view supplies).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "disposition", rename_all = "snake_case")]
pub enum TensionDisposition {
    Open,
    Resolved {
        by: OpId,
    },
    Accepted {
        by: OpId,
    },
    /// The steward judged this a detector false-positive (not a real
    /// contradiction). Distinct from [`Accepted`](Self::Accepted), which
    /// is a *real* conflict the community tolerates.
    Dismissed {
        by: OpId,
    },
    /// Not an open question because one of its rules is no longer in force
    /// (superseded or retracted). View-only — the fold can't know this
    /// without the edge's endpoints, which this join supplies. Keeps a
    /// resolved conflict closed after an atlas rebuild renumbers its edge,
    /// and keeps a fresh rule's conflict with already-dead law off the
    /// agenda.
    Moot {
        dead_endpoint: AtomId,
    },
}

/// A surfaced tension with both rule texts attached, ready to render as
/// a meeting-agenda row.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TensionView {
    pub id: EdgeId,
    pub rule_a: AtomId,
    pub text_a: String,
    pub rule_b: AtomId,
    pub text_b: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub why: Option<String>,
    pub confidence: f32,
    pub disposition: TensionDisposition,
}

/// Glass-box data-integrity finding — surfaced, never silently dropped.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "issue", rename_all = "snake_case")]
pub enum GovernanceIssue {
    /// The oplog governs a rule id with no Claim atom in `atoms.json`
    /// (a human-drafted superseding rule not yet written back, or atom
    /// drift after re-extraction).
    RuleHasNoAtom { rule: AtomId },
    /// A Tension edge references a rule atom that doesn't exist.
    TensionEndpointMissing { tension: EdgeId, endpoint: AtomId },
    /// A live adjudication maps to no current tension and can't be
    /// re-matched — genuine drift the steward should re-adjudicate.
    /// Fires only for (a) a legacy edge-id-only decision whose edge no
    /// longer surfaces, or (b) an endpoint-carrying decision one of whose
    /// rule atoms has vanished (the rule text was edited). A decision
    /// whose endpoints still exist but whose edge the detector simply
    /// didn't re-surface this rebuild is *normal weekly variance*, held in
    /// the pair map for re-match — deliberately NOT an issue.
    AdjudicatedTensionNotSurfaced { tension: EdgeId },
    /// INV-2: an adjudication was authored by a non-human actor.
    UnattendedAct { op: OpId },
}

/// The joined read-model: every governed rule with status, every
/// surfaced tension with disposition (open first, ranked by
/// confidence), and any integrity issues.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct GovernanceView {
    pub rules: Vec<RuleView>,
    pub tensions: Vec<TensionView>,
    pub issues: Vec<GovernanceIssue>,
}

impl GovernanceView {
    /// Rules currently in force.
    pub fn active_rules(&self) -> impl Iterator<Item = &RuleView> {
        self.rules
            .iter()
            .filter(|r| matches!(r.status, RuleStatus::Active))
    }

    /// Tensions still awaiting adjudication — the meeting agenda.
    pub fn open_tensions(&self) -> impl Iterator<Item = &TensionView> {
        self.tensions
            .iter()
            .filter(|t| matches!(t.disposition, TensionDisposition::Open))
    }

    /// Section ids (an atom's evidence `chunk_id` is a *section* id like
    /// `"sec_00001"`, not a chunk row id) that carry a superseded or
    /// retracted rule — the *dead-law sections* retrieval must drop so an
    /// answer is never grounded in a rule no longer in force (FR-9 RL-3,
    /// the no-dead-law red line).
    ///
    /// An amended section is treated as dead-law *wholesale*: chunk-level
    /// retrieval can't surgically excise one rule's sentence from a chunk
    /// it shares with co-located rules, so the conservative-for-RL-3 choice
    /// is to drop the amended section and rely on the *superseding* decision
    /// — which lives in its own (kept) section. Co-located un-amended
    /// provisions in the dropped section are lost with it; the precise fix
    /// is sub-chunk (atom-span) filtering. Pair with [`chunk_to_section_map`]
    /// to turn these section ids into the chunk row ids retrieval carries.
    pub fn dead_law_sections(&self) -> HashSet<String> {
        self.rules
            .iter()
            .filter(|r| {
                matches!(
                    r.status,
                    RuleStatus::Superseded { .. } | RuleStatus::Retracted { .. }
                )
            })
            .filter_map(|r| r.citation.as_ref().map(|c| c.chunk_id.clone()))
            .collect()
    }

    /// Read `atoms.json` + `edges.json` + the governance oplog from a
    /// corpus atlas dir and build the view. Missing files read as empty,
    /// so a corpus mid-setup degrades gracefully rather than erroring.
    pub fn from_atlas_dir(atlas_dir: impl AsRef<Path>) -> Result<Self> {
        let dir = atlas_dir.as_ref();
        let rules = read_rule_atoms(dir)?;
        let tensions = read_tensions(dir)?;
        let ops = GovernanceOplog::new(dir).read_all()?;
        Ok(build_view(&rules, &tensions, &ops))
    }
}

/// Why a corpus's chunk → section map came back empty.
///
/// This distinction is the whole point. Until 2026-08-05 an empty map meant
/// either "this corpus has no section structure" or "this corpus HAS section
/// structure and its join was never written", and no caller could tell which.
/// The second state went unnoticed across 1779 of 1788 local corpora for as
/// long as the field existed, because every reader treated the empty map as
/// the benign case. An absence that cannot be distinguished from a legitimate
/// zero is not reported — it is defaulted (ARCH_PRINCIPLES §18.3).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JoinStatus {
    /// The join is present. (Possibly for only some sections — see
    /// [`SectionJoinStatus::sections_with_chunks`].)
    Present,
    /// No `chapters.json`, or it could not be read/parsed. The corpus has no
    /// declared section structure; a reader should behave as before.
    NoSectionStructure,
    /// `chapters.json` declares sections and NOT ONE carries a chunk id.
    /// A fault, not a shape: the corpus knows its own headings and cannot
    /// connect any of them to retrievable text. Repair with
    /// `svrn enrich backfill-sections <corpus>`.
    JoinMissing,
}

/// The map plus why it is the size it is.
#[derive(Debug, Clone)]
pub struct SectionJoinStatus {
    pub map: HashMap<u64, String>,
    pub status: JoinStatus,
    /// Sections declared in the manifest.
    pub sections_total: usize,
    /// Sections that carry at least one chunk id. Less than `sections_total`
    /// is a PARTIAL join — legitimate (a section may hold no chunk) but worth
    /// seeing, because a sudden drop is how a re-ingest silently breaks it.
    pub sections_with_chunks: usize,
}

impl SectionJoinStatus {
    /// The one-line operator sentence, or `None` when there is nothing to
    /// say. Callers log this rather than composing their own wording, so the
    /// repair command is named identically everywhere (§10.6).
    pub fn warning(&self, corpus_hint: &str) -> Option<String> {
        match self.status {
            JoinStatus::JoinMissing => Some(format!(
                "corpus `{corpus_hint}` declares {} section(s) but NO chunk→section join — \
                 citations cannot name a section and section filters silently match nothing. \
                 Repair: `svrn enrich backfill-sections {corpus_hint}`",
                self.sections_total
            )),
            JoinStatus::Present | JoinStatus::NoSectionStructure => None,
        }
    }
}

/// `chunk row id → section id` from a corpus's `chapters.json` — the bridge
/// between what retrieval carries (LanceDB chunk row ids on `ScoredChunk`)
/// and what atoms cite (section ids like `"sec_00001"`). `index_root` is the
/// corpus index dir (the parent of `atlas/`), where `chapters.json` lives.
///
/// An empty map means "don't filter". Callers that need to know WHY it is
/// empty — and anything user-facing does — must use
/// [`chunk_to_section_map_status`] instead; this wrapper cannot tell a
/// structureless corpus from a broken join.
pub fn chunk_to_section_map(index_root: impl AsRef<Path>) -> HashMap<u64, String> {
    chunk_to_section_map_status(index_root).map
}

/// The map, plus whether an empty one is a shape or a fault.
pub fn chunk_to_section_map_status(index_root: impl AsRef<Path>) -> SectionJoinStatus {
    #[derive(serde::Deserialize)]
    struct ChaptersFile {
        #[serde(default)]
        chapters: Vec<ChapterRow>,
    }
    #[derive(serde::Deserialize)]
    struct ChapterRow {
        id: String,
        #[serde(default)]
        chunk_ids: Vec<serde_json::Value>,
    }
    let absent = |status| SectionJoinStatus {
        map: HashMap::new(),
        status,
        sections_total: 0,
        sections_with_chunks: 0,
    };
    let path = index_root.as_ref().join("chapters.json");
    let Ok(bytes) = std::fs::read(&path) else {
        return absent(JoinStatus::NoSectionStructure);
    };
    let Ok(file) = serde_json::from_slice::<ChaptersFile>(&bytes) else {
        return absent(JoinStatus::NoSectionStructure);
    };
    let sections_total = file.chapters.len();
    let mut sections_with_chunks = 0usize;
    let mut map = HashMap::new();
    for ch in file.chapters {
        let mut any = false;
        for ci in &ch.chunk_ids {
            let id = match ci {
                serde_json::Value::Number(n) => n.as_u64(),
                serde_json::Value::String(s) => s.parse::<u64>().ok(),
                _ => None,
            };
            if let Some(id) = id {
                map.insert(id, ch.id.clone());
                any = true;
            }
        }
        if any {
            sections_with_chunks += 1;
        }
    }
    // A manifest with no sections at all is a structureless corpus wearing a
    // file, not a broken join — there is nothing that COULD have been joined.
    let status = if sections_total == 0 {
        JoinStatus::NoSectionStructure
    } else if sections_with_chunks == 0 {
        JoinStatus::JoinMissing
    } else {
        JoinStatus::Present
    };
    SectionJoinStatus {
        map,
        status,
        sections_total,
        sections_with_chunks,
    }
}

/// `section id → human title` from `chapters.json` — e.g. `"sec_00007"` →
/// `"Decision — 2026-03-14 — Guest Policy Revisited"`. Lets a caller match a
/// rule's section against the titles a model cites in its answer (so e.g.
/// supersession provenance fires only for a decision the answer actually
/// relied on). Empty on a missing/unreadable manifest.
pub fn section_titles(index_root: impl AsRef<Path>) -> HashMap<String, String> {
    #[derive(serde::Deserialize)]
    struct ChaptersFile {
        #[serde(default)]
        chapters: Vec<ChapterRow>,
    }
    #[derive(serde::Deserialize)]
    struct ChapterRow {
        id: String,
        #[serde(default)]
        title: String,
    }
    let path = index_root.as_ref().join("chapters.json");
    let Ok(bytes) = std::fs::read(&path) else {
        return HashMap::new();
    };
    let Ok(file) = serde_json::from_slice::<ChaptersFile>(&bytes) else {
        return HashMap::new();
    };
    file.chapters
        .into_iter()
        .filter(|c| !c.title.is_empty())
        .map(|c| (c.id, c.title))
        .collect()
}

// ── Pure builder ─────────────────────────────────────────────

/// Map a folded [`TensionStatus`] to its view disposition.
fn disposition_from_status(s: &TensionStatus) -> TensionDisposition {
    match s {
        TensionStatus::Resolved { by } => TensionDisposition::Resolved { by: by.clone() },
        TensionStatus::Accepted { by } => TensionDisposition::Accepted { by: by.clone() },
        TensionStatus::Dismissed { by } => TensionDisposition::Dismissed { by: by.clone() },
    }
}

/// Decide how a surfaced tension stands, in four steps of decreasing
/// specificity. The order is load-bearing for *living* governance, where
/// the atlas is rebuilt weekly and every edge id is re-minted:
///
/// 1. **Edge-id match** — same build, or a legacy edge-id-only decision.
/// 2. **Endpoint-pair match** — the same two rules, adjudicated under a
///    now-stale edge id. This is what carries a decision across a rebuild.
/// 3. **Mootness** — a tension one of whose rules is superseded/retracted
///    is not a live question. Independently keeps a resolved conflict off
///    the agenda after rebuild (resolve always supersedes a rule) and
///    drops a fresh rule's conflict with already-dead law.
/// 4. **Open** — genuinely awaiting adjudication.
fn tension_disposition(
    edge: &EdgeId,
    rule_a: &AtomId,
    rule_b: &AtomId,
    active: &ActiveSet,
) -> TensionDisposition {
    if let Some(s) = active.tensions.get(edge) {
        return disposition_from_status(s);
    }
    if let Some(s) = active.tension_pairs.get(&PairKey::new(rule_a, rule_b)) {
        return disposition_from_status(s);
    }
    for endpoint in [rule_a, rule_b] {
        if matches!(
            active.rules.get(endpoint),
            Some(RuleStatus::Superseded { .. } | RuleStatus::Retracted { .. })
        ) {
            return TensionDisposition::Moot {
                dead_endpoint: endpoint.clone(),
            };
        }
    }
    TensionDisposition::Open
}

/// Join rule content + surfaced tensions + the act log into a
/// [`GovernanceView`]. Pure; the single source of read-model truth.
///
/// The governed rule set is defined by the **oplog**, not by a heuristic
/// over claim fields: a rule appears here iff some op touched its id
/// (ingest emits `AssertRule` per extracted rule-claim). Claims the log
/// never asserts are simply not governed rules and don't appear.
pub fn build_view(
    rules: &[RuleAtom],
    tensions: &[RuleTension],
    ops: &[Op<GovernanceOpKind>],
) -> GovernanceView {
    let active = derive_active(ops);
    let by_id: BTreeMap<&AtomId, &RuleAtom> = rules.iter().map(|r| (&r.id, r)).collect();

    let mut issues = Vec::new();

    // Rules: one view per oplog-governed rule, joined to its content.
    // `active.rules` is a BTreeMap, so iteration is already id-sorted.
    let mut rule_views = Vec::new();
    for (rid, status) in &active.rules {
        match by_id.get(rid) {
            Some(r) => rule_views.push(RuleView {
                id: rid.clone(),
                text: r.text.clone(),
                deontic: r.deontic.clone(),
                scope: r.scope.clone(),
                citation: r.citation.clone(),
                status: status.clone(),
            }),
            None => {
                issues.push(GovernanceIssue::RuleHasNoAtom { rule: rid.clone() });
                rule_views.push(RuleView {
                    id: rid.clone(),
                    text: String::new(),
                    deontic: None,
                    scope: None,
                    citation: None,
                    status: status.clone(),
                });
            }
        }
    }

    // Tensions: attach both rule texts and the disposition.
    let mut tension_views = Vec::new();
    let mut surfaced: BTreeSet<&EdgeId> = BTreeSet::new();
    for t in tensions {
        surfaced.insert(&t.id);
        let text_a = match by_id.get(&t.rule_a) {
            Some(r) => r.text.clone(),
            None => {
                issues.push(GovernanceIssue::TensionEndpointMissing {
                    tension: t.id.clone(),
                    endpoint: t.rule_a.clone(),
                });
                String::new()
            }
        };
        let text_b = match by_id.get(&t.rule_b) {
            Some(r) => r.text.clone(),
            None => {
                issues.push(GovernanceIssue::TensionEndpointMissing {
                    tension: t.id.clone(),
                    endpoint: t.rule_b.clone(),
                });
                String::new()
            }
        };
        let disposition = tension_disposition(&t.id, &t.rule_a, &t.rule_b, &active);
        tension_views.push(TensionView {
            id: t.id.clone(),
            rule_a: t.rule_a.clone(),
            text_a,
            rule_b: t.rule_b.clone(),
            text_b,
            why: t.why.clone(),
            confidence: t.confidence,
            disposition,
        });
    }

    // Dangling adjudications. Edge ids are re-minted on every atlas
    // rebuild, so a bare "adjudicated edge no longer surfaces" test would
    // false-positive on every past decision — the weekly-treadmill bug.
    // Instead: walk the LIVE, winning adjudication for each edge (matched
    // by `by()` == op.id, which the fold sets last-write-wins, so reverted
    // and superseded decisions are skipped) and flag only genuine drift —
    // a legacy decision with no surfaced edge, or an endpoint-carrying
    // decision whose rule atom has vanished. A valid pair simply awaiting
    // re-detection is normal variance, not an issue.
    for op in ops {
        let (edge, endpoints) = match &op.kind {
            GovernanceOpKind::ResolveTension {
                tension, endpoints, ..
            }
            | GovernanceOpKind::DismissTension {
                tension, endpoints, ..
            }
            | GovernanceOpKind::AcceptTension {
                tension, endpoints, ..
            } => (tension, endpoints),
            _ => continue,
        };
        // Only the live, winning adjudication for this edge counts.
        if active.tensions.get(edge).map(TensionStatus::by) != Some(&op.id) {
            continue;
        }
        // Matched to a currently-surfaced edge → fine.
        if surfaced.contains(edge) {
            continue;
        }
        match endpoints {
            // Pair carried: dangling only if an endpoint atom is gone.
            Some((a, b)) if by_id.contains_key(a) && by_id.contains_key(b) => {}
            // Legacy (no endpoints) unsurfaced, or a vanished endpoint atom.
            _ => issues.push(GovernanceIssue::AdjudicatedTensionNotSurfaced {
                tension: edge.clone(),
            }),
        }
    }

    // INV-2: every adjudication must be human-authored (report all).
    for op in ops {
        if !matches!(op.kind, GovernanceOpKind::AssertRule { .. })
            && !op.actor.starts_with("human:")
        {
            issues.push(GovernanceIssue::UnattendedAct { op: op.id.clone() });
        }
    }

    // Agenda order: open tensions first, then by confidence (desc),
    // then by id for a stable tie-break.
    tension_views.sort_by(|a, b| {
        let a_open = matches!(a.disposition, TensionDisposition::Open);
        let b_open = matches!(b.disposition, TensionDisposition::Open);
        b_open
            .cmp(&a_open)
            .then(b.confidence.total_cmp(&a.confidence))
            .then(a.id.as_str().cmp(b.id.as_str()))
    });

    GovernanceView {
        rules: rule_views,
        tensions: tension_views,
        issues,
    }
}

// ── IO adapter (the only atlas-schema-coupled part) ──────────

fn read_rule_atoms(dir: &Path) -> Result<Vec<RuleAtom>> {
    let path = dir.join("atoms.json");
    if !path.exists() {
        return Ok(Vec::new());
    }
    let bytes = std::fs::read(&path).map_err(Error::Io)?;
    let file: AtomsFile = serde_json::from_slice(&bytes)
        .map_err(|e| Error::Extraction(format!("governance_view: atoms.json: {e}")))?;
    Ok(file
        .atoms
        .iter()
        .filter_map(|a| match a {
            AtomEnvelope::Claim(c) => Some(project_claim(c)),
            _ => None,
        })
        .collect())
}

fn project_claim(c: &Claim) -> RuleAtom {
    RuleAtom {
        id: c.id.clone(),
        text: c.content.clone(),
        deontic: c.claim_kind.clone(),
        scope: c.attributed_to.clone(),
        citation: c.evidence.first().cloned(),
    }
}

fn read_tensions(dir: &Path) -> Result<Vec<RuleTension>> {
    let path = dir.join("edges.json");
    if !path.exists() {
        return Ok(Vec::new());
    }
    let bytes = std::fs::read(&path).map_err(Error::Io)?;
    let file: EdgesFile = serde_json::from_slice(&bytes)
        .map_err(|e| Error::Extraction(format!("governance_view: edges.json: {e}")))?;
    Ok(file
        .edges
        .iter()
        .filter(|e| e.edge_type == EdgeType::Tension)
        .map(project_tension)
        .collect())
}

fn project_tension(e: &Edge) -> RuleTension {
    RuleTension {
        id: e.id.clone(),
        rule_a: e.source.clone(),
        rule_b: e.target.clone(),
        why: e.sub_question.clone(),
        confidence: e.confidence,
    }
}

