// SPDX-License-Identifier: AGPL-3.0-or-later
//! Shard operations: the three-operation contract between corpus-engine
//! and Commonwealth.
//!
//! - `index_stats`: report chunk ID range, count, and size
//! - `extract_shard`: extract a subset of an index into a new directory
//! - `merge_shards`: merge multiple shard directories into a single index

use std::path::{Path, PathBuf};
use std::sync::Arc;

use arrow::compute::filter_record_batch;
use arrow_array::{Array, ArrayRef, BooleanArray, Int64Array, RecordBatch, StringArray};
use futures::TryStreamExt;
use lancedb::query::{ExecutableQuery, QueryBase, Select};

use crate::error::{Error, Result};
use crate::index::CorpusIndex;
use crate::types::{ChunkRange, IndexInfo, IndexStats, ShardInfo};

/// Promote a single partition directory to a canonical corpus index by
/// renaming it into place, then rewriting `_corpus_meta.json` so it no
/// longer carries partition-specific fields (`is_shard`, chunk range,
/// `processed_shards`) and is marked ingestion-complete.
///
/// Zero-copy finalisation for the "no peers ever joined" case — avoids
/// copying tens of gigabytes of chunks into a fresh LanceDB index only
/// to end up with the same content.
///
/// # The canonical directory is a shared address
///
/// `<index_dir>/<corpus_id>/` is not owned by ingest. While ingest is
/// still filling the partition, other subsystems are already writing
/// into that same directory: the SCIP reindexer (`scip_graph.db`), the
/// enrichment sink (`_enrichment_state.json`), the watched-folder
/// machinery (`_watched_folder_state.json`), the atlas builder
/// (`atlas/`), the asset cache (`assets/`). Which of them lands before
/// the promote is a race.
///
/// Refusing whenever the destination already holds a same-named entry
/// loses that race *permanently*: the Lance data stays in the
/// partition, the ingest job still emits its Complete event, retrieval
/// still finds the chunks (it enumerates directories and keys off each
/// meta's `corpus_id`), but the reading surface — which resolves
/// canonical by directory name — cannot deref a single citation.
/// Observed on a real install; see note 79fdd04c.
///
/// So promotion is **merge-tolerant per entry kind**:
///
/// | collision | resolution |
/// |---|---|
/// | `_corpus_meta.json`, `chunks.lance` | refuse — a real ambiguity about which index *is* the corpus |
/// | two plain directories | recurse, so unrelated siblings on both sides survive |
/// | two byte-identical files | drop the partition copy |
/// | two `*.jsonl` logs | union — canonical lines, then unseen partition lines |
/// | anything else (`*.lance` datasets, state files, symlinks) | newest mtime keeps the name; the loser is preserved as `<name>.superseded` |
///
/// No collision is ever resolved by deleting bytes.
///
/// Errors out (without touching either path) when:
///   - the source does not exist, does not contain `_corpus_meta.json`,
///     or is a file rather than a directory;
///   - the output already holds its own `_corpus_meta.json` — that is a
///     finalized corpus, and the caller should use the full
///     `merge_shards` path to fold into it.
///
/// The rename falls back to copy-then-remove when source and output are
/// on different filesystems (common when `index_dir` is a bind mount).
///
/// `merge_shards` routes its single-shard fast path through here, and
/// `merge_partitions_into_canonical` routes through *that*, so every
/// promotion path in the system inherits this behaviour.
pub fn promote_single_shard(source: &Path, output: &Path) -> Result<()> {
    if !source.is_dir() {
        return Err(Error::NoShardsFound(format!(
            "promote_single_shard: source {} is not a directory",
            source.display()
        )));
    }
    let source_meta = source.join("_corpus_meta.json");
    if !source_meta.exists() {
        return Err(Error::NoShardsFound(format!(
            "promote_single_shard: {} has no _corpus_meta.json",
            source.display()
        )));
    }
    // The "canonical Lance is already finalized" marker is
    // `_corpus_meta.json`, not directory existence: the SCIP
    // reindexer co-locates `<corpus>/scip_graph.db` and creates the
    // parent dir long before Lance ingest runs. Refusing on bare
    // directory existence used to strand every Lance promote behind
    // a healthy SCIP sidecar.
    if output.join("_corpus_meta.json").exists() {
        return Err(Error::Database(format!(
            "promote_single_shard: refusing to overwrite existing canonical at {}",
            output.display()
        )));
    }

    if let Some(parent) = output.parent() {
        std::fs::create_dir_all(parent)?;
    }
    if !output.exists() {
        // Fast path: same-filesystem atomic rename. Fall back to a
        // recursive copy on EXDEV-style failures.
        if let Err(e) = std::fs::rename(source, output) {
            tracing::warn!(
                source = %source.display(),
                output = %output.display(),
                error = %e,
                "promote_single_shard: atomic rename failed, falling back to copy"
            );
            copy_dir_recursive(source, output)?;
            std::fs::remove_dir_all(source)?;
        }
    } else {
        // Slow path: the output dir already exists and may already
        // hold entries written by the other subsystems described
        // above. Merge per entry kind rather than refusing wholesale
        // — unrelated siblings on both sides must survive, and a
        // sidecar collision must never strand the corpus.
        //
        // Scan for the refusal case FIRST. `read_dir` order is
        // arbitrary, so detecting it mid-loop would refuse only after
        // having already moved some entries — leaving the partition
        // half-drained and the canonical half-populated, a worse
        // state than either input.
        refuse_on_corpus_data_collision(source, output)?;
        let mut tally = MergeTally::default();
        merge_into_existing_dir(source, output, &mut tally)?;
        // Source dir is empty after the merge; drop it.
        std::fs::remove_dir(source).ok();
        tracing::info!(
            source = %source.display(),
            output = %output.display(),
            moved = tally.moved,
            merged_dirs = tally.merged_dirs,
            identical = tally.identical,
            unioned_lines = tally.unioned_lines,
            superseded = tally.superseded,
            "promote_single_shard: merged partition into a canonical dir that already had entries"
        );
    }

    // Rewrite meta to drop partition-specific fields and mark complete.
    let raw = std::fs::read_to_string(output.join("_corpus_meta.json"))?;
    let mut meta: serde_json::Value =
        serde_json::from_str(&raw).map_err(|e| Error::Serialization(format!("read meta: {e}")))?;
    if let Some(obj) = meta.as_object_mut() {
        obj.insert("is_shard".into(), serde_json::Value::Bool(false));
        obj.insert("chunk_range_start".into(), serde_json::Value::Null);
        obj.insert("chunk_range_end".into(), serde_json::Value::Null);
        obj.insert(
            "processed_shards".into(),
            serde_json::Value::Array(Vec::new()),
        );
        obj.insert(
            "ingestion_in_progress".into(),
            serde_json::Value::Bool(false),
        );
    }
    std::fs::write(
        output.join("_corpus_meta.json"),
        serde_json::to_string_pretty(&meta)
            .map_err(|e| Error::Serialization(format!("write meta: {e}")))?,
    )?;
    Ok(())
}

/// Entries that ARE the corpus rather than a sidecar of it. A
/// same-name collision on one of these means two candidate indexes
/// claim the same corpus, and no rule short of a human can say which
/// one is real — so promotion refuses and touches nothing.
const CORPUS_DATA_ENTRIES: [&str; 2] = ["_corpus_meta.json", "chunks.lance"];

/// Suffix for the copy that loses a same-name collision. Nothing reads
/// it back; it exists so promotion never destroys bytes and an
/// operator can diff the two afterwards.
const SUPERSEDED_SUFFIX: &str = "superseded";

/// Ceiling on how much of a colliding sidecar we will read into memory
/// to compare or union. Past it the entry degrades to the opaque
/// newest-wins rule, which needs only metadata.
const SIDECAR_INSPECT_CAP_BYTES: u64 = 32 * 1024 * 1024;

/// What a merge-tolerant promote actually did, logged as one line.
/// Promotion into a non-empty directory is exactly the situation where
/// a silent outcome is unacceptable — this is the receipt.
#[derive(Default)]
struct MergeTally {
    /// Entries with no counterpart in the destination.
    moved: usize,
    /// Directories present on both sides, merged child by child.
    merged_dirs: usize,
    /// Collisions where both copies had the same bytes.
    identical: usize,
    /// Lines appended to destination `*.jsonl` logs.
    unioned_lines: usize,
    /// Collisions resolved by mtime, loser preserved beside the winner.
    superseded: usize,
}

/// Refuse — before a single byte has moved — when both sides hold the
/// same piece of corpus data. Two `chunks.lance` under one corpus id
/// is a real ambiguity about which index *is* the corpus, and no rule
/// short of a human can settle it.
fn refuse_on_corpus_data_collision(source: &Path, output: &Path) -> Result<()> {
    for name in CORPUS_DATA_ENTRIES {
        let dest = output.join(name);
        if source.join(name).symlink_metadata().is_ok()
            && dest.symlink_metadata().is_ok()
            && !is_stale_symlink(&dest, source)
        {
            return Err(corpus_data_collision(source, output, name));
        }
    }
    Ok(())
}

/// True when a destination symlink cannot survive the promote: it
/// already dangles, or it resolves inside the partition that is about
/// to be consumed.
///
/// Such a link is not content, and treating it as content is actively
/// harmful — the mtime rule would keep the link and move the real file
/// aside, leaving the canonical index with a broken entry exactly where
/// readers expect data. Links into the partition are what a hand-repair
/// of an earlier strand leaves behind, so promotion meets them on
/// precisely the corpora that most need repairing.
fn is_stale_symlink(link: &Path, source: &Path) -> bool {
    if !link.symlink_metadata().is_ok_and(|m| m.is_symlink()) {
        return false;
    }
    match (std::fs::canonicalize(link), std::fs::canonicalize(source)) {
        // Dangles already.
        (Err(_), _) => true,
        (Ok(target), Ok(src)) => target.starts_with(src),
        (Ok(_), Err(_)) => false,
    }
}

fn corpus_data_collision(source: &Path, output: &Path, name: &str) -> Error {
    Error::Database(format!(
        "promote_single_shard: cannot merge {} into {} — both hold corpus data named \
         {name:?}. Sidecar collisions are merged, but promotion will not guess which of \
         two indexes is the corpus; remove or rename one.",
        source.display(),
        output.display(),
    ))
}

/// Move every entry of `source` into the already-populated `output`,
/// resolving name collisions per the table on `promote_single_shard`.
///
/// Recurses only into plain directories present on both sides. Symlinks
/// are opaque on purpose: following one would let a link back into
/// `source` (an operator hand-repair we have seen in the wild) turn the
/// walk into a loop, and `Path::is_dir` follows links where
/// `symlink_metadata` does not.
fn merge_into_existing_dir(source: &Path, output: &Path, tally: &mut MergeTally) -> Result<()> {
    for entry in std::fs::read_dir(source)? {
        let entry = entry?;
        let from = entry.path();
        let name = entry.file_name();
        let to = output.join(&name);

        let Ok(to_meta) = std::fs::symlink_metadata(&to) else {
            // No counterpart in the destination — the common case.
            move_entry(&from, &to, entry.file_type()?.is_dir())?;
            tally.moved += 1;
            continue;
        };
        // A destination link that dangles or points into the
        // partition is not content — drop it and let the real entry
        // take the name.
        if is_stale_symlink(&to, source) {
            std::fs::remove_file(&to)?;
            move_entry(&from, &to, entry.file_type()?.is_dir())?;
            tally.moved += 1;
            continue;
        }

        let from_meta = std::fs::symlink_metadata(&from)?;
        let name_str = name.to_string_lossy();

        // Belt-and-suspenders: the top-level pre-flight already
        // refused this case atomically. Kept so a nested occurrence
        // can never be silently resolved by the mtime rule.
        if CORPUS_DATA_ENTRIES.contains(&name_str.as_ref()) {
            return Err(corpus_data_collision(source, output, &name_str));
        }

        // A `*.lance` directory is a dataset whose manifest names the
        // files it owns. Interleaving two of them yields a dataset
        // pointing at fragments from the other — so it stays an
        // all-or-nothing unit even though it is a directory.
        let both_plain_dirs =
            from_meta.is_dir() && to_meta.is_dir() && !name_str.ends_with(".lance");
        if both_plain_dirs {
            merge_into_existing_dir(&from, &to, tally)?;
            std::fs::remove_dir(&from).ok();
            tally.merged_dirs += 1;
            continue;
        }

        if from_meta.is_file() && to_meta.is_file() {
            if files_identical(&from, &to)? {
                std::fs::remove_file(&from)?;
                tally.identical += 1;
                continue;
            }
            if name_str.ends_with(".jsonl") {
                if let Some(appended) = union_jsonl(&from, &to)? {
                    tally.unioned_lines += appended;
                    continue;
                }
            }
        }

        supersede(&from, &to, &from_meta, &to_meta, tally)?;
    }
    Ok(())
}

/// Resolve an opaque collision: the more recently written side keeps
/// the canonical name, the other is preserved beside it as
/// `<name>.superseded`.
fn supersede(
    from: &Path,
    to: &Path,
    from_meta: &std::fs::Metadata,
    to_meta: &std::fs::Metadata,
    tally: &mut MergeTally,
) -> Result<()> {
    // No usable mtime (exotic filesystem): the partition is this
    // ingest's own output, so it wins the tie.
    let partition_wins = match (from_meta.modified(), to_meta.modified()) {
        (Ok(f), Ok(t)) => f >= t,
        _ => true,
    };

    let (Some(parent), Some(name)) = (to.parent(), to.file_name()) else {
        return Err(Error::Database(format!(
            "promote_single_shard: cannot place a superseded copy beside {}",
            to.display()
        )));
    };
    let aside = unique_aside_path(parent, &name.to_string_lossy())?;

    if partition_wins {
        std::fs::rename(to, &aside)?;
        move_entry(from, to, from_meta.is_dir())?;
    } else {
        move_entry(from, &aside, from_meta.is_dir())?;
    }
    tally.superseded += 1;

    tracing::warn!(
        kept = if partition_wins { "partition" } else { "canonical" },
        canonical = %to.display(),
        preserved_as = %aside.display(),
        "promote_single_shard: name collision resolved by mtime — the losing copy was \
         preserved, not deleted"
    );
    Ok(())
}

/// First free `<name>.superseded[.N]` under `dir`. A corpus can be
/// promoted more than once over its life; each loser needs its own
/// resting place or the second promote silently overwrites the first.
fn unique_aside_path(dir: &Path, name: &str) -> Result<PathBuf> {
    let base = format!("{name}.{SUPERSEDED_SUFFIX}");
    let mut candidate = dir.join(&base);
    for n in 1..1000 {
        if candidate.symlink_metadata().is_err() {
            return Ok(candidate);
        }
        candidate = dir.join(format!("{base}.{n}"));
    }
    Err(Error::Database(format!(
        "promote_single_shard: {} already has 1000 superseded copies of {name}",
        dir.display()
    )))
}

/// Byte-compare two regular files. Capped: a collision between two
/// large sidecars degrades to "different" rather than reading both
/// into memory.
fn files_identical(a: &Path, b: &Path) -> Result<bool> {
    let (len_a, len_b) = (a.metadata()?.len(), b.metadata()?.len());
    if len_a != len_b || len_a > SIDECAR_INSPECT_CAP_BYTES {
        return Ok(false);
    }
    Ok(std::fs::read(a)? == std::fs::read(b)?)
}

/// Union two append-only JSONL logs: the destination keeps its lines
/// and order, then gains every partition line it did not already have.
/// Consumes the source file on success.
///
/// Returns `None` — leaving both files in place for the caller to
/// resolve by mtime — when either side is not UTF-8 or is too large to
/// hold in memory.
fn union_jsonl(from: &Path, to: &Path) -> Result<Option<usize>> {
    if from.metadata()?.len() > SIDECAR_INSPECT_CAP_BYTES
        || to.metadata()?.len() > SIDECAR_INSPECT_CAP_BYTES
    {
        return Ok(None);
    }
    let (Ok(existing), Ok(incoming)) = (std::fs::read_to_string(to), std::fs::read_to_string(from))
    else {
        return Ok(None);
    };

    let seen: std::collections::HashSet<&str> = existing.lines().collect();
    let mut appended = String::new();
    let mut count = 0usize;
    for line in incoming.lines() {
        if line.trim().is_empty() || seen.contains(line) {
            continue;
        }
        appended.push_str(line);
        appended.push('\n');
        count += 1;
    }

    if !appended.is_empty() {
        let mut merged = String::with_capacity(existing.len() + appended.len() + 1);
        merged.push_str(&existing);
        if !existing.is_empty() && !existing.ends_with('\n') {
            merged.push('\n');
        }
        merged.push_str(&appended);
        std::fs::write(to, merged)?;
    }
    std::fs::remove_file(from)?;
    Ok(Some(count))
}

/// Rename `from` onto `to`, falling back to copy-then-remove across
/// filesystem boundaries.
fn move_entry(from: &Path, to: &Path, is_dir: bool) -> Result<()> {
    if let Err(e) = std::fs::rename(from, to) {
        tracing::warn!(
            from = %from.display(),
            to = %to.display(),
            error = %e,
            "promote_single_shard: per-entry rename failed, falling back to copy"
        );
        if is_dir {
            copy_dir_recursive(from, to)?;
            std::fs::remove_dir_all(from)?;
        } else {
            std::fs::copy(from, to)?;
            std::fs::remove_file(from)?;
        }
    }
    Ok(())
}

fn copy_dir_recursive(src: &Path, dst: &Path) -> Result<()> {
    std::fs::create_dir_all(dst)?;
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let src_child = entry.path();
        let dst_child = dst.join(entry.file_name());
        if entry.file_type()?.is_dir() {
            copy_dir_recursive(&src_child, &dst_child)?;
        } else {
            std::fs::copy(&src_child, &dst_child)?;
        }
    }
    Ok(())
}

/// Report chunk ID range, count, and size for an index.
pub async fn index_stats(index_path: &Path) -> Result<IndexStats> {
    let index = CorpusIndex::open(index_path).await?;
    let info = index.info().await?;

    // Query min/max IDs.
    let batches: Vec<RecordBatch> = index
        .table()
        .query()
        .select(Select::Columns(vec!["id".into()]))
        .execute()
        .await
        .map_err(|e| Error::Database(format!("stats query: {e}")))?
        .try_collect()
        .await
        .map_err(|e| Error::Database(format!("stats collect: {e}")))?;

    let mut min_id = u64::MAX;
    let mut max_id = 0u64;
    for batch in &batches {
        if let Some(ids) = batch
            .column_by_name("id")
            .and_then(|c| c.as_any().downcast_ref::<Int64Array>())
        {
            for i in 0..ids.len() {
                let id = ids.value(i) as u64;
                min_id = min_id.min(id);
                max_id = max_id.max(id);
            }
        }
    }

    if min_id == u64::MAX {
        min_id = 0;
    }

    Ok(IndexStats {
        corpus_id: info.corpus_id,
        total_chunks: info.chunk_count,
        min_chunk_id: min_id,
        max_chunk_id: max_id + 1, // exclusive
        index_size_bytes: info.index_size_bytes,
    })
}

/// Extract a subset of an existing index into a new directory.
/// Output contains only chunks with IDs in the given range.
pub async fn extract_shard(
    source_path: &Path,
    chunk_range: ChunkRange,
    output_path: &Path,
) -> Result<ShardInfo> {
    let source = CorpusIndex::open(source_path).await?;
    let source_info = source.info().await?;

    // Create the shard index.
    let shard = CorpusIndex::create(
        output_path,
        &source_info.corpus_id,
        &source_info.corpus_name,
        &source_info.embedding_model,
        source_info.embedding_dimensions,
        source_info.mesh_sharing,
        "",
    )
    .await?;

    // Mark as shard.
    shard.set_shard_meta(chunk_range)?;

    // Query chunks in range from source.
    let filter = format!(
        "id >= {} AND id < {}",
        chunk_range.start_id, chunk_range.end_id
    );
    let batches: Vec<RecordBatch> = source
        .table()
        .query()
        .only_if(filter)
        .execute()
        .await
        .map_err(|e| Error::Database(format!("shard extract query: {e}")))?
        .try_collect()
        .await
        .map_err(|e| Error::Database(format!("shard extract collect: {e}")))?;

    if !batches.is_empty() {
        shard
            .table()
            .add(batches)
            .execute()
            .await
            .map_err(|e| Error::Database(format!("shard insert: {e}")))?;
    }

    let chunk_count = shard.chunk_count().await?;
    let size_bytes = dir_size(output_path);

    Ok(ShardInfo {
        path: output_path.to_path_buf(),
        chunk_range,
        chunk_count,
        size_bytes,
    })
}

/// Merge multiple shard directories into a single index.
///
/// Chunks are renumbered to form a contiguous ID space. Duplicate chunks
/// are dropped by a two-key lookup:
///
/// 1. **`content_hash`** (primary) — handles legacy in-flight overlap
///    (same file appears in two shards after coordinator/peer reassignment)
///    AND pull-based lease-expiry overlap (two peers process the same
///    `unit_id` → identical chunking → identical content_hashes).
/// 2. **`unit_id`** (secondary, pull-based only) — when a chunk's
///    `content_hash` is NULL (shouldn't happen under the ingest pipeline
///    but defensive), the `(unit_id, source_doc_id)` pair catches
///    duplicates that content_hash dedup would miss.
///
/// Chunks with both keys NULL are always included (conservative: cannot
/// deduplicate without any signal).
pub async fn merge_shards(shard_paths: &[PathBuf], output_path: &Path) -> Result<IndexInfo> {
    if shard_paths.is_empty() {
        return Err(Error::NoShardsFound("no shard paths provided".into()));
    }

    // Single-shard fast path: when the coordinator (or a solo install)
    // has only one input to "merge", copying every chunk into a fresh
    // LanceDB index is pure waste — that's tens of gigabytes of I/O for
    // Wikipedia. Atomic-rename the shard directory into place instead
    // and rewrite `_corpus_meta.json` to shed its is_shard/partition
    // metadata. The fast path refuses when the output path already
    // holds data so we never clobber a prior canonical index; callers
    // that actually do want to fold a partition into an existing
    // canonical fall through to the full merge below (which dedupes
    // via `content_hash`).
    if shard_paths.len() == 1 {
        let source = &shard_paths[0];
        let output_has_data = output_path.join("_corpus_meta.json").exists();
        if !output_has_data && source != output_path {
            promote_single_shard(source, output_path)?;
            return CorpusIndex::open(output_path).await?.info().await;
        }
    }

    // Read metadata from first shard.
    let first = CorpusIndex::open(&shard_paths[0]).await?;
    let first_info = first.info().await?;
    drop(first);

    // Validate that all shards share the same embedding model and
    // dimensions. A genuine mismatch would silently produce a merged
    // index where vectors from different embedding spaces are
    // compared directly — nonsense results. We must reject those.
    //
    // BUT: an empty `embedding_model` string ("") is treated as a
    // wildcard, not as a mismatch. Observed in the wild on
    // peer-pulled partition meta where the peer-pull copy path
    // failed to stamp the model name — the chunks themselves are
    // valid (the peer's actual embed function produced them) but
    // the meta wasn't carried over. Treating "" as compatible with
    // any non-empty value lets recovery merges proceed instead of
    // dead-ending an otherwise-fine partition; the canonical output
    // is stamped with the resolved (non-empty) model below.
    //
    // Embedding dimensions are still compared strictly — those come
    // from the actual vector schema, which is impossible to fake or
    // omit, so a dim mismatch is always real.
    let mut total_input_chunks: u64 = first_info.chunk_count;
    let mut resolved_model = first_info.embedding_model.clone();
    for shard_path in shard_paths.iter().skip(1) {
        let shard = CorpusIndex::open(shard_path).await?;
        let shard_info = shard.info().await?;
        drop(shard);

        // Resolve embedding_model across the shards.
        match (
            resolved_model.is_empty(),
            shard_info.embedding_model.is_empty(),
        ) {
            (true, false) => {
                tracing::info!(
                    shard = %shard_path.display(),
                    resolved = %shard_info.embedding_model,
                    "merge_shards: first shard had empty embedding_model — \
                     adopting '{}' from a later shard for the canonical meta",
                    shard_info.embedding_model,
                );
                resolved_model = shard_info.embedding_model.clone();
            }
            (false, true) => {
                tracing::warn!(
                    shard = %shard_path.display(),
                    expected = %resolved_model,
                    "merge_shards: shard meta is missing embedding_model — \
                     treating as wildcard match for '{}' (typically a \
                     peer-pull copy bug; chunks are still valid)",
                    resolved_model,
                );
            }
            (true, true) => {
                // Both empty so far — keep looking.
            }
            (false, false) => {
                if shard_info.embedding_model != resolved_model {
                    return Err(Error::ShardMismatch(format!(
                        "embedding model mismatch: shard '{}' uses '{}' but resolved model is '{}'",
                        shard_path.display(),
                        shard_info.embedding_model,
                        resolved_model,
                    )));
                }
            }
        }

        if shard_info.embedding_dimensions != first_info.embedding_dimensions {
            return Err(Error::ShardMismatch(format!(
                "embedding dimensions mismatch: shard '{}' has {} dims but first shard has {}",
                shard_path.display(),
                shard_info.embedding_dimensions,
                first_info.embedding_dimensions,
            )));
        }
        total_input_chunks += shard_info.chunk_count;
    }
    if resolved_model.is_empty() {
        return Err(Error::ShardMismatch(format!(
            "every input shard has an empty embedding_model — cannot determine \
             the embedding model to stamp on the merged canonical. Input paths: {}",
            shard_paths
                .iter()
                .map(|p| p.display().to_string())
                .collect::<Vec<_>>()
                .join(", ")
        )));
    }

    tracing::info!(
        corpus_id = %first_info.corpus_id,
        shard_count = shard_paths.len(),
        total_input_chunks,
        embedding_model = %resolved_model,
        embedding_dimensions = first_info.embedding_dimensions,
        output = %output_path.display(),
        "merge_shards: starting — merging {} shard(s) into {}",
        shard_paths.len(), output_path.display(),
    );
    for (i, p) in shard_paths.iter().enumerate() {
        tracing::info!(
            shard_index = i,
            path = %p.display(),
            "merge_shards: shard {}/{}", i + 1, shard_paths.len(),
        );
    }

    // Create output index. Stamp the resolved (non-empty) embedding
    // model so the canonical's meta is authoritative even when a
    // peer-pulled input had blank meta.
    let merged = CorpusIndex::create(
        output_path,
        &first_info.corpus_id,
        &first_info.corpus_name,
        &resolved_model,
        first_info.embedding_dimensions,
        first_info.mesh_sharing,
        "",
    )
    .await?;

    // Propagate the mutable-merge policy from the first shard onto the
    // merged canonical so subsequent merges of this canonical against
    // newer partitions take the same dedupe branch. `None` is the
    // classic content-hash dedupe; the alignment recipe sets
    // `SourceDocIdNewestMtime`.
    if let Some(policy) = first_info.mutable_merge {
        merged.set_mutable_merge(Some(policy))?;
    }

    let dim = first_info.embedding_dimensions;

    // Mutable-merge branch (alignment-style corpora). Reconciles
    // divergent rows for the same `source_doc_id` by keeping the
    // newest `mtime` across all input shards, then renumbers.
    if matches!(
        first_info.mutable_merge,
        Some(crate::recipe::MutableMergePolicy::SourceDocIdNewestMtime)
    ) {
        let dedup_count =
            merge_shards_source_doc_id_newest_mtime(&merged, shard_paths, dim, output_path).await?;
        let result = merged.info().await?;
        tracing::info!(
            corpus_id = %result.corpus_id,
            chunks_merged = result.chunk_count,
            chunks_deduped = dedup_count,
            output = %output_path.display(),
            "merge_shards: complete (mutable/source_doc_id_newest_mtime) — \
             {} chunks written ({} input, {} deduped)",
            result.chunk_count, total_input_chunks, dedup_count,
        );
        return Ok(result);
    }

    let mut next_id: i64 = 1;
    // Track seen content_hashes (primary key) and (unit_id, source_doc_id)
    // pairs (secondary key for rows with NULL content_hash).
    let mut seen_hashes: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut seen_units: std::collections::HashSet<(i32, String)> = std::collections::HashSet::new();
    let mut dedup_count: u64 = 0;

    for shard_path in shard_paths {
        let shard = CorpusIndex::open(shard_path).await?;

        let batches: Vec<RecordBatch> = shard
            .table()
            .query()
            .execute()
            .await
            .map_err(|e| Error::Database(format!("shard read: {e}")))?
            .try_collect()
            .await
            .map_err(|e| Error::Database(format!("shard collect: {e}")))?;

        for batch in &batches {
            let num_rows = batch.num_rows();
            if num_rows == 0 {
                continue;
            }

            // ── Two-key deduplication ─────────────────────────────────
            // Primary: content_hash. Secondary: (unit_id, source_doc_id)
            // for rows with NULL content_hash (defensive fallback; under
            // the pull-based queue path every chunk has a populated hash).
            // Build a boolean keep-mask: true for rows whose primary OR
            // secondary key has not been seen in any earlier shard.
            let hash_col = batch
                .column_by_name("content_hash")
                .and_then(|c| c.as_any().downcast_ref::<StringArray>());
            let unit_id_col = batch
                .column_by_name("unit_id")
                .and_then(|c| c.as_any().downcast_ref::<arrow_array::Int32Array>());
            let source_doc_col = batch
                .column_by_name("source_doc_id")
                .and_then(|c| c.as_any().downcast_ref::<StringArray>());

            let keep_mask: BooleanArray = (0..num_rows)
                .map(|row| {
                    // Primary key: content_hash.
                    if let Some(col) = hash_col {
                        if !col.is_null(row) {
                            let h = col.value(row);
                            if seen_hashes.contains(h) {
                                dedup_count += 1;
                                return false;
                            }
                            seen_hashes.insert(h.to_string());
                            return true;
                        }
                    }
                    // Secondary key: (unit_id, source_doc_id) when both exist.
                    if let (Some(u_col), Some(d_col)) = (unit_id_col, source_doc_col) {
                        if !u_col.is_null(row) && !d_col.is_null(row) {
                            let key = (u_col.value(row), d_col.value(row).to_string());
                            if seen_units.contains(&key) {
                                dedup_count += 1;
                                return false;
                            }
                            seen_units.insert(key);
                            return true;
                        }
                    }
                    // Neither key available — include (cannot deduplicate).
                    true
                })
                .collect();

            // Filter the batch to kept rows.
            let filtered = filter_record_batch(batch, &keep_mask)
                .map_err(|e| Error::Serialization(format!("dedup filter: {e}")))?;

            let keep_count = filtered.num_rows();
            if keep_count == 0 {
                continue;
            }

            // Renumber IDs for kept rows only.
            let new_ids: Vec<i64> = (0..keep_count).map(|i| next_id + i as i64).collect();
            next_id += keep_count as i64;

            // Rebuild batch with new IDs and filtered rows.
            // Column order must match corpus_schema() exactly.
            let schema = crate::index::corpus_schema(dim);
            let null_str_col: ArrayRef =
                Arc::new(StringArray::from(vec![Option::<String>::None; keep_count]));
            let null_i32_col: ArrayRef = Arc::new(arrow_array::Int32Array::from(vec![
                    Option::<i32>::None;
                    keep_count
                ]));
            let null_i64_col: ArrayRef =
                Arc::new(Int64Array::from(vec![Option::<i64>::None; keep_count]));
            let col_or_null_str = |name: &str| {
                filtered
                    .column_by_name(name)
                    .cloned()
                    .unwrap_or_else(|| null_str_col.clone())
            };
            let col_or_null_i32 = |name: &str| {
                filtered
                    .column_by_name(name)
                    .cloned()
                    .unwrap_or_else(|| null_i32_col.clone())
            };
            let col_or_null_i64 = |name: &str| {
                filtered
                    .column_by_name(name)
                    .cloned()
                    .unwrap_or_else(|| null_i64_col.clone())
            };

            let new_batch = RecordBatch::try_new(
                schema.clone(),
                vec![
                    Arc::new(Int64Array::from(new_ids)),
                    filtered.column_by_name("content").unwrap().clone(),
                    filtered.column_by_name("title").unwrap().clone(),
                    filtered.column_by_name("url").unwrap().clone(),
                    filtered.column_by_name("embedding").unwrap().clone(),
                    filtered.column_by_name("metadata").unwrap().clone(),
                    col_or_null_str("content_hash"),
                    col_or_null_str("source_doc_id"),
                    col_or_null_str("symbol_name"),
                    col_or_null_str("symbol_kind"),
                    col_or_null_str("file_path"),
                    col_or_null_i32("line_start"),
                    col_or_null_i32("line_end"),
                    col_or_null_str("language"),
                    col_or_null_i64("mtime"),
                    // Preserve unit_id through merge so downstream tooling
                    // can attribute each chunk to the pull-queue unit that
                    // produced it. Legacy shards without the column get a
                    // NULL-filled replacement via col_or_null_i32.
                    col_or_null_i32("unit_id"),
                ],
            )
            .map_err(|e| Error::Serialization(format!("merge batch: {e}")))?;

            merged
                .table()
                .add(vec![new_batch])
                .execute()
                .await
                .map_err(|e| Error::Database(format!("merge insert: {e}")))?;
        }
    }

    if dedup_count > 0 {
        tracing::info!(
            dedup_count,
            output = %output_path.display(),
            "merge_shards: deduplication dropped {} duplicate chunks", dedup_count,
        );
    }

    let result = merged.info().await?;
    tracing::info!(
        corpus_id = %result.corpus_id,
        chunks_merged = result.chunk_count,
        chunks_deduped = dedup_count,
        output = %output_path.display(),
        "merge_shards: complete — {} chunks written ({} input, {} deduped)",
        result.chunk_count, total_input_chunks, dedup_count,
    );
    Ok(result)
}

/// Mutable-merge dedupe used by `alignment` and any future corpus
/// whose `_corpus_meta.json` carries
/// `mutable_merge = "source_doc_id_newest_mtime"`. Two-pass:
///
///   - Pass 1 walks every shard and records, per `source_doc_id`,
///     the `(shard_idx, batch_idx, row_idx)` of the row with the
///     highest `mtime`. Ties prefer the earliest shard (stable).
///   - Pass 2 walks the shards again and emits exactly the winning
///     rows into the merged canonical, renumbering ids contiguously.
///
/// Rows whose `source_doc_id` is null fall back to content-hash
/// dedupe so a stray non-alignment shard never silently doubles up.
/// The function returns the dedup count for logging.
async fn merge_shards_source_doc_id_newest_mtime(
    merged: &CorpusIndex,
    shard_paths: &[PathBuf],
    embedding_dim: usize,
    output_path: &Path,
) -> Result<u64> {
    use std::collections::{HashMap, HashSet};

    #[derive(Clone, Copy)]
    struct WinnerKey {
        shard_idx: usize,
        batch_idx: usize,
        row_idx: usize,
        mtime: i64,
    }

    // Read every shard once into memory. Alignment corpora are small
    // (markdown files + notes JSON) so this is bounded; the API
    // doesn't promise mutable-merge for huge corpora.
    let mut all_batches: Vec<Vec<RecordBatch>> = Vec::with_capacity(shard_paths.len());
    for shard_path in shard_paths {
        let shard = CorpusIndex::open(shard_path).await?;
        let batches: Vec<RecordBatch> = shard
            .table()
            .query()
            .execute()
            .await
            .map_err(|e| Error::Database(format!("mutable shard read: {e}")))?
            .try_collect()
            .await
            .map_err(|e| Error::Database(format!("mutable shard collect: {e}")))?;
        drop(shard);
        all_batches.push(batches);
    }

    // Pass 1 — find per-source_doc_id winners and collect the
    // null-source_doc_id rows under content-hash dedupe.
    let mut winners: HashMap<String, WinnerKey> = HashMap::new();
    let mut seen_hashes: HashSet<String> = HashSet::new();
    // Null-source_doc_id rows are addressed by their (shard, batch, row)
    // triple in pass 2; populate this set with the triples that should
    // be kept.
    let mut keep_null_docid: HashSet<(usize, usize, usize)> = HashSet::new();
    let mut dedup_count: u64 = 0;

    for (shard_idx, batches) in all_batches.iter().enumerate() {
        for (batch_idx, batch) in batches.iter().enumerate() {
            let source_doc_col = batch
                .column_by_name("source_doc_id")
                .and_then(|c| c.as_any().downcast_ref::<StringArray>());
            let mtime_col = batch
                .column_by_name("mtime")
                .and_then(|c| c.as_any().downcast_ref::<Int64Array>());
            let hash_col = batch
                .column_by_name("content_hash")
                .and_then(|c| c.as_any().downcast_ref::<StringArray>());

            for row_idx in 0..batch.num_rows() {
                let doc_id_opt = source_doc_col.and_then(|c| {
                    if c.is_null(row_idx) {
                        None
                    } else {
                        Some(c.value(row_idx).to_string())
                    }
                });

                if let Some(doc_id) = doc_id_opt {
                    let row_mtime = mtime_col
                        .and_then(|c| {
                            if c.is_null(row_idx) {
                                None
                            } else {
                                Some(c.value(row_idx))
                            }
                        })
                        .unwrap_or(0);
                    let candidate = WinnerKey {
                        shard_idx,
                        batch_idx,
                        row_idx,
                        mtime: row_mtime,
                    };
                    match winners.get(&doc_id) {
                        Some(existing) if existing.mtime >= row_mtime => {
                            dedup_count += 1;
                        }
                        Some(_) => {
                            winners.insert(doc_id, candidate);
                            dedup_count += 1;
                        }
                        None => {
                            winners.insert(doc_id, candidate);
                        }
                    }
                } else if let Some(col) = hash_col {
                    if col.is_null(row_idx) {
                        // Neither key — keep (cannot dedupe) for parity
                        // with the classic branch.
                        keep_null_docid.insert((shard_idx, batch_idx, row_idx));
                    } else {
                        let h = col.value(row_idx);
                        if seen_hashes.contains(h) {
                            dedup_count += 1;
                        } else {
                            seen_hashes.insert(h.to_string());
                            keep_null_docid.insert((shard_idx, batch_idx, row_idx));
                        }
                    }
                } else {
                    keep_null_docid.insert((shard_idx, batch_idx, row_idx));
                }
            }
        }
    }

    // Build the inverse index: (shard, batch, row) → "is winner" for
    // O(1) keep_mask construction in pass 2.
    let mut winning_triples: HashSet<(usize, usize, usize)> = HashSet::new();
    for w in winners.values() {
        winning_triples.insert((w.shard_idx, w.batch_idx, w.row_idx));
    }
    for triple in &keep_null_docid {
        winning_triples.insert(*triple);
    }

    // Pass 2 — emit winners with renumbered ids. Reuses the same
    // column-or-null fallback shape as the classic branch so legacy
    // shards without code-intel columns merge cleanly.
    let schema = crate::index::corpus_schema(embedding_dim);
    let mut next_id: i64 = 1;

    for (shard_idx, batches) in all_batches.iter().enumerate() {
        for (batch_idx, batch) in batches.iter().enumerate() {
            let num_rows = batch.num_rows();
            if num_rows == 0 {
                continue;
            }
            let keep_mask: BooleanArray = (0..num_rows)
                .map(|row_idx| winning_triples.contains(&(shard_idx, batch_idx, row_idx)))
                .collect();
            let filtered = filter_record_batch(batch, &keep_mask)
                .map_err(|e| Error::Serialization(format!("mutable dedup filter: {e}")))?;
            let keep_count = filtered.num_rows();
            if keep_count == 0 {
                continue;
            }
            let new_ids: Vec<i64> = (0..keep_count).map(|i| next_id + i as i64).collect();
            next_id += keep_count as i64;

            let null_str_col: ArrayRef =
                Arc::new(StringArray::from(vec![Option::<String>::None; keep_count]));
            let null_i32_col: ArrayRef = Arc::new(arrow_array::Int32Array::from(vec![
                    Option::<i32>::None;
                    keep_count
                ]));
            let null_i64_col: ArrayRef =
                Arc::new(Int64Array::from(vec![Option::<i64>::None; keep_count]));
            let col_or_null_str = |name: &str| {
                filtered
                    .column_by_name(name)
                    .cloned()
                    .unwrap_or_else(|| null_str_col.clone())
            };
            let col_or_null_i32 = |name: &str| {
                filtered
                    .column_by_name(name)
                    .cloned()
                    .unwrap_or_else(|| null_i32_col.clone())
            };
            let col_or_null_i64 = |name: &str| {
                filtered
                    .column_by_name(name)
                    .cloned()
                    .unwrap_or_else(|| null_i64_col.clone())
            };

            let new_batch = RecordBatch::try_new(
                schema.clone(),
                vec![
                    Arc::new(Int64Array::from(new_ids)),
                    filtered.column_by_name("content").unwrap().clone(),
                    filtered.column_by_name("title").unwrap().clone(),
                    filtered.column_by_name("url").unwrap().clone(),
                    filtered.column_by_name("embedding").unwrap().clone(),
                    filtered.column_by_name("metadata").unwrap().clone(),
                    col_or_null_str("content_hash"),
                    col_or_null_str("source_doc_id"),
                    col_or_null_str("symbol_name"),
                    col_or_null_str("symbol_kind"),
                    col_or_null_str("file_path"),
                    col_or_null_i32("line_start"),
                    col_or_null_i32("line_end"),
                    col_or_null_str("language"),
                    col_or_null_i64("mtime"),
                    col_or_null_i32("unit_id"),
                ],
            )
            .map_err(|e| Error::Serialization(format!("mutable merge batch: {e}")))?;

            merged
                .table()
                .add(vec![new_batch])
                .execute()
                .await
                .map_err(|e| Error::Database(format!("mutable merge insert: {e}")))?;
        }
    }

    if dedup_count > 0 {
        tracing::info!(
            dedup_count,
            output = %output_path.display(),
            "merge_shards (mutable): kept newest-mtime per source_doc_id; dropped {} older row(s)",
            dedup_count,
        );
    }

    Ok(dedup_count)
}

/// Phase signals emitted by `merge_partitions_into_canonical` for
/// callers that want to render progress (CLI status lines, daemon
/// tracing, future progress streams to the UI).
#[derive(Debug, Clone)]
pub enum MergePhaseProgress {
    /// Discovery + preflight finished. `partition_count` is the
    /// number of `<corpus>-partition-*/` dirs that will be merged.
    DiscoveryComplete { partition_count: usize },
    /// Chunk merge phase finished (the `merge_shards` call). Reports
    /// the deduplication that happened during merge.
    MergeComplete {
        chunks_merged: u64,
        chunks_deduped: u64,
    },
    /// Meta-stamping phase finished (scope, processed_shards,
    /// total_shards, provenance).
    MetaStamped,
    /// Sub-phase of `build_indexes` finished — propagates the
    /// `(done, total)` pair from `build_indexes`'s callback.
    BuildSubPhase { done: u64, total: u64 },
    /// `build_indexes` finished and the canonical was marked
    /// `ingestion_complete`. Recovery is finished.
    Complete,
}

/// Result of a partition-merge recovery operation.
#[derive(Debug, Clone)]
pub struct PartitionMergeReport {
    pub partition_paths: Vec<PathBuf>,
    pub canonical_path: PathBuf,
    /// Total chunks across the input partitions before dedup.
    pub chunks_input: u64,
    /// Chunks present in the canonical after dedup + merge.
    pub chunks_merged: u64,
    /// Union of `processed_shards` across all input partitions.
    pub shard_union: std::collections::BTreeSet<usize>,
    /// Resolved `total_shards` (max across inputs, falling back to
    /// `max(union)+1` when none stamped).
    pub total_shards: Option<usize>,
    /// Resolved `embedding_model` stamped on the canonical (treats
    /// empty inputs as wildcard; see `merge_shards`).
    pub embedding_model: String,
    pub embedding_dimensions: usize,
}

/// Discover every `<corpus>-partition-*/` directory under `index_dir`,
/// merge them into the canonical `<corpus>/` index, dedup during
/// merge, stamp the canonical's metadata (scope, processed_shards,
/// total_shards, provenance), build vector + FTS indexes, and mark
/// the corpus ingestion-complete.
///
/// This is the durable recovery primitive shared by:
/// - `sovereign corpus merge-partitions <id>` (one-shot CLI rescue)
/// - The daemon's `auto_recover` loop (reactive recovery when
///   `corpus_collaborate` finds the queue drained with no canonical
///   and no live handoff blob to re-fire).
///
/// Refuses (without touching disk) when:
/// - The canonical `<corpus>/_corpus_meta.json` already exists.
///   Callers must `corpus remove` first if they really want to
///   rebuild from partitions.
/// - No `<corpus>-partition-*/` dirs exist.
/// - Embedding model genuinely conflicts (two distinct non-empty
///   values). An empty value on any input is treated as wildcard
///   (peer-pull stamp omission); see `merge_shards`.
/// - Embedding dimensions differ across any pair of partitions.
///
/// `progress` callback is fired at each phase boundary; pass `None`
/// to skip progress reporting. The callback runs synchronously on
/// this task — keep it cheap.
///
/// Returns a `PartitionMergeReport` describing what was merged.
/// Partition directories are LEFT IN PLACE; the caller decides
/// whether to delete them post-success.
pub async fn merge_partitions_into_canonical(
    index_dir: &Path,
    corpus_id: &str,
    progress: Option<Arc<dyn Fn(MergePhaseProgress) + Send + Sync>>,
) -> Result<PartitionMergeReport> {
    let canonical_path = index_dir.join(corpus_id);
    if canonical_path.join("_corpus_meta.json").exists() {
        return Err(Error::Database(format!(
            "merge_partitions_into_canonical: canonical at {} already exists — \
             refusing to clobber. Remove it first if you really want to rebuild \
             from partitions.",
            canonical_path.display(),
        )));
    }

    // Discovery: walk index_dir for <corpus>-partition-*/ dirs.
    let prefix = format!("{corpus_id}-partition-");
    let mut partition_paths: Vec<PathBuf> = Vec::new();
    let entries = std::fs::read_dir(index_dir).map_err(|e| {
        Error::Database(format!(
            "merge_partitions_into_canonical: cannot read {}: {e}",
            index_dir.display()
        ))
    })?;
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let name = entry.file_name();
        let Some(name_str) = name.to_str() else {
            continue;
        };
        if !name_str.starts_with(&prefix) {
            continue;
        }
        if !path.join("_corpus_meta.json").exists() {
            continue;
        }
        partition_paths.push(path);
    }
    partition_paths.sort();

    if partition_paths.is_empty() {
        return Err(Error::NoShardsFound(format!(
            "merge_partitions_into_canonical: no <{corpus_id}-partition-*> dirs in {}",
            index_dir.display()
        )));
    }

    // Read each partition's metadata: chunk_count, embedding_model/dim,
    // processed_shards, total_shards, scope. Used both for the
    // canonical post-merge stamp and for assembling the report.
    let mut chunks_input: u64 = 0;
    let mut shard_union: std::collections::BTreeSet<usize> = std::collections::BTreeSet::new();
    let mut total_shards_max: Option<usize> = None;
    let mut scope: Option<crate::index::ScopeMeta> = None;
    let mut embedding_model: Option<String> = None;
    let mut embedding_dimensions: Option<usize> = None;

    for path in &partition_paths {
        let idx = CorpusIndex::open(path).await?;
        let info = idx.info().await?;
        chunks_input = chunks_input.saturating_add(info.chunk_count);

        if embedding_dimensions.is_none() {
            embedding_dimensions = Some(info.embedding_dimensions);
        }
        // Resolve embedding_model: first non-empty wins; later
        // mismatches are caught by merge_shards (with the same
        // wildcard logic).
        if !info.embedding_model.is_empty() && embedding_model.is_none() {
            embedding_model = Some(info.embedding_model.clone());
        }

        for s in idx.processed_shards().unwrap_or_default() {
            shard_union.insert(s);
        }
        if let Some(s) = idx.read_scope().ok().flatten() {
            if scope.is_none() {
                scope = Some(s);
            }
        }

        // Read total_shards directly from the meta JSON since it's
        // not exposed via IndexInfo.
        let raw = std::fs::read_to_string(path.join("_corpus_meta.json")).unwrap_or_default();
        if let Ok(v) = serde_json::from_str::<serde_json::Value>(&raw) {
            if let Some(n) = v["total_shards"].as_u64() {
                let n = n as usize;
                total_shards_max = Some(total_shards_max.map_or(n, |m| m.max(n)));
            }
        }
    }

    let total_shards =
        total_shards_max.or_else(|| shard_union.iter().last().copied().map(|m| m + 1));

    if let Some(cb) = &progress {
        cb(MergePhaseProgress::DiscoveryComplete {
            partition_count: partition_paths.len(),
        });
    }

    // ── Phase 1: chunk merge + dedup ──────────────────────────────
    let merged_info = merge_shards(&partition_paths, &canonical_path).await?;
    let chunks_deduped = chunks_input.saturating_sub(merged_info.chunk_count);
    if let Some(cb) = &progress {
        cb(MergePhaseProgress::MergeComplete {
            chunks_merged: merged_info.chunk_count,
            chunks_deduped,
        });
    }

    // ── Phase 2: stamp metadata that merge_shards doesn't preserve ─
    // CorpusIndex::create() (called inside merge_shards) writes a
    // default meta with empty processed_shards, no scope, no
    // total_shards, and the engine's default provenance. Replay the
    // resolved values from inputs onto the canonical.
    let canonical = CorpusIndex::open(&canonical_path).await?;

    if let Some(scope) = scope {
        canonical.write_scope(Some(scope))?;
    }
    for shard_idx in &shard_union {
        canonical.record_processed_shard(*shard_idx)?;
    }
    if let Some(n) = total_shards {
        canonical.set_total_shards(n)?;
    }
    crate::index::set_provenance(
        &canonical_path,
        crate::index::CorpusProvenance::SelfInitiated,
    )?;
    if let Some(cb) = &progress {
        cb(MergePhaseProgress::MetaStamped);
    }

    // ── Phase 3: build search indexes (vector IVF-PQ + FTS) ───────
    let progress_for_build = progress.clone();
    let sub_phase_cb: Option<Box<dyn Fn(u64, u64) + Send + Sync>> =
        progress_for_build.map(|cb| -> Box<dyn Fn(u64, u64) + Send + Sync> {
            Box::new(move |done, total| {
                cb(MergePhaseProgress::BuildSubPhase { done, total });
            })
        });
    canonical
        .build_indexes(true, true, sub_phase_cb.as_deref())
        .await?;
    canonical.mark_indexes_built()?;
    canonical.mark_ingestion_complete()?;

    // Stamp the content fingerprint as the last write before
    // returning. Order matters: fingerprint must be written *after*
    // mark_ingestion_complete so an interrupted merge doesn't leave
    // a fingerprint advertised for an in-progress index. A peer
    // pulling against a fingerprint trusts that the chunk set is
    // stable; the ingestion-complete bit is the proxy for "stable."
    //
    // Failures are logged but non-fatal — the canonical is still
    // valid for local queries; mesh sync just falls back to chunk-
    // count-only comparisons until the next stamp succeeds.
    if let Err(e) = canonical.compute_and_stamp_fingerprint().await {
        tracing::warn!(
            corpus = corpus_id,
            error = %e,
            "merge_partitions_into_canonical: fingerprint stamping failed; \
             mesh sync will fall back to chunk-count comparisons"
        );
    }

    if let Some(cb) = &progress {
        cb(MergePhaseProgress::Complete);
    }

    Ok(PartitionMergeReport {
        partition_paths,
        canonical_path,
        chunks_input,
        chunks_merged: merged_info.chunk_count,
        shard_union,
        total_shards,
        embedding_model: merged_info.embedding_model,
        embedding_dimensions: merged_info.embedding_dimensions,
    })
}

// ---------------------------------------------------------------------------
// append_partition_to_canonical — incremental append into an existing corpus
// ---------------------------------------------------------------------------

/// Outcome of a single [`append_partition_to_canonical`] call.
#[derive(Debug, Clone)]
pub struct AppendReport {
    pub canonical_path: PathBuf,
    /// Total chunks in the canonical AFTER the append.
    pub canonical_chunks_after: u64,
    /// Number of input chunks read from `source_path`.
    pub source_chunks: u64,
    /// Number of chunks that survived dedupe and landed in canonical.
    pub chunks_inserted: u64,
    /// Number dropped because their `content_hash` already existed in
    /// canonical or earlier in this same source batch.
    pub chunks_deduped: u64,
}

/// Append every chunk from `source_path` (a per-work corpus dir
/// produced by a one-off ingest) into the canonical corpus at
/// `canonical_path`. If `canonical_path` is empty / non-existent
/// the canonical is created fresh.
///
/// Used by the catalog-driven on-demand ingest to land each fetched
/// article into a single shared corpus (e.g. `wikipedia-fetched`)
/// rather than spawning one corpus per article. Mirrors the dedupe
/// + renumber logic of [`merge_shards`] but operates on a single
/// source against an existing canonical destination.
///
/// `dedupe by content_hash`: rows with a `content_hash` already
/// present in canonical (or earlier in this source batch) are
/// dropped. Rows with NULL `content_hash` fall back to
/// `(unit_id, source_doc_id)` keying, then to "always insert".
///
/// Side effects:
///   - canonical's `_corpus_meta.json` is created on first append
///     and left intact on subsequent appends (chunk_count is
///     recomputed by the next `info()` call).
///   - FTS is NOT rebuilt here — caller is expected to do that
///     after a batch of appends to amortise the cost.
pub async fn append_partition_to_canonical(
    source_path: &Path,
    canonical_path: &Path,
    canonical_corpus_id: &str,
    canonical_corpus_name: &str,
    embedding_model: &str,
    embedding_dim: usize,
    mesh_sharing: bool,
) -> Result<AppendReport> {
    if !source_path.join("_corpus_meta.json").exists() {
        return Err(Error::NoShardsFound(format!(
            "append_partition_to_canonical: source {} has no _corpus_meta.json",
            source_path.display()
        )));
    }

    // Open or create the canonical destination. `create_or_resume`
    // tolerates both "fresh" and "already exists" — exactly what we
    // need for a corpus that grows over time across many calls.
    let (canonical, _existing_iter_pos) = CorpusIndex::create_or_resume(
        canonical_path,
        canonical_corpus_id,
        canonical_corpus_name,
        embedding_model,
        embedding_dim,
        mesh_sharing,
        "",
    )
    .await?;

    // Snapshot canonical state before the append so we can renumber
    // ids contiguously and dedupe against existing content.
    let pre_info = canonical.info().await?;
    let mut next_id: i64 = pre_info.chunk_count.saturating_add(1) as i64;

    // Pre-load existing content_hashes so we can drop dupes from the
    // source before inserting. For very large canonicals this is N
    // strings (one per chunk) — acceptable up to ~10M; if catalogs
    // get larger we'd switch to a bloom filter.
    let mut seen_hashes: std::collections::HashSet<String> = canonical
        .list_indexed_content_hashes()
        .await
        .unwrap_or_default();
    let mut seen_units: std::collections::HashSet<(i32, String)> = std::collections::HashSet::new();

    let source = CorpusIndex::open(source_path).await?;
    let source_info = source.info().await?;
    let dim = source_info.embedding_dimensions;
    if dim != embedding_dim {
        return Err(Error::Database(format!(
            "append_partition_to_canonical: source dim {} mismatches canonical dim {}",
            dim, embedding_dim
        )));
    }

    let batches: Vec<RecordBatch> = source
        .table()
        .query()
        .execute()
        .await
        .map_err(|e| Error::Database(format!("source read: {e}")))?
        .try_collect()
        .await
        .map_err(|e| Error::Database(format!("source collect: {e}")))?;

    let mut chunks_inserted: u64 = 0;
    let mut chunks_deduped: u64 = 0;

    for batch in &batches {
        let num_rows = batch.num_rows();
        if num_rows == 0 {
            continue;
        }

        let hash_col = batch
            .column_by_name("content_hash")
            .and_then(|c| c.as_any().downcast_ref::<StringArray>());
        let unit_id_col = batch
            .column_by_name("unit_id")
            .and_then(|c| c.as_any().downcast_ref::<arrow_array::Int32Array>());
        let source_doc_col = batch
            .column_by_name("source_doc_id")
            .and_then(|c| c.as_any().downcast_ref::<StringArray>());

        let keep_mask: BooleanArray = (0..num_rows)
            .map(|row| {
                if let Some(col) = hash_col {
                    if !col.is_null(row) {
                        let h = col.value(row);
                        if seen_hashes.contains(h) {
                            chunks_deduped += 1;
                            return false;
                        }
                        seen_hashes.insert(h.to_string());
                        return true;
                    }
                }
                if let (Some(u_col), Some(d_col)) = (unit_id_col, source_doc_col) {
                    if !u_col.is_null(row) && !d_col.is_null(row) {
                        let key = (u_col.value(row), d_col.value(row).to_string());
                        if seen_units.contains(&key) {
                            chunks_deduped += 1;
                            return false;
                        }
                        seen_units.insert(key);
                        return true;
                    }
                }
                true
            })
            .collect();

        let filtered = filter_record_batch(batch, &keep_mask)
            .map_err(|e| Error::Serialization(format!("dedup filter: {e}")))?;
        let keep_count = filtered.num_rows();
        if keep_count == 0 {
            continue;
        }

        let new_ids: Vec<i64> = (0..keep_count).map(|i| next_id + i as i64).collect();
        next_id += keep_count as i64;

        let schema = crate::index::corpus_schema(dim);
        let null_str_col: ArrayRef =
            Arc::new(StringArray::from(vec![Option::<String>::None; keep_count]));
        let null_i32_col: ArrayRef = Arc::new(arrow_array::Int32Array::from(vec![
                Option::<i32>::None;
                keep_count
            ]));
        let null_i64_col: ArrayRef =
            Arc::new(Int64Array::from(vec![Option::<i64>::None; keep_count]));
        let col_or_null_str = |name: &str| {
            filtered
                .column_by_name(name)
                .cloned()
                .unwrap_or_else(|| null_str_col.clone())
        };
        let col_or_null_i32 = |name: &str| {
            filtered
                .column_by_name(name)
                .cloned()
                .unwrap_or_else(|| null_i32_col.clone())
        };
        let col_or_null_i64 = |name: &str| {
            filtered
                .column_by_name(name)
                .cloned()
                .unwrap_or_else(|| null_i64_col.clone())
        };

        let new_batch = RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(Int64Array::from(new_ids)),
                filtered.column_by_name("content").unwrap().clone(),
                filtered.column_by_name("title").unwrap().clone(),
                filtered.column_by_name("url").unwrap().clone(),
                filtered.column_by_name("embedding").unwrap().clone(),
                filtered.column_by_name("metadata").unwrap().clone(),
                col_or_null_str("content_hash"),
                col_or_null_str("source_doc_id"),
                col_or_null_str("symbol_name"),
                col_or_null_str("symbol_kind"),
                col_or_null_str("file_path"),
                col_or_null_i32("line_start"),
                col_or_null_i32("line_end"),
                col_or_null_str("language"),
                col_or_null_i64("mtime"),
                col_or_null_i32("unit_id"),
            ],
        )
        .map_err(|e| Error::Serialization(format!("append batch: {e}")))?;

        canonical
            .table()
            .add(vec![new_batch])
            .execute()
            .await
            .map_err(|e| Error::Database(format!("append insert: {e}")))?;

        chunks_inserted += keep_count as u64;
    }

    let post_info = canonical.info().await?;

    Ok(AppendReport {
        canonical_path: canonical_path.to_path_buf(),
        canonical_chunks_after: post_info.chunk_count,
        source_chunks: source_info.chunk_count,
        chunks_inserted,
        chunks_deduped,
    })
}

fn dir_size(path: &Path) -> u64 {
    let mut total = 0;
    if let Ok(entries) = std::fs::read_dir(path) {
        for entry in entries.flatten() {
            let p = entry.path();
            if p.is_dir() {
                total += dir_size(&p);
            } else if let Ok(m) = p.metadata() {
                total += m.len();
            }
        }
    }
    total
}

