/// Minimal free-form CHARTER.md skeleton. Data, not program — lives
/// next to its consumer here rather than in an asset file because
/// it's a one-off with no anticipated operator-tuning. See
/// ARCH_PRINCIPLES.md §6 for when to split prose out.
const CHARTER_SKELETON: &str = r#"# Charter

<!-- Low-ceremony governance + onboarding doc. NOT auto-generated.
     DESIGN.md says what we're building; CHARTER.md says how we work
     together on it. Free-form — write honestly, not form-fill. -->

## Who we are


## How we decide


## Onboarding pointers

<!-- Where should a new teammate start? What should they read first,
     in what order? Pointers to DESIGN.md, IMPLEMENTATION_PLAN.md,
     runbooks, dashboards — whatever they'll need. -->


## Amendment log

<!-- Appended to by `svrn project amend`. -->
"#;

// ─── Amend routing ─────────────────────────────────────────────

/// Amend DESIGN.md: open in $EDITOR, diff H2 sections against the
/// curated catalog (`design.anchors` / `design.data-interfaces` /
/// `design.open-questions`), ask the matching adversarial question
/// for each changed section, and append the Q&A to
/// `## Amendment log` inside DESIGN.md itself.
///
/// Does NOT bump any lifecycle flags — DESIGN.md is iterative by
/// design (pun intended). The provenance is the log + git history.
async fn cmd_amend_design(args: &[String]) -> i32 {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        println!("svrn project amend design");
        println!();
        println!("Opens <repo>/DESIGN.md in $EDITOR. On save, section-level diff");
        println!("against the curated DESIGN catalog. For each changed section,");
        println!("asks one adversarial question. Appends the Q&A to DESIGN.md's");
        println!("`## Amendment log` section (creating it if absent).");
        return 0;
    }

    let repo_root = match find_repo_root() {
        Some(r) => r,
        None => std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
    };
    let path = crate::amend::design_md_path(&repo_root);
    let old_text = match std::fs::read_to_string(&path) {
        Ok(s) => s,
        Err(_) => {
            eprintln!("  \u{2717} No DESIGN.md at repo root ({}).", path.display());
            eprintln!("    Run `svrn project design` first.");
            return 2;
        }
    };

    // Snapshot BEFORE opening the editor so we can diff after.
    let old_signals = corpus_engine_atos::design_signals::extract(&old_text);
    let old_hash = hash_charter(&old_text);

    // Hand off to $EDITOR. `invoke_editor` returns the re-read file
    // contents on a clean exit, None if the editor failed — in
    // which case we exit without writing anything.
    let new_text = match crate::amend::invoke_editor(&path) {
        Some(s) => s,
        None => {
            eprintln!("  \u{2717} editor did not return cleanly — no amendment recorded.");
            return 1;
        }
    };
    if new_text == old_text {
        eprintln!("  \u{2026} DESIGN.md unchanged — nothing to amend.");
        return 0;
    }

    let new_signals = corpus_engine_atos::design_signals::extract(&new_text);
    let new_hash = hash_charter(&new_text);
    let changed = crate::amend::changed_design_sections(&old_signals, &new_signals);

    // Build adversarial Q&A — but only for curated sections. Non-
    // curated edits still get logged (the diff is real) but without
    // a forced question set. Keeps the catalog precise.
    let mut interlocutor = crate::amend::StdinAmendmentInterlocutor::new();
    let questions = crate::amend::questions_for(&changed);
    let mut qa: Vec<(crate::amend::AdversarialQuestion, String)> =
        Vec::with_capacity(questions.len());
    if !questions.is_empty() {
        eprintln!();
        eprintln!(
            "  {} curated section{} changed — adversarial review:",
            questions.len(),
            if questions.len() == 1 { "" } else { "s" }
        );
        for q in &questions {
            let answer = crate::amend::AmendmentInterlocutor::ask_adversarial(&mut interlocutor, q);
            qa.push((q.clone(), answer));
        }
    } else {
        eprintln!();
        eprintln!(
            "  \u{2026} DESIGN.md edited but no curated sections changed — logging the \
             diff without a Q&A (anchors/data-interfaces/open-questions untouched)."
        );
    }

    // Render the amendment-log entry and splice it into the
    // DESIGN.md we're about to persist. Newest entries at the top
    // of the log — matches the append_design_amendment_log
    // implementation and the convention in CHARTER.md's log.
    let today = today_iso();
    let entry = crate::amend::render_design_amendment_entry(&today, &qa, &old_hash, &new_hash);
    let final_md = crate::amend::append_design_amendment_log(&new_text, &entry);

    if let Err(e) = std::fs::write(&path, &final_md) {
        eprintln!("  \u{2717} could not write {}: {e}", path.display());
        return 1;
    }

    // Best-effort re-index.
    let docs_db = repo_root.join(".sovereign").join("project_docs.db");
    match corpus_engine_notes::ProjectDocsStore::open(&docs_db) {
        Ok(docs) => {
            if let Err(e) = docs.index_file(&path, &repo_root).await {
                eprintln!("    \u{26a0} project_docs index failed: {e}");
            }
        }
        Err(e) => eprintln!("    \u{26a0} could not open project_docs.db: {e}"),
    }

    eprintln!(
        "  \u{2713} DESIGN.md amended ({} section{} with Q&A; old sha=`{}` → new sha=`{}`).",
        qa.len(),
        if qa.len() == 1 { "" } else { "s" },
        &old_hash[..old_hash.len().min(12)],
        &new_hash[..new_hash.len().min(12)],
    );
    eprintln!("    Amendment log updated inline at top of the section.");
    eprintln!("    Next: re-run `svrn project plan` if DESIGN.md structure changed.");
    0
}

// ─── Charter ─────────────────────────────────────────────────
//
// Step 7 of the ATOS onboarding redesign. `cmd_charter` is the
// free-form culture/governance doc — distinct from DESIGN.md, which
// is the technical design artifact. First invocation writes a
// minimal skeleton and opens $EDITOR; subsequent runs just open
// the existing file.
//
// The existing canonical path (`.sovereign/CHARTER.md`) is
// preserved so `svrn project amend` and its drift detection
// stay wired up. (The plan's longer-term repo-root-move is a
// separate migration that affects amend + drift detection and
// hasn't landed yet.)
pub(crate) async fn cmd_charter(args: &[String]) -> i32 {
    if sovereign_cli_shared::help::wants_help(args) {
        sovereign_cli_shared::help::print(&HELP_CHARTER);
        return 0;
    }

    let mut print_only = false;
    for arg in args {
        match arg.as_str() {
            "--print" => print_only = true,
            flag if flag.starts_with("--") => {
                eprintln!("warning: unknown flag '{flag}' — ignored");
            }
            _ => {}
        }
    }

    let repo_root = match find_repo_root() {
        Some(r) => r,
        None => std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
    };

    let charter_path = crate::amend::charter_path(&repo_root);
    let sovereign_dir = match charter_path.parent() {
        Some(p) => p.to_path_buf(),
        None => {
            eprintln!(
                "  \u{2717} could not resolve .sovereign/ parent of {}",
                charter_path.display()
            );
            return 1;
        }
    };

    // Ensure .sovereign/ exists — init creates it, but cmd_charter
    // might be invoked in a repo where init was skipped. Safe/cheap.
    if let Err(e) = std::fs::create_dir_all(&sovereign_dir) {
        eprintln!(
            "  \u{2717} could not create {}: {e}",
            sovereign_dir.display()
        );
        return 1;
    }

    let created_fresh = !charter_path.exists();
    if created_fresh {
        if let Err(e) = std::fs::write(&charter_path, CHARTER_SKELETON) {
            eprintln!("  \u{2717} could not write {}: {e}", charter_path.display());
            return 1;
        }
        eprintln!(
            "  \u{2713} CHARTER.md skeleton written at {}.",
            charter_path.display()
        );
    }

    if print_only {
        let text = std::fs::read_to_string(&charter_path).unwrap_or_default();
        println!("{text}");
        return 0;
    }

    // Open in $EDITOR. `crate::amend::invoke_editor` already owns
    // the shell-escape + waitpid dance and is exactly what amend
    // uses when the user edits the charter — one code path, one
    // set of quirks.
    let _ = crate::amend::invoke_editor(&charter_path);

    // Post-edit: re-hash the file, index it, and persist the hash
    // into project.toml so amend's drift detection has a baseline.
    let charter_text = match std::fs::read_to_string(&charter_path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!(
                "  \u{2717} could not re-read {}: {e}",
                charter_path.display()
            );
            return 1;
        }
    };
    let new_hash = crate::found::hash_charter(&charter_text);

    let project_toml_path = sovereign_dir.join("project.toml");
    if let Ok(mut tf) = crate::project_toml::ProjectTomlFile::read(&project_toml_path) {
        tf.lifecycle.charter_hash = new_hash.clone();
        if let Err(e) = tf.write(&project_toml_path) {
            eprintln!("    \u{26a0} could not persist charter_hash to project.toml: {e}");
        }
    }

    // Index via ProjectDocsStore so `project_context("who we are")`
    // surfaces charter content. Best-effort — the markdown is the
    // source of truth; the index is a query accelerator.
    let docs_db = sovereign_dir.join("project_docs.db");
    match corpus_engine_notes::ProjectDocsStore::open(&docs_db) {
        Ok(docs) => {
            if let Err(e) = docs.index_file(&charter_path, &repo_root).await {
                eprintln!("    \u{26a0} project_docs index failed: {e}");
            }
        }
        Err(e) => eprintln!("    \u{26a0} could not open project_docs.db: {e}"),
    }

    eprintln!(
        "  \u{2713} charter saved ({} bytes, sha=`{}`).",
        charter_text.len(),
        &new_hash[..new_hash.len().min(12)]
    );
    if created_fresh {
        eprintln!(
            "    Next: fill in the Onboarding pointers section — new teammates read this first."
        );
    }
    0
}

// ─── sovereign project amend (M6.7) ──────────────────────────

/// Post-founding charter edit flow with adversarial review. See
/// `crate::amend` for the policy; this function owns the I/O.
///
/// Flow:
/// 1. Refuse unless founded.
/// 2. Read current CHARTER.md; check hash against `charter_hash`.
///    If drifted, ask the user to fold the drift in (y/N).
/// 3. Spawn `$EDITOR` on CHARTER.md.
/// 4. Diff → adversarial Q&A → preview → approve.
/// 5. On approve: write CHARTER.md, bump `charter_version`,
///    update `charter_hash`, persist a decision note with the full
///    Q&A so readers six weeks later can find "why".
pub(crate) async fn cmd_amend(args: &[String]) -> i32 {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        println!("svrn project amend [design|charter]");
        println!();
        println!("Edit with an adversarial review. Every amendment is logged —");
        println!("what changed, what arguments the system raised, and your");
        println!("responses.");
        println!();
        println!("  amend           (no target) — alias for `amend charter`");
        println!("  amend charter   — edit .sovereign/CHARTER.md; bumps charter_version");
        println!("  amend design    — edit DESIGN.md; appends `## Amendment log` entry");
        println!();
        println!("`amend charter` requires the project to be founded");
        println!("(`svrn project found`); `amend design` works on any repo");
        println!("with a DESIGN.md at repo root.");
        return 0;
    }

    // Subcommand routing: `amend design` goes to the DESIGN.md flow;
    // bare `amend` and `amend charter` fall through to the existing
    // CHARTER.md flow (preserved verbatim — back-compat). The charter
    // flow doesn't parse flags further so we don't rebind args here.
    if matches!(args.first().map(String::as_str), Some("design")) {
        return cmd_amend_design(&args[1..]).await;
    }

    let repo_root = match find_repo_root() {
        Some(r) => r,
        None => std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
    };
    let sovereign_dir = repo_root.join(".sovereign");
    let project_toml_path = sovereign_dir.join("project.toml");
    if !project_toml_path.exists() {
        eprintln!();
        eprintln!(
            "  sovereign project amend: no .sovereign/project.toml found.\n\
             Run `svrn project init` first, then `svrn project found`."
        );
        return 1;
    }
    let mut project_toml = match crate::project_toml::ProjectTomlFile::read(&project_toml_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("  sovereign project amend: cannot read project.toml: {e}");
            return 1;
        }
    };
    if !project_toml.lifecycle.founded {
        eprintln!();
        eprintln!(
            "  sovereign project amend: this project hasn't been founded yet.\n\
             Run `svrn project found` first — the charter it produces is \
             what `amend` edits."
        );
        return 1;
    }

    let charter_path = crate::amend::charter_path(&repo_root);
    let old_charter = match std::fs::read_to_string(&charter_path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("  sovereign project amend: cannot read CHARTER.md: {e}");
            return 1;
        }
    };

    // Drift detection.
    let disk_hash = crate::found::hash_charter(&old_charter);
    let mut interlocutor = crate::amend::StdinAmendmentInterlocutor::new();
    if disk_hash != project_toml.lifecycle.charter_hash {
        let hint = crate::amend::drift_summary(&project_toml.lifecycle.charter_hash, &old_charter);
        if !crate::amend::AmendmentInterlocutor::confirm_drift(&mut interlocutor, &hint) {
            eprintln!();
            eprintln!(
                "  Amendment cancelled. To discard the drift first:\n    git checkout -- {}\n  Then re-run `svrn project amend`.",
                charter_path.display()
            );
            return 0;
        }
    }

    // Editor.
    println!();
    println!("  Opening CHARTER.md in your editor… save and exit when done.");
    let edited_charter = match crate::amend::invoke_editor(&charter_path) {
        Some(c) => c,
        None => {
            eprintln!("  Amendment cancelled (editor did not complete).");
            return 1;
        }
    };

    let committer = git_committer_identity_for_amend(&repo_root)
        .unwrap_or_else(|| "<unknown committer>".to_string());
    let next_version = project_toml.lifecycle.charter_version.saturating_add(1);
    let date = today_iso();

    let outcome = crate::amend::run_amend(
        &old_charter,
        &edited_charter,
        next_version,
        &date,
        &committer,
        &mut interlocutor,
    );

    match outcome {
        crate::amend::AmendOutcome::NoChange => {
            println!();
            println!("  No substantive changes detected — CHARTER.md left as-is.");
            0
        }
        crate::amend::AmendOutcome::Cancelled => {
            println!();
            println!(
                "  Amendment cancelled. Your editor changes are still in {} —\n\
                 re-open and re-run when ready, OR discard with `git checkout --`.",
                charter_path.display()
            );
            0
        }
        crate::amend::AmendOutcome::Approved { new_charter, entry } => {
            if let Err(e) = std::fs::write(&charter_path, &new_charter) {
                eprintln!("  Could not write CHARTER.md: {e}");
                return 1;
            }
            project_toml.lifecycle.charter_version = entry.version;
            project_toml.lifecycle.charter_hash = entry.new_charter_hash.clone();
            if let Err(e) = project_toml.write(&project_toml_path) {
                eprintln!("  Could not update project.toml: {e}");
                return 1;
            }

            // Decision-kind note mirrors the amendment log entry so
            // `read_notes --kind decision` surfaces it without
            // parsing CHARTER.md.
            let notes_path = sovereign_dir.join("notes.db");
            if let Ok(note_store) = corpus_engine_notes::NoteStore::open(&notes_path) {
                let body = crate::amend::render_amendment_note_body(&entry);
                let session_id = format!("amend-v{}", entry.version);
                let rt = tokio::runtime::Handle::current();
                let _ = tokio::task::block_in_place(|| {
                    rt.block_on(note_store.write_note_scoped(
                        "decision",
                        &body,
                        Vec::new(),
                        Vec::new(),
                        &session_id,
                        corpus_engine_notes::NoteScope::Global,
                        None,
                    ))
                });
            }

            println!();
            println!("    \u{2713} CHARTER.md updated");
            println!(
                "    \u{2713} project.toml: charter_version={}, charter_hash={}",
                entry.version,
                &entry.new_charter_hash[..8.min(entry.new_charter_hash.len())]
            );
            println!(
                "    \u{2713} decision note written (session=amend-v{})",
                entry.version
            );
            0
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn project serve` — the lightweight MCP server for locally-indexed
//! projects (no model required), plus `scip_graph_reloader`, the 30s poller
//! that hot-swaps the SCIP call graph on disk changes. `load_merged_graph` /
//! `snapshot_graph_mtimes` stay re-exported from `super`. Split out of
//! `project_cmd` (2026-07-13); pure move. Shared plumbing via `use super::*`.

use super::*;

const HELP_SERVE: sovereign_cli_shared::help::Help = sovereign_cli_shared::help::Help {
    command: "svrn project serve",
    summary: "Start a lightweight MCP server for locally-indexed projects (no model required).",
    sections: &[
        sovereign_cli_shared::help::HelpSection::Usage(
            "svrn project serve [--port <port>] [--data-dir <dir>]\n    \
             [--sovereign-dir <dir>]",
        ),
        sovereign_cli_shared::help::HelpSection::Flags(&[
            ("--port <port>", "Listen port (default: 9741)"),
            (
                "--data-dir <dir>",
                "Index directory (default: ~/.svrnmesh/indexes)",
            ),
            (
                "--sovereign-dir <dir>",
                "Path to .sovereign/ (default: nearest ancestor with .sovereign/)",
            ),
        ]),
    ],
};

// ─── Serve ───────────────────────────────────────────────────

pub(crate) async fn cmd_serve(args: &[String]) -> i32 {
    if sovereign_cli_shared::help::wants_help(args) {
        sovereign_cli_shared::help::print(&HELP_SERVE);
        return 0;
    }

    // Check whether the daemon already owns :9741. If so, running
    // the legacy in-process server on top collides (silent bind
    // failure) and degrades the user's MCP surface. Refuse to
    // start and redirect to the daemon workflow.
    if daemon_is_running().await {
        eprintln!();
        eprintln!("  `svrn project serve` is superseded.");
        eprintln!();
        eprintln!("  The running sovereign daemon already serves MCP on :9741 and");
        eprintln!("  owns freshness (FS watcher + git HEAD poll + startup catch-up).");
        eprintln!("  There's no need to run a second server on top of it.");
        eprintln!();
        eprintln!("  To have the daemon watch this project:");
        eprintln!("    sovereign project register");
        eprintln!();
        eprintln!("  To inspect watcher state:");
        eprintln!("    sovereign project watch status");
        eprintln!();
        eprintln!("  If you really want the legacy in-process server (e.g. the daemon");
        eprintln!("  is broken and you need a fallback), stop the daemon first:");
        eprintln!("    launchctl stop com.svrnmesh.daemon   # macOS");
        eprintln!("    systemctl --user stop sovereign       # Linux");
        return 1;
    }

    let mut port: u16 = 9741;
    let mut data_dir: Option<PathBuf> = None;
    let mut sovereign_dir_arg: Option<PathBuf> = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--port" => {
                i += 1;
                if let Some(v) = args.get(i) {
                    match v.parse::<u16>() {
                        Ok(p) => port = p,
                        Err(_) => {
                            eprintln!("error: --port must be a number");
                            return 1;
                        }
                    }
                }
            }
            "--data-dir" => {
                i += 1;
                data_dir = args.get(i).map(PathBuf::from);
            }
            "--sovereign-dir" => {
                i += 1;
                sovereign_dir_arg = args.get(i).map(PathBuf::from);
            }
            _ => {}
        }
        i += 1;
    }

    let data_dir = data_dir
        .or_else(default_data_dir)
        .unwrap_or_else(|| PathBuf::from("./sovereign-indexes"));

    if !data_dir.exists() {
        eprintln!(
            "error: index directory does not exist: {}",
            data_dir.display()
        );
        eprintln!("Run `svrn project init` in at least one project first.");
        return 1;
    }

    eprintln!("  Sovereign Code Intelligence MCP Server");
    eprintln!("  {}", "─".repeat(54));

    // ── Build CorpusEngine (zero-vector, no model) ──────────────

    let embed: EmbedFn = Arc::new(|_text: &str| {
        Box::pin(async {
            Ok::<Vec<f32>, corpus_engine::Error>(vec![0.0; corpus_engine::DEFAULT_EMBED_DIM])
        })
    });
    let recipes_dir = data_dir.clone();
    let engine = Arc::new(
        CorpusEngine::new(recipes_dir, data_dir.clone(), embed)
            .with_embedding_model(&configured_embed_model_name()),
    );

    // List discovered indexes.
    match engine.installed_indexes().await {
        Ok(indexes) => {
            let code_indexes: Vec<_> = indexes
                .iter()
                // Accept any index with content — the model string is
                // informational after setup no longer locks everyone to a
                // single default.
                .filter(|i| i.chunk_count > 0)
                .collect();
            if code_indexes.is_empty() {
                eprintln!("  warning: no indexes found in {}", data_dir.display());
            } else {
                eprintln!("  Corpora:");
                for info in &code_indexes {
                    eprintln!(
                        "    \u{2713} {} ({} symbols)",
                        info.corpus_id, info.chunk_count
                    );
                }
            }
        }
        Err(e) => {
            eprintln!("  warning: could not list indexes: {e}");
        }
    }

    // ── Discover and merge SCIP graphs ──────────────────────────

    eprintln!();
    eprintln!("  Call graph:");

    let (initial_graph, _summary) = load_merged_graph(&data_dir, true).await;
    let merged_graph: sovereign_tools::ScipGraphHandle =
        Arc::new(ArcSwap::from_pointee(initial_graph));
    let health_checker = Arc::new(sovereign_tools::IndexHealthChecker::new(Arc::clone(
        &merged_graph,
    )));

    // Spawn the background reloader: every 30s, stat each scip_graph.db,
    // and if any mtime changed (or a file appeared/disappeared) rebuild the
    // merged graph and swap it in atomically. Tools grab `load_full()` per
    // query so the swap is lock-free.
    {
        let handle = Arc::clone(&merged_graph);
        let dir = data_dir.clone();
        tokio::spawn(async move {
            scip_graph_reloader(handle, dir).await;
        });
    }

    // ── Repo root + sovereign config ────────────────────────────
    //
    // Priority: nearest ancestor with .sovereign/ > git root > cwd.
    // This allows `svrn project serve` to be launched from a monorepo
    // root that is not itself a git repository.

    let cwd = std::env::current_dir()
        .ok()
        .unwrap_or_else(|| PathBuf::from("."));
    let sovereign_dir = sovereign_dir_arg
        .map(|p| if p.is_absolute() { p } else { cwd.join(p) })
        .or_else(|| find_sovereign_dir(&cwd))
        .or_else(|| find_repo_root().map(|r| r.join(".sovereign")))
        .unwrap_or_else(|| cwd.join(".sovereign"));
    let repo_root = sovereign_dir
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| cwd.clone());
    let sovereign_cfg = corpus_engine::SovereignConfig::load_or_default(&sovereign_dir);

    // ── Open result stores (SQLite, always-on) ──────────────────
    eprintln!();
    eprintln!("  Stores:");

    let test_store =
        match corpus_engine_watchers::TestResultStore::open(&data_dir.join("test_results.db")) {
            Ok(s) => {
                eprintln!("  test_results.db  ✓");
                Arc::new(s)
            }
            Err(e) => {
                eprintln!("  warning: could not open test results DB: {e}");
                Arc::new(
                    corpus_engine_watchers::TestResultStore::open(std::path::Path::new(":memory:"))
                        .expect("in-memory test store"),
                )
            }
        };

    let lint_store =
        match corpus_engine_watchers::LintResultStore::open(&data_dir.join("lint_results.db")) {
            Ok(s) => {
                eprintln!("  lint_results.db  ✓");
                Arc::new(s)
            }
            Err(e) => {
                eprintln!("  warning: could not open lint results DB: {e}");
                Arc::new(
                    corpus_engine_watchers::LintResultStore::open(std::path::Path::new(":memory:"))
                        .expect("in-memory lint store"),
                )
            }
        };

    // ── Notes store ─────────────────────────────────────────────

    let notes_db_path = sovereign_dir.join("notes.db");
    let notes_store = match corpus_engine_notes::NoteStore::open(&notes_db_path) {
        Ok(s) => {
            eprintln!("  notes.db         ✓");
            // Write a pointer file so `svrn reflect` can find this
            // database from any working directory, regardless of where the
            // user invokes it from.
            let pointer_dir = sovereign_cli_shared::dirs::sovereign_root();
            let _ = std::fs::create_dir_all(&pointer_dir);
            let _ = std::fs::write(
                pointer_dir.join("active_notes_db"),
                notes_db_path.to_string_lossy().as_bytes(),
            );
            Arc::new(s)
        }
        Err(e) => {
            eprintln!("  warning: could not open notes DB: {e}");
            Arc::new(
                corpus_engine_notes::NoteStore::open(std::path::Path::new(":memory:"))
                    .expect("in-memory notes store"),
            )
        }
    };

    // ── Feature store (ATOS charters + milestones) ─────────────
    let features_db_path = sovereign_dir.join("features.db");
    let features_store = match corpus_engine_atos::FeatureStore::open(&features_db_path) {
        Ok(s) => {
            eprintln!("  features.db      ✓");
            Arc::new(s)
        }
        Err(e) => {
            eprintln!("  warning: could not open features DB: {e}");
            Arc::new(
                corpus_engine_atos::FeatureStore::open(std::path::Path::new(":memory:"))
                    .expect("in-memory features store"),
            )
        }
    };

    // Print any open todos from previous sessions at startup.
    if let Ok(todos) = notes_store.open_todos(5).await {
        if !todos.is_empty() {
            eprintln!();
            eprintln!(
                "  {} open todo{} from previous sessions:",
                todos.len(),
                if todos.len() == 1 { "" } else { "s" }
            );
            for t in &todos {
                let preview: String = t.content.chars().take(80).collect();
                eprintln!("    [todo] {preview}");
            }
            eprintln!("  Use read_notes to retrieve full context.");
        }
    }

    // ── Project docs store ───────────────────────────────────────

    let docs_store =
        match corpus_engine_notes::ProjectDocsStore::open(&data_dir.join("project_docs.db")) {
            Ok(s) => {
                let store = Arc::new(s);
                // Index on first run without blocking serve startup.
                if store.is_empty().await.unwrap_or(true) {
                    let s2 = Arc::clone(&store);
                    let root = repo_root.clone();
                    tokio::spawn(async move {
                        let files = corpus_engine_notes::find_markdown_files(&root);
                        let mut count = 0usize;
                        for f in &files {
                            count += s2.index_file(f, &root).await.unwrap_or(0);
                        }
                        if count > 0 {
                            tracing::info!(
                                "indexed {} doc chunks from {} md files",
                                count,
                                files.len()
                            );
                        }
                    });
                }
                eprintln!("  project_docs.db  ✓");
                Some(store)
            }
            Err(e) => {
                eprintln!("  warning: could not open project docs DB: {e}");
                None
            }
        };

    // ── Build background watchers ───────────────────────────────

    // Shared run slot so lint + test cargo invocations serialize
    // instead of double-spawning on every debounced edit flush.
    let run_slot = Arc::new(tokio::sync::Semaphore::new(1));

    let test_watcher: Option<Arc<corpus_engine_watchers::TestWatcher>> =
        sovereign_cfg.test_runner.as_ref().map(|cfg| {
            let working_dir = cfg.working_dir.as_ref().map(|d| {
                let p = PathBuf::from(d);
                if p.is_absolute() {
                    p
                } else {
                    repo_root.join(p)
                }
            });
            eprintln!(
                "  test_runner      ✓  {}",
                cfg.command.chars().take(60).collect::<String>()
            );
            Arc::new(
                corpus_engine_watchers::TestWatcher::new(
                    &cfg.command,
                    working_dir,
                    cfg.timeout_secs.unwrap_or(300),
                    Arc::clone(&test_store),
                )
                .with_run_slot(Arc::clone(&run_slot)),
            )
        });

    let lint_watcher: Option<Arc<corpus_engine_watchers::LintWatcher>> =
        sovereign_cfg.lint_runner.as_ref().map(|cfg| {
            let working_dir = cfg.working_dir.as_ref().map(|d| {
                let p = PathBuf::from(d);
                if p.is_absolute() {
                    p
                } else {
                    repo_root.join(p)
                }
            });
            eprintln!(
                "  lint_runner      ✓  {}",
                cfg.command.chars().take(60).collect::<String>()
            );
            Arc::new(
                corpus_engine_watchers::LintWatcher::new(
                    &cfg.command,
                    working_dir,
                    cfg.timeout_secs.unwrap_or(120),
                    Arc::clone(&lint_store),
                )
                .with_run_slot(Arc::clone(&run_slot)),
            )
        });

    if test_watcher.is_none() && lint_watcher.is_none() {
        eprintln!(
            "  warning: no watchers configured — add [test_runner] / [lint_runner] \
             to {}",
            sovereign_dir.join("sovereign.toml").display()
        );
    }

    // Scope strings for lint/test status tools — shown to agents so they can
    // confirm the watcher covers the crates they just edited.
    let test_watched_scope: Option<String> = sovereign_cfg
        .test_runner
        .as_ref()
        .map(|c| c.command.clone());
    let lint_watched_scope: Option<String> = sovereign_cfg
        .lint_runner
        .as_ref()
        .map(|c| c.command.clone());

    // Shared flag: set to true after coordinator.start() succeeds. Tools expose
    // this as watcher_active so agents know the FS watcher is live.
    let watcher_active_flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));

    // ── Register tools ──────────────────────────────────────────

    let mut tools = sovereign_core::ToolRegistry::new();
    tools.register(Box::new(
        sovereign_tools::SymbolLookupTool::new(Arc::clone(&engine), Arc::clone(&merged_graph))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    tools.register(Box::new(sovereign_tools::CodeSearchTool::new(Arc::clone(
        &engine,
    ));
    tools.register(Box::new(sovereign_tools::RecentChangesTool::new(
        Arc::clone(&engine),
    )));
    tools.register(Box::new(
        sovereign_tools::FindCalleesTool::new(Arc::clone(&engine), Arc::clone(&merged_graph))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    tools.register(Box::new(
        sovereign_tools::FindCallersTool::new(Arc::clone(&engine), Arc::clone(&merged_graph))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    // Capability map — derived "what the codebase does" overview.
    tools.register(Box::new(sovereign_tools::CapabilityMapTool::new()));
    // Architecture observability (quality program) — report + posture.
    tools.register(Box::new(sovereign_tools::ArchReportTool::new()));
    tools.register(Box::new(sovereign_tools::ArchPostureTool::new()));

    // ── Test / lint watcher tools ───────────────────────────────

    {
        let mut tool = sovereign_tools::TestStatusTool::new(Arc::clone(&test_store))
            .with_watcher_active(Arc::clone(&watcher_active_flag));
        if let Some(scope) = test_watched_scope {
            tool = tool.with_watched_scope(scope);
        }
        tools.register(Box::new(tool));
    }
    if let Some(ref watcher) = test_watcher {
        tools.register(Box::new(sovereign_tools::RunTestsTool::new(Arc::clone(
            watcher,
        ));
    }
    tools.register(Box::new(sovereign_tools::GetRunOutputTool::new(
        Arc::clone(&test_store),
    )));

    {
        let mut tool = sovereign_tools::LintStatusTool::new(Arc::clone(&lint_store))
            .with_watcher_active(Arc::clone(&watcher_active_flag))
            .with_workspace_root(repo_root.clone());
        if let Some(scope) = lint_watched_scope {
            tool = tool.with_watched_scope(scope);
        }
        tools.register(Box::new(tool));
    }
    tools.register(Box::new(
        sovereign_tools::DriftPostureTool::new().with_workspace_root(repo_root.clone()),
    ));
    tools.register(Box::new(sovereign_tools::GetLintOutputTool::new(
        Arc::clone(&lint_store),
    )));

    // ── Agent partnership tools (notes, blast radius, project context) ──

    tools.register(Box::new(sovereign_tools::WriteNoteTool::new(Arc::clone(
        &notes_store,
    ));
    tools.register(Box::new(sovereign_tools::ReadNotesTool::new(Arc::clone(
        &notes_store,
    ))));
    tools.register(Box::new(sovereign_tools::DeleteNoteTool::new(Arc::clone(
        &notes_store,
    ))));
    // Work atlas — coordination layer for agents sharing this repo.
    // The serve path runs the GC loop and exposes the three claim
    // tools alongside the code-intel surface. Per spec §10 the
    // origin-remote MUST gate is checked at *boot*: a repo with no
    // origin still gets a serve, but every `declare_scope` call
    // fails with an actionable error rather than silently writing
    // partial state.
    let atlas_mesh_db = sovereign_dir.join("mesh.db");
    if let Some(parent) = atlas_mesh_db.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let atlas_mesh_store = Arc::new(
        commonwealth_state::MeshStore::open(&atlas_mesh_db)
            .or_else(|_| commonwealth_state::MeshStore::in_memory())
            .expect("work atlas mesh store"),
    );
    let atlas_node_id = sovereign_mesh::persist::load_or_generate_self_node_id(&data_dir);
    let atlas_store = Arc::new(sovereign_work_atlas::WorkAtlasStore::new(
        Arc::clone(&atlas_mesh_store),
        atlas_node_id,
    ));
    let atlas_cfg_path = sovereign_cli_shared::dirs::work_atlas_toml();
    let atlas_cfg = sovereign_work_atlas::WorkAtlasConfig::load_or_default(&atlas_cfg_path)
        .unwrap_or_else(|e| {
            tracing::warn!(
                error = %e,
                path = %atlas_cfg_path.display(),
                "work_atlas: failed to load config, falling back to defaults"
            );
            sovereign_work_atlas::WorkAtlasConfig::defaults()
        });
    let atlas_broadcaster: Arc<dyn sovereign_work_atlas::tools::ClaimBroadcaster> =
        Arc::new(sovereign_work_atlas::tools::NullBroadcaster);
    let (atlas_repo_root, atlas_repo_id) = match sovereign_work_atlas::resolve_repo_id(&repo_root) {
        Ok(pair) => pair,
        Err(e) => {
            tracing::warn!(
                error = %e,
                "work_atlas:repo_id_missing — declare_scope will reject calls"
            );
            (repo_root.clone(), String::new())
        }
    };
    let atlas_branch = crate::code_cmd::current_branch(&atlas_repo_root);
    tools.register(Box::new(
        sovereign_work_atlas::tools::DeclareScopeTool::new(
            Arc::clone(&atlas_store),
            atlas_cfg.clone(),
            Arc::clone(&atlas_broadcaster),
            atlas_repo_root.clone(),
            atlas_repo_id.clone(),
            atlas_branch.clone(),
        ),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::ReleaseScopeTool::new(
            Arc::clone(&atlas_store),
            Arc::clone(&atlas_broadcaster),
        ),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::WorkInFlightTool::new(Arc::clone(&atlas_store)),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::ResourceMayITool::new(Arc::clone(&atlas_store)),
    ));
    // GC loop. Holds onto the handle so dropping it aborts cleanly
    // when serve terminates.
    let _atlas_gc_handle =
        sovereign_work_atlas::gc::WorkAtlasGc::new(Arc::clone(&atlas_store), atlas_cfg.clone())
            .spawn();

    tools.register(Box::new(
        sovereign_tools::BlastRadiusTool::new(Arc::clone(&merged_graph))
            .with_project_root(repo_root.clone())
            .with_health_checker(Arc::clone(&health_checker))
            .with_atlas(Arc::clone(&atlas_store)),
    ));
    if let Some(ref ds) = docs_store {
        tools.register(Box::new(
            sovereign_tools::ProjectContextTool::new(Arc::clone(ds))
                .with_features(Arc::clone(&features_store)),
        ));
    }

    // ── ATOS feature management ─────────────────────────────────
    tools.register(Box::new(sovereign_tools::ProvisionFeatureTool::new(
        Arc::clone(&features_store),
    )));
    tools.register(Box::new(sovereign_tools::ArchiveFeatureTool::new(
        Arc::clone(&features_store),
    )));
    tools.register(Box::new(sovereign_tools::ReadNoteByIdTool::new(
        Arc::clone(&notes_store),
    )));
    tools.register(Box::new(sovereign_tools::PromoteNoteTool::new(Arc::clone(
        &notes_store,
    ))));
    // ReadNoteDigestTool runs in fallback (header-only) mode here —
    // `svrn project serve` doesn't load a model, so the Fast-slot
    // summarization path is unavailable. The banner in the fallback
    // digest makes the degraded state visible to agents. The daemon
    // binary wires inference in via `.with_inference(...)`.
    tools.register(Box::new(sovereign_tools::ReadNoteDigestTool::new(
        Arc::clone(&notes_store),
    )));
    tools.register(Box::new(sovereign_tools::RecordAtosEventTool::new(
        Arc::clone(&features_store),
    )));
    // atos_plan_emit intentionally NOT registered — see runtime
    // tools_cmd/registry.rs for rationale (markdown plan path
    // replaced structured-JSON path).
    tools.register(Box::new(sovereign_tools::WriteRedteamFindingTool::new(
        Arc::clone(&notes_store),
    )));

    // ── Session reflection (feedback loop) ─────────────────────────────
    tools.register(Box::new(sovereign_tools::SessionReflectionTool::new(
        Arc::clone(&notes_store),
    )));

    // ── Doc path checker ────────────────────────────────────────────────
    tools.register(Box::new(
        sovereign_tools::CheckDocPathsTool::new().with_project_root(repo_root.clone()),
    ));

    // ── DESIGN.md structural signals ────────────────────────────────────
    //
    // Project-scoped: bound to this repo's DESIGN.md by default, so the
    // agent can call `design_signals_extract()` with no args and get the
    // right file. Absolute paths still work — the tool resolves them
    // verbatim, bypassing project_root.
    tools.register(Box::new(
        sovereign_tools::DesignSignalsExtractTool::new().with_project_root(repo_root.clone()),
    ));

    // ── Start watcher coordinator ───────────────────────────────

    let debounce_ms = sovereign_cfg
        .test_runner
        .as_ref()
        .and_then(|c| c.debounce_ms)
        .or_else(|| {
            sovereign_cfg
                .lint_runner
                .as_ref()
                .and_then(|c| c.debounce_ms)
        })
        .unwrap_or(500);

    let mut coordinator = corpus_engine_watchers::WatcherCoordinator::new(debounce_ms);
    if let Some(ref w) = test_watcher {
        coordinator.register(Arc::clone(w) as Arc<dyn corpus_engine_watchers::BackgroundWatcher>);
    }
    if let Some(ref w) = lint_watcher {
        coordinator.register(Arc::clone(w) as Arc<dyn corpus_engine_watchers::BackgroundWatcher>);
    }
    if let Some(ref ds) = docs_store {
        let pw =
            corpus_engine_watchers::ProjectIndexWatcher::new(Arc::clone(ds), repo_root.clone());
        coordinator.register(Arc::new(pw) as Arc<dyn corpus_engine_watchers::BackgroundWatcher>);
    }

    let _coordinator_handle = if !coordinator.registered_ids().is_empty() {
        match coordinator.start(vec![repo_root.clone()]).await {
            Ok(handle) => {
                eprintln!("  Watcher started (watching {})", repo_root.display());
                watcher_active_flag.store(true, std::sync::atomic::Ordering::Release);
                Some(handle)
            }
            Err(e) => {
                eprintln!("  warning: could not start watcher: {e}");
                None
            }
        }
    } else {
        None
    };

    let tools = Arc::new(tools);
    eprintln!();
    eprintln!("  Tools: {} registered", tools.count());

    // ── Start MCP HTTP server ───────────────────────────────────

    let bind_addr = format!("127.0.0.1:{port}");
    eprintln!("  Listening on http://{bind_addr}/mcp");
    eprintln!();
    eprintln!("  {}", "─".repeat(54));
    eprintln!("  Ready. Configure Claude Code with:");
    eprintln!();
    eprintln!("    {{");
    eprintln!("      \"mcpServers\": {{");
    eprintln!("        \"sovereign\": {{");
    eprintln!("          \"type\": \"http\",");
    eprintln!("          \"url\": \"http://localhost:{port}/mcp\"");
    eprintln!("        }}");
    eprintln!("      }}");
    eprintln!("    }}");
    eprintln!();

    // Stable session ID for this server run — used by tool_call_log to group
    // calls from the same sovereign project serve invocation.
    let mcp_session_id = format!("serve-{}", uuid::Uuid::new_v4());

    // Phase 5: standalone `svrn serve` always knows its project
    // root (resolved above as `repo_root`). Pass it as the
    // FeatureRoot so `tools/list` consults
    // `.sovereign/features/*/spec.md` and only advertises the
    // spec-gated tools (`spec`, `drift`) when a spec exists. Cache
    // is process-global so repeated `tools/list` calls amortise the
    // stat against a 1-second TTL.
    let feature_root = sovereign_mesh::mcp_router::FeatureRoot::new(Some(repo_root.clone()));
    // Phase 5b: build a notifier and wire it to a SpecWatcher rooted
    // at repo_root. The watcher's on_change closure publishes to the
    // notifier; the notifier fans the JSON-RPC frame out to every
    // subscribed SSE client. Result: when the user creates
    // `.sovereign/features/foo/spec.md` (or edits ARCHITECTURE.md),
    // every connected MCP agent sees `notifications/tools/list_changed`
    // within ~100ms and refetches `tools/list` — surfacing `spec` and
    // `drift` without a restart.
    let notifier = sovereign_mesh::mcp_router::McpNotifier::new();
    let watcher_notifier = notifier.clone();
    let _spec_watcher =
        match sovereign_tools::spec_watcher::SpecWatcher::start(&repo_root, move || {
            watcher_notifier.notify_tools_list_changed()
        }) {
            Ok(w) => Some(w),
            Err(e) => {
                // Don't fail the whole serve over a non-critical watcher;
                // fall back to TTL-only cache freshness. Log so the
                // operator sees why list_changed events aren't firing.
                tracing::warn!(
                    error = %e,
                    root = %repo_root.display(),
                    "spec_watcher: failed to start; falling back to 1s TTL — \
                     spec edits will surface within a second instead of \
                     immediately"
                );
                None
            }
        };
    let app = sovereign_mesh::mcp_router::mcp_router(
        tools,
        Arc::clone(&notes_store),
        mcp_session_id,
        feature_root,
        notifier,
    );

    let listener = match tokio::net::TcpListener::bind(&bind_addr).await {
        Ok(l) => l,
        Err(e) => {
            eprintln!("error: cannot bind to {bind_addr}: {e}");
            return 1;
        }
    };

    let service = app.into_make_service_with_connect_info::<std::net::SocketAddr>();
    if let Err(e) = axum::serve(listener, service).await {
        eprintln!("error: server failed: {e}");
        return 1;
    }
    // _spec_watcher dropped here on serve exit — releases the FS
    // backend and stops the dispatch task. Made explicit by
    // shadowing in the let-binding above.
    drop(_spec_watcher);

    0
}

// ─── SCIP graph loading & hot-reload ──────────────────────────

/// Poll `data_dir` for SCIP graph file changes every 30 seconds. On any
/// change, rebuild the merged graph out-of-band and atomically swap it
/// into `handle`. Tools (FindCalleesTool, FindCallersTool) pick up the
/// new graph on their next `load_full()`.
async fn scip_graph_reloader(handle: sovereign_tools::ScipGraphHandle, data_dir: PathBuf) {
    const POLL_INTERVAL: Duration = Duration::from_secs(30);

    let mut last_seen = snapshot_graph_mtimes(&data_dir);
    tracing::debug!(
        watched = last_seen.len(),
        "scip reloader: polling scip_graph.db files every 30s"
    );

    loop {
        tokio::time::sleep(POLL_INTERVAL).await;

        let current = snapshot_graph_mtimes(&data_dir);
        if current == last_seen {
            continue;
        }

        tracing::info!(
            prev_graphs = last_seen.len(),
            current_graphs = current.len(),
            "scip reloader: change detected, rebuilding merged graph"
        );

        let (fresh, summary) = load_merged_graph(&data_dir, false).await;
        handle.store(Arc::new(fresh));
        last_seen = current;

        tracing::info!(
            graphs = summary.graphs_found,
            symbols = summary.total_symbols,
            edges = summary.total_refs,
            "scip reloader: merged graph swapped"
        );
    }
}

// ─── sovereign project found (Phase 6: retired) ─────────────
//
// Phase 6 of the CLI refactor retires the structured "founding"
// conversation. The default flow is now:
//
//   sovereign init   →   write `.sovereign/features/<id>/spec.md`
//                    →   git commit  (= approval; see approval_gate)
//                    →   work
//
// Founding is implicit — the first `init` + commit is sufficient.
// `svrn charter` remains as the explicit team-conventions
// surface for projects that want one. The legacy questionnaire
// flow (Stage 1/2 elicitation, fault-line selection, charter
// composition, approval gate) lives on under
// [`crate::found`] for `svrn project amend` and the audit's
// charter-hash check; only the user-facing entry point is gone.
//

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Build a `ToolRegistry` with enough infrastructure for agent-driven
//! `svrn tools <cmd>` invocations.
//!
//! Distilled from `project_cmd::cmd_serve` — keeps the tool
//! construction identical so both surfaces produce the same
//! `ToolDescriptor`s (important for the agent-facing manifest) but
//! drops the MCP HTTP server, the FS watcher coordinator, and the
//! long-running tokio tasks. The goal is fast startup: opening the
//! stores + constructing the tool instances takes tens of
//! milliseconds, not seconds.
//!
//! Tools whose *execute* path needs a live watcher (e.g. `lint_status`
//! without a running `svrn daemon`) still register cleanly —
//! they just report `never_run` / `stale` when called, which is
//! exactly the existing behaviour.
//!
//! Per ARCH_PRINCIPLES §3.2, this is the seam where a shared
//! registry-setup helper will eventually live. The
//! highest-divergence-risk piece — the MCP allowlist + alias map
//! — was centralised into [`sovereign_tools::mcp_surface`] in the
//! Phase 2 refactor, so the daemon's `mcp_router` and the
//! standalone `routes_mcp` server now agree on exactly the same
//! exposed surface without a manual sync.
//!
//! What remains duplicated: the tool construction calls below
//! (`tools.register(Box::new(...))` for each tool) are mirrored in
//! `project_cmd::cmd_serve`. Both paths build the same
//! `ToolRegistry` shape; if either grows new tools without the
//! other, descriptors drift. Extracting that into a shared
//! `sovereign-tools::registry_builder` is tracked as a follow-up.
//! The path-resolution helpers / SCIP loader prerequisite landed
//! with the `sovereign-cli-shared` crate split — `load_merged_graph`,
//! `find_sovereign_dir`, and `default_data_dir` now live there and
//! are imported below.

use std::path::PathBuf;
use std::sync::Arc;

use arc_swap::ArcSwap;

use corpus_engine::{CorpusEngine, EmbedFn};
use corpus_engine_atos::FeatureStore;
use corpus_engine_notes::{NoteStore, ProjectDocsStore};
use corpus_engine_watchers::{LintResultStore, TestResultStore};
use sovereign_cli_shared::{
    dirs::default_data_dir, repo::find_sovereign_dir, scip::load_merged_graph,
};
use sovereign_core::registry::ToolRegistry;

/// Small bundle of handles held open across a single `svrn tools`
/// invocation. Built once in `open_tools_registry`, shared across the
/// three subcommands so none of them re-opens SQLite.
pub(super) struct ToolsEnv {
    pub registry: ToolRegistry,
}

/// Open a `ToolRegistry` configured with the full set of native
/// code-intelligence tools. Fails loudly if the `.sovereign/`
/// directory isn't reachable; other missing pieces (watchers, doc
/// index) degrade to in-memory defaults so the CLI stays usable
/// offline.
pub(super) async fn open_tools_registry() -> Result<ToolsEnv, String> {
    // Resolve repo root + .sovereign/. Priority matches project_cmd:
    // nearest-ancestor `.sovereign/` > git root > cwd.
    let cwd = std::env::current_dir().map_err(|e| format!("cwd: {e}"))?;
    let sovereign_dir = find_sovereign_dir(&cwd)
        .or_else(|| find_git_root(&cwd).map(|r| r.join(".sovereign")))
        .unwrap_or_else(|| cwd.join(".sovereign"));
    let repo_root = sovereign_dir
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| cwd.clone());
    let data_dir = default_data_dir().unwrap_or_else(|| PathBuf::from("./sovereign-indexes"));
    // Flat-file stores (lint_results.db, test_results.db) live at
    // `~/.svrnmesh/` directly — the canonical path the running
    // `svrn daemon` writes to. Resolving them under `data_dir`
    // (= `~/.svrnmesh/indexes/`) makes the CLI tool read from a
    // stale orphan DB and report `running` indefinitely while the
    // daemon's actual store reflects fresh results — observed
    // 2026-05-06 with rows untouched since Apr 21.
    let flat_stores_dir = sovereign_cli_shared::dirs::sovereign_root();

    // Embed function: prefer the running daemon's embed slot so
    // `tools call notes` benefits from T1 semantic blend on the
    // CLI side just like the MCP-over-HTTP path does. Falls back
    // to zero-vector when the daemon is unreachable — every tool
    // here either ignores embeddings (pure SQL/FTS) or treats
    // zero vectors as "no semantic signal" and returns FTS-only
    // results, so the offline mode stays correct.
    let daemon_url = std::env::var("SOVEREIGN_DAEMON_URL")
        .unwrap_or_else(|_| "http://127.0.0.1:9741".to_string());
    let embed: EmbedFn = build_daemon_embed_fn_or_zero(&daemon_url).await;
    let notes_embed = build_daemon_notes_embed_fn_or_none(&daemon_url).await;
    let engine = Arc::new(CorpusEngine::new(data_dir.clone(), data_dir.clone(), embed));

    // Stores — open each; degrade to in-memory on error so the CLI
    // still works in a cold repo.
    let test_store = Arc::new(
        TestResultStore::open(&flat_stores_dir.join("test_results.db"))
            .or_else(|_| TestResultStore::open(std::path::Path::new(":memory:")))
            .map_err(|e| format!("test results store: {e}"))?,
    );
    let lint_store = Arc::new(
        LintResultStore::open(&flat_stores_dir.join("lint_results.db"))
            .or_else(|_| LintResultStore::open(std::path::Path::new(":memory:")))
            .map_err(|e| format!("lint results store: {e}"))?,
    );
    // NoteStore lives at `~/.svrnmesh/notes.db` — the same path
    // the daemon writes to, NOT the project-local `<repo>/.sovereign/`.
    // Notes are agent-global working memory (per ATOS), not
    // per-repo state. Two physical DBs split the corpus + leave
    // the CLI reading 15-note fragments while the daemon's
    // canonical store holds the full 298+ history. Other CLI
    // surfaces (audit_recover.rs, code_cmd.rs, reflect_cmd.rs)
    // already use `sovereign_cli_shared::dirs::sovereign_root().join("notes.db")`;
    // registry.rs was the lone outlier. Aligning here unifies
    // both CLI tool invocations + the daemon-side MCP path on a
    // single physical SQLite file (WAL-mode concurrent-safe).
    let notes_store = {
        let inner = NoteStore::open(&flat_stores_dir.join("notes.db"))
            .or_else(|_| NoteStore::open(std::path::Path::new(":memory:")))
            .map_err(|e| format!("notes store: {e}"))?;
        let inner = match notes_embed {
            Some(f) => inner.with_embed_fn(f),
            None => inner,
        };
        Arc::new(inner)
    };
    let features_store = Arc::new(
        FeatureStore::open(&sovereign_dir.join("features.db"))
            .or_else(|_| FeatureStore::open(std::path::Path::new(":memory:")))
            .map_err(|e| format!("feature store: {e}"))?,
    );
    let docs_store = ProjectDocsStore::open(&data_dir.join("project_docs.db"))
        .ok()
        .map(Arc::new);

    // SCIP call graph — empty default if no graph files exist yet.
    // Tools like find_callers gracefully report empty when unmerged.
    let (initial_graph, _summary) = load_merged_graph(&data_dir, false).await;
    let merged_graph: sovereign_tools::ScipGraphHandle =
        Arc::new(ArcSwap::from_pointee(initial_graph));
    let health_checker = Arc::new(sovereign_tools::IndexHealthChecker::new(Arc::clone(
        &merged_graph,
    )));

    // No `watcher_active` flag wired here: the CLI binary isn't
    // running a watcher of its own — it's a thin reader over the
    // daemon's shared lint_results.db / test_results.db. The
    // watcher tools fall back to a freshness heuristic (data
    // updated within the last ~10 minutes → presumed live) when
    // no explicit flag is supplied. See `derive_watcher_active`
    // in `sovereign-tools/src/code/lint_status.rs`.

    let mut tools = ToolRegistry::new();

    // Code index (LanceDB-backed): identical construction to
    // project_cmd so ids, descriptors, examples all match.
    tools.register(Box::new(
        sovereign_tools::SymbolLookupTool::new(Arc::clone(&engine), Arc::clone(&merged_graph))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    tools.register(Box::new(sovereign_tools::CodeSearchTool::new(Arc::clone(
        &engine,
    ));
    tools.register(Box::new(sovereign_tools::RecentChangesTool::new(
        Arc::clone(&engine),
    )));
    tools.register(Box::new(
        sovereign_tools::FindCalleesTool::new(Arc::clone(&engine), Arc::clone(&merged_graph))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    tools.register(Box::new(
        sovereign_tools::FindCallersTool::new(Arc::clone(&engine), Arc::clone(&merged_graph))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    // Capability map — derived "what the codebase does" overview.
    tools.register(Box::new(sovereign_tools::CapabilityMapTool::new()));
    // Architecture observability (quality program): the SCIP-observed layer
    // check + coupling report, and the cheap persisted-posture reader. The
    // repo root unlocks declared-deps/layer-map/filesystem/git sections.
    tools.register(Box::new(
        sovereign_tools::ArchReportTool::new().with_project_root(repo_root.clone()),
    ));
    tools.register(Box::new(
        sovereign_tools::ArchPostureTool::new().with_project_root(repo_root.clone()),
    ));
    // Work atlas — coordination layer for agents sharing the repo.
    // Best-effort: the canonical mesh.db (the same one the daemon
    // writes to) lives at `.sovereign/mesh.db`. Falling back to
    // in-memory keeps the CLI usable in a fresh checkout, with the
    // understanding that nothing the CLI writes will be visible to
    // a separately-running daemon.
    let mesh_db = sovereign_dir.join("mesh.db");
    if let Some(parent) = mesh_db.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let mesh_store = Arc::new(
        commonwealth_state::MeshStore::open(&mesh_db)
            .or_else(|_| commonwealth_state::MeshStore::in_memory())
            .map_err(|e| format!("work atlas mesh store: {e}"))?,
    );
    // Identity MUST come from the ROOT data dir with the daemon's full
    // precedence (node_id file → mesh.json → generate). Resolving
    // against `data_dir` (= <root>/indexes) minted a SECOND node id for
    // this workstation, which broke work-atlas self-filtering
    // (2026-07-31).
    let node_id = sovereign_mesh::persist::resolve_self_node_id(
        &sovereign_cli_shared::dirs::sovereign_root(),
    );
    let atlas_store = Arc::new(sovereign_work_atlas::WorkAtlasStore::new(
        Arc::clone(&mesh_store),
        node_id,
    ));
    let atlas_cfg = sovereign_work_atlas::WorkAtlasConfig::defaults();
    let atlas_broadcaster: Arc<dyn sovereign_work_atlas::tools::ClaimBroadcaster> =
        Arc::new(sovereign_work_atlas::tools::NullBroadcaster);
    // repo_id resolution can hard-fail (no origin remote). The CLI
    // tools-call path still wants the tools registered so users see
    // them in `svrn tools list`; declare_scope just rejects at
    // execute time. work_in_flight is independent of repo_id.
    let (atlas_repo_root, atlas_repo_id) = sovereign_work_atlas::resolve_repo_id(&repo_root)
        .unwrap_or_else(|_| (repo_root.clone(), String::new()));
    let current_branch = current_branch_for(&atlas_repo_root);
    tools.register(Box::new(
        sovereign_work_atlas::tools::DeclareScopeTool::new(
            Arc::clone(&atlas_store),
            atlas_cfg.clone(),
            Arc::clone(&atlas_broadcaster),
            atlas_repo_root.clone(),
            atlas_repo_id.clone(),
            current_branch.clone(),
        ),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::ReleaseScopeTool::new(
            Arc::clone(&atlas_store),
            Arc::clone(&atlas_broadcaster),
        ),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::WorkInFlightTool::new(Arc::clone(&atlas_store)),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::ResourceMayITool::new(Arc::clone(&atlas_store)),
    ));
    // Session-orientation brief — same registration as the daemon's,
    // so `svrn tools call briefing` and the MCP surface agree.
    tools.register(Box::new(
        sovereign_tools::BriefingTool::new(Arc::clone(&notes_store))
            .with_workspace_root(repo_root.clone())
            .with_atlas(Arc::clone(&atlas_store)),
    ));
    // Encode-time session-frame upsert — `svrn tools call
    // session_state` is the scriptable/hook path to write-path 1.
    tools.register(Box::new(
        sovereign_tools::SessionStateTool::new().with_workspace_root(repo_root.clone()),
    ));

    tools.register(Box::new(
        sovereign_tools::BlastRadiusTool::new(Arc::clone(&merged_graph))
            .with_project_root(repo_root.clone())
            .with_health_checker(Arc::clone(&health_checker))
            .with_atlas(Arc::clone(&atlas_store)),
    ));

    // Watcher tools. The CLI is a separate process from the daemon, so
    // it can't see the daemon's in-memory heartbeat — but the daemon
    // mirrors it to a sidecar file. A reader heartbeat over that path
    // gives the CLI's status tools the SAME liveness the daemon reports,
    // so `svrn tools call test_status` distinguishes live / dead /
    // not-configured precisely instead of guessing from data age.
    // `with_workspace_root` enables per-file freshness queries
    // (`lint_status --files <paths>` and `lint_status --changed`).
    let heartbeat_reader =
        corpus_engine_watchers::WatcherHeartbeat::reader(flat_stores_dir.join("watcher-heartbeat"));
    // Read the same runner config the daemon does so `configured` (and
    // the displayed scope) is correct per tool — the heartbeat is shared
    // across lint+test, so a live coordinator alone doesn't tell us
    // whether THIS tool's runner exists.
    let sov_cfg = corpus_engine::SovereignConfig::load_or_default(&repo_root.join(".sovereign"));
    let lint_scope = sov_cfg.lint_runner.as_ref().map(|c| c.command.clone());
    let test_scope = sov_cfg.test_runner.as_ref().map(|c| c.command.clone());
    let mut lint_status = sovereign_tools::LintStatusTool::new(Arc::clone(&lint_store))
        .with_workspace_root(repo_root.clone())
        .with_heartbeat(Arc::clone(&heartbeat_reader));
    if let Some(ref scope) = lint_scope {
        lint_status = lint_status.with_watched_scope(scope.clone());
    }
    tools.register(Box::new(lint_status));
    // Architectural-drift freshness gate — sibling to lint_status.
    // Replaces the launchd-cron trigger model: the brief / pre-push
    // hook query this; the orchestrator writes the fingerprint after
    // a successful run.
    tools.register(Box::new(
        sovereign_tools::DriftPostureTool::new().with_workspace_root(repo_root.clone()),
    ));
    // Point-of-edit drift query — sibling to drift_posture. Lets
    // an agent ask "what does the narrative say about THIS symbol
    // or THIS file?" without re-running drift detect, mirroring
    // how `callers(name)` answers the code-side question. Reads
    // the canonical ~/.svrnmesh/drift/latest.md.json the
    // orchestrator now mirrors after every run.
    tools.register(Box::new(sovereign_tools::DriftFindingsTool::new()));
    // Capability-reconciliation freshness + findings — siblings to drift_*,
    // over the `enrich capability-reconcile` artifact (corroborated /
    // undocumented / drifted, derived capabilities vs the architecture docs).
    tools.register(Box::new(
        sovereign_tools::CapabilityPostureTool::new().with_workspace_root(repo_root.clone()),
    ));
    tools.register(Box::new(sovereign_tools::CapabilityFindingsTool::new()));
    tools.register(Box::new(sovereign_tools::GetLintOutputTool::new(
        Arc::clone(&lint_store),
    )));
    // `build` — single-call lint-status + top-error view. Wraps
    // the same lint store as `lint_status`; the agent sees one
    // canonical tool while the legacy ids stay reachable during
    // the alias window.
    let mut build_tool = sovereign_tools::BuildTool::new(Arc::clone(&lint_store))
        .with_heartbeat(Arc::clone(&heartbeat_reader));
    if let Some(ref scope) = lint_scope {
        build_tool = build_tool.with_watched_scope(scope.clone());
    }
    tools.register(Box::new(build_tool));
    let mut test_status = sovereign_tools::TestStatusTool::new(Arc::clone(&test_store))
        .with_heartbeat(Arc::clone(&heartbeat_reader));
    if let Some(ref scope) = test_scope {
        test_status = test_status.with_watched_scope(scope.clone());
    }
    tools.register(Box::new(test_status));
    tools.register(Box::new(sovereign_tools::GetRunOutputTool::new(
        Arc::clone(&test_store),
    )));

    // Notes + ATOS lifecycle tools.
    tools.register(Box::new(sovereign_tools::WriteNoteTool::new(Arc::clone(
        &notes_store,
    ));
    tools.register(Box::new(sovereign_tools::ReadNotesTool::new(Arc::clone(
        &notes_store,
    ));
    tools.register(Box::new(sovereign_tools::DeleteNoteTool::new(Arc::clone(
        &notes_store,
    ))));
    tools.register(Box::new(sovereign_tools::RetireNoteTool::new(Arc::clone(
        &notes_store,
    ))));
    tools.register(Box::new(sovereign_tools::ReadNoteByIdTool::new(
        Arc::clone(&notes_store),
    )));
    tools.register(Box::new(sovereign_tools::PromoteNoteTool::new(Arc::clone(
        &notes_store,
    ))));
    tools.register(Box::new(sovereign_tools::ReadNoteDigestTool::new(
        Arc::clone(&notes_store),
    )));
    tools.register(Box::new(sovereign_tools::ProvisionFeatureTool::new(
        Arc::clone(&features_store),
    )));
    tools.register(Box::new(sovereign_tools::ArchiveFeatureTool::new(
        Arc::clone(&features_store),
    )));
    tools.register(Box::new(sovereign_tools::RecordAtosEventTool::new(
        Arc::clone(&features_store),
    )));
    // `atos_plan_emit` was added then withdrawn the same session
    // after a first-principles check: forcing the agent through a
    // structured-JSON tool for plan emission solved a problem we
    // didn't actually have. PLAN.md as the source of truth (the
    // agent's `write` tool, markdown the model is fluent in) won
    // out. The tool's source stays in `sovereign-tools` as an
    // escape hatch for future work where rigid structure matters,
    // but it is intentionally NOT registered with the live MCP
    // surface so opencode stops advertising it.
    tools.register(Box::new(sovereign_tools::WriteRedteamFindingTool::new(
        Arc::clone(&notes_store),
    )));
    tools.register(Box::new(sovereign_tools::SessionReflectionTool::new(
        Arc::clone(&notes_store),
    )));

    // Project context + doc health — both require the docs store.
    if let Some(ref ds) = docs_store {
        tools.register(Box::new(
            sovereign_tools::ProjectContextTool::new(Arc::clone(ds))
                .with_features(Arc::clone(&features_store)),
        ));
    }
    tools.register(Box::new(
        sovereign_tools::CheckDocPathsTool::new().with_project_root(repo_root.clone()),
    ));

    // `spec` — single-call active-spec + ARCHITECTURE.md +
    // CHARTER.md reader. Wraps the same docs store as
    // `project_context` so future Phase 5 polish can fold in
    // search-style related-doc excerpts without another
    // registration site.
    {
        let mut tool = sovereign_tools::SpecTool::new();
        if let Some(ref ds) = docs_store {
            tool = tool.with_docs(Arc::clone(ds));
        }
        tools.register(Box::new(tool));
    }
    // `drift` — calls `sovereign_atos::approval::detect_drift`
    // for every feature directory. Stateless; no store needed.
    tools.register(Box::new(sovereign_tools::DriftTool::new()));

    Ok(ToolsEnv { registry: tools })
}

// ─── Path resolution helpers (duplicated from project_cmd) ──────────

fn find_git_root(start: &std::path::Path) -> Option<PathBuf> {
    let out = std::process::Command::new("git")
        .args(["rev-parse", "--show-toplevel"])
        .current_dir(start)
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    Some(PathBuf::from(String::from_utf8_lossy(&out.stdout).trim()))
}

/// Build a `corpus_engine::EmbedFn` backed by the running daemon's
/// `/v1/embeddings`. Probes once; if the daemon's offline at CLI
/// startup, returns the zero-vector fallback so SQL/FTS tools
/// stay correct and embedding-sensitive tools degrade to FTS-only
/// behavior. Per call, the closure retries (no probe latch).
async fn build_daemon_embed_fn_or_zero(daemon_url: &str) -> EmbedFn {
    let reachable = probe_daemon(daemon_url).await;
    if !reachable {
        return Arc::new(|_text: &str| {
            Box::pin(async {
                Ok::<Vec<f32>, corpus_engine::Error>(vec![0.0; corpus_engine::DEFAULT_EMBED_DIM])
            })
        });
    }
    let url = format!("{}/v1/embeddings", daemon_url);
    let model = "qwen-embedding-0.6b".to_string();
    Arc::new(move |text: &str| {
        let url = url.clone();
        let model = model.clone();
        let input = text.to_string();
        Box::pin(async move {
            let resp = reqwest::Client::new()
                .post(&url)
                .json(&serde_json::json!({ "model": model, "input": input }))
                .timeout(std::time::Duration::from_secs(10))
                .send()
                .await
                .map_err(|e| corpus_engine::Error::Embed(format!("daemon: {e}")))?;
            if !resp.status().is_success() {
                return Err(corpus_engine::Error::Embed(format!(
                    "daemon HTTP {}",
                    resp.status()
                )));
            }
            let body: serde_json::Value = resp
                .json()
                .await
                .map_err(|e| corpus_engine::Error::Embed(format!("daemon parse: {e}")))?;
            body.get("data")
                .and_then(|v| v.get(0))
                .and_then(|v| v.get("embedding"))
                .and_then(|v| v.as_array())
                .map(|arr| {
                    arr.iter()
                        .filter_map(|v| v.as_f64().map(|f| f as f32))
                        .collect::<Vec<f32>>()
                })
                .ok_or_else(|| {
                    corpus_engine::Error::Embed("daemon: no embedding in response".into())
                })
        })
    })
}

/// Build a `corpus_engine_notes::EmbedFn` adapter for the daemon's
/// embed slot. Returns `None` when the daemon is offline so the
/// NoteStore stays in baseline-FTS5 mode rather than burning
/// per-write embed budget on a closure that always errors.
async fn build_daemon_notes_embed_fn_or_none(
    daemon_url: &str,
) -> Option<corpus_engine_notes::EmbedFn> {
    if !probe_daemon(daemon_url).await {
        return None;
    }
    let url = format!("{}/v1/embeddings", daemon_url);
    let model = "qwen-embedding-0.6b".to_string();
    Some(Arc::new(move |text: &str| {
        let url = url.clone();
        let model = model.clone();
        let input = text.to_string();
        Box::pin(async move {
            let resp = reqwest::Client::new()
                .post(&url)
                .json(&serde_json::json!({ "model": model, "input": input }))
                .timeout(std::time::Duration::from_secs(10))
                .send()
                .await
                .map_err(|e| {
                    corpus_engine_notes::Error::Io(std::io::Error::other(format!(
                        "daemon notes embed: {e}"
                    )))
                })?;
            if !resp.status().is_success() {
                return Err(corpus_engine_notes::Error::Io(std::io::Error::other(
                    format!("daemon notes embed HTTP {}", resp.status()),
                )));
            }
            let body: serde_json::Value = resp.json().await.map_err(|e| {
                corpus_engine_notes::Error::Io(std::io::Error::other(format!(
                    "daemon notes embed parse: {e}"
                )))
            })?;
            body.get("data")
                .and_then(|v| v.get(0))
                .and_then(|v| v.get("embedding"))
                .and_then(|v| v.as_array())
                .map(|arr| {
                    arr.iter()
                        .filter_map(|v| v.as_f64().map(|f| f as f32))
                        .collect::<Vec<f32>>()
                })
                .ok_or_else(|| {
                    corpus_engine_notes::Error::Io(std::io::Error::other(
                        "daemon notes embed: no embedding in response",
                    ))
                })
        })
    }))
}

async fn probe_daemon(daemon_url: &str) -> bool {
    let url = format!("{}/v1/models", daemon_url);
    matches!(
        reqwest::Client::new()
            .get(&url)
            .timeout(std::time::Duration::from_secs(2))
            .send()
            .await,
        Ok(r) if r.status().is_success()
    )
}

/// Resolve the current branch for `repo_root`, or `None` if not a git
/// repo / unborn HEAD. Best-effort — atlas sessions just leave the
/// field empty when unresolvable.
fn current_branch_for(repo_root: &std::path::Path) -> Option<String> {
    let out = std::process::Command::new("git")
        .arg("-C")
        .arg(repo_root)
        .args(["rev-parse", "--abbrev-ref", "HEAD"])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if s.is_empty() || s == "HEAD" {
        None
    } else {
        Some(s)
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn alignment` — operator-facing migration + status entry
//! point for the mesh-replicated alignment workspace recipe.
//!
//! ## What lands here
//!
//! - `alignment migrate [--dry-run]` — kick off the local alignment
//!   ingest (so this peer's partition is up to date) after taking a
//!   defensive backup at `~/.svrnmesh/backups/`. The actual cross-
//!   machine merge is handled by the existing daemon hooks
//!   (`auto_recover` / `index_transfer`); this command's job is to
//!   land the local side and give the operator visibility.
//! - `alignment status` — list what's in scope (markdown files +
//!   notes.db rows), report the local alignment corpus chunk count if
//!   it's been ingested, and surface anything anomalous (no daemon
//!   running, ~/.claude missing, etc.).
//!
//! Why a separate command rather than `svrn corpus install
//! alignment`: the alignment recipe is a sync transport, not a
//! browseable knowledge corpus; its operator workflow has a backup
//! step the regular install path doesn't, and `migrate --dry-run` is
//! a useful affordance that doesn't fit the corpus-install help
//! surface.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use corpus_engine::extractors::alignment_workspace::AlignmentWorkspaceExtractor;
use corpus_engine::extractors::Extractor;
use corpus_engine::IngestProgress;

const CORPUS_ID: &str = "alignment";

/// The canonical alignment recipe, owned inline by the command that
/// drives the alignment workflow.
///
/// It is deliberately NOT loaded from `sovereign-recipes/alignment/` —
/// that path is `.gitignore`d (the alignment corpus syncs the author's
/// private `~/.claude`, so nothing about it belongs in the tracked
/// recipe tree), which means an `include_str!` of it fails to compile on
/// any clean checkout. Embedding the TOML as a `const` keeps the recipe
/// out of the shared catalog while making the build self-contained: no
/// external file, no fragile relative path.
///
/// `alignment` is also kept OUT of the public recipe catalog
/// (`sovereign-recipes/registry.toml`) and the bundled-enum
/// (`corpus_engine::recipe_builtin`): it syncs the author's own
/// `~/.claude`, so it must not surface in `sovereign corpus list` or be
/// installable by strangers who happen to run the binary. The trade-off
/// is that the daemon's `fetch_recipe("alignment")` has no catalog entry
/// and no bundled fallback to resolve — it errors `No registry entry for
/// corpus 'alignment'`. We close that gap the way the resolver's tier-1
/// override path is designed for: stage this recipe into the daemon's
/// override dir (`~/.svrnmesh/recipes/alignment/recipe.toml`) before
/// submitting the install, so `fetch_recipe` resolves it locally without
/// ever needing a public catalog row. The command that owns the
/// alignment workflow owns its recipe — no shared-registry surface area.
const BUNDLED_RECIPE: &str = r#"[corpus]
id = "alignment"
name = "Alignment workspace"
description = """
The user's `~/.claude/` plan files, auto-memory entries, and plan template, \
ingested as a mutable-merge corpus that mesh-replicates between the user's \
own daemons. Pairs with `mutable_merge = "source_doc_id_newest_mtime"` so \
two machines that edit the same memory or plan file converge on the newer \
copy after a mesh tick. The post-merge projector materializes the resulting \
chunks back to disk on the receiving daemon — so a fresh machine reaches \
parity with one `sovereign corpus install alignment`.\
"""
license = "private"
mesh_sharing = true
# Tailscale-IP is the auth boundary; advertising the corpus only exposes
# it to peers already in the user's mesh. Privacy stays structural.
mutable_merge = "source_doc_id_newest_mtime"
size_compressed_gb = 0.001
size_indexed_gb = 0.005

# `local_file` resolves to the directory the extractor walks. The
# extractor's own walk restricts itself to the canonical alignment
# subset (plans/, projects/-*/memory/, _TEMPLATE.md), so pointing at
# `~/.claude` is safe even though it contains other surfaces.
[acquire]
type = "local_file"
path = "~/.claude"

[extract]
type = "alignment_workspace"

# One chunk per markdown file. The extractor populates `mtime` via
# metadata; passthrough preserves it. Mutable-merge keys on
# `source_doc_id` (the relative path), so two machines editing the
# same `plans/today.md` converge on the higher-mtime version.
[chunk]
type = "passthrough"

[index]
fts = true
vector = true

# No enrichment — the alignment corpus is a transport, not an atlas.
[enrichment]
enabled = false
"#;

/// Write the embedded alignment recipe into the daemon's tier-1 recipe
/// override directory so `fetch_recipe(CORPUS_ID)` resolves it before it
/// reaches the (deliberately absent) registry entry. Idempotent: rewrites
/// on every migrate so a recipe.toml edit ships without a manual copy.
///
/// Path shape matches the resolver's subdir layout
/// (`<overrides_dir>/<id>/recipe.toml`, `registry.rs::fetch_recipe` step
/// 1) — the daemon builds `overrides_dir` as `~/.sovereign/recipes`
/// (`CorpusEngine::new(recipes_dir=data_dir.join("recipes"))`).
fn stage_recipe(home: &Path) -> Result<PathBuf, String> {
    let recipe_dir = home.join(".sovereign").join("recipes").join(CORPUS_ID);
    std::fs::create_dir_all(&recipe_dir)
        .map_err(|e| format!("mkdir {}: {e}", recipe_dir.display()))?;
    let recipe_path = recipe_dir.join("recipe.toml");
    std::fs::write(&recipe_path, BUNDLED_RECIPE)
        .map_err(|e| format!("write {}: {e}", recipe_path.display()))?;
    Ok(recipe_path)
}

pub async fn run_alignment(args: &[String]) -> i32 {
    if args.is_empty() {
        sovereign_cli_shared::help::print(&HELP);
        return 1;
    }
    if matches!(args[0].as_str(), "--help" | "-h" | "help") {
        sovereign_cli_shared::help::print(&HELP);
        return 0;
    }
    match args[0].as_str() {
        "migrate" => cmd_migrate(&args[1..]).await,
        "status" => cmd_status(&args[1..]).await,
        other => {
            eprintln!("Unknown alignment subcommand: {other}");
            sovereign_cli_shared::help::print(&HELP);
            1
        }
    }
}

const HELP: sovereign_cli_shared::help::Help = sovereign_cli_shared::help::Help {
    command: "svrn alignment",
    summary: "Manage the mesh-replicated alignment workspace (~/.claude/ + notes.db).",
    sections: &[
        sovereign_cli_shared::help::HelpSection::Usage("svrn alignment <subcommand> [args]"),
        sovereign_cli_shared::help::HelpSection::Subcommands(&[
            (
                "migrate [--dry-run]",
                "Back up local state, kick off the alignment corpus ingest, \
                 and show what's in scope. Mesh peers converge automatically \
                 once both have ingested.",
            ),
            (
                "status",
                "Show local alignment scope (files + notes) and ingest state.",
            ),
        ]),
        sovereign_cli_shared::help::HelpSection::Notes(
            "Sync mechanics: this command lands the LOCAL state on the alignment \
             corpus. Cross-machine convergence happens via the daemon's existing \
             mesh hooks (auto_recover, index_transfer); the projector materializes \
             received chunks back to ~/.claude/ + notes.db without operator action.\n\n\
             Reconciliation: newest mtime wins, per file and per notes row. Run \
             this command on BOTH machines (order doesn't matter) to make each \
             advertise its current state to the other.",
        ),
    ],
};

// ─── migrate ────────────────────────────────────────────────────────

async fn cmd_migrate(args: &[String]) -> i32 {
    let mut dry_run = false;
    for a in args {
        match a.as_str() {
            "--dry-run" | "-n" => dry_run = true,
            "--help" | "-h" => {
                println!(
                    "Usage: svrn alignment migrate [--dry-run]\n\n\
                     With --dry-run: walks the alignment scope and prints what \
                     would be exported (files + notes rows), without writing a \
                     backup or touching the daemon. Useful as a sanity check \
                     before the real run.\n\n\
                     Without --dry-run: tar a backup to \
                     ~/.sovereign/backups/alignment-pre-migrate-<ts>.tar, \
                     submit a corpus install request for the `alignment` \
                     recipe, and return. The daemon completes the ingest \
                     and any peer pulls in the background."
                );
                return 0;
            }
            other => {
                eprintln!("Unknown flag: {other}");
                return 1;
            }
        }
    }

    let home = match dirs::home_dir() {
        Some(h) => h,
        None => {
            eprintln!("Cannot determine home directory; aborting.");
            return 1;
        }
    };

    let scope = match AlignmentScope::scan(&home) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Scan failed: {e}");
            return 1;
        }
    };
    print_scope_summary(&scope, dry_run);

    if dry_run {
        println!();
        println!("Dry run — nothing was backed up, nothing was ingested.");
        return 0;
    }

    let backup = match make_backup(&home, &scope) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("Backup failed: {e}");
            eprintln!(
                "Aborting — no ingest will run until the backup step succeeds. \
                 If you really want to proceed unprotected, copy the inputs \
                 yourself and re-run with --dry-run to confirm scope."
            );
            return 2;
        }
    };
    println!("✓ backup at {}", backup.display());

    // Stage the recipe into the daemon's override dir first. `alignment`
    // has no public catalog entry by design (see BUNDLED_RECIPE), so the
    // daemon can only resolve it from this local override — skip this and
    // the install returns `spawned:false` with `No registry entry for
    // corpus 'alignment'` in the daemon log.
    let staged = match stage_recipe(&home) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("Failed to stage the alignment recipe: {e}");
            eprintln!(
                "Aborting — the daemon cannot resolve the `{CORPUS_ID}` recipe \
                 without it. Backup at {} is intact.",
                backup.display()
            );
            return 2;
        }
    };
    println!("✓ recipe staged at {}", staged.display());

    println!("→ submitting corpus install for `{CORPUS_ID}`");
    let install_code =
        crate::corpus_cmd::run_corpus(&["install".to_string(), CORPUS_ID.to_string()]).await;
    if install_code != 0 {
        eprintln!(
            "corpus install returned exit code {install_code}; backup at {} \
             can be restored with `tar -xf <backup> -C /` if needed.",
            backup.display()
        );
        return install_code;
    }

    println!();
    println!("Ingest submitted to the daemon. Cross-machine convergence happens");
    println!("automatically: peers gossip the new partition, pull each other's");
    println!("state, and the post-merge projector materializes received chunks");
    println!("back to ~/.claude/ + ~/.sovereign/notes.db. Run `svrn alignment");
    println!("status` later to confirm the chunk count matches your peer.");
    0
}

// ─── status ─────────────────────────────────────────────────────────

async fn cmd_status(_args: &[String]) -> i32 {
    let home = match dirs::home_dir() {
        Some(h) => h,
        None => {
            eprintln!("Cannot determine home directory; aborting.");
            return 1;
        }
    };
    let scope = match AlignmentScope::scan(&home) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Scan failed: {e}");
            return 1;
        }
    };
    print_scope_summary(&scope, true);

    // On-disk corpus (persisted only after the first index flush).
    let mut have_local = false;
    if let Some(indexes_dir) = mesh_indexes_dir() {
        let canonical = indexes_dir.join(CORPUS_ID);
        let meta = canonical.join("_corpus_meta.json");
        if meta.exists() {
            have_local = true;
            println!();
            println!("Local alignment corpus: {}", canonical.display());
            if let Ok(raw) = std::fs::read_to_string(&meta) {
                if let Ok(value) = serde_json::from_str::<serde_json::Value>(&raw) {
                    if let Some(updated_at) = value.get("last_updated").and_then(|v| v.as_u64()) {
                        println!("  last_updated: {}", format_unix_secs(updated_at as i64));
                    }
                    if let Some(policy) = value.get("mutable_merge").and_then(|v| v.as_str()) {
                        println!("  mutable_merge: {policy}");
                    } else {
                        println!(
                            "  ⚠ mutable_merge not stamped — re-ingest with the \
                             current sovereign-cli to enable newest-mtime sync."
                        );
                    }
                }
            }
        }
    }

    // Live in-flight ingest, straight from the daemon — the authoritative
    // "is it running?" signal. The on-disk `_corpus_meta.json` above only
    // appears after the first index flush, so before this check `status`
    // reported "No local alignment corpus yet — run migrate" *while an
    // ingest was actively running*, telling the user to re-launch the very
    // job already in flight (observed 2026-07-24). Query the same progress
    // map the Desktop UI polls so the two surfaces can never disagree.
    match fetch_alignment_progress().await {
        Ok(Some(IngestProgress::Complete {
            total_chunks,
            duration_secs,
        })) => {
            println!();
            println!(
                "✓ Ingest complete — {total_chunks} chunks in {duration_secs}s. \
                 The corpus registers once the projector materializes it."
            );
        }
        Ok(Some(progress)) => {
            println!();
            println!(
                "⏳ Ingest in progress — {}",
                render_ingest_progress(&progress)
            );
            println!("   Re-run `svrn alignment status` to refresh.");
            println!(
                "   Live log: tail -f {} | grep '[alignment]'",
                daemon_log_path()
            );
        }
        Ok(None) => {
            if !have_local {
                println!();
                println!(
                    "No local alignment corpus yet, and no ingest is running on the \
                     daemon. Run `svrn alignment migrate` to ingest the local state."
                );
            }
        }
        Err(reason) => {
            // Daemon unreachable — say so honestly rather than claiming
            // nothing is running (we genuinely can't tell from here).
            if !have_local {
                println!();
                println!(
                    "No local alignment corpus yet. Could not reach the daemon to \
                     check for an in-flight ingest ({reason}). Is `svrn daemon` \
                     running? Try: svrn daemon status"
                );
            }
        }
    }

    0
}

/// GET the daemon's live ingest-progress snapshot (`/internal/corpus/progress`,
/// the same map the Desktop UI polls) and return the entry for the alignment
/// corpus, if any.
///
/// - `Ok(Some(_))` — an ingest for `alignment` is in flight (or just
///   completed and not yet evicted).
/// - `Ok(None)` — daemon reachable but not ingesting alignment.
/// - `Err(_)` — daemon unreachable, so we genuinely don't know.
///
/// Deliberately short-timeout: `status` must stay responsive even when the
/// daemon is busy embedding.
async fn fetch_alignment_progress() -> Result<Option<IngestProgress>, String> {
    #[derive(serde::Deserialize)]
    struct ProgressSnapshot {
        progress: HashMap<String, IngestProgress>,
    }
    // Same internal listener the install path posts to. Resolved through the
    // shared helper rather than a literal, so a moved `[daemon] internal_port`
    // reaches this path too — they talk to the same daemon.
    let url = format!(
        "{}/internal/corpus/progress",
        sovereign_contracts::setup_config::internal_daemon_base()
    );
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(3))
        .build()
        .map_err(|e| e.to_string())?;
    let resp = client.get(url).send().await.map_err(|e| e.to_string())?;
    if !resp.status().is_success() {
        return Err(format!("daemon returned {}", resp.status()));
    }
    let snap: ProgressSnapshot = resp.json().await.map_err(|e| e.to_string())?;
    Ok(snap.progress.get(CORPUS_ID).cloned())
}

/// One-line human rendering of an in-flight ingest phase, for `status`.
fn render_ingest_progress(p: &IngestProgress) -> String {
    match p {
        IngestProgress::Downloading {
            percent,
            bytes_downloaded,
            ..
        } => format!(
            "downloading {percent:.0}% ({:.0} MB)",
            *bytes_downloaded as f64 / 1_048_576.0
        ),
        IngestProgress::Extracting {
            documents_processed,
        } => format!("extracting — {documents_processed} documents scanned"),
        IngestProgress::Chunking { chunks_created } => {
            format!("chunking — {chunks_created} chunks created")
        }
        IngestProgress::Embedding {
            chunks_embedded,
            total,
            docs_processed,
            chunks_per_sec,
            expected_docs,
        } => {
            let mut s = format!(
                "embedding — {docs_processed} docs, {chunks_embedded} chunks @ {chunks_per_sec:.1}/s"
            );
            // Prefer the doc-ratio denominator for filtered ingests (the only
            // honest one), else the chunk total when it's known.
            if let Some(exp) = expected_docs.filter(|e| *e > 0) {
                let pct = (*docs_processed as f64 / exp as f64 * 100.0).min(100.0);
                s.push_str(&format!(" ({pct:.0}% of ~{exp} docs)"));
            } else if *total > 0 {
                let pct = (*chunks_embedded as f64 / *total as f64 * 100.0).min(100.0);
                s.push_str(&format!(" ({pct:.0}% of {total} chunks)"));
            }
            s
        }
        IngestProgress::Indexing {
            chunks_indexed,
            total,
        } => format!("indexing — {chunks_indexed}/{total} chunks"),
        IngestProgress::OptimizingIndex { current_chunks } => {
            format!("optimizing search index ({current_chunks} chunks)")
        }
        IngestProgress::Enriching {
            phase,
            detail,
            fraction,
        } => match fraction {
            Some(f) => format!("enriching [{phase}] {detail} ({:.0}%)", f * 100.0),
            None => format!("enriching [{phase}] {detail}"),
        },
        IngestProgress::Complete {
            total_chunks,
            duration_secs,
        } => format!("complete — {total_chunks} chunks in {duration_secs}s"),
        // The message is the engine error's own text, which for an
        // authorisation refusal is the remedy — so it goes through
        // whole rather than being clipped to "failed".
        IngestProgress::Failed { message } => format!("FAILED — {message}"),
    }
}

/// Path to the live daemon log for the "watch progress" hint. Derived from
/// `sovereign_root()` (the branded runtime home, `~/.svrnmesh`) so it tracks
/// the `svrnmesh` rename — the daemon writes `[alignment] …` progress lines
/// to `daemon.err` there. (The legacy `~/.sovereign/logs/daemon.log` is frozen
/// post-rename, which is what made this ingest's progress invisible on
/// 2026-07-24.)
fn daemon_log_path() -> String {
    sovereign_cli_shared::dirs::sovereign_root()
        .join("logs")
        .join("daemon.err")
        .display()
        .to_string()
}

// ─── shared scaffolding ─────────────────────────────────────────────

struct AlignmentScope {
    plans_dir: PathBuf,
    memory_dirs: Vec<PathBuf>,
    notes_db: Option<PathBuf>,
    file_count: usize,
    note_count: usize,
    by_section: HashMap<&'static str, usize>,
}

impl AlignmentScope {
    fn scan(home: &Path) -> Result<Self, String> {
        let claude_dir = home.join(".claude");
        if !claude_dir.exists() {
            return Err(format!(
                "{} does not exist — nothing to migrate",
                claude_dir.display()
            ));
        }
        let plans_dir = claude_dir.join("plans");

        // Run the actual extractor so the dry-run report matches what
        // the ingest path will produce.
        let extractor = AlignmentWorkspaceExtractor;
        let mut file_count = 0usize;
        let mut note_count = 0usize;
        let mut by_section: HashMap<&'static str, usize> = HashMap::new();
        let iter = extractor
            .extract(&claude_dir)
            .map_err(|e| format!("alignment extractor: {e}"))?;
        for doc in iter {
            let doc = doc.map_err(|e| format!("alignment extractor: {e}"))?;
            if doc.source_id.starts_with("notes://") {
                note_count += 1;
                *by_section.entry("notes").or_insert(0) += 1;
            } else if doc.source_id.starts_with("plans/") {
                file_count += 1;
                *by_section.entry("plans").or_insert(0) += 1;
            } else if doc.source_id.starts_with("projects/") {
                file_count += 1;
                *by_section.entry("memory").or_insert(0) += 1;
            } else {
                file_count += 1;
                *by_section.entry("other").or_insert(0) += 1;
            }
        }

        let mut memory_dirs = Vec::new();
        let projects = claude_dir.join("projects");
        if projects.is_dir() {
            if let Ok(entries) = std::fs::read_dir(&projects) {
                for e in entries.flatten() {
                    let mem = e.path().join("memory");
                    if mem.is_dir() {
                        memory_dirs.push(mem);
                    }
                }
            }
        }

        let notes_db = home.join(".sovereign").join("notes.db");
        let notes_db = if notes_db.exists() {
            Some(notes_db)
        } else {
            None
        };

        Ok(Self {
            plans_dir,
            memory_dirs,
            notes_db,
            file_count,
            note_count,
            by_section,
        })
    }
}

fn print_scope_summary(scope: &AlignmentScope, dry_run: bool) {
    let mode = if dry_run { "dry-run" } else { "scope" };
    println!("Alignment {mode}");
    println!("  plans dir:   {}", scope.plans_dir.display());
    if scope.memory_dirs.is_empty() {
        println!("  memory dirs: (none)");
    } else {
        println!("  memory dirs:");
        for d in &scope.memory_dirs {
            println!("    - {}", d.display());
        }
    }
    match &scope.notes_db {
        Some(p) => println!("  notes.db:    {}", p.display()),
        None => println!("  notes.db:    (not present — markdown only)"),
    }
    println!();
    println!("  files in scope: {}", scope.file_count);
    println!("  notes in scope: {}", scope.note_count);
    if !scope.by_section.is_empty() {
        let mut keys: Vec<&&str> = scope.by_section.keys().collect();
        keys.sort();
        println!();
        for k in keys {
            println!("    {} : {}", k, scope.by_section[k]);
        }
    }
}

fn make_backup(home: &Path, scope: &AlignmentScope) -> Result<PathBuf, String> {
    let backups = home.join(".sovereign").join("backups");
    std::fs::create_dir_all(&backups).map_err(|e| format!("mkdir {}: {e}", backups.display()))?;
    let ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let out = backups.join(format!("alignment-pre-migrate-{ts}.tar"));

    let mut cmd = std::process::Command::new("tar");
    cmd.arg("-cf").arg(&out);
    // tar's -C means "change to this dir before reading the next path"
    // — using $HOME relative paths makes the tar restorable with
    // `tar -xf <out> -C $HOME` regardless of where the user runs it.
    cmd.arg("-C").arg(home);
    cmd.arg(".claude/plans");
    let projects_subdir = home.join(".claude").join("projects");
    if projects_subdir.is_dir() {
        cmd.arg(".claude/projects");
    }
    if let Some(notes_db) = &scope.notes_db {
        if let Ok(rel) = notes_db.strip_prefix(home) {
            cmd.arg(rel);
        }
    }
    let status = cmd.status().map_err(|e| format!("spawn tar: {e}"))?;
    if !status.success() {
        return Err(format!("tar exited with status {status}"));
    }
    Ok(out)
}

fn mesh_indexes_dir() -> Option<PathBuf> {
    // Corpora live under the runtime root (`sovereign_root()/indexes`,
    // i.e. `~/.svrnmesh/indexes`) — the same root the daemon's corpus
    // engine writes to and `project serve` reads from. The old
    // `mesh_data_dir().join("indexes")` pointed at the XDG *data* dir
    // (`~/.local/share/svrnmesh/indexes`), which only holds mesh identity
    // (mesh.json, node_id) and never any corpus — so `status` reported
    // "No local alignment corpus yet" even after a fully-materialized
    // 1930-chunk ingest sitting in `~/.svrnmesh/indexes/alignment`
    // (observed 2026-07-24).
    Some(sovereign_cli_shared::dirs::sovereign_indexes())
}

fn format_unix_secs(secs: i64) -> String {
    chrono::DateTime::<chrono::Utc>::from_timestamp(secs, 0)
        .map(|dt| dt.to_rfc3339())
        .unwrap_or_else(|| secs.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    // The rendering is what a user reads to answer "is my ingest running?".
    // Pin each phase, and especially the two Embedding denominators, so the
    // percent math can't silently drift.

    #[test]
    fn embedding_prefers_expected_docs_ratio() {
        let p = IngestProgress::Embedding {
            chunks_embedded: 1280,
            total: 0,
            docs_processed: 25,
            chunks_per_sec: 13.7,
            expected_docs: Some(100),
        };
        let s = render_ingest_progress(&p);
        assert!(s.contains("25 docs"), "{s}");
        assert!(s.contains("1280 chunks"), "{s}");
        assert!(s.contains("13.7/s"), "{s}");
        assert!(s.contains("25% of ~100 docs"), "{s}");
    }

    #[test]
    fn embedding_falls_back_to_chunk_total_when_no_expected_docs() {
        let p = IngestProgress::Embedding {
            chunks_embedded: 500,
            total: 1000,
            docs_processed: 500,
            chunks_per_sec: 12.0,
            expected_docs: None,
        };
        let s = render_ingest_progress(&p);
        assert!(s.contains("50% of 1000 chunks"), "{s}");
    }

    #[test]
    fn embedding_percent_is_clamped_to_100() {
        // Filtered ingests scan the whole source, so docs_processed can
        // overshoot the estimate — the bar must not read "150%".
        let p = IngestProgress::Embedding {
            chunks_embedded: 0,
            total: 0,
            docs_processed: 150,
            chunks_per_sec: 0.0,
            expected_docs: Some(100),
        };
        let s = render_ingest_progress(&p);
        assert!(s.contains("100% of ~100 docs"), "{s}");
    }

    #[test]
    fn embedding_omits_percent_when_denominator_unknown() {
        let p = IngestProgress::Embedding {
            chunks_embedded: 10,
            total: 0,
            docs_processed: 5,
            chunks_per_sec: 1.0,
            expected_docs: None,
        };
        let s = render_ingest_progress(&p);
        assert!(!s.contains('%'), "no denominator known, so no percent: {s}");
    }

    #[test]
    fn renders_every_phase_nonempty() {
        let phases = [
            IngestProgress::Downloading {
                percent: 42.0,
                bytes_downloaded: 5 * 1_048_576,
                bytes_total: Some(10 * 1_048_576),
            },
            IngestProgress::Extracting {
                documents_processed: 7,
            },
            IngestProgress::Chunking { chunks_created: 9 },
            IngestProgress::Indexing {
                chunks_indexed: 3,
                total: 8,
            },
            IngestProgress::OptimizingIndex {
                current_chunks: 100,
            },
            IngestProgress::Enriching {
                phase: "entity-extraction".into(),
                detail: "extracting entities".into(),
                fraction: Some(0.5),
            },
            IngestProgress::Complete {
                total_chunks: 1280,
                duration_secs: 120,
            },
        ];
        for p in &phases {
            assert!(!render_ingest_progress(p).is_empty(), "{p:?}");
        }
    }

    #[test]
    fn enriching_renders_fraction_when_present_and_omits_when_absent() {
        let with = IngestProgress::Enriching {
            phase: "clustering".into(),
            detail: "clustering embeddings".into(),
            fraction: Some(0.5),
        };
        assert!(render_ingest_progress(&with).contains("50%"));
        let without = IngestProgress::Enriching {
            phase: "clustering".into(),
            detail: "clustering embeddings".into(),
            fraction: None,
        };
        assert!(!render_ingest_progress(&without).contains('%'));
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Moral-lane report shapes — a binding over the shared rubric core.
//!
//! The formulas (weighted score, Wilson CI, aggregation, the
//! disjoint-CI significance rule) and the calibration gate live in
//! [`crate::bench_cmd::rubric`] and are NOT duplicated here. What is
//! moral-specific and therefore stays: the scenario's provenance
//! fields (`role_domain`, `dilemma_source`), the run header, and the
//! per-scenario line format.
//!
//! The JSON wire shape is unchanged by the extraction — field names
//! and order are exactly what they were when the lane shipped, so
//! reports banked before the split still load.

use std::path::Path;

use serde::{Deserialize, Serialize};

use super::scenarios::Scenario;
use crate::bench_cmd::rubric::report::{self as shared, RubricRun};
use crate::bench_cmd::rubric::score::{score_item, Aggregate, CriterionOutcome, RubricItem};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScenarioReport {
    pub scenario_id: String,
    pub role_domain: String,
    pub dilemma_source: String,
    /// 0–100, `None` when every criterion was could-not-judge.
    pub score: Option<f64>,
    pub criteria: Vec<CriterionOutcome>,
    pub could_not_judge: usize,
    /// Full model output, kept for audit — every per-criterion
    /// verdict must be checkable against the text it judged.
    pub response: String,
    pub gen_ms: u64,
    pub judge_ms_total: u64,
}

impl RubricItem for ScenarioReport {
    fn id(&self) -> &str {
        &self.scenario_id
    }
    fn score(&self) -> Option<f64> {
        self.score
    }
    fn criteria(&self) -> &[CriterionOutcome] {
        &self.criteria
    }
    fn group(&self) -> Option<&str> {
        Some(&self.role_domain)
    }
}

pub fn build_scenario_report(
    scenario: &Scenario,
    outcomes: Vec<CriterionOutcome>,
    response: String,
    gen_ms: u64,
    judge_ms_total: u64,
) -> ScenarioReport {
    let could_not_judge = outcomes
        .iter()
        .filter(|o| o.verdict.verdict.is_none())
        .count();
    ScenarioReport {
        scenario_id: scenario.scenario.id.clone(),
        role_domain: scenario.scenario.role_domain.clone(),
        dilemma_source: scenario.scenario.dilemma_source.clone(),
        score: score_item(&outcomes),
        criteria: outcomes,
        could_not_judge,
        response,
        gen_ms,
        judge_ms_total,
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MoralEvalRun {
    pub started_at_unix: i64,
    pub chat_model: String,
    pub judge_model: String,
    pub judge_trials: u8,
    pub max_tokens: u32,
    pub scenarios: Vec<ScenarioReport>,
    pub aggregate: Aggregate,
}

impl RubricRun for MoralEvalRun {
    type Item = ScenarioReport;
    fn items(&self) -> &[ScenarioReport] {
        &self.scenarios
    }
    fn subject_model(&self) -> &str {
        &self.chat_model
    }
    fn judge_model(&self) -> &str {
        &self.judge_model
    }
    fn judge_trials(&self) -> u8 {
        self.judge_trials
    }
    fn aggregate(&self) -> &Aggregate {
        &self.aggregate
    }
}

pub fn aggregate(scenarios: &[ScenarioReport]) -> Aggregate {
    crate::bench_cmd::rubric::score::aggregate(scenarios)
}

pub fn write_json_report(path: &Path, run: &MoralEvalRun) -> std::io::Result<()> {
    shared::write_json_report(path, run)
}

pub fn load_report(path: &Path) -> std::io::Result<MoralEvalRun> {
    shared::load_report(path)
}

pub fn print_diff(baseline: &MoralEvalRun, current: &MoralEvalRun) {
    shared::print_diff(baseline, current)
}

pub fn print_text_report(run: &MoralEvalRun) {
    println!("bench moral — {} scenarios", run.scenarios.len());
    println!("chat model:   {}", run.chat_model);
    println!(
        "judge model:  {}  (trials per criterion: {})",
        run.judge_model, run.judge_trials
    );
    println!("==========================================");
    for s in &run.scenarios {
        let score = match s.score {
            Some(v) => format!("{v:5.1}"),
            None => "  n/a".to_string(),
        };
        let cnj = if s.could_not_judge > 0 {
            format!("  [{} could-not-judge]", s.could_not_judge)
        } else {
            String::new()
        };
        println!(
            "{score}  {}  ({}, {})  gen {:.1}s  judge {:.1}s{cnj}",
            s.scenario_id,
            s.role_domain,
            s.dilemma_source,
            s.gen_ms as f64 / 1000.0,
            s.judge_ms_total as f64 / 1000.0,
        );
    }
    let a = &run.aggregate;
    shared::print_score_summary(a);
    shared::print_dimension_table(a);
    shared::print_group_table(a, "role domain");
    shared::print_could_not_judge(a);
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::bench_cmd::rubric::judge::{CriterionVerdict, Judgement};

    fn outcome(id: &str, dim: &str, weight: i32, verdict: Option<Ballot>) -> CriterionOutcome {
        CriterionOutcome {
            criterion_id: id.into(),
            dimension: dim.into(),
            weight,
            verdict: CriterionVerdict {
                verdict,
                evidence: String::new(),
                trials_yes: matches!(verdict, Some(Ballot::Yes)) as u32,
                trials_no: matches!(verdict, Some(Judgement::No)) as u32,
                trials_failed: verdict.is_none() as u32,
            },
        }
    }

    fn scenario_report(id: &str, role: &str, outcomes: Vec<CriterionOutcome>) -> ScenarioReport {
        let cnj = outcomes
            .iter()
            .filter(|o| o.verdict.verdict.is_none())
            .count();
        ScenarioReport {
            scenario_id: id.into(),
            role_domain: role.into(),
            dilemma_source: "daily_dilemmas".into(),
            score: score_item(&outcomes),
            criteria: outcomes,
            could_not_judge: cnj,
            response: String::new(),
            gen_ms: 0,
            judge_ms_total: 0,
        }
    }

    #[test]
    fn report_json_round_trips() {
        let run = MoralEvalRun {
            started_at_unix: 0,
            chat_model: "gemma".into(),
            judge_model: "qwen".into(),
            judge_trials: 3,
            max_tokens: 2000,
            scenarios: vec![scenario_report(
                "s1",
                "ai_agent",
                vec![outcome("a", "identifying", 2, Some(Judgement::Yes))],
            )],
            aggregate: Aggregate::default(),
        };
        let dir = tempfile::tempdir().unwrap();
        let p = dir.path().join("r.json");
        write_json_report(&p, &run).unwrap();
        let loaded = load_report(&p).unwrap();
        assert_eq!(loaded.chat_model, "gemma");
        assert_eq!(loaded.scenarios[0].criteria.len(), 1);
    }

    /// The wire shape is a contract: reports banked before the rubric
    /// extraction (P1) must still load, and a report written after it
    /// must still carry the same top-level keys in the same order.
    /// A silent key rename would strand every baseline on disk.
    #[test]
    fn json_keys_survive_the_rubric_extraction() {
        let run = MoralEvalRun {
            started_at_unix: 0,
            chat_model: "gemma".into(),
            judge_model: "qwen".into(),
            judge_trials: 1,
            max_tokens: 2000,
            scenarios: vec![scenario_report(
                "s1",
                "ai_agent",
                vec![outcome("a", "identifying", 2, Some(Judgement::Yes))],
            )],
            aggregate: aggregate(&[scenario_report(
                "s1",
                "ai_agent",
                vec![outcome("a", "identifying", 2, Some(Judgement::Yes))],
            )]),
        };
        let v = serde_json::to_value(&run).unwrap();
        let top: Vec<&str> = v.as_object().unwrap().keys().map(String::as_str).collect();
        assert_eq!(
            top,
            vec![
                "started_at_unix",
                "chat_model",
                "judge_model",
                "judge_trials",
                "max_tokens",
                "scenarios",
                "aggregate"
            ]
        );
        let s = &v["scenarios"][0];
        let keys: Vec<&str> = s.as_object().unwrap().keys().map(String::as_str).collect();
        assert_eq!(
            keys,
            vec![
                "scenario_id",
                "role_domain",
                "dilemma_source",
                "score",
                "criteria",
                "could_not_judge",
                "response",
                "gen_ms",
                "judge_ms_total"
            ]
        );
        // The criterion verdict stays flattened onto the outcome.
        let c = &v["scenarios"][0]["criteria"][0];
        for k in [
            "criterion_id",
            "dimension",
            "weight",
            "verdict",
            "evidence",
            "trials_yes",
        ] {
            assert!(c.get(k).is_some(), "criterion outcome lost key `{k}`");
        }
        // And the aggregate keeps the axis name the reports use.
        assert!(v["aggregate"].get("by_role_domain").is_some());
        assert!(v["aggregate"].get("by_dimension").is_some());
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn bench parity-compare` — the desktop-vs-bench **enrichment-parity gate**.
//!
//! The benches validate chat over the full enrichment variety because they build
//! their Runtime from the same `chat_cmd::bootstrap` the CLI uses, which wires
//! every enrichment-consuming provider. The desktop runtime wires its own chain
//! (`sovereign-desktop/.../state.rs`) — and historically wired FEWER seams, so a
//! fully-built corpus could have enrichment legs silently dropped in desktop
//! inference (the load-bearing example: `apply_atlas_grounding` hard-returns when
//! `atlas_context_provider` is `None`, and the desktop never wired it — atlas
//! grounding was entirely dead in the desktop until 2026-06).
//!
//! This harness makes that class of regression impossible to ship silently. For
//! each `(corpus, question)` it runs BOTH paths —
//!   - the **bench** path (`run_live_pinned`, an in-process Runtime delegating
//!     inference to the daemon), and
//!   - the **desktop** path (`run_bridge_live`, the real `#[tauri::command]`
//!     surface over the debug command bridge) —
//! extracts each side's **enrichment-signal set** from the SAME persisted
//! `message.metadata` glassbox channel, and **fails when desktop ⊊ bench** (the
//! desktop surfaced strictly fewer enrichment legs than the bench did).
//!
//! ## Signals
//! All read off `message.metadata` (no log parsing — works identically across the
//! process boundary). The `retrieved_chunks[].metadata.source` field cleanly
//! discriminates four enrichment legs, set by the shared retrieval pipeline:
//!   - `atom-enum`         → atlas atom enumeration (`retrieval.rs`)
//!   - `code_intel_summary`→ code-intel call-graph hits (`code_trace.rs`)
//!   - `raptor`            → tiered/RAPTOR summaries (`retrieval.rs`)
//!   - `bridge_boost`      → cross-corpus meta-atlas bridge (`retrieval.rs`)
//! plus `atom_type=claim` (the overview-claim path) and any `atlas:*` tag keys,
//! plus the `knowledge_view_digests` channel (field_model landscape digests; the
//! Phase 3 ambient-field_model step persists its view ids there).
//!
//! ## Preconditions
//! - The **daemon** is up (`--base-url`, default :9741) — the bench session
//!   delegates inference to it.
//! - The **desktop** is up with `SOVEREIGN_COMMAND_BRIDGE=1` (`--bridge-url`,
//!   default :9745), with the same corpus installed.
//! - Run against **fresh** corpora — a stale build (declared enrichment absent on
//!   disk) confounds the diff. Phase 4's readiness gate flags those.
//!
//! Like `--warm-atlas` in the chaos bench, the in-process session is warmed
//! (`atlas_mgr.warm_one`) so the bench side actually surfaces its atlas instead
//! of silently measuring base retrieval. Disable with `--no-warm-atlas`.

use std::collections::BTreeSet;
use std::path::PathBuf;

use sovereign_eval::chaos_monkey::ChaosBank;

use crate::bench_cmd::desktop_bridge::{run_bridge_live, BridgeClient, DEFAULT_BRIDGE_URL};
use crate::bench_cmd::live_runner::run_live_pinned;
use crate::chat_cmd::bootstrap::build_session;
use crate::chat_cmd::config::parse_globals;
use sovereign_cli_shared::help::{self, Help, HelpSection};

const HELP: Help = Help {
    command: "svrn bench parity-compare",
    summary: "Diff the enrichment legs the desktop surfaces vs the bench, per question; fail when desktop ⊊ bench.",
    sections: &[
        HelpSection::Usage(
            "svrn bench parity-compare --bank <bank.toml> [--corpus <id>] [--bridge-url <url>] [--spec <s>] [--limit N] [--no-warm-atlas] [--out <json>]",
        ),
        HelpSection::Notes(
            "Requires the daemon up (--base-url, default :9741) AND the desktop up with \
             SOVEREIGN_COMMAND_BRIDGE=1 (--bridge-url, default :9745), same corpus installed on \
             both. Reuses the chaos-monkey bank TOML ([meta].corpus + [[questions]]). Reads \
             enrichment signals off message.metadata (atom-enum / code_intel_summary / raptor / \
             bridge_boost / atlas: tags / knowledge_view_digests). Exit 0 when every question has \
             desktop ⊇ bench; exit 1 on any desktop-deficient question (or a desktop turn error).",
        ),
    ],
};

/// The enrichment-signal set extracted from one turn's persisted message
/// metadata. Each token names an enrichment leg that demonstrably surfaced. The
/// parity gate requires `desktop ⊇ bench` per question, i.e.
/// `bench.difference(desktop)` is empty.
///
/// Pure over the JSON — unit-tested below; the two transports feed it the
/// identical `message.metadata` shape so one extractor judges both.
fn extract_signals(meta: &serde_json::Value) -> BTreeSet<String> {
    let mut sig = BTreeSet::new();
    if let Some(chunks) = meta.get("retrieved_chunks").and_then(|v| v.as_array()) {
        for c in chunks {
            // `source` discriminates four enrichment legs. project_retrieved_chunks
            // copies it to the top level AND keeps the full map under `metadata`;
            // read the map first, fall back to the top-level mirror.
            let map = c.get("metadata").and_then(|v| v.as_object());
            let source = map
                .and_then(|m| m.get("source"))
                .and_then(|v| v.as_str())
                .or_else(|| c.get("source").and_then(|v| v.as_str()));
            match source {
                Some("atom-enum") => {
                    sig.insert("atom_enum".to_string());
                }
                Some("code_intel_summary") => {
                    sig.insert("code_intel".to_string());
                }
                Some("raptor") => {
                    sig.insert("raptor".to_string());
                }
                Some("bridge_boost") => {
                    sig.insert("cross_corpus_bridge".to_string());
                }
                _ => {}
            }
            if let Some(m) = map {
                if m.get("atom_type").and_then(|v| v.as_str()) == Some("claim") {
                    sig.insert("atom_claim".to_string());
                }
                for k in m.keys() {
                    if let Some(rest) = k.strip_prefix("atlas:") {
                        sig.insert(format!("atlas_tag:{rest}"));
                    }
                }
            }
        }
    }
    // field_model / knowledge_view landscape digests — not chunks. The shared
    // runtime persists the spliced view ids here (Phase 3 ambient field_model +
    // the existing 3-view digests) so this channel is visible across the bridge.
    if let Some(digs) = meta
        .get("knowledge_view_digests")
        .and_then(|v| v.as_array())
    {
        for d in digs {
            if let Some(view) = d.as_str() {
                sig.insert(format!("digest:{view}"));
            }
        }
    }
    sig
}

/// Whether the visible answer is a real answer (non-empty after think-strip).
fn answered(visible: &str) -> bool {
    !visible.trim().is_empty()
}

struct ParityArgs {
    bank: PathBuf,
    corpus: Option<String>,
    bridge_url: String,
    spec: String,
    limit: Option<usize>,
    warm_atlas: bool,
    out: Option<PathBuf>,
}

fn parse_parity_args(rest: &[String]) -> Result<ParityArgs, String> {
    let mut bank: Option<PathBuf> = None;
    let mut corpus = None;
    let mut bridge_url = DEFAULT_BRIDGE_URL.to_string();
    let mut spec = "bench:parity-compare".to_string();
    let mut limit = None;
    let mut warm_atlas = true;
    let mut out: Option<PathBuf> = None;

    let mut i = 0;
    macro_rules! val {
        ($l:expr) => {{
            i += 1;
            rest.get(i)
                .cloned()
                .ok_or_else(|| format!("{} requires a value", $l))?
        }};
    }
    while i < rest.len() {
        match rest[i].as_str() {
            "--bank" => bank = Some(PathBuf::from(val!("--bank"))),
            "--corpus" => corpus = Some(val!("--corpus")),
            "--bridge-url" => bridge_url = val!("--bridge-url"),
            "--spec" => spec = val!("--spec"),
            "--limit" => {
                limit = Some(
                    val!("--limit")
                        .parse()
                        .map_err(|_| "--limit must be a usize")?,
                )
            }
            "--no-warm-atlas" => warm_atlas = false,
            "--out" => out = Some(PathBuf::from(val!("--out"))),
            other => return Err(format!("unknown flag `{other}`")),
        }
        i += 1;
    }
    Ok(ParityArgs {
        bank: bank.ok_or("--bank is required")?,
        corpus,
        bridge_url,
        spec,
        limit,
        warm_atlas,
        out,
    })
}

pub async fn cmd_parity_compare(args: &[String]) -> i32 {
    if args
        .iter()
        .any(|a| a == "--help" || a == "-h" || a == "help")
    {
        help::print(&HELP);
        return 0;
    }
    // Globals first (base-url, dirs), then our flags from the remainder.
    let (mut globals, rest) = match parse_globals(args) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("error: {e}");
            return 2;
        }
    };
    if globals.temperature.is_none() {
        globals.temperature = Some(0.0);
    }
    let pargs = match parse_parity_args(&rest) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {e}");
            help::print(&HELP);
            return 2;
        }
    };

    let bank = match ChaosBank::load(&pargs.bank) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("error: {e}");
            return 1;
        }
    };
    let corpus = match pargs
        .corpus
        .clone()
        .filter(|c| !c.is_empty())
        .or_else(|| Some(bank.meta.corpus.clone()).filter(|c| !c.is_empty()))
    {
        Some(c) => c,
        None => {
            eprintln!("error: no corpus — set --corpus or [meta].corpus in the bank");
            return 1;
        }
    };

    // Bench path: in-process Runtime (delegates inference to the daemon).
    let session = match build_session(&globals).await {
        Ok(s) => s,
        Err(e) => {
            eprintln!(
                "error: could not build bench chat session (is the daemon up at {}?): {e}",
                globals.daemon_base
            );
            return 1;
        }
    };
    // Warm the sealed corpus's atlas into the in-process manager (cache-only
    // build_session would otherwise contribute 0 atlas contexts → the bench side
    // would silently measure base retrieval and the parity diff would be a lie).
    let atlas_warm_entries = if pargs.warm_atlas {
        let n = session.atlas_mgr.warm_one(&corpus).await;
        eprintln!(
            "[parity] atlas-warm: {n} context entr{} loaded for `{corpus}`",
            if n == 1 { "y" } else { "ies" }
        );
        if n == 0 {
            eprintln!(
                "[parity] WARN: atlas warm loaded 0 entries for `{corpus}` — if this corpus has an \
                 atlas, relax the filter (SOVEREIGN_ATLAS_MIN_DESCRIPTION_CHARS=0 \
                 SOVEREIGN_ATLAS_INCLUDE_CLAIMS=1); a stale/atlas-less corpus makes the diff \
                 uninformative (Phase 4 readiness gate flags those)."
            );
        }
        n
    } else {
        0
    };

    // Freshness gate (Phase 4): a corpus whose recipe DECLARES an enrichment the
    // disk lacks (a stale local index) measures a DIFFERENT surface than the
    // recipe promises — a confounded comparison that would read as spurious
    // desktop deficiency. Surface it loudly; the run still proceeds (glassbox
    // over silent skip) but the report records the staleness so CI can gate on it.
    let corpus_stale_reason = session.corpus_engine.enrichment_drift(&corpus).await;
    if let Some(reason) = &corpus_stale_reason {
        eprintln!("[parity] WARN: corpus `{corpus}` looks STALE — {reason}");
        eprintln!(
            "[parity] WARN: the comparison below may be CONFOUNDED by missing enrichment; \
             re-sync/rebuild the corpus for a clean parity run."
        );
    }

    // Desktop path: the real command bridge.
    let client = BridgeClient::new(&pargs.bridge_url);
    if let Err(e) = client.healthz().await {
        eprintln!("error: {e}");
        return 1;
    }
    for ev in ["message-complete", "message-error"] {
        if let Err(e) = client.listen(ev).await {
            eprintln!("error: bridge listen {ev}: {e}");
            return 1;
        }
    }

    eprintln!(
        "[parity] bank={:?} corpus={corpus} questions={} transport: bench(in-process @ {}) vs desktop(bridge @ {})",
        pargs.bank,
        bank.questions.len(),
        globals.daemon_base,
        pargs.bridge_url,
    );

    let take = pargs.limit.unwrap_or(bank.questions.len());
    let mut rows = Vec::new();
    let mut deficient_questions = 0usize;
    let mut bridge_errors = 0usize;

    for (qi, q) in bank.questions.iter().take(take).enumerate() {
        let bench = run_live_pinned(&session, &corpus, &q.question, None).await;
        let bench_sig = extract_signals(&bench.metadata);

        let (desk_sig, desk_answered, desk_gate, bridge_error) =
            match run_bridge_live(&client, Some(&corpus), &q.question, &pargs.spec).await {
                Ok(turn) => {
                    let s = extract_signals(&turn.answer.metadata);
                    (
                        s,
                        answered(&turn.answer.visible),
                        turn.answer.gate_action.clone(),
                        None,
                    )
                }
                Err(e) => {
                    bridge_errors += 1;
                    (BTreeSet::new(), false, None, Some(e))
                }
            };

        let deficient: Vec<String> = bench_sig.difference(&desk_sig).cloned().collect();
        let surplus: Vec<String> = desk_sig.difference(&bench_sig).cloned().collect();
        let is_deficient = !deficient.is_empty() || bridge_error.is_some();
        if is_deficient {
            deficient_questions += 1;
        }

        // Glassbox per-question line.
        let fmt_set = |s: &BTreeSet<String>| -> String {
            if s.is_empty() {
                "{}".to_string()
            } else {
                format!("{{{}}}", s.iter().cloned().collect::<Vec<_>>().join(", "))
            }
        };
        println!("  [{:>2}/{}] {} ({})", qi + 1, take, q.id, q.qtype.label());
        if let Some(err) = &bridge_error {
            println!("         desktop turn ERRORED: {err}");
        }
        eprintln!("         bench   signals: {}", fmt_set(&bench_sig));
        eprintln!("         desktop signals: {}", fmt_set(&desk_sig));
        if is_deficient {
            eprintln!(
                "         -> DESKTOP DEFICIENT: missing {{{}}}  [FAIL]",
                deficient.join(", ")
            );
        } else if !surplus.is_empty() {
            eprintln!(
                "         -> PARITY OK (desktop surplus {{{}}})",
                surplus.join(", ")
            );
        } else {
            eprintln!("         -> PARITY OK");
        }

        rows.push(serde_json::json!({
            "id": q.id,
            "qtype": q.qtype.label(),
            "question": q.question,
            "bench_signals": bench_sig.iter().cloned().collect::<Vec<_>>(),
            "desktop_signals": desk_sig.iter().cloned().collect::<Vec<_>>(),
            "deficient": deficient,
            "surplus": surplus,
            "bench_answered": answered(&bench.visible),
            "desktop_answered": desk_answered,
            "bench_gate": bench.gate_action,
            "desktop_gate": desk_gate,
            "bridge_error": bridge_error,
        }));
    }

    let result = if deficient_questions == 0 {
        "pass"
    } else {
        "fail"
    };
    eprintln!(
        "[parity] SUMMARY: {} questions, {deficient_questions} desktop-deficient, {bridge_errors} bridge-error",
        rows.len(),
    );
    eprintln!(
        "[parity] RESULT: {} ({} questions where desktop surfaced fewer enrichment legs than the bench)",
        result.to_uppercase(),
        deficient_questions,
    );

    let report = serde_json::json!({
        "bank": pargs.bank.to_string_lossy(),
        "corpus": corpus,
        "bridge_url": pargs.bridge_url,
        "base_url": globals.daemon_base,
        "atlas_warm_entries": atlas_warm_entries,
        "corpus_stale": corpus_stale_reason,
        "questions": rows,
        "summary": {
            "total": take.min(bank.questions.len()),
            "deficient_questions": deficient_questions,
            "bridge_errors": bridge_errors,
            "result": result,
        },
    });
    if let Some(out) = &pargs.out {
        if let Some(parent) = out.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        match serde_json::to_string_pretty(&report) {
            Ok(s) => {
                if let Err(e) = std::fs::write(out, s) {
                    eprintln!("[parity] WARN: could not write report {out:?}: {e}");
                } else {
                    eprintln!("[parity] report → {out:?}");
                }
            }
            Err(e) => eprintln!("[parity] WARN: could not serialize report: {e}"),
        }
    }

    if deficient_questions == 0 {
        0
    } else {
        1
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn extracts_atom_enum_and_claim_from_chunk_source() {
        let meta = json!({
            "retrieved_chunks": [
                { "metadata": { "source": "atom-enum", "atom_type": "claim" } },
                { "metadata": { "source": "document" } },
            ]
        });
        let sig = extract_signals(&meta);
        assert!(sig.contains("atom_enum"));
        assert!(sig.contains("atom_claim"));
    }

    #[test]
    fn discriminates_all_four_source_legs_plus_digests() {
        let meta = json!({
            "retrieved_chunks": [
                { "metadata": { "source": "atom-enum" } },
                { "metadata": { "source": "code_intel_summary" } },
                { "metadata": { "source": "raptor" } },
                { "metadata": { "source": "bridge_boost" } },
                { "metadata": { "source": "document", "atlas:topic": "x" } },
            ],
            "knowledge_view_digests": ["personal-knowledge", "field:maple-house"],
        });
        let sig = extract_signals(&meta);
        for want in [
            "atom_enum",
            "code_intel",
            "raptor",
            "cross_corpus_bridge",
            "atlas_tag:topic",
            "digest:personal-knowledge",
            "digest:field:maple-house",
        ] {
            assert!(sig.contains(want), "missing signal {want} in {sig:?}");
        }
    }

    #[test]
    fn top_level_source_mirror_is_a_fallback() {
        // project_retrieved_chunks copies source to the top level; if the map is
        // absent we still catch it.
        let meta = json!({ "retrieved_chunks": [ { "source": "atom-enum" } ] });
        assert!(extract_signals(&meta).contains("atom_enum"));
    }

    #[test]
    fn empty_or_null_metadata_yields_no_signals() {
        assert!(extract_signals(&serde_json::Value::Null).is_empty());
        assert!(extract_signals(&json!({})).is_empty());
        assert!(extract_signals(&json!({ "retrieved_chunks": [] })).is_empty());
    }

    #[test]
    fn parity_gate_is_subset_not_equality() {
        // desktop ⊇ bench passes even with surplus; desktop ⊊ bench fails.
        let bench: BTreeSet<String> = ["atom_enum"].into_iter().map(String::from).collect();
        let desk_ok: BTreeSet<String> = ["atom_enum", "raptor"]
            .into_iter()
            .map(String::from)
            .collect();
        let desk_bad: BTreeSet<String> = ["raptor"].into_iter().map(String::from).collect();
        assert!(
            bench.difference(&desk_ok).next().is_none(),
            "superset should pass"
        );
        assert!(
            bench.difference(&desk_bad).next().is_some(),
            "deficient should fail"
        );
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn bench routing-replay` — replay a routing bank through a
//! live desktop's production chat path and score the intent that
//! ACTUALLY fired, read back from each turn's glassbox metadata
//! (`provenance.intent`).
//!
//! This simultaneously regression-tests routing under the desktop
//! surface AND the glassbox surface itself: a turn whose metadata
//! carries no intent fails the row even if the answer was fine.
//!
//! Scoring is exact-match accuracy per category — the same contract
//! `bench all --routing-only` applies to these banks via the eval
//! runner, projected onto the desktop transport. Routing banks carry
//! `category` labels; the category→Intent mapping below mirrors the
//! bank header's documentation.

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde::Deserialize;

use super::desktop_bridge::{run_bridge_live, BridgeClient, DEFAULT_BRIDGE_URL};
use sovereign_cli_shared::help::{self, Help, HelpSection};

const HELP: Help = Help {
    command: "svrn bench routing-replay",
    summary: "Replay a routing bank through a live desktop (command bridge) and score provenance.intent against the bank's expected categories.",
    sections: &[
        HelpSection::Usage(
            "svrn bench routing-replay --bank <bank.toml> [--bridge-url <url>] [--limit N] [--out <json>]",
        ),
        HelpSection::Notes(
            "Requires a desktop running with SOVEREIGN_COMMAND_BRIDGE=1. Each question runs the FULL \
             production turn (routing + retrieval + synthesis) — slower than the routing-only eval, \
             but it scores what the desktop user actually experiences, and proves the glassbox \
             metadata carries the fired intent.",
        ),
    ],
};

/// Bank categories → the Intent name the runtime records in
/// `provenance.intent`. Mirrors the documented mapping in
/// `sovereign/bench/routing/cells_v1.toml`'s header.
fn expected_intents(category: &str) -> &'static [&'static str] {
    match category {
        "conation" => &["ConationQuery"],
        "commissive" => &["CommissiveQuery"],
        "expressive" => &["ExpressiveQuery"],
        "metalingual" => &["MetalingualQuery"],
        // Structural questions about our own code — "what calls X", "where is
        // Y implemented". Shares the in-system locator with `metalingual` and
        // is separated from it by what the user wants back: a call-graph trace
        // rather than a definition. Added when `skills_migration_smoke` was
        // re-adjudicated against `Intent::CodeQuery`, which post-dates the
        // bank; without an entry here a `category = "code"` question with no
        // `expected_intent` override would expect NOTHING and pass vacuously.
        "code" => &["CodeQuery"],
        "comparative" => &["ComparisonQuery"],
        "factual_recall" => &["KnowledgeQuery", "SimpleQuery"],
        "multi_article_synthesis" => &["DeepQuery"],
        _ => &[],
    }
}

/// Canonicalise an intent name for comparison: lowercase, alphanumerics only.
/// Lets the bank's snake_case `expected_intent` override (`knowledge_query`)
/// match the CamelCase `provenance.intent` the router fires (`KnowledgeQuery`).
fn norm_intent(s: &str) -> String {
    s.chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect()
}

/// Expected intents for a cell. A per-cell `expected_intent` override is
/// AUTHORITATIVE — the bank re-adjudicates specific cells whose category
/// default is wrong for them (e.g. `regression_meta_named_source`, a definition
/// lookup tagged `metalingual` that must RETRIEVE via KnowledgeQuery). Only when
/// no override is present do we fall back to the category→intent mapping. Prior
/// to this the override was ignored, false-failing every re-adjudicated cell.
fn cell_expected(q: &BankQuestion) -> Vec<String> {
    match &q.expected_intent {
        Some(ei) if !ei.trim().is_empty() => vec![ei.clone()],
        _ => expected_intents(&q.category)
            .iter()
            .map(|s| s.to_string())
            .collect(),
    }
}

#[derive(Debug, Deserialize)]
struct Bank {
    #[serde(default)]
    questions: Vec<BankQuestion>,
}

#[derive(Debug, Deserialize)]
struct BankQuestion {
    id: String,
    #[serde(alias = "prompt", alias = "question")]
    question: String,
    #[serde(default)]
    category: String,
    /// Optional per-cell authoritative expected intent (snake_case, e.g.
    /// `knowledge_query`). Overrides the category→intent default when present.
    #[serde(default)]
    expected_intent: Option<String>,
}

pub async fn cmd_routing_replay(args: &[String]) -> i32 {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        help::print(&HELP);
        return 0;
    }
    let mut bank_path: Option<PathBuf> = None;
    let mut bridge_url = DEFAULT_BRIDGE_URL.to_string();
    let mut limit: Option<usize> = None;
    let mut out: Option<PathBuf> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--bank" => {
                i += 1;
                bank_path = args.get(i).map(PathBuf::from);
            }
            "--bridge-url" => {
                i += 1;
                bridge_url = args.get(i).cloned().unwrap_or(bridge_url);
            }
            "--limit" => {
                i += 1;
                limit = args.get(i).and_then(|v| v.parse().ok());
            }
            "--out" => {
                i += 1;
                out = args.get(i).map(PathBuf::from);
            }
            other => {
                eprintln!("error: unknown flag `{other}`");
                return 2;
            }
        }
        i += 1;
    }
    let Some(bank_path) = bank_path else {
        eprintln!("error: --bank is required");
        return 2;
    };

    let text = match std::fs::read_to_string(&bank_path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("error: read {}: {e}", bank_path.display());
            return 1;
        }
    };
    let bank: Bank = match toml::from_str(&text) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("error: parse bank: {e}");
            return 1;
        }
    };
    let known: Vec<&BankQuestion> = bank
        .questions
        .iter()
        .filter(|q| !cell_expected(q).is_empty())
        .collect();
    let skipped = bank.questions.len() - known.len();
    let take = limit.unwrap_or(known.len()).min(known.len());

    let client = BridgeClient::new(&bridge_url);
    if let Err(e) = client.healthz().await {
        eprintln!("error: {e}");
        return 1;
    }
    for ev in ["message-complete", "message-error"] {
        if let Err(e) = client.listen(ev).await {
            eprintln!("error: {e}");
            return 1;
        }
    }
    eprintln!(
        "[routing-replay] bank={} questions={} (skipped {} with unmapped categories) bridge={}",
        bank_path.display(),
        take,
        skipped,
        bridge_url,
    );

    let mut rows: Vec<serde_json::Value> = Vec::new();
    let mut per_category: BTreeMap<String, (usize, usize)> = BTreeMap::new();
    for (qi, q) in known.iter().take(take).enumerate() {
        let turn = run_bridge_live(&client, None, &q.question, "bench:routing-replay").await;
        let (fired, glassbox_ok) = match &turn {
            Ok(t) => {
                // Two metadata contracts coexist: referential handlers
                // attach a full ResponseProvenance (`provenance.intent`),
                // speech-act handlers (conation/commissive/expressive/
                // metalingual) attach a top-level `intent` only.
                let fired = t.metadata["provenance"]["intent"]
                    .as_str()
                    .or_else(|| t.metadata["intent"].as_str())
                    .unwrap_or("")
                    .to_string();
                let ok = !fired.is_empty();
                (fired, ok)
            }
            Err(e) => {
                eprintln!("  [{}] turn failed: {e}", q.id);
                (String::new(), false)
            }
        };
        let expected = cell_expected(q);
        let fired_norm = norm_intent(&fired);
        let pass = glassbox_ok && expected.iter().any(|e| norm_intent(e) == fired_norm);
        let bucket = per_category.entry(q.category.clone()).or_insert((0, 0));
        bucket.1 += 1;
        if pass {
            bucket.0 += 1;
        }
        eprintln!(
            "  [{:>2}/{}] {:<28} {:<14} → {:<16} {}",
            qi + 1,
            take,
            q.id,
            q.category,
            if fired.is_empty() {
                "(no intent!)"
            } else {
                &fired
            },
            if pass { "PASS" } else { "FAIL" },
        );
        rows.push(serde_json::json!({
            "id": q.id,
            "category": q.category,
            "expected": expected,
            "fired": fired,
            "glassbox_intent_present": glassbox_ok,
            "pass": pass,
        }));
    }

    let total = rows.len();
    let passed = rows.iter().filter(|r| r["pass"] == true).count();
    println!("\n── routing-replay (desktop transport) ──");
    for (cat, (p, t)) in &per_category {
        println!("  {:<26} {:>2}/{:<2}", cat, p, t);
    }
    eprintln!(
        "  overall: {passed}/{total} ({:.0}%)",
        if total == 0 {
            0.0
        } else {
            100.0 * passed as f64 / total as f64
        }
    );

    if let Some(out) = out {
        let doc = serde_json::json!({
            "bank": bank_path.display().to_string(),
            "transport": "desktop-bridge",
            "passed": passed,
            "total": total,
            "rows": rows,
        });
        if let Some(parent) = out.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        if let Err(e) = std::fs::write(&out, serde_json::to_string_pretty(&doc).unwrap()) {
            eprintln!("error: write {}: {e}", out.display());
            return 1;
        }
        eprintln!("  wrote {}", out.display());
    }
    if passed == total {
        0
    } else {
        1
    }
}

