    #[test]
    fn live_journeys_sort_by_tier_and_drop_skipped() {
        let c = Contract::parse(
            r#"
[[journey]]
id = "b-specialist"
title = "t"
persona = "developer"
experience = "e"
tier = 5
[[journey]]
id = "a-critical"
title = "t"
persona = "end-user"
experience = "e"
tier = 1
[[journey]]
id = "c-multimachine"
title = "t"
persona = "operator"
experience = "e"
tier = 2
skip_live = "needs a second machine"
"#,
        )
        .expect("parse");
        let live: Vec<&str> = c.live_journeys().iter().map(|j| j.id.as_str()).collect();
