        let (_tmp, reader) = make_atlas();
        let page = reader
            .list_atoms("wiki", AtomFilter::default(), PageCursor::default())
            .await
            .unwrap();
        assert_eq!(page.total_matching, 5);
        assert_eq!(page.items.len(), 5);
        assert!(page.next_offset.is_none());
    }

