// SPDX-License-Identifier: AGPL-3.0-or-later
//! Rule-lane next-edit prediction (`sovereign/docs/NEXT_EDIT.md`
//! §2–§4) — the deterministic half of the two-lane design. Pure: no
//! inference, no state, no editor knowledge. The daemon owns ALL
//! policy (context expansion, guards, induction, firing threshold)
//! so every IDE client stays a thin capture-and-render shell and the
//! JetBrains port inherits the behavior for free.
//!
//! The client streams coalesced edit units (`{before, after}` plus a
//! snippet of untouched context each side, captured at unit close);
//! we induce a literal rewrite rule, count support, threshold on
//! structural confidence, and return the remaining sites as a
//! tab-through queue. A wrong edit proposal is the expensive failure
//! (§1), so every gate here prefers silence.

/// One coalesced edit unit as the client captured it. `left`/`right`
/// are the UNTOUCHED context around the edit site at close time —
/// they make the unit self-contained, so induction never needs the
/// historical document states the edits happened in.
#[derive(Debug, Clone)]
pub struct HistoryUnit {
    pub before: String,
    pub after: String,
    pub left: String,
    pub right: String,
}

/// A literal rewrite rule with per-end identifier guards. A guarded
/// end refuses matches abutting a word character — which both keeps
/// matches out of longer identifiers and keeps a rule from
/// re-matching its own output (`word` → `wordNext`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GuardedRule {
    pub find: String,
    pub replace: String,
    pub guard_left: bool,
    pub guard_right: bool,
}

impl GuardedRule {
    /// Stable identity for client-side session suppression (Esc).
    pub fn key(&self) -> String {
        serde_json::to_string(&[&self.find, &self.replace]).unwrap_or_default()
    }
}

/// One proposed replacement. Offsets are BYTE offsets into the text
/// `predict` was given; the route layer converts to UTF-16 for the
/// wire (`sovereign/docs/NEXT_EDIT.md` §3).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Edit {
    pub start: usize,
    pub end: usize,
    pub new_text: String,
}

/// Outcome of one prediction pass. Silence is a first-class result:
/// `reason_silent` says which gate held (glassbox §9), and `rule` /
/// `support` are still reported when a rule existed but didn't fire.
#[derive(Debug)]
pub struct Prediction {
    pub edits: Vec<Edit>,
    pub rule: Option<GuardedRule>,
    pub support: usize,
    pub sites: usize,
    pub edits_capped: bool,
    pub reason_silent: Option<&'static str>,
}

/// Induction looks at this many most-recent units.
pub const HISTORY_WINDOW: usize = 8;
/// Context absorbed into a rule per side, in chars.
const MAX_CTX: usize = 40;
/// Queue cap — beyond this the debug block reports truncation.
const MAX_EDITS: usize = 256;

fn is_ctx_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '_' | '$' | '.')
}

pub(crate) fn is_word_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// Induce a rule from one unit, absorbing the untouched identifier
/// run (plus a trailing call-paren) on each side: editing
/// `log`→`debug` inside `console.log(` induces `console.log(` →
/// `console.debug(`, not the noisy bare `log`. Returns None for
/// units the rule lane doesn't reason about: no-ops and multi-line
/// edits.
pub fn expand_rule(unit: &HistoryUnit) -> Option<GuardedRule> {
    if unit.before == unit.after {
        return None;
    }
    if unit.before.contains('\n') || unit.after.contains('\n') {
        return None;
    }

    let left_start = unit
        .left
        .char_indices()
        .rev()
        .take(MAX_CTX)
        .take_while(|(_, c)| is_ctx_char(*c))
        .last()
        .map(|(i, _)| i)
        .unwrap_or(unit.left.len());
    let left = &unit.left[left_start..];

    let mut right_end = 0;
    for (i, c) in unit.right.char_indices().take(MAX_CTX) {
        if is_ctx_char(c) {
            right_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    // A trailing call-paren is cheap specificity: it is what
    // separates `console.log(` from the prefix of `console.logger`.
    if unit.right[right_end..].starts_with('(') {
        right_end += 1;
    }
    let right = &unit.right[..right_end];

    let find = format!("{left}{}{right}", unit.before);
    let replace = format!("{left}{}{right}", unit.after);
    if find == replace || find.trim().is_empty() {
        return None;
    }
    let guard_left = find.chars().next().is_some_and(is_word_char);
    let guard_right = find.chars().next_back().is_some_and(is_word_char);
    Some(GuardedRule {
        find,
        replace,
        guard_left,
        guard_right,
    })
}

/// Induce from recent unit rules (oldest first; None = uninducible
/// unit). The rule is always the MOST RECENT unit's — we only ever
/// propose continuing what the user just did — and support counts
/// window agreement rather than strict consecutiveness: a mid-burst
/// settle splits one logical edit into partial-progress units, and
/// strictness would let that noise erase real support.
pub fn induce(rules: &[Option<GuardedRule>]) -> Option<(GuardedRule, usize)> {
    let window_start = rules.len().saturating_sub(HISTORY_WINDOW);
    let recent: Vec<&GuardedRule> = rules[window_start..].iter().flatten().collect();
    let last = (*recent.last()?).clone();
    let support = recent.iter().filter(|r| **r == &last).count();
    Some((last, support))
}

/// Minimum `find` length, in trimmed chars, for a rule to fire. See
/// [`should_fire`] for the measured frontier that chose 5.
///
/// This is not only a filter — it is a ROUTER, and that is the
/// non-obvious thing to know before changing it. Declining a rule here
/// does not end the request: `predict` falls through to the pair kinds
/// ([`induce_insertion`], [`induce_deletion`]), which induce from the
/// SAME history and yield a longer, line-anchored rule. So raising this
/// bar can *increase* useful edits by handing the case to a more
/// specific lane. See [`should_fire`] for the measured example.
const MIN_RULE_CHARS: usize = 5;

/// The firing threshold — the whole "when may the system interrupt"
/// policy in one place (§4): never without a remaining site, never on
/// one supporting edit, never on a rule too short to be specific.
///
/// **The support tier is gone, and that is a result rather than a
/// simplification for its own sake.** The policy used to read "2
/// supports fire only a specific rule (≥4 chars); 3+ lower the bar (≥2)".
/// Once the curve below chose 2 for the support-2 case, the two arms
/// held the same condition and the distinction stopped distinguishing
/// anything — so it is one condition now.
///
/// [`MIN_RULE_CHARS`] went 4 → 2 → 5 in one day, and the reversal is
/// not a flip-flop: **the objective changed.** The 4→2 move maximised
/// `useful-fire`, which the scorer defines as `useful + partial`
/// (`score_golden.py:297`) — so it rewards a rule that fires wide and
/// happens to be right somewhere. Told that a user simply does not
/// accept a wrong fire, the right question stopped being "what
/// maximises the headline" and became "what is the most useful we can
/// be at each level of wrong". On that question the value 2 is
/// dominated outright.
///
/// Swept at 3 rule kinds over the whole golden set
/// (`gym/next-edit/golden/`, 1,098 cases, model lane off), reporting
/// STRICT useful — every proposed hunk one the author actually made —
/// beside the wrong count, rather than the headline:
///
/// | min | strict useful | wrong (of which negatives) |
/// |-----|---------------|----------------------------|
/// |  2  | 138           | 52 (32)                    |  <- dominated
/// |  4  | 139           | 48 (28)                    |
/// |  5  | 141           | 39 (27)                    |  <- chosen
/// |  6  | 143           | 38 (27)                    |
/// |  8  | 133           | 35 (24)                    |
/// | 16  | 116           | 17 ( 7)                    |
///
/// 5 rather than 6 because 141-vs-143 is inside sampling noise
/// (Wilson on 138/711 is ±2.9pts ≈ ±21 cases) while the wrong-fire
/// plateau starts at 5 — the value is chosen on the plateau's edge,
/// not on an argmax over 168 swept cells, which one bank cannot
/// support. Note `c97bf8cd` carries the frontier and the port.
///
/// WHY A STRICTER BAR YIELDS MORE USEFUL, which is the counter-
/// intuitive part: declining the short rule ROUTES the case to the
/// pair kinds, which re-induce from the same history and anchor on a
/// whole line. `fetch` → `-c core.fsmonitor=false fetch` matched 62
/// sites and scored `partial`; the anchored rule the fallback induces
/// instead, `` `git `` → `` `git -c core.fsmonitor=false ``, matches 8
/// and scores `useful`. Paired ledger for this move: 31 partial→missed,
/// 9 partial→useful, 7 useful→missed, and 14 wrong fires removed.
pub fn should_fire(rule: &GuardedRule, support: usize, remaining_sites: usize) -> bool {
    if remaining_sites < 1 {
        return false;
    }
    support >= 2 && rule.find.trim().chars().count() >= MIN_RULE_CHARS
}

/// Ceiling on an induced rule's `find`/`replace`. Rules come from
/// coalesced keystroke bursts plus a bounded context expansion, so a
/// real one is tens of bytes; the wire's 2 KiB-per-field allowance is
/// slack for the *unit*, not a licence for the rule derived from it.
const MAX_RULE_BYTES: usize = 512;
/// A replacement that contains its own target more than this many
/// times is not an edit pattern, it is a pathological input: each
/// occurrence is an alignment that must be probed at every site.
const MAX_ALIGNMENTS: usize = 8;
/// Ceiling on matches examined while scanning for sites. The queue
/// itself is capped at [`MAX_EDITS`] (256), so a file with more
/// occurrences than this is already past the point where more
/// scanning changes what the user sees.
const MAX_SITE_SCAN: usize = 4096;

/// Offsets at which `find` sits inside `replace` — the alignments an
/// occurrence of `find` could occupy within an already-applied
/// `replace`. `None` means the rule is degenerate (too many
/// alignments to probe); callers decline it rather than pay
/// occurrences × sites of comparison.
fn alignments(find: &str, replace: &str) -> Option<Vec<usize>> {
    if find == replace || !replace.contains(find) {
        return Some(Vec::new());
    }
    let mut out = Vec::new();
    let mut start = 0;
    while let Some(f) = replace[start..].find(find).map(|i| start + i) {
        if out.len() == MAX_ALIGNMENTS {
            return None;
        }
        out.push(f);
        start = f + 1;
    }
    Some(out)
}

/// True when the occurrence of `find` at `o` sits inside an existing
/// instance of `replace`, at one of the precomputed `aligns` — i.e.
/// the user already made this edit here. Only possible for
/// insertion-shaped rules (`replace` contains `find`): those leave
/// `find` matching at every already-edited site, and re-proposing one
/// would stack the insertion (`await fetch(` → `await await fetch(`).
///
/// The alignments are computed once per rule, never once per site:
/// doing it per site made this quadratic in the rule's self-similarity
/// and turned a single request into 23 s of blocking CPU on a crafted
/// input (measured 2026-07-30 at 512 KiB of text).
fn already_applied(text: &str, o: usize, aligns: &[usize], replace: &str) -> bool {
    aligns.iter().any(|&f| {
        o.checked_sub(f)
            .is_some_and(|b| text.get(b..b + replace.len()) == Some(replace))
    })
}

/// Non-overlapping byte offsets of the rule's `find` in `text`,
/// ordered as a tab-through queue: document order from `from`,
/// wrapping to the sites before it. Sites the rule was already
/// applied to are excluded (see [`already_applied`]).
pub fn find_guarded_sites(text: &str, rule: &GuardedRule, from: usize) -> Vec<usize> {
    let find = rule.find.as_str();
    if find.is_empty() || find.len() > MAX_RULE_BYTES || rule.replace.len() > MAX_RULE_BYTES {
        return Vec::new();
    }
    let Some(aligns) = alignments(find, &rule.replace) else {
        return Vec::new();
    };
    let mut all = Vec::new();
    let mut at = 0;
    let mut examined = 0usize;
    while let Some(rel) = text[at..].find(find) {
        examined += 1;
        if examined > MAX_SITE_SCAN {
            break;
        }
        let o = at + rel;
        let left_ok = !rule.guard_left || !text[..o].chars().next_back().is_some_and(is_word_char);
        let right_ok = !rule.guard_right
            || !text[o + find.len()..]
                .chars()
                .next()
                .is_some_and(is_word_char);
        if left_ok && right_ok && !already_applied(text, o, &aligns, &rule.replace) {
            all.push(o);
        }
        at = o + find.len();
    }
    let split = all.partition_point(|&o| o < from);
    let mut out = all.split_off(split);
    out.extend(all);
    out
}

/// Induce an ANCHORED REPEAT-INSERTION from a pair of insertions —
/// the second rule kind, added 2026-08-06.
///
/// [`expand_rule`] induces from ONE unit and always yields a rewrite:
/// some `find` that occurs in the document is replaced. An insertion
/// has no `find` — the developer typed a block that was not there
/// before — so the single-unit induction cannot express it at all, and
/// returns `None`. That hole is the largest single gap on the golden
/// set: pure-INSERT truths scored 14.0% against 44.6% for replacements,
/// and forcing a model at them moved nothing (`gym/next-edit/golden/`,
/// note `53abe423`).
///
/// What a PAIR buys is the anchor. Two insertions of the same block
/// tell us both *what* to insert (the shared payload) and *where* (the
/// longest common line-aligned tail of their left contexts). Rendered
/// as `find = anchor`, `replace = anchor + payload`, the result is an
/// ordinary insertion-shaped [`GuardedRule`], so site finding, the
/// already-applied exclusion, the firing threshold and the edit queue
/// all apply unchanged — this adds a way to *induce*, not a second
/// pipeline to keep in step.
///
/// Measured as a fallback behind the literal lane: **+21 useful edits
/// for 2 wrong fires, nothing regressed, and 0 wrong fires across the
/// 387 negatives** (15 missed→useful, 6 missed→partial, 2 missed→wrong).
///
/// Word guards are off by construction: the anchor is line-aligned, so
/// its boundaries are newlines rather than identifier edges, and a word
/// guard there would reject every site.
pub fn induce_insertion(history: &[HistoryUnit]) -> Option<GuardedRule> {
    let [a, b] = match history {
        [.., a, b] => [a, b],
        _ => return None,
    };
    // Both units must be pure insertions carrying the SAME payload.
    // A per-site-varying payload is a different shape (`param_insert`)
    // and guessing which variant belongs at an unseen site is exactly
    // the inference this lane refuses to do.
    if !a.before.is_empty() || !b.before.is_empty() {
        return None;
    }
    if a.after != b.after || a.after.trim().is_empty() {
        return None;
    }
    let payload = &a.after;
    if payload.len() > MAX_RULE_BYTES {
        return None;
    }

    // The anchor is the longest common TAIL of the two left contexts,
    // trimmed forward to a line boundary. Cutting to a whole line is
    // what makes the anchor mean "after this line" rather than "after
    // this arbitrary suffix of a line", which would match mid-token.
    let (la, lb) = (a.left.as_bytes(), b.left.as_bytes());
    let mut n = 0;
    while n < la.len().min(lb.len()) && la[la.len() - 1 - n] == lb[lb.len() - 1 - n] {
        n += 1;
    }
    let mut anchor = match a.left.get(a.left.len() - n..) {
        Some(s) => s,
        // The common tail landed inside a multi-byte char; back off to
        // the nearest boundary rather than slicing a char in half.
        None => return None,
    };
    if let Some(i) = anchor.find('\n') {
        anchor = &anchor[i + 1..];
    }
    if anchor.trim().chars().count() < MIN_ANCHOR_CHARS || anchor.len() > MAX_RULE_BYTES {
        return None;
    }

    Some(GuardedRule {
        find: anchor.to_string(),
        replace: format!("{anchor}{payload}"),
        guard_left: false,
        guard_right: false,
    })
}

/// Induce a REPEAT BLOCK DELETION from a pair of identical deletions —
/// the third rule kind, and deliberately the narrowest.
///
/// A deletion is expressible as a [`GuardedRule`] (`replace` empty), so
/// [`expand_rule`] would already reach these but for its multi-line
/// guard. The guard is right to be there: measured against the 387
/// negatives, deleting on a *single*-line repeat fires wrongly 13 times
/// (`neg_exhausted` ×8, `neg_literal_trap` ×5), because a short literal
/// recurs innocently all over a document and a wrong deletion is the
/// most destructive edit this system can make.
///
/// Requiring the repeated block to be MULTI-LINE removes every one of
/// those: at ≥2 lines the bank measures 0 wrong fires on negatives and
/// 0 wrong on positives, for +5 useful edits. That is a small win taken
/// at zero measured risk, not a general deletion capability.
///
/// **What this deliberately does NOT do.** `delete_propagation`'s real
/// shape on the golden set is a developer bulk-removing a *run* of
/// sibling blocks, where each block differs and the truth is "remove
/// the rest of the list" — knowing where the list ends is a structural
/// judgment, not a repeat. The two obvious generalisations were
/// measured and rejected: identifier-scoped line deletion scores 2.9%
/// useful with 14 wrong fires on negatives, and single-line repeat
/// deletion 50% with 13. Neither is a trade this lane makes; 38 of the
/// 43 `delete_propagation` episodes stay open (note `53abe423`).
pub fn induce_deletion(history: &[HistoryUnit]) -> Option<GuardedRule> {
    let [a, b] = match history {
        [.., a, b] => [a, b],
        _ => return None,
    };
    if !a.after.is_empty() || !b.after.is_empty() {
        return None;
    }
    if a.before != b.before || a.before.trim().is_empty() {
        return None;
    }
    if a.before.lines().count() < MIN_DELETE_LINES || a.before.len() > MAX_RULE_BYTES {
        return None;
    }
    Some(GuardedRule {
        find: a.before.clone(),
        replace: String::new(),
        guard_left: false,
        guard_right: false,
    })
}

/// Minimum repeated-block size for [`induce_deletion`], in lines. At 1
/// the bank measures 13 wrong fires on negatives; at 2, zero.
const MIN_DELETE_LINES: usize = 2;

/// Minimum anchor length for [`induce_insertion`]. An anchor shorter
/// than this is not specific enough to name a site — it would match
/// punctuation runs and blank structure all over the document.
const MIN_ANCHOR_CHARS: usize = 3;

/// The whole rule-lane pipeline: history → rule → sites → threshold
/// → queue. `cursor` is a byte offset into `text`.
pub fn predict(history: &[HistoryUnit], text: &str, cursor: usize) -> Prediction {
    let silent = |reason, rule: Option<GuardedRule>, support, sites| Prediction {
        edits: Vec::new(),
        rule,
        support,
        sites,
        edits_capped: false,
        reason_silent: Some(reason),
    };

    // The literal lane first; the insertion lane only picks up what it
    // declines. Ordering matters: where both could speak the literal
    // rule is the more specific claim, and letting the anchor lane
    // preempt it measured as pure loss (11 cases the literal lane
    // already won).
    let fire = |rule: GuardedRule, support, sites: Vec<usize>| Prediction {
        edits_capped: sites.len() > MAX_EDITS,
        sites: sites.len(),
        support,
        edits: sites
            .iter()
            .take(MAX_EDITS)
            .map(|&s| Edit {
                start: s,
                end: s + rule.find.len(),
                new_text: rule.replace.clone(),
            })
            .collect(),
        rule: Some(rule),
        reason_silent: None,
    };
    // An insertion pair is its own support: two units agreeing on one
    // payload IS the repetition the threshold exists to require, so
    // `should_fire`'s length bar (written for rewrites) does not apply.
    // The anchor carries the specificity instead, via MIN_ANCHOR_CHARS.
    let insertion = |reason, rule: Option<GuardedRule>, support, n_sites| {
        for pair_rule in [induce_insertion(history), induce_deletion(history)]
            .into_iter()
            .flatten()
        {
            let sites = keep(&pair_rule, find_guarded_sites(text, &pair_rule, cursor));
            if !sites.is_empty() {
                return fire(pair_rule, 2, sites);
            }
        }
        silent(reason, rule, support, n_sites)
    };

    let rules: Vec<Option<GuardedRule>> = history.iter().map(expand_rule).collect();
    let Some((rule, support)) = induce(&rules) else {
        return insertion("no_rule", None, 0, 0);
    };
    let sites = keep(&rule, find_guarded_sites(text, &rule, cursor));
    if !should_fire(&rule, support, sites.len()) {
        let reason = if sites.is_empty() {
            "no_sites"
        } else {
            "below_threshold"
        };
        return insertion(reason, Some(rule), support, sites.len());
    }
    let edits: Vec<Edit> = sites
        .iter()
        .take(MAX_EDITS)
        .map(|&s| Edit {
            start: s,
            end: s + rule.find.len(),
            new_text: rule.replace.clone(),
        })
        .collect();
    Prediction {
        edits_capped: sites.len() > MAX_EDITS,
        sites: sites.len(),
        support,
        rule: Some(rule),
        edits,
        reason_silent: None,
    }
}

// ---- UTF-16 ↔ byte offset mapping ------------------------------------
//
// The wire contract (§3) is UTF-16 code units — the native offset
// space of every editor client we serve — while all Rust-side work is
// byte offsets. Conversion lives here, next to the code that makes it
// necessary.

/// Byte offset for a UTF-16 code-unit offset, clamped into the text.
pub fn utf16_to_byte(text: &str, utf16: usize) -> usize {
    let mut u = 0;
    for (i, c) in text.char_indices() {
        if u >= utf16 {
            return i;
        }
        u += c.len_utf16();
    }
    text.len()
}

/// UTF-16 code-unit offsets for the given byte offsets (any order),
/// in one pass over the text. Offsets inside a char round down.
pub fn bytes_to_utf16(text: &str, byte_offsets: &[usize]) -> Vec<usize> {
    let mut sorted: Vec<usize> = byte_offsets.to_vec();
    sorted.sort_unstable();
    sorted.dedup();
    let mut map = std::collections::HashMap::new();
    let mut next = sorted.iter().copied().peekable();
    let mut u = 0;
    for (i, c) in text.char_indices() {
        while next.peek().is_some_and(|&b| b <= i) {
            map.insert(next.next().unwrap(), u);
        }
        u += c.len_utf16();
    }
    for b in next {
        map.insert(b, u);
    }
    byte_offsets.iter().map(|b| map[b]).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn unit(before: &str, after: &str, left: &str, right: &str) -> HistoryUnit {
        HistoryUnit {
            before: before.into(),
            after: after.into(),
            left: left.into(),
            right: right.into(),
        }
    }

    fn console_rule() -> GuardedRule {
        expand_rule(&unit("log", "debug", "  console.", "(\"a\");")).unwrap()
    }

    #[test]
    fn expand_absorbs_member_access_and_call_paren() {
        let r = console_rule();
        assert_eq!(r.find, "console.log(");
        assert_eq!(r.replace, "console.debug(");
        assert!(r.guard_left, "identifier start must be guarded");
        assert!(!r.guard_right, "call paren needs no guard");
    }

    #[test]
    fn expand_guards_pure_identifier_rename_both_ends() {
        // inserted "Next" after "count": `count` → `countNext`
        let r = expand_rule(&unit("", "Next", "let count", " = count + 1;")).unwrap();
        assert_eq!(r.find, "count");
        assert_eq!(r.replace, "countNext");
        assert!(r.guard_left && r.guard_right);
        // the guards prevent the rule re-matching its own output
        assert_eq!(
            find_guarded_sites("let countNext = countNext + 1;", &r, 0),
            Vec::<usize>::new()
        );
    }

    #[test]
    fn expand_declines_noops_and_multiline() {
        assert!(expand_rule(&unit("b", "b", "a", "c")).is_none());
        assert!(expand_rule(&unit("x", "\n", "a", "c")).is_none());
    }

    #[test]
    fn induce_anchors_most_recent_and_window_counts() {
        let a = Some(console_rule());
        let b = expand_rule(&unit("foo", "bar", " ", " "));
        let got = induce(&[a.clone(), b, None, a.clone()]).unwrap();
        assert_eq!(got.0, console_rule());
        assert_eq!(got.1, 2, "support survives interleaved noise");
        assert!(induce(&[]).is_none());
        assert!(induce(&[None, None]).is_none());
    }

    #[test]
    fn threshold_table() {
        let specific = console_rule(); // find len 12
        let short = GuardedRule {
            find: "ab".into(),
            replace: "ax".into(),
            guard_left: true,
            guard_right: true,
        };
        let single = GuardedRule {
            find: "a".into(),
            replace: "x".into(),
            guard_left: true,
            guard_right: true,
        };
        let at_bar = GuardedRule {
            find: "abcde".into(), // exactly MIN_RULE_CHARS
            replace: "abcdx".into(),
            guard_left: true,
            guard_right: true,
        };
        let under_bar = GuardedRule {
            find: "abcd".into(), // one short
            replace: "abcx".into(),
            guard_left: true,
            guard_right: true,
        };
        assert!(!should_fire(&specific, 5, 0), "never without a site");
        assert!(should_fire(&specific, 2, 1));
        assert!(!should_fire(&specific, 1, 10), "one edit never fires");
        // The minimum `find` is 5 trimmed chars, RAISED from 2 on the
        // measured frontier (see `should_fire`): at 2 the config is
        // Pareto-dominated — 138 strict-useful against 52 wrong fires,
        // where 5 gets 141 against 39. Pin both sides of the bar so the
        // constant cannot drift without a test saying so.
        assert!(should_fire(&at_bar, 2, 10), "a rule at the bar fires");
        assert!(
            !should_fire(&under_bar, 2, 10),
            "one char under the bar does not"
        );
        assert!(
            !should_fire(&short, 2, 10),
            "a two-char rule is the literal trap"
        );
        assert!(
            !should_fire(&single, 2, 10),
            "one-char rule is never specific enough"
        );
        assert!(
            !should_fire(&single, 9, 10),
            "and no amount of support rescues it"
        );
        // The support tier stayed collapsed across the 2→5 move: more
        // support still does not buy a shorter rule.
        assert_eq!(should_fire(&short, 2, 10), should_fire(&short, 7, 10));
        assert_eq!(
            should_fire(&under_bar, 2, 10),
            should_fire(&under_bar, 9, 10)
        );
    }

    /// Two insertions of one block, at siblings differing only in the
    /// value on the anchor line.
    fn insert_pair() -> Vec<HistoryUnit> {
        vec![
            unit(
                "",
                "  retries: 3,\n",
                "a = {\n  port: 1,\n  os: linux,\n",
                "};\n",
            ),
            unit(
                "",
                "  retries: 3,\n",
                "b = {\n  port: 2,\n  os: linux,\n",
                "};\n",
            ),
        ]
    }

    const INSERT_ANCHOR: &str = "  os: linux,\n";

    #[test]
    fn insertion_induces_an_anchored_rule() {
        let r = induce_insertion(&insert_pair()).expect("pair induces");
        // The anchor is the common line-aligned tail — the shared line
        // that precedes both insertion points. The differing `port:`
        // lines above it are not part of what the contexts agree on.
        assert_eq!(r.find, INSERT_ANCHOR);
        assert_eq!(r.replace, format!("{}{}", r.find, "  retries: 3,\n"));
        assert!(
            !r.guard_left && !r.guard_right,
            "line anchors have no word boundaries"
        );
    }

    #[test]
    fn insertion_refuses_what_it_cannot_know() {
        // Per-site-varying payload: which variant belongs at an unseen
        // site is a guess, and this lane does not guess.
        let varying = vec![
            unit("", "  retries: 3,\n", "a = {\n  port: 1,\n", "};\n"),
            unit("", "  retries: 9,\n", "b = {\n  port: 2,\n", "};\n"),
        ];
        assert!(
            induce_insertion(&varying).is_none(),
            "varying payload is param_insert's shape"
        );

        // Not a pure insertion — that is a rewrite, and `expand_rule`
        // already owns it.
        let rewrite = vec![
            unit("log", "debug", "console.", "(1);"),
            unit("log", "debug", "console.", "(2);"),
        ];
        assert!(induce_insertion(&rewrite).is_none());

        // Nothing in common to anchor on.
        let unanchored = vec![
            unit("", "x\n", "totally\n", ""),
            unit("", "x\n", "different\n", ""),
        ];
        assert!(
            induce_insertion(&unanchored).is_none(),
            "an anchor must be specific"
        );

        assert!(induce_insertion(&[]).is_none());
    }

    #[test]
    fn insertion_is_a_fallback_and_never_preempts_the_literal_lane() {
        // Literal lane declines (no rule from a bare insertion), so the
        // anchor lane fires on the remaining sibling.
        let text = "a = {\n  port: 1,\n  os: linux,\n  retries: 3,\n};\n\
                    b = {\n  port: 2,\n  os: linux,\n  retries: 3,\n};\n\
                    c = {\n  port: 3,\n  os: linux,\n};\n";
        let p = predict(&insert_pair(), text, 0);
        assert!(
            p.reason_silent.is_none(),
            "anchor lane fires where the literal lane cannot"
        );
        assert_eq!(p.edits.len(), 1, "only the site still missing the block");
        assert_eq!(
            p.edits[0].new_text,
            format!("{INSERT_ANCHOR}  retries: 3,\n")
        );

        // A site that already carries the payload is excluded, so a
        // fully-propagated document stays silent rather than stacking.
        let done = "a = {\n  port: 1,\n  os: linux,\n  retries: 3,\n};\n";
        let q = predict(&insert_pair(), done, 0);
        assert!(
            q.edits.is_empty(),
            "already-applied sites are not re-proposed"
        );

        // And where the literal lane DOES fire it keeps the floor: the
        // more specific claim wins.
        let owns = vec![
            unit("log", "debug", "console.", "(1);"),
            unit("log", "debug", "console.", "(2);"),
        ];
        let r = predict(&owns, "console.log(3);\n", 0);
        assert_eq!(r.rule.as_ref().unwrap().find, "console.log(");
    }

    #[test]
    fn deletion_repeats_only_multi_line_blocks() {
        let block = "  legacy: true,\n  deprecated: yes,\n";
        let pair = vec![
            unit(block, "", "a = {\n", "};\n"),
            unit(block, "", "b = {\n", "};\n"),
        ];
        let r = induce_deletion(&pair).expect("multi-line repeat induces");
        assert_eq!(r.find, block);
        assert!(r.replace.is_empty(), "a deletion is an empty replace");

        // ONE line is refused: measured at 13 wrong fires across the
        // bank's negatives, because a short literal recurs innocently.
        let one = vec![
            unit("  legacy: true,\n", "", "a = {\n", "};\n"),
            unit("  legacy: true,\n", "", "b = {\n", "};\n"),
        ];
        assert!(
            induce_deletion(&one).is_none(),
            "single-line deletion repeat is not safe"
        );

        // Differing blocks are a bulk-removal run, not a repeat — the
        // shape this lane explicitly does not attempt.
        let differing = vec![
            unit("  a: 1,\n  b: 2,\n", "", "x = {\n", "};\n"),
            unit("  c: 3,\n  d: 4,\n", "", "y = {\n", "};\n"),
        ];
        assert!(induce_deletion(&differing).is_none());

        // Not a deletion at all.
        assert!(induce_deletion(&insert_pair()).is_none());
    }

    fn bare_rule(find: &str, replace: &str) -> GuardedRule {
        GuardedRule {
            find: find.into(),
            replace: replace.into(),
            guard_left: false,
            guard_right: false,
        }
    }

    #[test]
    fn sites_order_after_cursor_then_wrap() {
        let text = "log a\nlog b\nlog c\n";
        assert_eq!(
            find_guarded_sites(text, &bare_rule("log", "dbg"), 3),
            vec![6, 12, 0]
        );
        // non-overlapping stepping
        assert_eq!(
            find_guarded_sites("aaaa", &bare_rule("aa", "bb"), 0),
            vec![0, 2]
        );
    }

    #[test]
    fn insertion_rule_skips_already_applied_sites() {
        // `fetch(` → `await fetch(`: replace CONTAINS find, so edited
        // lines still match textually — re-proposing them would stack
        // the insertion. Found by gym/next-edit case a11 (2026-07-30).
        let text = "a = await fetch(u1)\nb = await fetch(u2)\nc = fetch(u3)\nd = fetch(u4)\n";
        let u = unit("", "await ", "b = ", "fetch(u2)");
        let p = predict(&[u.clone(), u], text, 0);
        assert!(p.reason_silent.is_none());
        assert_eq!(p.edits.len(), 2, "only the two un-edited sites");
        for e in &p.edits {
            assert_eq!(&text[e.start..e.end], "fetch(");
            assert!(
                !text[..e.start].ends_with("await "),
                "already-edited site re-proposed"
            );
        }
        // Deletion-shaped rules (find contains replace) are unaffected.
        let d = expand_rule(&unit(".unwrap()", "", "res", ";")).unwrap();
        assert_eq!(find_guarded_sites("res;\nres.unwrap();\n", &d, 0), vec![5]);
    }

    /// The already-applied probe used to re-derive `find`'s positions
    /// inside `replace` at EVERY site, so a self-similar rule over a
    /// large file was quadratic: a crafted 512 KiB request measured
    /// 23 s of blocking CPU on one tokio worker, needing no model lane
    /// and no opt-in to reach. Rules this shape are declined, and the
    /// site scan is bounded regardless.
    #[test]
    fn pathological_rules_cannot_wedge_the_scan() {
        let text = "(".repeat(512 * 1024);
        let degenerate = bare_rule("(", &format!("{}{}", "(".repeat(2047), ")"));
        let t0 = std::time::Instant::now();
        assert!(
            find_guarded_sites(&text, &degenerate, 0).is_empty(),
            "a replacement containing its own target 2047 times is not an edit pattern"
        );
        // Same file, a rule that is merely common rather than
        // degenerate: bounded work, still a usable queue.
        let common = bare_rule("(", "(x");
        let sites = find_guarded_sites(&text, &common, 0);
        assert!(!sites.is_empty() && sites.len() <= MAX_SITE_SCAN);
        assert!(
            t0.elapsed() < std::time::Duration::from_secs(2),
            "bounded work, not seconds of blocking CPU (took {:?})",
            t0.elapsed()
        );
        // An oversized induced rule is refused outright.
        assert!(find_guarded_sites("abc", &bare_rule(&"a".repeat(600), "b"), 0).is_empty());
    }

    #[test]
    fn predict_end_to_end_console_case() {
        // Two sites already edited (units), three remain; cursor after
        // the second edit.
        let text = "console.debug(1);\nconsole.debug(2);\nconsole.log(3);\nconsole.log(4);\nconsole.log(5);\n";
        let u = unit("log", "debug", "console.", "(2);");
        let p = predict(&[u.clone(), u], text, 30);
        assert!(p.reason_silent.is_none());
        assert_eq!(p.support, 2);
        assert_eq!(p.sites, 3);
        assert_eq!(p.edits.len(), 3);
        let first = &p.edits[0];
        assert_eq!(&text[first.start..first.end], "console.log(");
        assert_eq!(first.new_text, "console.debug(");
    }

    #[test]
    fn predict_silences_carry_reasons() {
        assert_eq!(predict(&[], "x", 0).reason_silent, Some("no_rule"));
        let u = unit("log", "debug", "console.", "(1);");
        // one support only
        assert_eq!(
            predict(&[u.clone()], "console.log(9);", 0).reason_silent,
            Some("below_threshold")
        );
        // rule supported but no sites left
        let p = predict(&[u.clone(), u], "console.debug(9);", 0);
        assert_eq!(p.reason_silent, Some("no_sites"));
        assert_eq!(p.support, 2);
    }

    #[test]
    fn utf16_mapping_round_trips_past_astral_chars() {
        // "a💡b" — '💡' is 4 bytes / 2 UTF-16 units.
        let text = "a💡bc";
        assert_eq!(utf16_to_byte(text, 0), 0);
        assert_eq!(utf16_to_byte(text, 1), 1);
        assert_eq!(utf16_to_byte(text, 3), 5); // past the emoji
        assert_eq!(utf16_to_byte(text, 99), text.len());
        assert_eq!(bytes_to_utf16(text, &[5, 0, 1, 6, 7]), vec![3, 0, 1, 4, 5]);
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Model-lane next-edit prediction (`sovereign/docs/NEXT_EDIT.md` §2,
//! §4, §8 P2) — the pure half: consult gate, needle derivation, region
//! selection, prompt shaping, output parsing, and region diffing. No
//! inference here; the route layer owns the `LocalInferenceService`
//! call and threads its output through [`parse_rewrite`] +
//! [`diff_region`].
//!
//! The gate is deterministic and mirrored by the Python replica in
//! `gym/next-edit/gen/author.py` — a divergence fails the §6
//! generalization bank loudly whichever side is wrong. Every check
//! prefers silence: the model is consulted only when the rule lane
//! declined AND the recent units are similar-but-not-identical, and a
//! model output that fails validation is dropped, not repaired.

use crate::next_edit::{
    expand_rule, find_guarded_sites, GuardedRule, HistoryUnit, Prediction, HISTORY_WINDOW,
};

/// Total lines in the rewrite region handed to the model.
pub const REGION_LINES: usize = 24;
/// Byte ceiling on that same region. Lines bound it for ordinary
/// source; bytes bound it for files that are mostly one line (a
/// minified bundle is a single 512 KiB line, and `text` is capped at
/// 512 KiB, so without this the "24-line" region is the whole file
/// and the prompt is ~1 MiB of prefill on the shared slot).
pub const MAX_REGION_BYTES: usize = 8 * 1024;
/// Per-side context fed to the needle's longest-common-substring
/// search. The needle is a short anchor (`MIN_NEEDLE` is 3), so the
/// quadratic DP never needs the full 2 KiB-per-field the wire allows.
const MAX_NEEDLE_CTX: usize = 192;
/// Two per-site-varying replacements must share this many prefix chars.
const MIN_PARAM_PREFIX: usize = 4;
/// A shorter needle is noise, not an anchor.
const MIN_NEEDLE: usize = 3;
/// Most-recent real units rendered into the prompt.
const MAX_PROMPT_UNITS: usize = 4;
/// A rewrite growing the region beyond this is a runaway, not an edit.
const MAX_GROWTH_BYTES: usize = 2048;
/// …and so is one that shrinks it by more than this. The growth cap
/// alone is one-sided: a truncated or lazy completion is *smaller*
/// than the region, and without this a single accepted hunk could
/// delete almost the whole region (measured 2026-07-30: 480 KiB
/// deleted from a 24-line region whose line count was unchanged).
const MAX_SHRINK_BYTES: usize = 2048;
/// A rewrite adding/removing more lines than this is a runaway.
const MAX_LINE_DELTA: usize = 16;

/// One region-relative proposed replacement (route adds the region
/// origin before converting to the UTF-16 wire).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RegionEdit {
    pub start: usize,
    pub end: usize,
    pub new_text: String,
}

/// Outcome of the consult gate — glassbox either way.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Consult {
    No {
        skipped: &'static str,
    },
    Yes {
        reason: &'static str,
        needle: Option<String>,
    },
}

// ---- casing renderings ------------------------------------------------

const STYLES: [Style; 4] = [Style::Snake, Style::Screaming, Style::Camel, Style::Pascal];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Style {
    Snake,
    Screaming,
    Camel,
    Pascal,
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// `getUserData` → `[get, user, data]`; `PARSE_ARGS` → `[parse, args]`.
fn split_words(run: &str) -> Vec<String> {
    let mut words = Vec::new();
    for piece in run.split('_') {
        let mut w = String::new();
        for ch in piece.chars() {
            if !w.is_empty() && ch.is_uppercase() && !w.chars().next_back().unwrap().is_uppercase()
            {
                words.push(w);
                w = String::new();
            }
            w.push(ch);
        }
        if !w.is_empty() {
            words.push(w);
        }
    }
    words.iter().map(|w| w.to_lowercase()).collect()
}

fn render_words(words: &[String], style: Style) -> String {
    fn cap(w: &str) -> String {
        let mut cs = w.chars();
        match cs.next() {
            Some(c) => c.to_uppercase().collect::<String>() + cs.as_str(),
            None => String::new(),
        }
    }
    match style {
        Style::Snake => words.join("_"),
        Style::Screaming => words
            .iter()
            .map(|w| w.to_uppercase())
            .collect::<Vec<_>>()
            .join("_"),
        Style::Camel => {
            let mut out = words.first().cloned().unwrap_or_default();
            for w in &words[1.min(words.len())..] {
                out.push_str(&cap(w));
            }
            out
        }
        Style::Pascal => words.iter().map(|w| cap(w)).collect(),
    }
}

/// Re-render every identifier run of `s` in `style`, separators verbatim.
fn restyle(s: &str, style: Style) -> String {
    let mut out = String::with_capacity(s.len() + 8);
    let mut run = String::new();
    for c in s.chars() {
        if is_word(c) {
            run.push(c);
        } else {
            if !run.is_empty() {
                out.push_str(&render_words(&split_words(&run), style));
                run.clear();
            }
            out.push(c);
        }
    }
    if !run.is_empty() {
        out.push_str(&render_words(&split_words(&run), style));
    }
    out
}

/// First casing rendering of `rule.find` with a live guarded site in
/// `text` (styles probed in fixed order; already-applied sites of the
/// same-styled replace are excluded, mirroring the rule lane).
fn casing_variant_needle(text: &str, rule: &GuardedRule) -> Option<String> {
    for style in STYLES {
        let vfind = restyle(&rule.find, style);
        if vfind == rule.find {
            continue;
        }
        let vrule = GuardedRule {
            guard_left: vfind
                .chars()
                .next()
                .is_some_and(crate::next_edit::is_word_char),
            guard_right: vfind
                .chars()
                .next_back()
                .is_some_and(crate::next_edit::is_word_char),
            replace: restyle(&rule.replace, style),
            find: vfind,
        };
        if !find_guarded_sites(text, &vrule, 0).is_empty() {
            return Some(vrule.find);
        }
    }
    None
}

// ---- similarity helpers ----------------------------------------------

fn common_prefix_len(a: &str, b: &str) -> usize {
    a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count()
}

/// Longest common substring (chars). Callers MUST bound the inputs:
/// this is an O(n·m) DP on a request-path thread with no `.await` in
/// it, and the wire allows 2 KiB per unit field.
fn lcsubstr(a: &str, b: &str) -> String {
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    let mut best_len = 0usize;
    let mut best_end = 0usize;
    // Two rolling rows, reused — not one allocation per row.
    let mut prev = vec![0usize; bc.len() + 1];
    let mut cur = vec![0usize; bc.len() + 1];
    for i in 1..=ac.len() {
        cur.fill(0);
        for j in 1..=bc.len() {
            if ac[i - 1] == bc[j - 1] {
                cur[j] = prev[j - 1] + 1;
                if cur[j] > best_len {
                    best_len = cur[j];
                    best_end = i;
                }
            }
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    ac[best_end - best_len..best_end].iter().collect()
}

/// Last `n` chars of `s` (char-boundary safe).
fn tail(s: &str, n: usize) -> &str {
    match s.char_indices().nth_back(n.saturating_sub(1)) {
        Some((i, _)) if s.chars().count() > n => &s[i..],
        _ => s,
    }
}

/// First `n` chars of `s` (char-boundary safe).
fn head(s: &str, n: usize) -> &str {
    match s.char_indices().nth(n) {
        Some((i, _)) => &s[..i],
        None => s,
    }
}

/// The needle anchors a region; it is drawn from the text immediately
/// around each edit, so only the nearest [`MAX_NEEDLE_CTX`] chars per
/// side can contribute. Bounding here keeps [`lcsubstr`] off the
/// wire's full 6 KiB-per-unit worst case.
fn ctx_needle(a: &HistoryUnit, b: &HistoryUnit) -> Option<String> {
    let near = |u: &HistoryUnit| {
        format!(
            "{}{}{}",
            tail(&u.left, MAX_NEEDLE_CTX),
            head(&u.before, MAX_NEEDLE_CTX),
            head(&u.right, MAX_NEEDLE_CTX)
        )
    };
    let s = lcsubstr(&near(a), &near(b)).trim().to_string();
    (s.chars().count() >= MIN_NEEDLE).then_some(s)
}

// ---- the consult gate -------------------------------------------------

/// The two most recent content-bearing units in the history window —
/// the exemplars every consult shape is defined over, `(most recent,
/// second most recent)`. Shared by [`should_consult`] (which decides
/// FROM them) and [`verify_pattern`] (which holds the model's output
/// TO them), so the two stages can never disagree about which edits
/// form the pattern.
pub fn exemplar_pair(history: &[HistoryUnit]) -> Option<(&HistoryUnit, &HistoryUnit)> {
    let window_start = history.len().saturating_sub(HISTORY_WINDOW);
    let cores: Vec<&HistoryUnit> = history[window_start..]
        .iter()
        .filter(|u| u.before != u.after)
        .collect();
    if cores.len() < 2 {
        return None;
    }
    Some((cores[cores.len() - 1], cores[cores.len() - 2]))
}

/// Decide whether the model lane may be consulted. `p` is the rule
/// lane's outcome on the same request; a fired rule lane always wins.
pub fn should_consult(history: &[HistoryUnit], text: &str, p: &Prediction) -> Consult {
    if !p.edits.is_empty() {
        return Consult::No {
            skipped: "rule_fired",
        };
    }
    let Some((a, b)) = exemplar_pair(history) else {
        return Consult::No { skipped: "gate" };
    };
    let (ra, rb) = (expand_rule(a), expand_rule(b));

    // 1. Casing variant: a real, exhausted literal rule whose rename
    // remains at another casing of the same token sequence. DETECTED
    // but DEFERRED in v1: bank runs 1–2 (2026-07-30) showed Mellum2
    // destructive on exactly this shape — 4 of 9 casing fires wrong
    // (block deletion, reversed rename) against 0 of 60 wrong
    // everywhere else, and a casing-specific instruction made it
    // worse, not better. The variant find/replace computed here is
    // fully deterministic, so the right home for this category is a
    // rule-engine sub-lane, not a model consult; until that exists
    // the gate declines, by name.
    if p.reason_silent == Some("no_sites") && p.support >= 2 {
        if let Some(rule) = p.rule.as_ref() {
            if casing_variant_needle(text, rule).is_some() {
                return Consult::No {
                    skipped: "casing_deferred",
                };
            }
        }
    }

    let multiline = |u: &HistoryUnit| u.before.contains('\n') || u.after.contains('\n');

    // 2. Multiline fan-out: identical multi-line insertion at two sites —
    // uninducible by design, but unmistakably one pattern.
    if ra.is_none()
        && rb.is_none()
        && multiline(a)
        && multiline(b)
        && a.before == b.before
        && a.after == b.after
        && a.after.trim().chars().count() >= MIN_NEEDLE
    {
        return Consult::Yes {
            reason: "multiline_fanout",
            needle: ctx_needle(a, b),
        };
    }

    // 3 & 4. DETECTED but DECLINED, by name, on the golden set's
    // verdict (note 2c22ec10, `gym/next-edit/golden/`, 1,098 cases).
    // Scored per admitting gate rather than per bank shape, the three
    // consult reasons do not perform alike — they are three different
    // bets wearing one name:
    //
    //   multiline_fanout   18 spoke   17 useful   1 wrong   94.4%
    //   fanout_insert      19 spoke    2 useful  17 wrong   10.5%
    //   param_insert        8 spoke    2 useful   6 wrong   25.0%
    //
    // Silencing the bottom two moves the lane from 45 fires / 24 wrong
    // to 18 fires / 1 wrong, and moves the system from 36.0% useful /
    // 21.0% wrong-fire to 35.4% / 15.2% — i.e. it keeps nearly all the
    // model's contribution at a LOWER wrong-fire than switching the
    // model lane off entirely (33.1% / 15.8%). `fanout_insert` was also
    // the path by which 7 of the `neg_literal_trap` wrong fires reached
    // the model.
    //
    // The detection stays live and the decline is named so the
    // admission table still counts how often these shapes occur — that
    // count is what a re-open has to argue against. Flip condition and
    // review-by: `sovereign/DEFAULTS_LEDGER.md`.
    if let (Some(ra), Some(rb)) = (&ra, &rb) {
        if ra != rb && a.before == b.before {
            if a.after == b.after {
                return Consult::No {
                    skipped: "fanout_insert_deferred",
                };
            }
            if common_prefix_len(&a.after, &b.after) >= MIN_PARAM_PREFIX {
                return Consult::No {
                    skipped: "param_insert_deferred",
                };
            }
        }
    }
    Consult::No { skipped: "gate" }
}

// ---- region selection -------------------------------------------------

/// Byte range of the ~[`REGION_LINES`]-line window the model may
/// rewrite, anchored on the needle's next occurrence from the cursor
/// (wrapping), else on the cursor line. Returns `(start, end,
/// needle_hit)`; the range always ends on a line boundary (or EOF).
pub fn select_region(text: &str, cursor: usize, needle: Option<&str>) -> (usize, usize, bool) {
    let anchor = needle.filter(|n| !n.is_empty()).and_then(|n| {
        text.get(cursor..)
            .and_then(|t| t.find(n).map(|i| cursor + i))
            .or_else(|| text.get(..cursor).and_then(|t| t.rfind(n)))
    });
    let hit = anchor.is_some();
    let target = anchor.unwrap_or_else(|| cursor.min(text.len()));

    let starts: Vec<usize> = std::iter::once(0)
        .chain(
            text.char_indices()
                .filter(|(_, c)| *c == '\n')
                .map(|(i, _)| i + 1),
        )
        .collect();
    let line_count = if text.ends_with('\n') {
        starts.len() - 1
    } else {
        starts.len()
    };
    let target_line = starts.partition_point(|&s| s <= target).saturating_sub(1);
    // Center on the target, then slide up at EOF so the window keeps
    // its full height whenever the document allows it.
    let first = target_line
        .saturating_sub(REGION_LINES / 2 - 1)
        .min(line_count.saturating_sub(REGION_LINES));
    let start = starts[first.min(starts.len() - 1)];
    let end = starts
        .get(first + REGION_LINES)
        .copied()
        .unwrap_or(text.len());
    if end - start <= MAX_REGION_BYTES {
        return (start, end, hit);
    }
    // Over the byte budget: rebuild the window by growing outward from
    // the target line while both budgets hold. Ordinary source never
    // reaches this branch (24 lines is far under 8 KiB), so region
    // selection is unchanged for every real file. When even the target
    // line alone exceeds the budget the region stays that one line and
    // the route declines it (`region_too_large`) rather than prefilling
    // a megabyte nobody can read.
    let line_end = |l: usize| starts.get(l + 1).copied().unwrap_or(text.len());
    let (mut lo, mut hi) = (target_line, target_line);
    let mut used = line_end(target_line) - starts[target_line];
    loop {
        let mut grew = false;
        if lo > 0 && hi - lo + 1 < REGION_LINES {
            let add = starts[lo] - starts[lo - 1];
            if used + add <= MAX_REGION_BYTES {
                lo -= 1;
                used += add;
                grew = true;
            }
        }
        if hi + 1 < line_count && hi - lo + 1 < REGION_LINES {
            let add = line_end(hi + 1) - starts[hi + 1];
            if used + add <= MAX_REGION_BYTES {
                hi += 1;
                used += add;
                grew = true;
            }
        }
        if !grew {
            break;
        }
    }
    (starts[lo], line_end(hi), hit)
}

// ---- prompt -----------------------------------------------------------

pub const REGION_START_MARKER: &str = "<|editable_region_start|>";
pub const REGION_END_MARKER: &str = "<|editable_region_end|>";

// ---- bakeoff formats: zeta2 / sweep raw prompts -----------------------
//
// Completion-style edit models speak their fine-tune's own contract,
// not ours. Each format below reproduces the model's published prompt
// shape exactly (Zeta 2.1 model card; Sweep's run_model.py) and rides
// the FIM slot's raw path (`FimCompletionRequest.raw_prompt`,
// `FimMode::Verbatim`). Format selection is explicit config
// (`[models.fim].next_edit_format`) — see NEXT_EDIT.md.

// Zeta 2.x brackets its editable region with GIT-MERGE markers, not
// with `<|marker_N|>` sentinels. Corrected 2026-08-05 against the
// canonical `sample.prompt` / `sample.output` in `zed-industries/zeta-2`
// itself; the previous constants were written from a model-card
// description and had never been run against the weights. The bakeoff's
// first zeta-2 arm scored 0/30 with 19 `invalid` + 11 `truncated` — a
// 100% parse failure, which is what an unexercised dialect looks like.
/// Zeta 2.x editable-region open marker.
pub const ZETA_MARKER_1: &str = "<<<<<<< CURRENT";
/// Zeta 2.x separator: the prompt ends here and the model writes the
/// UPDATED side after `<[fim-middle]>`.
pub const ZETA_MARKER_2: &str = "=======";
/// Zeta 2.x terminator the model emits after the rewritten region. Also
/// the stop string — without it a completion runs to the token ceiling
/// and lands as `truncated`.
pub const ZETA_UPDATED_END: &str = ">>>>>>> UPDATED";
/// Zeta 2.x cursor position marker, inserted inside the region.
pub const ZETA_CURSOR: &str = "<|user_cursor|>";
const ZETA_FIM_PREFIX: &str = "<[fim-prefix]>";
const ZETA_FIM_SUFFIX: &str = "<[fim-suffix]>";
const ZETA_FIM_MIDDLE: &str = "<[fim-middle]>";
/// Sweep's section separator (a Qwen2.5-Coder special token).
pub const SWEEP_FILE_SEP: &str = "<|file_sep|>";
/// File-context windows around the region in raw prompts, in bytes.
/// Same role as the FIM slot's prefix/suffix clamps: bound the
/// prefill an adversarial file can buy.
const RAW_PREFIX_WINDOW: usize = 4096;
const RAW_SUFFIX_WINDOW: usize = 2048;

/// Keep the TAIL of `s` beyond `max` bytes (char-boundary safe).
fn tail_bytes(s: &str, max: usize) -> &str {
    if s.len() <= max {
        s
    } else {
        &s[s.ceil_char_boundary(s.len() - max)..]
    }
}

/// Keep the HEAD of `s` up to `max` bytes (char-boundary safe).
fn head_bytes(s: &str, max: usize) -> &str {
    if s.len() <= max {
        s
    } else {
        &s[..s.floor_char_boundary(max)]
    }
}

/// The edit-history units every prompt format shows: the same window
/// the consult gate judged (`should_consult`) — showing a model units
/// the gate never looked at would let it generalize from a pattern
/// nothing authorized — trimmed to the newest [`MAX_PROMPT_UNITS`]
/// real edits.
fn shown_units(history: &[HistoryUnit]) -> Vec<&HistoryUnit> {
    let window = &history[history.len().saturating_sub(HISTORY_WINDOW)..];
    let cores: Vec<&HistoryUnit> = window.iter().filter(|u| u.before != u.after).collect();
    cores[cores.len().saturating_sub(MAX_PROMPT_UNITS)..].to_vec()
}

/// Zeta-shaped instruct prompt: edit history as diff snippets + the
/// marker-bracketed region, output = the rewritten region. `reason` is
/// the consult-gate verdict — casing consults carry an extra
/// instruction, because the first bank run showed the model either
/// ignores cross-casing renames or turns destructive on them
/// (gym/next-edit/gen, run 1: cv01 deleted an unrelated block, cv07
/// applied the rename backwards).
pub fn build_prompt(
    history: &[HistoryUnit],
    region: &str,
    path: Option<&str>,
    language: Option<&str>,
    reason: &str,
) -> String {
    let mut p = String::with_capacity(region.len() * 2 + 512);
    p.push_str(
        "You are the next-edit engine of a code editor. \
         The developer just made these edits, oldest first:\n",
    );
    let shown = shown_units(history);
    for (i, u) in shown.iter().enumerate() {
        p.push_str(&format!(
            "\nEdit {}:\n-{}{}{}\n+{}{}{}\n",
            i + 1,
            u.left,
            u.before,
            u.right,
            u.left,
            u.after,
            u.right
        ));
    }
    let file = match (path, language) {
        (Some(pa), Some(l)) => format!("`{pa}` ({l})"),
        (Some(pa), None) => format!("`{pa}`"),
        (None, Some(l)) => format!("a {l} file"),
        (None, None) => "the file".to_string(),
    };
    let casing_note = if reason == "casing_variant" {
        "The developer's rename may also apply to identifiers spelled in \
         other casing styles (snake_case, camelCase, PascalCase, \
         SCREAMING_SNAKE). Apply the same rename to those too, keeping \
         each identifier's existing casing style. "
    } else {
        ""
    };
    p.push_str(&format!(
        "\nContinue the developer's pattern. Below is a region of {file}. \
         Rewrite it, applying the developer's pattern wherever it applies \
         within the region. {casing_note}Make ONLY edits that continue \
         the pattern, in the same direction the developer made them: \
         never undo their edits, never delete or rewrite unrelated code, \
         never add anything the pattern does not call for. Reply with \
         ONLY the rewritten region — every line of it, no markers, no \
         code fence, no explanation. If the pattern applies nowhere in \
         the region, reply with the region exactly \
         unchanged.\n\n{REGION_START_MARKER}\n{region}{REGION_END_MARKER}\n",
    ));
    p
}

/// Zeta 2.x raw prompt (model card, SPM ordering): suffix section,
/// then prefix section carrying the edit history as unified-diff
/// snippets and the target file's code before the region, then the
/// marker-bracketed editable region with the cursor marker, then the
/// generation marker. `rs..re` is the region's byte range in `text`;
/// `cursor` a byte offset (marker inserted only when it falls inside
/// the region — a needle-anchored region away from the cursor has no
/// honest cursor position to mark).
pub fn build_prompt_zeta2(
    history: &[HistoryUnit],
    text: &str,
    rs: usize,
    re: usize,
    cursor: usize,
    path: Option<&str>,
) -> String {
    let region = &text[rs..re];
    let prefix_win = tail_bytes(&text[..rs], RAW_PREFIX_WINDOW);
    let suffix_win = head_bytes(&text[re..], RAW_SUFFIX_WINDOW);
    let path = path.unwrap_or("untitled");
    let mut p = String::with_capacity(region.len() * 2 + prefix_win.len() + suffix_win.len() + 512);
    p.push_str(ZETA_FIM_SUFFIX);
    p.push('\n');
    p.push_str(suffix_win);
    if !suffix_win.is_empty() && !suffix_win.ends_with('\n') {
        p.push('\n');
    }
    p.push_str(ZETA_FIM_PREFIX);
    p.push_str("<filename>edit_history\n");
    for u in shown_units(history) {
        p.push_str(&format!("--- a/{path}\n+++ b/{path}\n"));
        let old = format!("{}{}{}", u.left, u.before, u.right);
        let new = format!("{}{}{}", u.left, u.after, u.right);
        for l in old.lines() {
            p.push('-');
            p.push_str(l);
            p.push('\n');
        }
        for l in new.lines() {
            p.push('+');
            p.push_str(l);
            p.push('\n');
        }
    }
    p.push_str(&format!("\n<filename>{path}\n"));
    p.push_str(prefix_win);
    if !prefix_win.is_empty() && !prefix_win.ends_with('\n') {
        p.push('\n');
    }
    p.push_str(ZETA_MARKER_1);
    p.push('\n');
    if cursor >= rs && cursor <= re {
        p.push_str(&region[..cursor - rs]);
        p.push_str(ZETA_CURSOR);
        p.push_str(&region[cursor - rs..]);
    } else {
        p.push_str(region);
    }
    if !region.ends_with('\n') {
        p.push('\n');
    }
    p.push_str(ZETA_MARKER_2);
    p.push('\n');
    p.push_str(ZETA_FIM_MIDDLE);
    p
}

/// Sweep raw prompt (run_model.py): `<|file_sep|>` sections — one
/// `.diff` original/updated block per history unit, then the region
/// before the most recent edit (`original/`), the region as it stands
/// (`current/`), and the `updated/` header the model completes.
/// Sections joined by `\n`, matching the reference builder exactly.
pub fn build_prompt_sweep(history: &[HistoryUnit], region: &str, path: Option<&str>) -> String {
    let path = path.unwrap_or("untitled");
    let shown = shown_units(history);
    let mut parts: Vec<String> = Vec::new();
    for u in &shown {
        parts.push(format!("{SWEEP_FILE_SEP}{path}.diff"));
        parts.push("original:".to_string());
        parts.push(format!("{}{}{}", u.left, u.before, u.right));
        parts.push("updated:".to_string());
        parts.push(format!("{}{}{}", u.left, u.after, u.right));
    }
    // Sweep's training format encodes momentum as original→current:
    // `current/` includes the most recent edit, `original/` predates
    // it. Reconstruct that when the edit's site lies inside the
    // region; when it doesn't (region away from the edit), the two
    // sections are honestly identical.
    let original = shown
        .last()
        .and_then(|u| unapply_in_region(region, u))
        .unwrap_or_else(|| region.to_string());
    parts.push(format!("{SWEEP_FILE_SEP}original/{path}"));
    parts.push(original);
    parts.push(format!("{SWEEP_FILE_SEP}current/{path}"));
    parts.push(region.to_string());
    parts.push(format!("{SWEEP_FILE_SEP}updated/{path}"));
    parts.join("\n")
}

/// Reverse one history unit inside the region: find its post-edit
/// text (`left+after+right`) and restore the pre-edit text at that
/// one site. `None` when the site isn't in the region (or the unit
/// carries no change), so the caller falls back to the region itself.
fn unapply_in_region(region: &str, u: &HistoryUnit) -> Option<String> {
    let cur = format!("{}{}{}", u.left, u.after, u.right);
    let old = format!("{}{}{}", u.left, u.before, u.right);
    if cur.is_empty() || cur == old {
        return None;
    }
    let i = region.find(&cur)?;
    let mut out = String::with_capacity(region.len() + old.len());
    out.push_str(&region[..i]);
    out.push_str(&old);
    out.push_str(&region[i + cur.len()..]);
    Some(out)
}

/// Instinct's fixed system turn and user preamble, held verbatim as
/// assets rather than inlined: they are a third party's trained
/// contract, not our prose, so they must be reproducible byte-for-byte
/// and diffable when Continue revises them (ARCH §6.2).
pub const INSTINCT_SYSTEM: &str = include_str!("prompts/instinct_system.txt");
const INSTINCT_USER_PREAMBLE: &str = include_str!("prompts/instinct_user_preamble.txt");
const INSTINCT_CURSOR: &str = "<|user_cursor_is_here|>";

/// Instinct chat prompt, reproduced from its published training data
/// (`continuedev/instinct-data`, `test_typescript`): a fixed system
/// turn, then a user turn of `### Context:` / `### User Edits:` /
/// `### User Excerpt:`.
///
/// Instinct ships NO wire dialect of its own — its GGUF carries the
/// stock Qwen2.5-Coder ChatML template — so the training data is the
/// only authoritative source for its shape.
///
/// Three details are load-bearing, and getting them wrong is why the
/// Phase 0 run scored 0/30 (`bench/next-edit-bakeoff/RESULTS_PHASE0.md`
/// records that as could-not-judge, a statement about our integration):
///
/// 1. Instinct's system prompt orders edit history **most recent
///    first**. `shown_units` is oldest-first, so it is reversed here.
/// 2. Instinct is trained to emit the region **without** the markers
///    ("Do not include the tags in your output"). `parse_rewrite`
///    already requires exactly that, so this format needs no parser of
///    its own — and `region_instruct`'s "if the pattern applies
///    nowhere, reply with the region unchanged" instruction, which
///    Instinct was never trained on, is precisely what produced its 18
///    echoed `noop`s.
/// 3. The cursor is marked in-band with [`INSTINCT_CURSOR`], inside the
///    editable region only.
///
/// `### Context:` stays even though this pipeline carries no cross-file
/// snippets: every training row has the header, and an adapter that
/// silently drops a section of the trained shape is the same class of
/// bug as #1.
pub fn build_prompt_instinct(
    history: &[HistoryUnit],
    text: &str,
    rs: usize,
    re: usize,
    cursor: usize,
    path: Option<&str>,
) -> String {
    let region = &text[rs..re];
    let prefix_win = tail_bytes(&text[..rs], RAW_PREFIX_WINDOW);
    let suffix_win = head_bytes(&text[re..], RAW_SUFFIX_WINDOW);
    let path = path.unwrap_or("untitled");
    let mut p = String::with_capacity(region.len() * 2 + prefix_win.len() + suffix_win.len() + 1024);
    p.push_str(INSTINCT_USER_PREAMBLE);
    p.push_str("### Context:\n\n");
    p.push_str("### User Edits:\n\n");
    for u in shown_units(history).into_iter().rev() {
        p.push_str(&format!("User edited file \"{path}\"\n\n```diff\n"));
        let old = format!("{}{}{}", u.left, u.before, u.right);
        let new = format!("{}{}{}", u.left, u.after, u.right);
        for l in old.lines() {
            p.push('-');
            p.push_str(l);
            p.push('\n');
        }
        for l in new.lines() {
            p.push('+');
            p.push_str(l);
            p.push('\n');
        }
        p.push_str("```\n\n");
    }
    p.push_str(&format!("### User Excerpt:\n\"{path}\"\n\n"));
    p.push_str(prefix_win);
    if !prefix_win.is_empty() && !prefix_win.ends_with('\n') {
        p.push('\n');
    }
    p.push_str(REGION_START_MARKER);
    p.push('\n');
    if cursor >= rs && cursor <= re {
        p.push_str(&region[..cursor - rs]);
        p.push_str(INSTINCT_CURSOR);
        p.push_str(&region[cursor - rs..]);
    } else {
        p.push_str(region);
    }
    if !region.ends_with('\n') {
        p.push('\n');
    }
    p.push_str(REGION_END_MARKER);
    p.push('\n');
    p.push_str(suffix_win);
    p
}

// ---- output parsing ---------------------------------------------------

/// Validate + normalize the model's output into a rewritten region.
/// Errors are glassbox drop reasons (`sovereign_debug.model.dropped`):
/// no suggestion beats a wrong one, so anything suspicious is dropped
/// whole — never repaired into a partial edit.
pub fn parse_rewrite(raw: &str, region: &str) -> Result<String, &'static str> {
    let mut out = raw;
    // Thinking-model preamble (alias mode can route to a chat model).
    if let Some(rest) = out.trim_start().strip_prefix("<think>") {
        out = match rest.split_once("</think>") {
            Some((_, tail)) => tail,
            None => return Err("invalid"),
        };
    }
    let mut s = out.trim_start_matches('\n').to_string();
    // One wrapping code fence, with or without a language tag — and
    // nothing else. Prose outside the fence, or a second fenced block
    // with commentary between, is a chat reply rather than a region;
    // repairing it would splice the commentary into the user's file.
    // Closing on the FIRST fence, not the last, is what stops that.
    let t = s.trim();
    if t.starts_with("```") {
        let inner = t.trim_start_matches("```");
        let body = inner.split_once('\n').map(|(_, b)| b).unwrap_or("");
        let Some(i) = body.find("```") else {
            return Err("invalid");
        };
        if !body[i + 3..].trim().is_empty() {
            return Err("invalid");
        }
        s = body[..i].to_string();
    } else if t.contains("```") {
        return Err("invalid");
    }
    // Echoed markers are malformed, whole stop. An earlier version
    // stripped marker-only lines and rebuilt the output from
    // `lines()`, which silently deleted any real file line that
    // happened to BE a marker and rewrote every line ending on the
    // way through — repairing suspicious output into a confident
    // wrong edit, which is exactly the trade this lane refuses.
    if s.contains("editable_region") {
        return Err("invalid");
    }
    validate_rewrite(s, region)
}

/// Format-agnostic rewrite validation — the guards every prompt
/// format shares, applied after the format-specific unwrap. The
/// region is the authority for line endings and trailing newline;
/// growth/shrink/line-delta bounds are the same bars the §6 bank
/// gates were pre-registered against, so a format adapter can never
/// quietly relax them.
fn validate_rewrite(mut s: String, region: &str) -> Result<String, &'static str> {
    // Line endings: a CRLF region against an LF rewrite makes every
    // line differ, so the line-LCS collapses to one hunk spanning the
    // whole region — the model gets free rein over code it never
    // meant to touch, and a faithful echo stops registering as a noop.
    if region.contains("\r\n") {
        s = s.replace("\r\n", "\n").replace('\n', "\r\n");
    }
    // Trailing newline, both directions: the region is the authority.
    if region.ends_with('\n') && !s.ends_with('\n') {
        s.push('\n');
    } else if !region.ends_with('\n') && s.ends_with('\n') {
        s.truncate(s.trim_end_matches('\n').trim_end_matches('\r').len());
    }
    if s.trim().is_empty() {
        return Err("invalid");
    }
    if s.len() > region.len() + MAX_GROWTH_BYTES {
        return Err("invalid");
    }
    // Shrink is bounded two ways because one bound is not enough: the
    // absolute cap catches a big region truncated mid-rewrite, and the
    // proportional one catches a small region gutted in place (20
    // lines of code replaced by 20 lines of `//` loses far less than
    // 2 KiB, and its line delta is zero). Continuing an edit pattern
    // never halves the region.
    if s.len() + MAX_SHRINK_BYTES < region.len() || s.len() * 2 < region.len() {
        return Err("invalid");
    }
    let delta = (s.lines().count() as i64 - region.lines().count() as i64).unsigned_abs() as usize;
    if delta > MAX_LINE_DELTA {
        return Err("invalid");
    }
    if s == region {
        return Err("noop");
    }
    Ok(s)
}

/// Parse a Zeta 2.x completion. The prompt ends at `=======` +
/// `<[fim-middle]>`, so the model resumes with the UPDATED side
/// **bare** — no opening marker — and terminates it with
/// `>>>>>>> UPDATED`.
///
/// The terminator is not *required* here, because it is also the stop
/// string: llama.cpp consumes a matched stop rather than returning it,
/// so demanding it would fail every well-formed completion. An
/// unterminated run-on is already refused upstream — `finish` drops
/// `finish_reason == "length"` before parsing — so absence here means
/// the decode ended cleanly on stop or EOS.
pub fn parse_rewrite_zeta2(raw: &str, region: &str) -> Result<String, &'static str> {
    let body = match raw.find(ZETA_UPDATED_END) {
        Some(end) => {
            // Past the terminator, anything but whitespace is prose.
            if !raw[end + ZETA_UPDATED_END.len()..].trim().is_empty() {
                return Err("invalid");
            }
            &raw[..end]
        }
        None => raw,
    };
    let mut content = body.strip_suffix('\n').unwrap_or(body).to_string();
    if let Some(i) = content.find(ZETA_CURSOR) {
        content.replace_range(i..i + ZETA_CURSOR.len(), "");
    }
    // A second cursor, a re-emitted region marker, or a leaked FIM
    // sentinel all mean the model is writing protocol rather than code.
    if content.contains(ZETA_CURSOR)
        || content.contains(ZETA_MARKER_1)
        || content.contains(ZETA_UPDATED_END)
        || content.contains("<[fim-")
    {
        return Err("invalid");
    }
    validate_rewrite(content, region)
}

/// Parse a Sweep completion: the rewritten window, terminated by
/// `<|file_sep|>` or `</s>` when the stop tracker didn't already
/// consume them. The completion begins on the line after the
/// `updated/{path}` header, so exactly one leading newline is part of
/// the format, not the rewrite.
pub fn parse_rewrite_sweep(raw: &str, region: &str) -> Result<String, &'static str> {
    let mut s = raw;
    if let Some(i) = s.find(SWEEP_FILE_SEP) {
        s = &s[..i];
    }
    if let Some(i) = s.find("</s>") {
        s = &s[..i];
    }
    let s = s.strip_prefix('\n').unwrap_or(s);
    validate_rewrite(s.to_string(), region)
}

// ---- region diff ------------------------------------------------------

/// Line-LCS diff of the region against its rewrite, one [`RegionEdit`]
/// per contiguous hunk (char-trimmed), in document order — the same
/// tab-through queue shape the rule lane produces.
pub fn diff_region(orig: &str, new: &str) -> Vec<RegionEdit> {
    let o: Vec<&str> = orig.split_inclusive('\n').collect();
    let n: Vec<&str> = new.split_inclusive('\n').collect();
    // LCS table over lines.
    let mut dp = vec![vec![0usize; n.len() + 1]; o.len() + 1];
    for i in (0..o.len()).rev() {
        for j in (0..n.len()).rev() {
            dp[i][j] = if o[i] == n[j] {
                dp[i + 1][j + 1] + 1
            } else {
                dp[i + 1][j].max(dp[i][j + 1])
            };
        }
    }
    let mut opos = Vec::with_capacity(o.len() + 1);
    let mut acc = 0;
    for l in &o {
        opos.push(acc);
        acc += l.len();
    }
    opos.push(acc);

    let mut edits = Vec::new();
    let (mut i, mut j) = (0usize, 0usize);
    let mut hunk_start: Option<(usize, usize)> = None;
    loop {
        let matched =
            i < o.len() && j < n.len() && o[i] == n[j] && dp[i][j] == dp[i + 1][j + 1] + 1;
        if matched || (i >= o.len() && j >= n.len()) {
            if let Some((hi, hj)) = hunk_start.take() {
                let old_start = opos[hi];
                let old_end = opos[i];
                let new_text: String = n[hj..j].concat();
                edits.push(trim_hunk(orig, old_start, old_end, new_text));
            }
            if i >= o.len() && j >= n.len() {
                break;
            }
            i += 1;
            j += 1;
        } else {
            if hunk_start.is_none() {
                hunk_start = Some((i, j));
            }
            if i < o.len() && (j >= n.len() || dp[i + 1][j] >= dp[i][j + 1]) {
                i += 1;
            } else {
                j += 1;
            }
        }
    }
    edits
}

/// Char-level prefix/suffix trim inside one hunk, keeping offsets on
/// char boundaries.
fn trim_hunk(orig: &str, old_start: usize, old_end: usize, new_text: String) -> RegionEdit {
    let old = &orig[old_start..old_end];
    let mut p = 0;
    for (co, cn) in old.chars().zip(new_text.chars()) {
        if co != cn {
            break;
        }
        p += co.len_utf8();
    }
    let mut s = 0;
    for (co, cn) in old[p..].chars().rev().zip(new_text[p..].chars().rev()) {
        if co != cn {
            break;
        }
        s += co.len_utf8();
    }
    RegionEdit {
        start: old_start + p,
        end: old_end - s,
        new_text: new_text[p..new_text.len() - s].to_string(),
    }
}

// ---- V0 content verifier ----------------------------------------------
//
// The structural guards bound HOW MUCH the model may change; nothing
// above bounds WHAT the change says. But the gate only consults when
// the exemplars agree on a transformation, and for the identical-core
// shapes that transformation fixes the correct content: remove the
// exemplars' `before`, add their `after` (for `param_insert`, the
// shared prefix of the two `after`s — the tails vary per site and are
// deliberately not judged here). Every check below is a predicate the
// gate's own shape definitions imply, so the verifier generalizes
// exactly as far as the gate does — it knows nothing any bank case
// taught it.

/// What the exemplar transformation adds, in a countable form: the
/// content with every whitespace run collapsed to one space. Both
/// the pattern and the text are normalized the same way before
/// substring counting, so neither indentation drift at a new site
/// nor the line-fragment shape of an exemplar (an `after` like
/// `",\n    \"retries\": 3"` STARTS mid-line — its leading comma
/// belongs to the previous line in situ, so no line-wise matcher can
/// ever see it) can hide content the pattern names.
struct Pat {
    norm: String,
}

fn norm_ws(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn pat_of(s: &str) -> Option<Pat> {
    let norm = norm_ws(s);
    (!norm.is_empty()).then_some(Pat { norm })
}

fn count_pat(hay: &str, p: &Pat) -> usize {
    norm_ws(hay).match_indices(p.norm.as_str()).count()
}

/// Two occurrences with nothing but whitespace between them are one
/// site doubled, never two sites — the exemplars came from distinct
/// contexts by the gate's definition. In normalized space that means
/// consecutive matches separated by at most one space.
fn adjacent_dup(hay: &str, p: &Pat) -> bool {
    let h = norm_ws(hay);
    let pos: Vec<usize> = h.match_indices(p.norm.as_str()).map(|(i, _)| i).collect();
    pos.windows(2)
        .any(|w| h[w[0] + p.norm.len()..w[1]].trim().is_empty())
}

/// Full-line span of a hunk within the region (`pad` adds one line of
/// context each side). The hunk offsets are char-trimmed, so the
/// evidence of a re-application lives in the surrounding line, not in
/// the hunk bytes themselves.
fn line_span(region: &str, start: usize, end: usize, pad: bool) -> (usize, usize) {
    let mut s = region[..start].rfind('\n').map_or(0, |i| i + 1);
    let mut e = region[end..]
        .find('\n')
        .map_or(region.len(), |i| end + i + 1);
    if pad {
        if s > 0 {
            s = region[..s - 1].rfind('\n').map_or(0, |i| i + 1);
        }
        if e < region.len() {
            e = region[e..].find('\n').map_or(region.len(), |i| e + i + 1);
        }
    }
    (s, e)
}

/// Hold the model's hunks to the transformation the exemplars agree
/// on. `Err` is the wire-visible `dropped` reason plus the index of
/// the offending hunk (glassbox: the route echoes that hunk back in
/// `sovereign_debug` so a drop is diagnosable from the response
/// alone): `inconsistent` (a hunk does not advance the pattern, or
/// moves against it) or `already_applied` (a hunk re-applies it where
/// it already holds, or stacks it at one site). Any bad hunk drops
/// the whole prediction — no suggestion beats a wrong one.
pub fn verify_pattern(
    reason: &str,
    a: &HistoryUnit,
    b: &HistoryUnit,
    region: &str,
    edits: &[RegionEdit],
) -> Result<(), (&'static str, usize)> {
    let (add, remove) = match reason {
        "param_insert" => {
            let n = common_prefix_len(&a.after, &b.after);
            let prefix: String = a.after.chars().take(n).collect();
            (pat_of(&prefix), pat_of(&a.before))
        }
        _ => (pat_of(&a.after), pat_of(&a.before)),
    };
    // Only identical-content shapes can prove a re-application: a
    // `param_insert` neighborhood may legitimately already carry the
    // shared prefix (an earlier site's differing tail).
    let identical_content = reason != "param_insert";

    let mut content_hunks = 0usize;
    for (i, e) in edits.iter().enumerate() {
        // A hunk that touches no content is outside the pattern's
        // jurisdiction: the shape predicates constrain WHAT the edit
        // says, and a whitespace-only reflow (e.g. a completion
        // format's trailing-newline artifact) says nothing. A hunk
        // that DELETES content into whitespace is still judged.
        if e.new_text.trim().is_empty() && region[e.start..e.end].trim().is_empty() {
            continue;
        }
        content_hunks += 1;
        let (os, oe) = line_span(region, e.start, e.end, false);
        let old_own = &region[os..oe];
        let new_own = format!(
            "{}{}{}",
            &region[os..e.start],
            e.new_text,
            &region[e.end..oe]
        );
        if let Some(p) = &add {
            let oo = count_pat(old_own, p);
            let no = count_pat(&new_own, p);
            if no <= oo {
                return Err(("inconsistent", i));
            }
            if identical_content && oo >= 1 {
                return Err(("already_applied", i));
            }
            let (ps, pe) = line_span(region, e.start, e.end, true);
            let padded_old = &region[ps..pe];
            let padded_new = format!(
                "{}{}{}",
                &region[ps..e.start],
                e.new_text,
                &region[e.end..pe]
            );
            if adjacent_dup(&padded_new, p) && !adjacent_dup(padded_old, p) {
                return Err(("already_applied", i));
            }
        }
        if let Some(r) = &remove {
            let or = count_pat(old_own, r);
            let nr = count_pat(&new_own, r);
            if nr > or {
                return Err(("inconsistent", i));
            }
            if add.is_none() && nr >= or {
                return Err(("inconsistent", i));
            }
        }
    }
    if content_hunks == 0 {
        // Every hunk was whitespace: a formatted echo, not an edit.
        // The gate consulted for a content pattern and the model
        // proposed no content — that is the completion-trap answer
        // ("nothing left to do"), and it must land as silence, not as
        // a whitespace edit the user is asked to accept.
        return Err(("noop", 0));
    }
    Ok(())
}

// ---- the lane as two pure halves, split at the inference call --------
//
// Everything the model lane decides lives in `plan` (before inference)
// and `finish` (after it). Inference itself is the ONLY impure step, so
// the daemon route and the offline scorer
// (`examples/next_edit_score.rs`) differ in exactly that one place and
// share every decision. This split exists so a candidate model can be
// scored without a daemon and the score still be the daemon's answer:
// a second implementation of this ordering would be two rulers on one
// contract, which is the defect class the §9a hardening pass already
// caught once (NEXT_EDIT.md §9a, "Two rulers on one contract").

/// What the model expects on the wire. `Chat` is one user turn through
/// the chat template; `Raw` is the model's own verbatim prompt, which
/// completion-style edit models need — a chat template would wrap their
/// special tokens in a user turn and the fine-tune would never see the
/// shape it was trained on.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Prompt {
    Chat(String),
    Raw(String),
    /// A chat prompt whose fine-tune was trained with a distinct system
    /// turn. Folding that text into the user turn would change the
    /// token layout the model was trained on — the same reason
    /// [`Prompt::Raw`] bypasses the chat template.
    ChatSystem { system: String, user: String },
}

impl Prompt {
    /// The OpenAI `messages` array for a chat-shaped prompt; `None` for
    /// [`Prompt::Raw`], which goes to the completion endpoint verbatim.
    ///
    /// One decider for the message layout (ARCH §10.6): the daemon and
    /// the offline scorer must send byte-identical requests, or a
    /// bakeoff number measures the harness rather than the model — the
    /// exact failure `RESULTS_PHASE0.md` recorded as could-not-judge.
    pub fn chat_messages(&self) -> Option<serde_json::Value> {
        match self {
            Prompt::Raw(_) => None,
            Prompt::Chat(user) => {
                Some(serde_json::json!([{ "role": "user", "content": user }]))
            }
            Prompt::ChatSystem { system, user } => Some(serde_json::json!([
                { "role": "system", "content": system },
                { "role": "user", "content": user },
            ])),
        }
    }
}

/// A consult the pre-inference half approved, with everything the
/// caller needs to issue it and nothing about how.
#[derive(Debug, Clone)]
pub struct ConsultPlan {
    pub reason: &'static str,
    pub needle: Option<String>,
    /// Byte offsets of the rewrite region in the request text.
    pub region_start: usize,
    pub region_end: usize,
    pub needle_hit: bool,
    pub format: String,
    pub prompt: Prompt,
    pub max_tokens: u32,
    pub stop: Vec<String>,
    /// Sampling temperature. Lives here rather than at the call site
    /// because it is lane policy, not transport: the completion-style
    /// formats are scored greedily (their fine-tunes are trained for a
    /// single right answer) while the instruct format keeps a sliver of
    /// temperature. An offline scorer that guessed this would be
    /// measuring a different model than the daemon runs.
    pub temperature: f32,
    /// Suppress the model's thinking phase for this consult.
    ///
    /// Lane policy for the same reason `temperature` is (above), and
    /// the single most consequential knob this lane has. A general
    /// chat model asked for a region rewrite will reason first: measured
    /// 2026-08-07 on a 35B-A3B primary, it emitted ~1044 tokens of
    /// `reasoning_content` before its first answer byte, against the
    /// 64–1024 budget `max_tokens` grants — so **every** case finished
    /// `length` with empty content and scored 0/30. With thinking off,
    /// the same weights and prompt scored 21/30 useful with 0 wrong
    /// edits, matching a 1.5B next-edit specialist's 19/30.
    ///
    /// True exactly for the chat-template dialects. The raw-prompt
    /// dialects (`zeta2`, `sweep`) ride completion fine-tunes that have
    /// no thinking phase to suppress, and there is no chat template to
    /// carry the instruction.
    ///
    /// Two transports express this and they are NOT interchangeable:
    /// `chat_template_kwargs.enable_thinking=false` is what the Jinja
    /// template reads, while `think_budget=0` drives the daemon's
    /// `/no_think` injection. Callers set both — a budget of 0 alone was
    /// verified inert on this template (811 chars of `reasoning_content`
    /// still emitted, empty content, `finish=length`).
    pub suppress_thinking: bool,
}

/// Outcome of the pre-inference half — glassbox in all three arms.
#[derive(Debug, Clone)]
pub enum Plan {
    /// The consult gate refused; no model was involved (`skipped`).
    Skip {
        skipped: &'static str,
    },
    /// The gate said yes, then a region guard declined (`dropped`).
    Decline {
        reason: &'static str,
        needle: Option<String>,
        dropped: &'static str,
        /// Present only for `region_too_large`, which is the one
        /// decline whose magnitude the operator needs to see.
        region_bytes: Option<usize>,
    },
    Send(Box<ConsultPlan>),
}

/// Why a consulted prediction produced no edits. `hunk` is the
/// offending region edit when the V0 content verifier rejected one, so
/// the caller can show what it refused without re-deriving it.
#[derive(Debug, Clone)]
pub struct FinishDrop {
    pub dropped: &'static str,
    pub hunk: Option<RegionEdit>,
}

/// Everything the model lane decides BEFORE inference: consult gate,
/// region selection, the three region guards, and prompt shaping.
///
/// `format` is the wire dialect the slot speaks — it comes from the
/// inference service in the daemon and from a flag in the scorer, so it
/// is a parameter rather than a lookup. Callers that have no model
/// available should not call this; they report `unavailable` against
/// the gate's own answer instead (see `Plan::Skip` vs. the caller's
/// drop).
pub fn plan(
    history: &[HistoryUnit],
    text: &str,
    cursor: usize,
    p: &Prediction,
    path: Option<&str>,
    language: Option<&str>,
    format: &str,
    force: bool,
) -> Plan {
    // `force` is a MEASUREMENT affordance and the daemon always passes
    // `false`. It exists because every model number this project has is
    // conditioned on the consult gate: the gate admits ~9% of real
    // editing episodes (`gym/next-edit/golden/README.md`), so a model
    // scored through it has been judged on a sliver our routing chose,
    // not on what it can do. Forcing the consult measures the model's
    // ceiling independent of our gate, which is the only way to tell a
    // gate that protects us from a bad model apart from one that hides
    // a good one. The region guards below still apply — those bound
    // cost and correctness, not eligibility.
    let (reason, needle) = match should_consult(history, text, p) {
        Consult::No { skipped } if !force => return Plan::Skip { skipped },
        // Forced: no exemplar shape was recognised, so there is no
        // per-shape reason and no needle. Region selection falls back
        // to the cursor line, which is what an unanchored consult gets.
        Consult::No { .. } => ("forced", None),
        Consult::Yes { reason, needle } => (reason, needle),
    };
    let decline = |dropped, region_bytes| Plan::Decline {
        reason,
        needle: needle.clone(),
        dropped,
        region_bytes,
    };

    let (rs, re, needle_hit) = select_region(text, cursor, needle.as_deref());
    let region = &text[rs..re];
    // A region that blew the byte budget means a single line did (a
    // minified bundle is one 512 KiB line). Prefilling that on the
    // shared slot is a large, repeatable cost for a suggestion nobody
    // can read, so decline and say so.
    if region.len() > MAX_REGION_BYTES {
        return decline("region_too_large", Some(region.len()));
    }
    // An empty or blank region has nothing to rewrite, so every byte
    // the model returns is invention with no relationship to the file
    // — and the guards that normally bound a rewrite are all relative
    // to the region, so they bound nothing here.
    if region.trim().is_empty() {
        return decline("region_empty", None);
    }
    // A region already containing the active format's markers would
    // make the prompt ambiguous about where the editable span ends, and
    // every faithful echo would then fail parsing — the lane would look
    // silently broken on that one file forever. Which strings poison
    // the prompt depends on the format the slot speaks.
    let poisoned = match format {
        // `=======` also appears as a Markdown/RST setext underline and
        // inside a real merge conflict. Declining those is the correct
        // trade: an ambiguous region boundary corrupts a file, and
        // silence costs one suggestion.
        "zeta2" => {
            region.contains(ZETA_MARKER_1)
                || region.contains(ZETA_MARKER_2)
                || region.contains(ZETA_UPDATED_END)
                || region.contains("<[fim-")
                || region.contains(ZETA_CURSOR)
        }
        "sweep" => region.contains(SWEEP_FILE_SEP),
        // Instinct shares the editable-region markers and adds an
        // in-band cursor flag; either occurring in the region makes the
        // span boundary ambiguous.
        "instinct" => region.contains("editable_region") || region.contains(INSTINCT_CURSOR),
        _ => region.contains("editable_region"),
    };
    if poisoned {
        return decline("region_has_markers", None);
    }

    let max_tokens = ((region.len() / 3) + 160).clamp(64, 1024) as u32;
    // `</s>` is Sweep's documented terminator; zeta2's `<|marker_2|>`
    // is already a SeedCoder family stop.
    let (prompt, stop, temperature) = match format {
        "zeta2" => (
            Prompt::Raw(build_prompt_zeta2(history, text, rs, re, cursor, path)),
            vec![ZETA_UPDATED_END.to_string()],
            0.0,
        ),
        "sweep" => (
            Prompt::Raw(build_prompt_sweep(history, region, path)),
            vec!["</s>".to_string()],
            0.0,
        ),
        "instinct" => (
            Prompt::ChatSystem {
                system: INSTINCT_SYSTEM.to_string(),
                user: build_prompt_instinct(history, text, rs, re, cursor, path),
            },
            Vec::new(),
            0.0,
        ),
        _ => (
            Prompt::Chat(build_prompt(history, region, path, language, reason)),
            Vec::new(),
            0.1,
        ),
    };

    // Derived from the prompt shape rather than re-matched on `format`,
    // so a new chat-template dialect inherits thinking suppression by
    // construction instead of by someone remembering to add an arm here
    // (ARCH §7: make it structural, not remembered). Getting this wrong
    // is not a degradation — it is 0/30.
    let suppress_thinking = matches!(prompt, Prompt::Chat(_) | Prompt::ChatSystem { .. });

    Plan::Send(Box::new(ConsultPlan {
        reason,
        needle,
        region_start: rs,
        region_end: re,
        needle_hit,
        format: format.to_string(),
        prompt,
        max_tokens,
        stop,
        temperature,
        suppress_thinking,
    }))
}

/// Everything the model lane decides AFTER inference: finish-reason
/// screening, parsing, region diffing, and the V0 content verifier.
/// Returns REGION-RELATIVE edits; the caller rebases by
/// `plan.region_start`.
pub fn finish(
    plan: &ConsultPlan,
    history: &[HistoryUnit],
    region: &str,
    content: &str,
    finish_reason: Option<&str>,
) -> Result<Vec<RegionEdit>, FinishDrop> {
    let drop = |dropped| FinishDrop {
        dropped,
        hunk: None,
    };

    // A completion that hit the token ceiling is a region cut off
    // mid-rewrite. Diffed against the whole region it reads as "delete
    // everything after here" — the tail is missing, not unchanged.
    if finish_reason == Some("length") {
        return Err(drop("truncated"));
    }
    // Cancelled/errored decodes carry partial content; a partial
    // rewrite is the same mass-deletion hazard.
    if matches!(finish_reason, Some("cancelled") | Some("error")) {
        return Err(drop("error"));
    }

    let rewritten = match plan.format.as_str() {
        "zeta2" => parse_rewrite_zeta2(content, region),
        "sweep" => parse_rewrite_sweep(content, region),
        _ => parse_rewrite(content, region),
    }
    .map_err(drop)?;

    let region_edits = diff_region(region, &rewritten);
    if region_edits.is_empty() {
        return Err(drop("noop"));
    }
    // V0 content verifier: the structural guards above bound how much
    // changed; this holds WHAT changed to the exemplar transformation
    // the gate consulted over. The pair cannot be absent here — the
    // gate already required it — but a defensive miss just skips
    // verification rather than inventing a drop.
    if let Some((a, b)) = exemplar_pair(history) {
        if let Err((dropped, idx)) = verify_pattern(plan.reason, a, b, region, &region_edits) {
            return Err(FinishDrop {
                dropped,
                hunk: Some(region_edits[idx].clone()),
            });
        }
    }
    Ok(region_edits)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::next_edit::predict;

    fn unit(before: &str, after: &str, left: &str, right: &str) -> HistoryUnit {
        HistoryUnit {
            before: before.into(),
            after: after.into(),
            left: left.into(),
            right: right.into(),
        }
    }

    /// A rename exemplar with a second, un-renamed occurrence — the
    /// shape the consult gate is built to fire on, so `plan` reaches
    /// `Send` for every dialect.
    fn rename_scenario() -> (Vec<HistoryUnit>, String, Prediction) {
        let h = vec![unit(
            "getUserData",
            "fetchUserData",
            "  const raw = ",
            "(userId);",
        )];
        let text =
            "  const raw = fetchUserData(userId);\n  const b = getUserData(other);\n".to_string();
        let p = predict(&h, &text, 0);
        (h, text, p)
    }

    fn plan_for(format: &str) -> Box<ConsultPlan> {
        let (h, text, p) = rename_scenario();
        let cursor = text.find("getUserData(other").expect("fixture holds a second site");
        match plan(
            &h,
            &text,
            cursor,
            &p,
            Some("a.ts"),
            Some("typescript"),
            format,
            // Forced: this asserts on plan SHAPE, and routing
            // eligibility is a different question with its own tests.
            true,
        ) {
            Plan::Send(plan) => plan,
            other => panic!("{format}: expected Plan::Send, got {other:?}"),
        }
    }

    /// Thinking suppression follows the PROMPT SHAPE, and on a chat
    /// dialect getting it wrong is not a degradation — it is 0/30.
    /// A general chat model emits ~1044 reasoning tokens before its
    /// first answer byte, against the 64–1024 this lane grants, so
    /// every case finishes `length` with empty content (measured
    /// 2026-08-07). See `ConsultPlan::suppress_thinking`.
    #[test]
    fn chat_dialects_suppress_thinking() {
        for format in ["region_instruct", "instinct"] {
            assert!(
                plan_for(format).suppress_thinking,
                "{format} renders through the chat template, so an unsuppressed \
                 thinking block consumes the whole generation budget"
            );
        }
    }

    /// The raw dialects ride completion fine-tunes: no chat template to
    /// carry the instruction, and no thinking phase to suppress.
    /// Asserting the negative keeps the flag from becoming an
    /// unconditional `true` that nobody notices.
    #[test]
    fn raw_dialects_do_not_suppress_thinking() {
        for format in ["zeta2", "sweep"] {
            assert!(
                !plan_for(format).suppress_thinking,
                "{format} is a raw completion prompt — there is no chat template \
                 to carry a thinking instruction"
            );
        }
    }

    /// The flag must track the prompt variant rather than a
    /// format-string allowlist, so a dialect added later inherits the
    /// right behaviour by construction (ARCH §7).
    #[test]
    fn suppress_thinking_tracks_prompt_shape_not_format_name() {
        for format in ["region_instruct", "instinct", "zeta2", "sweep"] {
            let p = plan_for(format);
            let is_chat = matches!(p.prompt, Prompt::Chat(_) | Prompt::ChatSystem { .. });
            assert_eq!(
                p.suppress_thinking, is_chat,
                "{format}: suppress_thinking disagreed with the prompt variant"
            );
        }
        // An unknown dialect falls through to the chat default, and so
        // must suppress — the failure mode this guards is a new format
        // silently defaulting to "thinking on" and scoring zero.
        assert!(plan_for("some_future_instruct_dialect").suppress_thinking);
    }

    #[test]
    fn restyle_renders_all_casings() {
        assert_eq!(restyle("getUserData(", Style::Snake), "get_user_data(");
        assert_eq!(restyle("getUserData(", Style::Screaming), "GET_USER_DATA(");
        assert_eq!(restyle("get_user_data(", Style::Camel), "getUserData(");
        assert_eq!(restyle("parse_args", Style::Pascal), "ParseArgs");
        assert_eq!(restyle("MAX_RETRIES", Style::Camel), "maxRetries");
    }

    #[test]
    fn gate_casing_variant_is_detected_but_deferred() {
        let h = vec![
            unit(
                "getUserData",
                "fetchUserData",
                "  const raw = ",
                "(userId);",
            ),
            unit(
                "getUserData",
                "fetchUserData",
                "  const avatar = ",
                "(uid);",
            ),
        ];
        let with_variant = "const a = fetchUserData(x);\nconst b = fetchUserData(y);\n\
                            const c = get_user_data(z);\n";
        let p = predict(&h, with_variant, 0);
        assert_eq!(p.reason_silent, Some("no_sites"));
        // Detection is live (the needle machinery must keep working for
        // the future rule sub-lane) but the consult is declined by name.
        assert_eq!(
            casing_variant_needle(with_variant, p.rule.as_ref().unwrap()).as_deref(),
            Some("get_user_data(")
        );
        assert_eq!(
            should_consult(&h, with_variant, &p),
            Consult::No {
                skipped: "casing_deferred"
            }
        );
        // Same history, no variant anywhere: plain gate refusal.
        let without = "const a = fetchUserData(x);\nconst b = fetchUserData(y);\n";
        let p2 = predict(&h, without, 0);
        assert_eq!(
            should_consult(&h, without, &p2),
            Consult::No { skipped: "gate" }
        );
    }

    #[test]
    fn gate_defers_fanout_and_param_admits_multiline() {
        // The two deferred shapes are still DETECTED, and the decline
        // carries their name — that is what keeps them countable in the
        // admission table, and the count is what a re-open has to argue
        // against. Measured rates per gate are in `should_consult`'s
        // comment and note 2c22ec10.
        let text = "dial(a, x)\ndial(b, y)\ndial(c, z)\n";
        let fanout = vec![
            unit("", ", tmo", "dial(a, x", ")"),
            unit("", ", tmo", "dial(b, y", ")"),
        ];
        let p = predict(&fanout, text, 0);
        assert_eq!(
            should_consult(&fanout, text, &p),
            Consult::No {
                skipped: "fanout_insert_deferred"
            }
        );

        let param = vec![
            unit("unwrap()", "expect(\"a\")", "x().", ";"),
            unit("unwrap()", "expect(\"b\")", "y().", ";"),
        ];
        let t2 = "z().unwrap();\n";
        let p2 = predict(&param, t2, 0);
        assert_eq!(
            should_consult(&param, t2, &p2),
            Consult::No {
                skipped: "param_insert_deferred"
            }
        );

        let ml = vec![
            unit("", "\n  retries: 3,", "port: 1,", "\n};"),
            unit("", "\n  retries: 3,", "port: 2,", "\n};"),
        ];
        let t3 = "a\nb\nc\n";
        let p3 = predict(&ml, t3, 0);
        assert!(matches!(
            should_consult(&ml, t3, &p3),
            Consult::Yes {
                reason: "multiline_fanout",
                ..
            }
        ));
    }

    /// Each assertion here is a claim about `continuedev/instinct-data`,
    /// not about our taste. Phase 0 scored Instinct 0/30 by feeding it a
    /// dialect it was never trained on
    /// (`bench/next-edit-bakeoff/RESULTS_PHASE0.md`); a silent drift back
    /// to the wrong shape would look like the model getting worse.
    #[test]
    fn instinct_prompt_matches_its_trained_shape() {
        let text = "a\nb\nmark_here\nc\nd\n";
        let h = vec![
            unit("", ", tmo", "dial(older", ")"),
            unit("", ", tmo", "dial(newer", ")"),
        ];
        let p = build_prompt_instinct(&h, text, 0, text.len(), 4, Some("src/x.rs"));

        // 1. The three sections, in the trained order.
        let ctx = p.find("### Context:").expect("Context section");
        let edits = p.find("### User Edits:").expect("User Edits section");
        let excerpt = p.find("### User Excerpt:").expect("User Excerpt section");
        assert!(ctx < edits && edits < excerpt, "sections out of trained order");

        // 2. Edit history MOST RECENT FIRST. `shown_units` is
        // oldest-first, so this is the reversal — and getting it
        // backwards is invisible except as a quality loss.
        let newer = p.find("dial(newer").expect("newer edit present");
        let older = p.find("dial(older").expect("older edit present");
        assert!(newer < older, "instinct orders edit history most-recent-first");

        // 3. Marker-bracketed region with the cursor flagged in-band.
        let s = p.find(REGION_START_MARKER).expect("region start");
        let e = p.find(REGION_END_MARKER).expect("region end");
        let cur = p.find(INSTINCT_CURSOR).expect("cursor marker");
        assert!(s < cur && cur < e, "cursor marker must sit inside the region");
    }

    #[test]
    fn instinct_sends_a_distinct_system_turn() {
        let m = Prompt::ChatSystem { system: "S".into(), user: "U".into() }
            .chat_messages()
            .expect("chat-shaped");
        assert_eq!(m.as_array().unwrap().len(), 2);
        assert_eq!(m[0]["role"], "system");
        assert_eq!(m[1]["role"], "user");
        // Raw stays on the completion endpoint — a chat template would
        // wrap a fine-tune's special tokens in a user turn.
        assert!(Prompt::Raw("x".into()).chat_messages().is_none());
        assert_eq!(
            Prompt::Chat("U".into()).chat_messages().unwrap().as_array().unwrap().len(),
            1
        );
        // The vendored asset must actually be there; an empty include
        // would degrade silently to "no system prompt".
        assert!(INSTINCT_SYSTEM.contains("editable_region_start"));
        assert!(INSTINCT_SYSTEM.len() > 1000, "instinct system prompt looks truncated");
    }

    #[test]
    fn gate_refusals() {
        // Dissimilar cores.
        let h = vec![
            unit("parseHeader", "readHeader", "h = ", "(buf);"),
            unit("5000", "8000", "t = wait(", ");"),
        ];
        let t = "x = wait(5000);\n";
        let p = predict(&h, t, 0);
        assert_eq!(should_consult(&h, t, &p), Consult::No { skipped: "gate" });
        // Rule lane fired: the model must never be consulted.
        let owns = vec![
            unit("log", "debug", "console.", "(\"a\");"),
            unit("log", "debug", "console.", "(\"b\");"),
        ];
        let t2 = "console.log(\"c\");\n";
        let p2 = predict(&owns, t2, 0);
        assert!(!p2.edits.is_empty());
        assert_eq!(
            should_consult(&owns, t2, &p2),
            Consult::No {
                skipped: "rule_fired"
            }
        );
        // Identical rule below threshold: restraint is policy. The
        // rule here induces to a bare `i` — one char, under the 2-char
        // minimum, so it stays silent at any support. (It was `id`
        // until 2026-08-06; two chars now fires, which is the point of
        // that change.)
        let short = vec![
            unit("i", "ii", "const ", " = next();"),
            unit("i", "ii", "let ", " = 0;"),
        ];
        let t3 = "const i = parse(row);\n";
        let p3 = predict(&short, t3, 0);
        assert_eq!(p3.reason_silent, Some("below_threshold"));
        assert_eq!(
            should_consult(&short, t3, &p3),
            Consult::No { skipped: "gate" }
        );
        // Fewer than two real units.
        let one = vec![unit("a", "b", "x", "y")];
        let p4 = predict(&one, "a\n", 0);
        assert_eq!(
            should_consult(&one, "a\n", &p4),
            Consult::No { skipped: "gate" }
        );
    }

    #[test]
    fn region_anchors_on_needle_and_clamps() {
        let text: String = (0..40).map(|i| format!("line {i}\n")).collect();
        let needle_text = text.replace("line 30", "dial(a, b)");
        let (s, e, hit) = select_region(&needle_text, 0, Some("dial("));
        assert!(hit);
        assert!(needle_text[s..e].contains("dial(a, b)"));
        assert_eq!(needle_text[s..e].lines().count(), REGION_LINES);
        // No needle: cursor-centered; small doc: whole doc.
        let (s2, e2, hit2) = select_region("a\nb\nc\n", 2, None);
        assert!(!hit2);
        assert_eq!((s2, e2), (0, 6));
        // Needle behind the cursor is still found (wrap).
        let (_, _, hit3) = select_region(&needle_text, needle_text.len(), Some("dial("));
        assert!(hit3);
    }

    #[test]
    fn region_respects_the_byte_budget_on_long_lines() {
        // Ordinary source is untouched by the budget: still 24 lines.
        let ordinary: String = (0..60).map(|i| format!("let x{i} = {i};\n")).collect();
        let (s, e, _) = select_region(&ordinary, 0, None);
        assert_eq!(ordinary[s..e].lines().count(), REGION_LINES);

        // Long lines: fewer lines, but always within the budget.
        let long: String = (0..60)
            .map(|i| format!("{}// {i}\n", "x".repeat(900)))
            .collect();
        let (s, e, _) = select_region(&long, long.len() / 2, None);
        assert!(e - s <= MAX_REGION_BYTES, "region {} bytes", e - s);
        assert!(e > s, "still returns a usable window");
        assert!(long.is_char_boundary(s) && long.is_char_boundary(e));

        // The pathological file — one 200 KiB line, no newline at all.
        // The window cannot shrink below one line, so it comes back
        // over budget and the ROUTE declines it (`region_too_large`);
        // silently prefilling it is the failure this guards.
        let minified = "a".repeat(200 * 1024);
        let (s, e, _) = select_region(&minified, 0, None);
        assert!(e - s > MAX_REGION_BYTES, "route must see it as too large");
    }

    #[test]
    fn needle_context_is_bounded_but_still_anchors() {
        // 2 KiB per field is legal on the wire; the needle search must
        // not be handed all of it (quadratic DP on a request thread).
        let pad = "z".repeat(2000);
        let a = unit("", ", tmo", &format!("{pad}dial(a, x"), ")");
        let b = unit("", ", tmo", &format!("{pad}dial(b, y"), ")");
        let n = ctx_needle(&a, &b).expect("still finds an anchor");
        assert!(n.chars().count() >= MIN_NEEDLE);
        assert!(n.len() <= MAX_NEEDLE_CTX * 3);

        // Truncation is char-boundary safe on multi-byte context.
        let emoji = "💡".repeat(300);
        let c = unit("", "!", &emoji, &emoji);
        assert!(ctx_needle(&c, &c.clone()).is_some());
        assert_eq!(head("héllo", 2), "hé");
        assert_eq!(tail("héllo", 2), "lo");
        assert_eq!(head("hi", 9), "hi");
        assert_eq!(tail("hi", 9), "hi");
    }

    #[test]
    fn parse_rewrite_normalizes_and_drops() {
        let region = "a\nb\nc\n";
        assert_eq!(parse_rewrite("a\nB\nc\n", region).unwrap(), "a\nB\nc\n");
        // Wrapping fence + language tag.
        assert_eq!(
            parse_rewrite("```rust\na\nB\nc\n```", region).unwrap(),
            "a\nB\nc\n"
        );
        // Echoed markers are dropped, not repaired — see
        // `echoed_markers_are_dropped_never_repaired` for why.
        let echoed = format!("{REGION_START_MARKER}\na\nB\nc\n{REGION_END_MARKER}\n");
        assert_eq!(parse_rewrite(&echoed, region), Err("invalid"));
        // Think-block preamble stripped.
        assert_eq!(
            parse_rewrite("<think>hmm</think>\na\nB\nc\n", region).unwrap(),
            "a\nB\nc\n"
        );
        // Unchanged output is an explained noop, not an edit.
        assert_eq!(parse_rewrite("a\nb\nc\n", region), Err("noop"));
        // Runaway growth dropped.
        let runaway = "x\n".repeat(REGION_LINES + MAX_LINE_DELTA + 2);
        assert_eq!(parse_rewrite(&runaway, region), Err("invalid"));
        assert_eq!(parse_rewrite("", region), Err("invalid"));
    }

    /// Every one of these was a way to turn a suspicious completion
    /// into a confident wrong edit. The posture is drop-whole: no
    /// suggestion beats a wrong one.
    #[test]
    fn parse_rewrite_refuses_chat_shaped_output() {
        let region = "a\nb\nc\n";
        // Prose before the fence — the fence check used to only look
        // at position 0, so this sailed through unwrapped and spliced
        // the prose into the file.
        assert_eq!(
            parse_rewrite("Sure! Here you go:\n```\na\nB\nc\n```", region),
            Err("invalid")
        );
        // Two fenced blocks with commentary between: closing on the
        // LAST fence used to swallow the commentary as file content.
        assert_eq!(
            parse_rewrite(
                "```\na\nB\n```\nI also removed the dead code.\n```\nc\n```",
                region
            ),
            Err("invalid")
        );
        // Trailing commentary after a well-formed fence.
        assert_eq!(
            parse_rewrite("```\na\nB\nc\n```\nHope that helps!", region),
            Err("invalid")
        );
        // A well-formed single fence still parses.
        assert_eq!(
            parse_rewrite("```rust\na\nB\nc\n```", region).unwrap(),
            "a\nB\nc\n"
        );
    }

    /// A file line that IS a marker used to be deleted by the
    /// marker-stripping repair — a wrong edit manufactured out of a
    /// faithful echo.
    #[test]
    fn echoed_markers_are_dropped_never_repaired() {
        let region = format!("let x = 1;\n{REGION_END_MARKER}\n");
        assert_eq!(parse_rewrite(&region, &region), Err("invalid"));
        let echoed = format!("{REGION_START_MARKER}\na\nB\nc\n{REGION_END_MARKER}\n");
        assert_eq!(parse_rewrite(&echoed, "a\nb\nc\n"), Err("invalid"));
    }

    /// CRLF region + LF rewrite made every line differ, collapsing the
    /// line-LCS into one hunk over the whole region: the model got
    /// free rein over code it never claimed to touch, and a byte-
    /// faithful echo stopped registering as a noop.
    #[test]
    fn crlf_regions_survive_an_lf_rewrite() {
        let region = "one\r\ntwo\r\nthree\r\n";
        let out = parse_rewrite("one\r\nTWO\r\nthree\r\n", region).unwrap();
        assert_eq!(
            diff_region(region, &out).len(),
            1,
            "one hunk, not a whole-region flip"
        );

        let from_lf = parse_rewrite("one\ntwo\nthree\n", region);
        assert_eq!(
            from_lf,
            Err("noop"),
            "a faithful echo in LF is still a noop"
        );
        let changed = parse_rewrite("one\nTWO\nthree\n", region).unwrap();
        assert!(changed.contains("\r\n") && !changed.contains("\n\n"));
        let edits = diff_region(region, &changed);
        assert_eq!(edits.len(), 1);
        assert_eq!(&region[edits[0].start..edits[0].end], "two");
    }

    #[test]
    fn parse_rewrite_bounds_shrink_as_well_as_growth() {
        let region: String = (0..20)
            .map(|i| format!("line {i} with some real content\n"))
            .collect();
        // A truncated or lazy completion deletes the rest of the
        // region; the growth cap alone never saw this.
        assert_eq!(
            parse_rewrite("line 0 with some real content\n", &region),
            Err("invalid")
        );
        // A same-line-count gutting: line delta 0, bytes gone.
        let gutted: String = (0..20).map(|_| "//\n".to_string()).collect();
        assert_eq!(parse_rewrite(&gutted, &region), Err("invalid"));
        // Trailing newline is honoured in both directions.
        assert_eq!(parse_rewrite("a\nB\nc\n", "a\nb\nc").unwrap(), "a\nB\nc");
        assert_eq!(parse_rewrite("a\nB\nc", "a\nb\nc\n").unwrap(), "a\nB\nc\n");
    }

    #[test]
    fn diff_region_yields_per_site_hunks() {
        // Two separated line changes → two edits, char-trimmed.
        let orig = "aa\nbb\ncc\ndd\nee\n";
        let new = "aa\nbX\ncc\ndY\nee\n";
        let edits = diff_region(orig, new);
        assert_eq!(edits.len(), 2);
        assert_eq!(&orig[edits[0].start..edits[0].end], "b");
        assert_eq!(edits[0].new_text, "X");
        assert_eq!(&orig[edits[1].start..edits[1].end], "d");
        assert_eq!(edits[1].new_text, "Y");
        // Pure line insertion → zero-width edit at the insertion point.
        let ins = diff_region("aa\ncc\n", "aa\nbb\ncc\n");
        assert_eq!(ins.len(), 1);
        assert_eq!(ins[0].start, ins[0].end);
        assert_eq!(ins[0].new_text, "bb\n");
        // Identical inputs → no edits.
        assert!(diff_region("aa\n", "aa\n").is_empty());
    }

