    #[test]
    fn verify_whitespace_only_hunk_is_exempt_content_deletion_is_not() {
        // A trailing-newline artifact beside a correct application
        // must not sink the prediction (completion formats append
        // one; observed live with Sweep 2026-07-31)…
        let (a, b) = fanout_exemplars();
        let region = "\tconn := dial(primaryHost, 8080, timeoutMS)\n\
                      \tmirror := dial(mirrorHost, 9090)\n";
        let at = region.find("9090)").unwrap() + 4;
        let end = region.len();
        let edits = vec![
            RegionEdit {
                start: at,
                end: at,
                new_text: ", timeoutMS".into(),
            },
            RegionEdit {
                start: end,
                end,
                new_text: "\n".into(),
            },
        ];
        assert_eq!(
            verify_pattern("fanout_insert", &a, &b, region, &edits),
            Ok(())
        );
        // …but a hunk that deletes content into whitespace is judged,
        // and fails: it does not advance the pattern.
        let s = region.find("mirror").unwrap();
        let gut = vec![RegionEdit {
            start: s,
            end: s + "mirror := dial(mirrorHost, 9090)".len(),
            new_text: " ".into(),
        }];
        assert_eq!(
            verify_pattern("fanout_insert", &a, &b, region, &gut),
            Err(("inconsistent", 0))
        );
        // …and a prediction that is ONLY whitespace is a formatted
        // echo — the completion-trap answer — and must land as noop,
        // never as an accepted-able edit (observed live: Sweep answers
        // exhausted fan-outs with a bare trailing newline).
        let echo = vec![RegionEdit {
            start: end,
            end,
            new_text: "\n".into(),
        }];
        assert_eq!(
            verify_pattern("fanout_insert", &a, &b, region, &echo),
            Err(("noop", 0))
        );
    }

    #[test]
    fn verify_line_fragment_exemplar_matches_in_situ() {
        // JSON-ish insertion whose exemplar STARTS mid-line: the
        // leading comma attaches to the previous line in situ, so a
        // line-wise matcher can never see the pattern — regression
        // for exactly that false `inconsistent` (control run
        // 2026-07-31). Whitespace-normalized matching must both PASS
        // the fresh site and still CATCH the done site.
        let a = unit("", ",\n    \"retries\": 3", "    \"timeout\": 30", "\n}");
        let b = unit("", ",\n    \"retries\": 3", "    \"cap\": 4", "\n}");
        let fresh = "{\n    \"timeout\": 30\n}\n";
        let at = fresh.find("30").unwrap() + 2;
        let ins = vec![RegionEdit {
            start: at,
            end: at,
            new_text: ",\n    \"retries\": 3".into(),
        }];
        assert_eq!(
            verify_pattern("multiline_fanout", &a, &b, fresh, &ins),
            Ok(())
        );
        let done = "{\n    \"timeout\": 30,\n    \"retries\": 3\n}\n";
        let at = done.find('3').unwrap();
        let at = done[at..].find("3\n").unwrap() + at + 1;
        let ins = vec![RegionEdit {
            start: at,
            end: at,
            new_text: ",\n    \"retries\": 3".into(),
        }];
        assert_eq!(
            verify_pattern("multiline_fanout", &a, &b, done, &ins),
            Err(("already_applied", 0))
        );
    }

    #[test]
    fn verify_deletion_fanout_must_delete() {
        let a = unit(", legacyFlag", "", "\tstart(alpha", ")");
        let b = unit(", legacyFlag", "", "\tstart(beta", ")");
        let region = "\tstart(gamma, legacyFlag)\n";
        let s = region.find(", legacyFlag").unwrap();
        // Deleting the flag is the pattern.
        let del = vec![RegionEdit {
            start: s,
            end: s + ", legacyFlag".len(),
            new_text: "".into(),
        }];
        assert_eq!(
            verify_pattern("fanout_insert", &a, &b, region, &del),
            Ok(())
        );
        // Rewriting the line while KEEPING the flag is not.
        let keep = vec![RegionEdit {
            start: s,
            end: s + ", legacyFlag".len(),
            new_text: ", legacyFlag /* soon */".into(),
        }];
        assert_eq!(
            verify_pattern("fanout_insert", &a, &b, region, &keep),
            Err(("inconsistent", 0))
        );
    }

    #[test]
    fn verify_param_insert_allows_varying_tails() {
        // Tails vary per site by definition; a neighboring earlier site
        // carrying the shared prefix must not read as re-application.
        let a = unit(
            ".unwrap()",
            ".expect(\"cfg missing\")",
            "    let c = load(p)",
            ";",
        );
        let b = unit(
            ".unwrap()",
            ".expect(\"env missing\")",
            "    let e = read()",
            ";",
        );
        let region =
            "    let c = load(p).expect(\"cfg missing\");\n    let t = parse(s).unwrap();\n";
        let s = region.rfind(".unwrap()").unwrap();
        let edits = vec![RegionEdit {
            start: s,
            end: s + ".unwrap()".len(),
            new_text: ".expect(\"tz missing\")".into(),
        }];
        assert_eq!(
            verify_pattern("param_insert", &a, &b, region, &edits),
            Ok(())
        );
        // But a hunk that never brings the shared prefix is not the
        // pattern.
        let off = vec![RegionEdit {
            start: s,
            end: s + ".unwrap()".len(),
            new_text: ".ok()".into(),
        }];
        assert_eq!(
            verify_pattern("param_insert", &a, &b, region, &off),
            Err(("inconsistent", 0))
        );
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `POST /v1/completions` — the FIM inline-completion route
//! (`sovereign/docs/INLINE_COMPLETION.md` §3.4, decision D6).
//!
//! Deliberately thin: parse the dual wire shape (OpenAI-legacy
//! `prompt`+`suffix` vs the rich `prefix`+`suffix` the first-party
//! extension sends), unify onto [`FimCompletionRequest`], delegate to
//! [`LocalInferenceService::fim_completion_stream`], and bridge the
//! frame stream to either an aggregated OpenAI `text_completion`
//! object or SSE chunks + `[DONE]`. All prompt assembly, slot
//! routing, and stop-craft lives behind the seam (sovereign-mesh's
//! `fim_adapter`), so this handler never learns model details.
//!
//! Failure contract: 503 with an actionable body whenever the seam
//! errors — the adapter's message carries the exact `[models.fim]`
//! fix, and we surface it verbatim (a friend setting this up should
//! never have to read daemon logs for the common misconfigurations).

use axum::extract::State;
use axum::http::StatusCode;
use axum::response::sse::{Event, KeepAlive, Sse};
use axum::response::{IntoResponse, Response};
use axum::Json;
use futures::StreamExt;

use crate::openai_types::{CompletionsRequestWire, ErrorResponse, StopParam, StreamFrame};
use crate::state::{AppState, FimCompletionRequest, FimStreamStart};

/// POST /v1/completions.
pub async fn completions(
    State(state): State<AppState>,
    Json(wire): Json<CompletionsRequestWire>,
) -> Response {
    // Foreground-yield bump: same rationale as /v1/chat/completions —
    // keystroke-path latency must preempt background ingest work.
    state.bump_foreground_active();

    let Some(prefix) = wire.effective_prefix().map(str::to_string) else {
        return (
            StatusCode::BAD_REQUEST,
            Json(
                serde_json::to_value(ErrorResponse::new(
                    "missing `prefix` (or legacy `prompt`): /v1/completions is the FIM \
                     inline-completion surface and needs the code before the cursor",
                    "invalid_request",
                ))
                .unwrap_or_default(),
            ),
        )
            .into_response();
    };

    let Some(service) = state.inner.local_inference.as_ref() else {
        return (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(
                serde_json::to_value(ErrorResponse::new(
                    "no local inference service on this node — FIM completions need the \
                     embedded llama.cpp service (sovereign daemon)",
                    "model_not_ready",
                ))
                .unwrap_or_default(),
            ),
        )
            .into_response();
    };

    let debug_wanted = wire.debug.unwrap_or(false);
    let model_echo = wire.model.clone();
    let want_stream = wire.stream.unwrap_or(false);
    let request = FimCompletionRequest {
        prefix,
        suffix: wire.suffix.clone().unwrap_or_default(),
        path: wire.path.clone(),
        language: wire.language.clone(),
        max_tokens: wire.max_tokens,
        temperature: wire.temperature,
        stop: wire
            .stop
            .clone()
            .map(StopParam::into_vec)
            .unwrap_or_default(),
        debug: debug_wanted,
        raw_prompt: None,
    };

    let start = match service.fim_completion_stream(request).await {
        Ok(s) => s,
        Err(e) => {
            // The adapter's message is the operator-facing fix
            // (unconfigured → exact [models.fim] snippet; marker-less
            // model → which GGUF shape to use). Surface verbatim.
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                Json(
                    serde_json::to_value(ErrorResponse::new(e, "fim_unavailable"))
                        .unwrap_or_default(),
                ),
            )
                .into_response();
        }
    };

    if want_stream {
        serve_fim_sse(start, debug_wanted, model_echo)
    } else {
        serve_fim_aggregated(start, debug_wanted, model_echo).await
    }
}

/// Envelope ids follow the OpenAI convention (`cmpl-*` + ms epoch).
fn completion_id() -> String {
    format!(
        "cmpl-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0)
    )
}

fn unix_now() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// Non-streaming: consume the whole stream, aggregate the text, and
/// return one OpenAI `text_completion` object. `sovereign_debug` is
/// attached when (and only when) the request opted in.
async fn serve_fim_aggregated(
    start: FimStreamStart,
    debug_wanted: bool,
    model_echo: Option<String>,
) -> Response {
    let FimStreamStart {
        stream,
        model_id,
        slot: _,
        fim_style: _,
    } = start;
    let mut text = String::new();
    let mut finish_reason = "stop".to_string();
    let mut usage = None;
    let mut debug_payload = None;
    let mut stream = Box::pin(stream);
    while let Some(frame) = stream.next().await {
        match frame {
            StreamFrame::Token(t) => text.push_str(&t),
            StreamFrame::Finish { reason, usage: u } => {
                finish_reason = reason.as_openai_str().to_string();
                usage = u;
            }
            StreamFrame::Error(e) => {
                return (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Json(
                        serde_json::to_value(ErrorResponse::new(
                            format!("generation failed mid-stream: {e}"),
                            "backend_error",
                        ))
                        .unwrap_or_default(),
                    ),
                )
                    .into_response();
            }
            StreamFrame::Debug(v) => debug_payload = Some(v),
            StreamFrame::ToolCalls(_) => {
                // Never produced by the FIM adapter; ignore defensively.
            }
        }
    }
    let mut body = serde_json::json!({
        "id": completion_id(),
        "object": "text_completion",
        "created": unix_now(),
        "model": model_echo.unwrap_or(model_id),
        "choices": [{
            "text": text,
            "index": 0,
            "finish_reason": finish_reason,
        }],
    });
    if let Some(u) = usage {
        body["usage"] = serde_json::json!({
            "prompt_tokens": u.prompt_tokens,
            "completion_tokens": u.completion_tokens,
            "total_tokens": u.total_tokens,
        });
    }
    if debug_wanted {
        if let Some(d) = debug_payload {
            body["sovereign_debug"] = d;
        }
    }
    Json(body).into_response()
}

/// Streaming: bridge frames to SSE chunks (`text_completion` object
/// shape), a terminal chunk carrying the real `finish_reason` (+ the
/// opt-in `sovereign_debug`), then the `[DONE]` sentinel.
fn serve_fim_sse(
    start: FimStreamStart,
    debug_wanted: bool,
    model_echo: Option<String>,
) -> Response {
    let id = completion_id();
    let created = unix_now();
    let model = model_echo.unwrap_or_else(|| start.model_id.clone());

    let chunks = start.stream.map(move |frame| {
        let id = id.clone();
        let model = model.clone();
        match frame {
            StreamFrame::Token(delta) => {
                let chunk = serde_json::json!({
                    "id": id,
                    "object": "text_completion",
                    "created": created,
                    "model": model,
                    "choices": [{
                        "index": 0,
                        "text": delta,
                        "finish_reason": null
                    }]
                });
                Ok::<_, std::convert::Infallible>(Event::default().data(chunk.to_string()))
            }
            StreamFrame::Finish { reason, usage } => {
                let mut chunk = serde_json::json!({
                    "id": id,
                    "object": "text_completion",
                    "created": created,
                    "model": model,
                    "choices": [{
                        "index": 0,
                        "text": "",
                        "finish_reason": reason.as_openai_str()
                    }]
                });
                if let Some(u) = usage {
                    chunk["usage"] = serde_json::json!({
                        "prompt_tokens": u.prompt_tokens,
                        "completion_tokens": u.completion_tokens,
                        "total_tokens": u.total_tokens,
                    });
                }
                Ok(Event::default().data(chunk.to_string()))
            }
            StreamFrame::Debug(v) => {
                if debug_wanted {
                    let chunk = serde_json::json!({
                        "id": id,
                        "object": "text_completion",
                        "created": created,
                        "model": model,
                        "choices": [],
                        "sovereign_debug": v,
                    });
                    Ok(Event::default().data(chunk.to_string()))
                } else {
                    // Opted-out debug frames vanish — the comment event
                    // keeps the stream well-formed without payload.
                    Ok(Event::default().comment("debug dropped"))
                }
            }
            StreamFrame::Error(e) => Ok(Event::default().data(format!(
                "{{\"error\":{{\"message\":\"{}\"}}}}",
                e.replace('"', "\\\"")
            ))),
            StreamFrame::ToolCalls(_) => {
                // Never produced by the FIM adapter.
                Ok(Event::default().comment("tool_calls dropped"))
            }
        }
    });
    let done = futures::stream::once(async {
        Ok::<_, std::convert::Infallible>(Event::default().data("[DONE]"))
    });
    Sse::new(chunks.chain(done))
        .keep_alive(KeepAlive::default())
        .into_response()
}

