#[cfg(test)]
mod tests {
    use super::*;
    use std::net::TcpListener;

    #[test]
    fn rpc_worker_listening_reflects_actual_listener() {
        // A live listener on an ephemeral port reads as listening: connect_timeout
        // completes the kernel handshake even before the app calls accept().
        let live = TcpListener::bind("127.0.0.1:0").unwrap();
        let port = live.local_addr().unwrap().port();
        assert!(
            rpc_worker_listening(&format!("0.0.0.0:{port}")),
            "0.0.0.0 form must probe loopback and see the listener"
        );
        assert!(
            rpc_worker_listening(&format!("127.0.0.1:{port}")),
            "explicit-host form must connect too"
        );

        // Once freed, the same port reads as NOT listening — this is the bug we
        // fixed: SOVEREIGN_RPC_SERVE set, but no worker accepting => don't advertise.
        drop(live);
        assert!(
            !rpc_worker_listening(&format!("0.0.0.0:{port}")),
            "a configured-but-dead port must not be advertised"
        );
    }

    #[test]
    fn rpc_worker_listening_rejects_malformed_bind() {
        assert!(!rpc_worker_listening("not-a-bind"));
        assert!(!rpc_worker_listening("0.0.0.0:not-a-port"));
        assert!(!rpc_worker_listening(""));
    }
}

#[cfg(test)]
mod process_status_tests {
    use super::*;

    #[test]
    fn process_status_serializes_and_samples() {
        let p = ProcessStatus {
            uptime_seconds: 42,
            rss_mb: current_rss_mb(),
            peak_rss_mb: peak_rss_mb(),
        };
        // We're a live process: both samples must be present + nonzero
        // on unix targets.
        #[cfg(unix)]
        {
            assert!(p.rss_mb.unwrap() > 0);
            assert!(p.peak_rss_mb.unwrap() > 0);
        }
        let json = serde_json::to_value(&p).unwrap();
        assert_eq!(json["uptime_seconds"], 42);
    }

    #[test]
    fn convergence_arm_buckets_by_cadence_and_alarms_past_threshold() {
        // Fix 9: ages are BRACKETS, never points; staleness flips at
        // the alarm threshold (300s = 30 ticks of the 10s cadence);
        // `never` (None) is honest absence, NOT stale — there is no
        // silence duration to alarm on when the path never fired.
        let fresh = convergence_arm(Some(0));
        assert_eq!((fresh.age_bucket, fresh.stale), ("0-30s", false));
        assert_eq!(convergence_arm(Some(30)).age_bucket, "0-30s");
        assert_eq!(convergence_arm(Some(31)).age_bucket, "30s-2m");
        assert_eq!(convergence_arm(Some(120)).age_bucket, "30s-2m");
        assert_eq!(convergence_arm(Some(121)).age_bucket, "2-5m");
        assert_eq!(convergence_arm(Some(300)).age_bucket, "2-5m");
        let alarmed = convergence_arm(Some(301));
        assert_eq!((alarmed.age_bucket, alarmed.stale), ("5-30m", true));
        let deep = convergence_arm(Some(1800));
        assert_eq!((deep.age_bucket, deep.stale), ("5-30m", true));
        let long = convergence_arm(Some(2461));
        assert_eq!((long.age_bucket, long.stale), (">30m", true));
        let never = convergence_arm(None);
        assert_eq!((never.age_bucket, never.stale), ("never", false));
    }

    #[test]
    fn status_json_carries_the_convergence_section() {
        // Fix 9: a fresh AppState (no recorder installed — pre-boot
        // state) must still serialize the section, honestly reading
        // `never` on both arms rather than omitting the answer.
        let state = crate::state::test_app_state();
        let recorder = std::sync::Arc::new(crate::state::ConvergenceRecord::new());
        recorder.record_outbound_publish_success(sovereign_core::time::unix_now());
        state.inner.install_convergence_recorder(recorder);

        // The live status route needs a running mesh; render the
        // section the same way status() does and check the wire.
        let (outbound, inbound) = state.inner.convergence_recorder().unwrap().snapshot();
        let now = sovereign_core::time::unix_now();
        let section = ConvergenceStatus {
            alarm_threshold_secs: CONVERGENCE_ALARM_THRESHOLD_SECS as u64,
            outbound_publish: convergence_arm(outbound.map(|t| now - t)),
            inbound_ingest: convergence_arm(inbound.map(|t| now - t)),
        };
        let json = serde_json::to_value(&section).unwrap();
        assert_eq!(json["alarm_threshold_secs"], 300);
        assert_eq!(json["outbound_publish"]["age_bucket"], "0-30s");
        assert_eq!(json["outbound_publish"]["stale"], false);
        assert_eq!(json["inbound_ingest"]["age_bucket"], "never");
        assert_eq!(json["inbound_ingest"]["stale"], false);
    }

    #[test]
    fn zero_bucket_row_names_rejected_header_and_expected_form() {
        // Fix 7: the malformed-header bucket (node id 0) names the rejected
        // raw value + expected wire form; well-formed rows are unchanged —
        // the three fields are omitted from the JSON entirely, byte-identical
        // to pre-fix-7 hosts.
        let rejected = Some(crate::state::RejectedNodeIdHeader {
            raw: "not-a-node-id!".into(),
            at_unix: 1786549000,
        });
        let zero_row = PeerRequestStatus {
            node_id: "node-0000000000000000".into(),
            name: None,
            active: 1,
            served_total: 2,
            last_request_at: 1786549000,
            rejected_header_value: rejected.as_ref().map(|r| r.raw.clone()),
            rejected_at_unix: rejected.as_ref().map(|r| r.at_unix),
            expected_wire_form: rejected
                .is_some()
                .then(crate::state::RejectedNodeIdHeader::expected_wire_form),
        };
        let json = serde_json::to_value(&zero_row).unwrap();
        assert_eq!(json["rejected_header_value"], "not-a-node-id!");
        assert_eq!(json["rejected_at_unix"], 1786549000);
        assert!(json["expected_wire_form"]
            .as_str()
            .unwrap()
            .contains("32 lowercase hex chars"));

        let clean_row = PeerRequestStatus {
            node_id: "node-6c955b5f1361aaaa".into(),
            name: Some("BeefyMac".into()),
            active: 0,
            served_total: 5,
            last_request_at: 1786549000,
            rejected_header_value: None,
            rejected_at_unix: None,
            expected_wire_form: None,
        };
        let clean = serde_json::to_value(&clean_row).unwrap();
        assert_eq!(
            clean,
            serde_json::json!({
                "node_id": "node-6c955b5f1361aaaa",
                "name": "BeefyMac",
                "active": 0,
                "served_total": 5,
                "last_request_at": 1786549000,
            })
        );
    }

    #[test]
    fn rpc_worker_iroh_flag_is_additive_on_the_wire() {
        // false → key omitted entirely: byte-identical JSON to pre-task-6
        // workers, so old hosts parse it unchanged.
        let off = serde_json::to_value(RpcWorkerStatus {
            port: 50052,
            iroh: false,
        })
        .unwrap();
        assert_eq!(off, serde_json::json!({ "port": 50052 }));
        // true → advertised; hosts read it with `.get("iroh")` off the
        // opaque JSON, absent-means-false.
        let on = serde_json::to_value(RpcWorkerStatus {
            port: 50052,
            iroh: true,
        })
        .unwrap();
        assert_eq!(on, serde_json::json!({ "port": 50052, "iroh": true }));
    }
}

