    #[test]
    fn days_between_saturates_on_clock_skew() {
        assert_eq!(days_between(100, 50), 0);
        assert_eq!(days_between(100, 100), 0);
        assert_eq!(days_between(0, 86_400 * 3), 3);
    }

    #[test]
    fn format_iso_date_renders_utc_year_month_day() {
