            source: "agent".to_string(),
            supersedes: None,
            payload_json: None,
            origin_node_id: Some(format!("peer-{model_id}")),
        },
        embedding: Some(ExportedNoteEmbedding {
            model_id: model_id.to_string(),
            dim: vec.len() as i64,
            embedding: le_bytes(vec),
        }),
        entities: vec![],
        tombstone: false,
        updated_at: 1_700_000_000,
