    #[test]
    fn owner_is_the_crate_every_user_already_depends_on() {
        let syms = vec![
            sym("core", "m/Verdict#", "sovereign/crates/core/src/m.rs", 10),
            sym("mesh", "n/Verdict#", "sovereign/crates/mesh/src/n.rs", 20),
            sym(
                "contracts",
                "c/Anchor#",
                "sovereign/crates/contracts/src/c.rs",
