            ),
            sym("store", "s/Anchor#", "sovereign/crates/store/src/s.rs", 1),
        ];
        let defs = type_defs(&syms, &SourceScope::default());
        let refs = vec![
            // Both definitions are used by `cli`.
            rf(
                "cli",
                "f().",
                "core",
                "m/Verdict#",
                "sovereign/crates/cli/src/a.rs",
            ),
            rf(
                "cli",
                "f().",
                "mesh",
                "n/Verdict#",
                "sovereign/crates/cli/src/a.rs",
