    }

    #[test]
    fn no_shared_dependency_yields_no_candidate_rather_than_a_guess() {
        let syms = vec![
            sym("a", "m/Thing#", "sovereign/crates/a/src/m.rs", 1),
            sym("b", "n/Thing#", "sovereign/crates/b/src/n.rs", 1),
