    fn returns_empty_when_no_section_id() {
        let atoms = vec![entity_atom(1, "Alyosha", &[], "sec_0001")];
        assert!(detect_atom_spans("Alyosha walked.", None, &atoms).is_empty());
    }

    #[test]
    fn no_spans_when_atom_anchored_at_different_section() {
        let atoms = vec![entity_atom(1, "Alyosha", &[], "sec_0042")];
        // Same text, but the atom anchors at a different section —
        // so we don't light it up here.
        assert!(detect_atom_spans("Alyosha walked.", Some("sec_0001"), &atoms).is_empty());
    }

    #[test]
    fn finds_canonical_name_with_byte_offsets_that_round_trip() {
        let atoms = vec![entity_atom(1, "Alyosha", &[], "sec_0001")];
        let text = "When Alyosha entered the room, he was silent.";
        let spans = detect_atom_spans(text, Some("sec_0001"), &atoms);
        assert_eq!(spans.len(), 1);
        let s = &spans[0];
        assert_eq!(s.atom_type, "entity");
        assert_eq!(&text[s.span_start..s.span_end], "Alyosha");
        assert_eq!(s.surface_form, "Alyosha");
    }

    #[test]
    fn case_insensitive_match_preserves_original_casing_in_surface_form() {
        let atoms = vec![entity_atom(1, "Alyosha", &[], "sec_0001")];
        let text = "alyosha and ALYOSHA are the same person.";
        let spans = detect_atom_spans(text, Some("sec_0001"), &atoms);
        assert_eq!(spans.len(), 2);
        assert_eq!(spans[0].surface_form, "alyosha");
        assert_eq!(spans[1].surface_form, "ALYOSHA");
    }

    #[test]
    fn alias_matches_when_canonical_does_not() {
        let atoms = vec![entity_atom(
            1,
            "Alexei Fyodorovich Karamazov",
            &["Alyosha"],
            "sec_0001",
        )];
        let text = "Alyosha is a novice.";
        let spans = detect_atom_spans(text, Some("sec_0001"), &atoms);
        assert_eq!(spans.len(), 1);
        assert_eq!(spans[0].surface_form, "Alyosha");
    }

    #[test]
    fn whole_word_boundary_prevents_substring_false_positive() {
        // "Fyodor" should NOT match inside the patronymic
        // "Fyodorovich" — the textbook drift-confusion bug.
        let atoms = vec![entity_atom(1, "Fyodor", &[], "sec_0001")];
        let text = "Alexei Fyodorovich was the youngest.";
        let spans = detect_atom_spans(text, Some("sec_0001"), &atoms);
        assert!(spans.is_empty(), "spans = {:?}", spans);
    }

    #[test]
    fn longest_match_wins_on_overlap() {
        // Two atoms whose surface forms overlap on the same span:
        // the longer one should win, the shorter is suppressed.
        let atoms = vec![
            entity_atom(1, "Fyodor Karamazov", &[], "sec_0001"),
            entity_atom(2, "Fyodor", &[], "sec_0001"),
        ];
        let text = "Fyodor Karamazov died first.";
        let spans = detect_atom_spans(text, Some("sec_0001"), &atoms);
        assert_eq!(spans.len(), 1);
        assert_eq!(spans[0].surface_form, "Fyodor Karamazov");
        assert_eq!(spans[0].atom_id, "entity-0001");
    }

    #[test]
    fn state_label_lights_up() {
        let state = AtomEnvelope::State(State {
            id: AtomId::state(1),
            entity_id: AtomId::entity(1),
            label: "in crisis".into(),
            state_type: StateType::Psychological,
            evidence: vec![ChunkRef::new("sec_0001", None)],
            section_range: SectionRange::point("sec_0001"),
            confidence: None,
            enrichment_depth: EnrichmentDepth::Extracted,
        });
        let text = "By chapter three he was in crisis again.";
        let spans = detect_atom_spans(text, Some("sec_0001"), &[state]);
        assert_eq!(spans.len(), 1);
        assert_eq!(spans[0].atom_type, "state");
        assert_eq!(spans[0].surface_form, "in crisis");
    }

    #[test]
    fn empty_text_yields_empty_spans() {
        let atoms = vec![entity_atom(1, "Alyosha", &[], "sec_0001")];
        assert!(detect_atom_spans("", Some("sec_0001"), &atoms).is_empty());
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Canonical-index sync: pack/unpack helpers for cross-peer transfer.
//!
//! Phase 6 of the resilience track. The mesh's `auto_recover` path
//! and the `sovereign corpus pull` CLI both need to ship a complete
//! canonical index — `<index_dir>/<corpus_id>/` — over HTTP and
//! reconstruct it on the receiving node. This module is the
//! transport-agnostic packing primitive: it produces a tar stream
//! compressed with zstd, and the inverse extractor.
//!
//! ## Why tar+zstd
//!
//! - **tar**: handles the directory walk, preserves file modes /
//!   timestamps, and tolerates LanceDB's mix of small JSON files
//!   and large fragment shards in one archive. The pure-Rust `tar`
//!   crate's streaming writer doesn't need the size up front, which
//!   matters when the canonical contains 100s of fragment files
//!   none of which we want to stat-and-buffer twice.
//! - **zstd**: 3–5× compression on LanceDB binary data in practice,
//!   ~600 MB/s compression speed at the default level on a modern
//!   CPU. The `zstd` crate exposes a `Encoder<W>` that fits the
//!   `Write` trait, so we can chain `tar::Builder<Encoder<W>>` and
//!   pipe straight through.
//!
//! ## Streaming model
//!
//! Both pack and unpack are synchronous functions that take a
//! `Write` / `Read` respectively. Callers that want async streaming
//! (the HTTP server, the HTTP client) wrap them with the standard
//! `tokio_util::io::SyncIoBridge` inside a `spawn_blocking` task.
//! Keeping this module sync-only avoids pulling tokio into a
//! pure-data crate.

use std::io::{Read, Write};
use std::path::Path;

use crate::error::{Error, Result};

/// Pack the canonical index directory at `canonical_path` into a
/// tar+zstd stream written to `writer`. Returns the number of
/// uncompressed bytes streamed (sum of file sizes plus tar
/// overhead) so callers can log throughput.
///
/// `compression_level` is passed through to zstd; a sensible
/// default is `0` (zstd's default level — currently 3, balances
/// ratio vs CPU). For Wikipedia-scale canonicals on a fast
/// network, level 1 is ~2× faster with a ~10% size penalty.
///
/// **Filesystem inputs**: walks every regular file under
/// `canonical_path` and records relative paths. Symlinks, sockets,
/// and devices are skipped (LanceDB never produces them; refusing
/// is safer than blindly preserving). The function does NOT fsync
/// — callers that need durability after a checksum-validated
/// receive should fsync the destination directory themselves.
///
/// Aborts on the first I/O error rather than continuing with a
/// half-built archive.
pub fn pack_canonical<W: Write>(
    canonical_path: &Path,
    writer: W,
    compression_level: i32,
) -> Result<u64> {
    if !canonical_path.is_dir() {
        return Err(Error::IndexNotFound(format!(
            "pack_canonical: not a directory: {}",
            canonical_path.display()
        )));
    }

    let encoder = zstd::Encoder::new(writer, compression_level)
        .map_err(|e| Error::Database(format!("pack_canonical: zstd init: {e}")))?
        // `auto_finish` ensures the encoder's frame is finalized on
        // drop. Without it, a panic mid-walk produces a truncated
        // zstd stream the receiver rejects.
        .auto_finish();

    let mut builder = tar::Builder::new(encoder);
    builder.mode(tar::HeaderMode::Deterministic);

    // Walk relative to canonical_path so the archive contains
    // entries like `chunks.lance/_versions/...` rather than
    // absolute paths. The receiver unpacks into a fresh directory
    // under its own index_dir so this layout is what it needs.
    let mut bytes_in: u64 = 0;
    walk_and_append(&mut builder, canonical_path, canonical_path, &mut bytes_in)?;
    builder
        .finish()
        .map_err(|e| Error::Database(format!("pack_canonical: tar finish: {e}")))?;
    drop(builder); // Drops the auto_finish encoder, finalizing zstd.
    Ok(bytes_in)
}

fn walk_and_append<W: Write>(
    builder: &mut tar::Builder<W>,
    root: &Path,
    dir: &Path,
    bytes_in: &mut u64,
) -> Result<()> {
    let entries = std::fs::read_dir(dir)
        .map_err(|e| Error::Database(format!("pack_canonical: read_dir {}: {e}", dir.display())))?;
    for entry in entries {
        let entry =
            entry.map_err(|e| Error::Database(format!("pack_canonical: dir entry: {e}")))?;
        let path = entry.path();
        let rel = path
            .strip_prefix(root)
            .map_err(|e| Error::Database(format!("pack_canonical: strip_prefix: {e}")))?;

        let meta = entry.metadata().map_err(|e| {
            Error::Database(format!("pack_canonical: metadata {}: {e}", path.display()))
        })?;
        if meta.is_dir() {
            walk_and_append(builder, root, &path, bytes_in)?;
        } else if meta.is_file() {
            let mut header = tar::Header::new_gnu();
            header.set_size(meta.len());
            header.set_mode(0o644);
            header.set_mtime(0);
            header.set_cksum();
            let mut file = std::fs::File::open(&path).map_err(|e| {
                Error::Database(format!("pack_canonical: open {}: {e}", path.display()))
            })?;
            builder
                .append_data(&mut header, rel, &mut file)
                .map_err(|e| {
                    Error::Database(format!("pack_canonical: append {}: {e}", rel.display()))
                })?;
            *bytes_in = bytes_in.saturating_add(meta.len());
        }
        // Symlinks and other special files: silently skipped.
        // LanceDB never produces them in a canonical index dir;
        // if a future format does, we can extend this branch.
    }
    Ok(())
}

/// Inverse of [`pack_canonical`]. Decompresses + extracts the
/// stream from `reader` into `dest_path` (which must NOT already
/// exist — the caller is responsible for atomic rename semantics
/// after a fingerprint-validated unpack).
///
/// Returns the number of uncompressed bytes written so the caller
/// can log throughput.
///
/// **Path safety**: the tar extractor refuses entries whose
/// normalized path escapes `dest_path` (e.g. `../../etc/passwd`).
/// `tar::Archive::set_overwrite(false)` is set so a duplicate
/// entry can't blast over an earlier one — defence-in-depth even
/// though our `pack_canonical` won't produce duplicates.
pub fn unpack_canonical<R: Read>(reader: R, dest_path: &Path) -> Result<u64> {
    if dest_path.exists() {
        return Err(Error::Database(format!(
            "unpack_canonical: refuses to overwrite existing {}",
            dest_path.display()
        )));
    }
    std::fs::create_dir_all(dest_path).map_err(|e| {
        Error::Database(format!(
            "unpack_canonical: mkdir {}: {e}",
            dest_path.display()
        ))
    })?;

    let decoder = zstd::Decoder::new(reader)
        .map_err(|e| Error::Database(format!("unpack_canonical: zstd init: {e}")))?;
    let mut archive = tar::Archive::new(decoder);
    archive.set_overwrite(false);
    archive.set_preserve_permissions(false);

    let mut bytes_out: u64 = 0;
    let entries = archive
        .entries()
        .map_err(|e| Error::Database(format!("unpack_canonical: entries: {e}")))?;
    for entry in entries {
        let mut entry =
            entry.map_err(|e| Error::Database(format!("unpack_canonical: entry: {e}")))?;
        // Path safety check: tar::Entries::path returns the entry's
        // declared path; we additionally verify the canonicalised
        // unpack target falls under dest_path before unpacking.
        let entry_path = entry
            .path()
            .map_err(|e| Error::Database(format!("unpack_canonical: path: {e}")))?
            .into_owned();
        if entry_path.is_absolute() {
            return Err(Error::Database(format!(
                "unpack_canonical: refuses absolute path entry {}",
                entry_path.display()
            )));
        }
        if entry_path
            .components()
            .any(|c| matches!(c, std::path::Component::ParentDir))
        {
            return Err(Error::Database(format!(
                "unpack_canonical: refuses '..' in entry path {}",
                entry_path.display()
            )));
        }
        let target = dest_path.join(&entry_path);
        if let Some(parent) = target.parent() {
            std::fs::create_dir_all(parent).map_err(|e| {
                Error::Database(format!("unpack_canonical: mkdir {}: {e}", parent.display()))
            })?;
        }
        let written = entry.unpack(&target).map_err(|e| {
            Error::Database(format!(
                "unpack_canonical: unpack {}: {e}",
                target.display()
            ))
        })?;
        let _ = written; // Ok(()) variant
        bytes_out = bytes_out.saturating_add(entry.size());
    }
    Ok(bytes_out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::tempdir;

    /// Round-trip: pack a tiny synthetic canonical, unpack into a
    /// fresh dir, byte-for-byte assert the file tree is identical.
    #[test]
    fn pack_unpack_round_trips_directory_tree() {
        let src = tempdir().unwrap();
        let canonical = src.path().join("test-corpus");
        fs::create_dir_all(canonical.join("chunks.lance/_versions")).unwrap();
        fs::write(
            crate::corpus::Corpus::meta_in(&canonical),
            b"{\"corpus_id\":\"test\"}",
        )
        .unwrap();
        fs::write(canonical.join("chunks.lance/manifest.json"), b"manifest").unwrap();
        fs::write(
            canonical.join("chunks.lance/_versions/1.bin"),
            vec![0u8; 1024],
        )
        .unwrap();
        fs::write(
            canonical.join("chunks.lance/_versions/2.bin"),
            vec![42u8; 2048],
        )
        .unwrap();

        let dst = tempdir().unwrap();
        let dst_canonical = dst.path().join("restored");

        // Pack into an in-memory buffer (small enough), then unpack.
        let mut buf: Vec<u8> = Vec::new();
        let bytes_in = pack_canonical(&canonical, &mut buf, 1).unwrap();
        assert!(bytes_in > 0);
        let bytes_out = unpack_canonical(buf.as_slice(), &dst_canonical).unwrap();
        assert!(bytes_out > 0);

        // File tree equality.
        let read = |p: &Path| std::fs::read(p).unwrap();
        assert_eq!(
            read(&crate::corpus::Corpus::meta_in(&canonical)),
            read(&dst_canonical.join("_corpus_meta.json"))
        );
        assert_eq!(
            read(&canonical.join("chunks.lance/manifest.json")),
            read(&dst_canonical.join("chunks.lance/manifest.json"))
        );
        assert_eq!(
            read(&canonical.join("chunks.lance/_versions/1.bin")),
            read(&dst_canonical.join("chunks.lance/_versions/1.bin"))
        );
        assert_eq!(
            read(&canonical.join("chunks.lance/_versions/2.bin")),
            read(&dst_canonical.join("chunks.lance/_versions/2.bin"))
        );
    }

    /// `unpack_canonical` refuses an existing destination — the
    /// caller's atomic-rename pattern (write to temp, validate
    /// fingerprint, rename) depends on this behaviour. Without it,
    /// a partial-overlap unpack could mix-and-match files.
    #[test]
    fn unpack_canonical_refuses_existing_dest() {
        let dir = tempdir().unwrap();
        let dst = dir.path().join("preexists");
        std::fs::create_dir_all(&dst).unwrap();
        let buf: Vec<u8> = vec![0; 128];
        let r = unpack_canonical(buf.as_slice(), &dst);
        assert!(r.is_err(), "expected refusal on existing dest");
    }

    /// `pack_canonical` errors when the source isn't a directory
    /// (e.g. caller passed a file by mistake or the canonical was
    /// removed mid-flight). We surface a clear IndexNotFound rather
    /// than blindly producing an empty archive.
    #[test]
    fn pack_canonical_errors_on_non_directory() {
        let dir = tempdir().unwrap();
        let bogus = dir.path().join("does-not-exist");
        let mut buf: Vec<u8> = Vec::new();
        let r = pack_canonical(&bogus, &mut buf, 0);
        assert!(r.is_err());
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Section-aware chunking.
//!
//! Unlike `ParagraphChunker`, this splits text into sections first
//! (via a pluggable `SectionDetector`), then into paragraph-sized
//! chunks inside each section. Every emitted chunk carries the
//! containing section's id + title, so downstream phases can group
//! paragraphs back to their source section without re-parsing the
//! document.
//!
//! Used by the v2 enrichment pipeline to feed chapter-level inputs
//! into phase 1 (per-chapter question extraction) while still keeping
//! paragraph-level chunks for embedding-based clustering.
//!
//! The pure detector half (`SectionDetector`, `DetectedSection`,
//! `ChapterRegexDetector`, `TocAnchoredDetector`) lives in the
//! `corpus-engine-sections` leaf so the workflow `SectionTool` and this
//! and this bespoke ingest path share one segmentation implementation.
//! It is re-exported below at the historical path, so existing callers
//! (`corpus_engine::chunkers::sectioned::*`) are unaffected. Only the
//! `SectionedChunker` — which pairs a detector with this crate's
//! `ParagraphChunker` — stays here.

use std::collections::HashMap;

use super::paragraph::ParagraphChunker;
use super::{floor_char_boundary, Chunker};

pub use sovereign_contracts::recipe::sections::{
    ChapterRegexDetector, DetectedSection, SectionDetector, TocAnchoredDetector,
};

/// A paragraph chunk annotated with its containing section.
#[derive(Debug, Clone)]
pub struct SectionedChunk {
    pub content: String,
    /// Global 0-based index across the whole document.
    pub index: usize,
    pub section_id: String,
    pub section_title: String,
    /// 0-based index of this paragraph inside its section.
    pub paragraph_index: usize,
    /// Carried verbatim from the detector.
    pub metadata: HashMap<String, String>,
}

/// Chunks a document by section, then by paragraph within each section.
///
/// Generic over the detector so tests can swap in a stub without the
/// regex cost, and so future detectors (markdown, journal-by-date)
/// can be composed in.
pub struct SectionedChunker<D: SectionDetector> {
    detector: D,
    paragraph: ParagraphChunker,
}

impl<D: SectionDetector> SectionedChunker<D> {
    pub fn new(detector: D, paragraph: ParagraphChunker) -> Self {
        Self {
            detector,
            paragraph,
        }
    }

    pub fn with_detector(detector: D) -> Self {
        Self::new(detector, ParagraphChunker::default())
    }

    /// Detected sections without emitting chunks. Useful for
    /// `enrich init --dry-run` so the user can verify segmentation
    /// before committing to an ingest.
    pub fn dry_run(&self, text: &str) -> SectionReport {
        let sections = self.detector.detect(text);
        SectionReport {
            total: sections.len(),
            sections,
        }
    }

    pub fn chunk(&self, text: &str) -> Vec<SectionedChunk> {
        let sections = self.detector.detect(text);
        if sections.is_empty() {
            return Vec::new();
        }

        let mut out = Vec::new();
        let mut global_index = 0usize;
        for section in &sections {
            let start = floor_char_boundary(text, section.start_byte);
            let end = floor_char_boundary(text, section.end_byte);
            if end <= start {
                continue;
            }
            let section_text = &text[start..end];
            let paragraphs = self.paragraph.chunk(section_text);
            for (para_idx, para) in paragraphs.into_iter().enumerate() {
                out.push(SectionedChunk {
                    content: para.content,
                    index: global_index,
                    section_id: section.id.clone(),
                    section_title: section.title.clone(),
                    paragraph_index: para_idx,
                    metadata: section.metadata.clone(),
                });
                global_index += 1;
            }
        }
        out
    }
}

/// Summary of what a detector found without running the full chunker.
#[derive(Debug, Clone)]
pub struct SectionReport {
    pub total: usize,
    pub sections: Vec<DetectedSection>,
}

impl SectionReport {
    /// Human-readable summary used by `enrich init --dry-run`.
    pub fn format_summary(&self, text: &str) -> String {
        let mut out = format!("Detected {} section(s):\n", self.total);
        let shown = self.sections.len().min(20);
        for (i, sec) in self.sections.iter().take(shown).enumerate() {
            let body_end = sec.end_byte.min(text.len());
            let body_start = sec.start_byte.min(body_end);
            let first_line = text[body_start..body_end]
                .lines()
                .find(|l| !l.trim().is_empty())
                .unwrap_or("")
                .chars()
                .take(80)
                .collect::<String>();
            out.push_str(&format!("  {:>3}. {} — {}\n", i + 1, sec.title, first_line));
        }
        if self.sections.len() > shown {
            out.push_str(&format!("  ... and {} more\n", self.sections.len() - shown));
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn gutenberg_like(chapters: usize) -> String {
        let mut s = String::new();
        s.push_str("PREAMBLE: This should not be captured.\n\n");
        for i in 1..=chapters {
            s.push_str(&format!("Chapter {i}\n\n"));
            s.push_str(&format!(
                "This is the body of chapter {i}. It has two paragraphs.\n\n"
            ));
            s.push_str(&format!(
                "And here is the second paragraph of chapter {i}, still inside it.\n\n"
            ));
        }
        s
    }

    #[test]
    fn sectioned_chunker_attaches_section_id_to_paragraphs() {
        let text = gutenberg_like(2);
        let chunker = SectionedChunker::with_detector(ChapterRegexDetector::new());
        let chunks = chunker.chunk(&text);
        // Two chapters × two paragraphs each, but ParagraphChunker
        // coalesces small paragraphs into one chunk when they fit.
        // What we need to verify: every chunk has a section_id, and the
        // two chapters produce distinct section_ids.
        assert!(!chunks.is_empty());
        let ids: std::collections::HashSet<_> =
            chunks.iter().map(|c| c.section_id.as_str()).collect();
        assert_eq!(ids.len(), 2, "expected chunks spanning 2 sections");
        for chunk in &chunks {
            assert!(!chunk.section_id.is_empty());
            assert!(chunk.section_title.starts_with("Chapter"));
        }
    }

    #[test]
    fn sectioned_chunker_global_index_is_monotonic() {
        let text = gutenberg_like(3);
        let chunker = SectionedChunker::with_detector(ChapterRegexDetector::new());
        let chunks = chunker.chunk(&text);
        for (i, chunk) in chunks.iter().enumerate() {
            assert_eq!(chunk.index, i);
        }
    }

    #[test]
    fn sectioned_chunker_long_chapter_splits_into_many_paragraphs() {
        // One big chapter that will force paragraph splitting.
        let long_para = "A long repeated paragraph sentence that fills a lot of bytes. ".repeat(80);
        let text = format!(
            "Chapter 1\n\n{long_para}\n\n{long_para}\n\n{long_para}\n\nChapter 2\n\ntiny body\n"
        );
        let chunker =
            SectionedChunker::new(ChapterRegexDetector::new(), ParagraphChunker::new(512, 64));
        let chunks = chunker.chunk(&text);
        let ch1: Vec<_> = chunks
            .iter()
            .filter(|c| c.section_id == "sec_0001")
            .collect();
        let ch2: Vec<_> = chunks
            .iter()
            .filter(|c| c.section_id == "sec_0002")
            .collect();
        assert!(
            ch1.len() >= 3,
            "long chapter should produce multiple paragraph chunks, got {}",
            ch1.len()
        );
        assert_eq!(
            ch2.len(),
            1,
            "tiny chapter should produce exactly one chunk"
        );
        // paragraph_index is per-section and starts at 0.
        assert_eq!(ch1[0].paragraph_index, 0);
        assert_eq!(ch2[0].paragraph_index, 0);
    }

    #[test]
    fn dry_run_reports_detected_sections_without_chunking() {
        let text = gutenberg_like(5);
        let chunker = SectionedChunker::with_detector(ChapterRegexDetector::new());
        let report = chunker.dry_run(&text);
        assert_eq!(report.total, 5);
        let summary = report.format_summary(&text);
        assert!(summary.contains("Detected 5 section(s)"));
        assert!(summary.contains("Chapter 1"));
    }

    #[test]
    fn chunker_returns_empty_on_no_matches() {
        let text = "just prose, no chapter markers";
        let chunker = SectionedChunker::with_detector(ChapterRegexDetector::new());
        assert!(chunker.chunk(text).is_empty());
    }

    #[test]
    fn utf8_safe_at_section_bounds() {
        // A chapter heading followed by a body containing multibyte
        // characters (curly quotes, em-dashes). The floor_char_boundary
        // in SectionedChunker::chunk must keep us on char boundaries
        // even if the detector's bounds land mid-char — which they
        // shouldn't, but we defend anyway.
        let text = "Chapter 1\n\n\u{201C}Hello\u{2014}world\u{201D} she said.\n\nChapter 2\nend\n";
        let chunker = SectionedChunker::with_detector(ChapterRegexDetector::new());
        let chunks = chunker.chunk(text);
        assert!(!chunks.is_empty());
        assert!(chunks[0].content.contains("Hello"));
    }

    #[test]
    fn section_metadata_propagates_to_chunks() {
        let text = gutenberg_like(2);
        let chunker = SectionedChunker::with_detector(ChapterRegexDetector::new());
        let chunks = chunker.chunk(&text);
        let first = &chunks[0];
        assert_eq!(first.metadata.get("ordinal").map(String::as_str), Some("1"));
        let last = chunks.last().unwrap();
        assert_eq!(last.metadata.get("ordinal").map(String::as_str), Some("2"));
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Threaded-turn chunker for chat-transcript content.
//!
//! Reads the turn-block format emitted by `AnthropicExportExtractor`:
//!
//! ```text
//! ### [2025-09-04 18:01] user
//!
//! What was our burn rate last month?
//!
//! ### [2025-09-04 18:02] assistant
//!
//! Based on the bank statement you shared, burn was $312k.
//! ```
//!
//! Groups each `user` turn with the immediately-following `assistant`
//! reply into one chunk. A dangling `user` turn (no reply) or a
//! leading `assistant` turn (no preceding user — rare in claude.ai
//! exports) becomes a standalone chunk.
//!
//! ## Turn authorship
//!
//! Conversation history and inner-work journaling are corpora where
//! "who wrote this span?" is load-bearing — searching for "what did
//! *I* decide about X" must not return spans authored by the model,
//! and vice versa. The chunker therefore emits a parallel
//! `AttributedChunk` surface alongside the plain `TextChunk`:
//!
//! - `Chunker::chunk` returns `Vec<TextChunk>` for pipeline
//!   compatibility (embedding, FTS index, default retrieval).
//! - `chunk_attributed` returns `Vec<AttributedChunk>`, where each
//!   chunk carries `spans: Vec<TurnSpan>` listing the byte ranges
//!   inside the chunk content that came from each author.
//!
//! Downstream code that cares about authorship (atlas extraction,
//! filtered retrieval, bench scoring) consumes `chunk_attributed`;
//! everything else stays on the plain surface.
//!
//! ### Attribution enum scope
//!
//! Today the variants are `User` and `Assistant`. The enum reserves
//! `Unattributed` and `Pasted` for the inner-work journaling ingest
//! (a separate extractor): journals contain free-form prose (no
//! marker), and sometimes spans the user has pasted in from a model
//! elsewhere — authorship is the user, underlying generation is the
//! model, retrieval may want to weight that differently. Defining
//! the variants here keeps a single `Attribution` type across both
//! corpora so retrieval and bench code does not branch on corpus
//! type.

use regex::Regex;
use std::sync::OnceLock;

use super::{floor_char_boundary, Chunker, TextChunk};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Attribution {
    User,
    Assistant,
    /// Free-form prose with no explicit sender — reserved for the
    /// inner-work journaling ingest. Not emitted by this chunker.
    Unattributed,
    /// Text the user pasted from a model elsewhere; claimed author
    /// is the user, generated by a model. Reserved for inner-work
    /// journaling ingest. Not emitted by this chunker.
    Pasted,
}

impl Attribution {
    pub fn slug(self) -> &'static str {
        match self {
            Attribution::User => "user",
            Attribution::Assistant => "assistant",
            Attribution::Unattributed => "unattributed",
            Attribution::Pasted => "pasted",
        }
    }
}

#[derive(Debug, Clone)]
pub struct TurnSpan {
    pub attribution: Attribution,
    /// `YYYY-MM-DD HH:MM` shape if the source had a timestamp, else
    /// `None`. Inner-work journaling spans without timestamps will
    /// pass `None`.
    pub timestamp: Option<String>,
    /// Byte offsets inside the parent chunk's `content` string. Half-
    /// open: `[start, end)`. Always falls on UTF-8 char boundaries
    /// because the chunker only ever concatenates whole turn blocks.
    pub byte_range: (usize, usize),
}

#[derive(Debug, Clone)]
pub struct AttributedChunk {
    pub content: String,
    pub index: usize,
    pub spans: Vec<TurnSpan>,
}

pub struct ThreadedTurnsChunker;

/// Soft cap on the byte length of a single chunk emitted by this
/// chunker. Mirrors the default paragraph-chunker cap (1500 chars
/// ≈ ~400 tokens at English-prose densities) so paired-turn output
/// lands inside the embed slot's `max_input_tokens = 1024` budget
/// even when a user has pasted a large code block or document into
/// one turn.
///
/// Without this cap, oversized chunks throttled batch embedding to
/// 1.2 seqs/sec (vs. 29-33 seqs/sec on wikipedia paragraphs) during
/// the first end-to-end import of a real claude.ai export.
/// `_BAK-2026-05-18` in `~/.svrnmesh/conversations/` is the
/// reproducer; the conversations-anthropic ingest moved at
/// ~4 chunks/sec until this cap landed.
///
/// 1500 chars is a soft target — the splitter tries to break on a
/// blank line first (preserves paragraph shape), then any newline,
/// then falls back to a raw char boundary. The 1.4× safety margin
/// (`MAX_HARD_CHARS`) catches the rare case where no whitespace
/// exists in the chunk's tail (e.g. a base64 blob), keeping the
/// embed slot from truncating mid-multibyte.
const MAX_CHUNK_CHARS: usize = 1500;

/// Absolute ceiling — when the splitter can't find a soft boundary
/// inside the [MAX_CHUNK_CHARS, MAX_HARD_CHARS] window, it forces a
/// break at a UTF-8 char boundary at `MAX_HARD_CHARS`.
const MAX_HARD_CHARS: usize = 2100;

/// Inter-chunk overlap (in chars) for split sub-chunks. Bridges a
/// fact that straddled the soft boundary — the same posture
/// `ParagraphChunker` takes with its 100-char default. Sub-chunks
/// derived from one turn pair carry the same `Attribution` spans,
/// clipped to each sub-chunk's byte range.
const SPLIT_OVERLAP_CHARS: usize = 80;

impl ThreadedTurnsChunker {
    pub fn new() -> Self {
        Self
    }

    /// Chunk with per-span author. Each returned chunk has a
    /// `spans` vector — typically two entries (user + assistant), or
    /// one for a dangling turn.
    pub fn chunk_attributed(&self, text: &str) -> Vec<AttributedChunk> {
        let turns = parse_turns(text);
        if turns.is_empty() {
            let trimmed = text.trim();
            if trimmed.is_empty() {
                return Vec::new();
            }
            // Degrade: whole-text chunk with no attribution markers.
            // Caller using this chunker on non-conversation content
            // gets a single Unattributed span so authorship surfaces
            // are still type-coherent.
            let content = trimmed.to_string();
            let end = content.len();
            return vec![AttributedChunk {
                content,
                index: 0,
                spans: vec![TurnSpan {
                    attribution: Attribution::Unattributed,
                    timestamp: None,
                    byte_range: (0, end),
                }],
            }];
        }

        let mut chunks: Vec<AttributedChunk> = Vec::new();
        let mut idx = 0usize;
        let mut i = 0usize;
        while i < turns.len() {
            let curr = &turns[i];
            let next = turns.get(i + 1);
            let mut content = String::new();
            let mut spans: Vec<TurnSpan> = Vec::new();

            let append = |content: &mut String, spans: &mut Vec<TurnSpan>, t: &ParsedTurn| {
                if !content.is_empty() {
                    content.push_str("\n\n");
                }
                let start = content.len();
                content.push_str(&t.block);
                let end = content.len();
                spans.push(TurnSpan {
                    attribution: t.attribution,
                    timestamp: t.timestamp.clone(),
                    byte_range: (start, end),
                });
            };

            let step = if curr.attribution == Attribution::User
                && next.map(|n| n.attribution) == Some(Attribution::Assistant)
            {
                append(&mut content, &mut spans, curr);
                append(&mut content, &mut spans, next.unwrap());
                2
            } else {
                append(&mut content, &mut spans, curr);
                1
            };

            // Size cap: oversized chunks (e.g. user pasted a 30K-byte
            // code dump as one turn) throttle the embed pipeline
            // because the slot tokenises the whole input before
            // truncating at `max_input_tokens`. Split into sub-chunks
            // bounded by `MAX_CHUNK_CHARS`, preserving per-span
            // attribution by clipping each sub-chunk's spans to its
            // byte range.
            for sub in split_oversized(content, spans) {
                chunks.push(AttributedChunk {
                    content: sub.content,
                    index: idx,
                    spans: sub.spans,
                });
                idx += 1;
            }
            i += step;
        }
        chunks
    }
}

/// Helper: split a paired-turn chunk into one-or-more chunks each
/// ≤ `MAX_CHUNK_CHARS` (soft) / `MAX_HARD_CHARS` (hard). Returns the
/// content unchanged when the input is already small enough.
struct SplitChunk {
    content: String,
    spans: Vec<TurnSpan>,
}

fn split_oversized(content: String, spans: Vec<TurnSpan>) -> Vec<SplitChunk> {
    if content.len() <= MAX_CHUNK_CHARS {
        return vec![SplitChunk { content, spans }];
    }
    let mut out: Vec<SplitChunk> = Vec::new();
    let mut pos = 0usize;
    while pos < content.len() {
        let remaining = content.len() - pos;
        if remaining <= MAX_CHUNK_CHARS {
            let sub_content = content[pos..].to_string();
            let sub_spans = clip_spans(&spans, pos, content.len());
            out.push(SplitChunk {
                content: sub_content,
                spans: sub_spans,
            });
            break;
        }
        // Soft target: try to break on a blank line near MAX_CHUNK_CHARS.
        // Snap to a UTF-8 char boundary BEFORE any slicing — a naked
        // `pos + MAX_CHUNK_CHARS` can land inside an em-dash (3-byte
        // `—`) or any multi-byte glyph, and the subsequent `&content
        // [..soft_target]` slice panics. Real-world repro on an
        // anthropic export: byte 2979 fell inside `—` (2977..2980).
        let raw_soft = pos + MAX_CHUNK_CHARS;
        let soft_target = floor_char_boundary(&content, raw_soft);
        let mut end = next_soft_boundary(&content, soft_target).unwrap_or_else(|| {
            // Same boundary discipline on the hard fallback —
            // both targets are derived from byte arithmetic.
            let raw_hard = (soft_target + (MAX_HARD_CHARS - MAX_CHUNK_CHARS)).min(content.len());
            floor_char_boundary(&content, raw_hard)
        });
        // Don't loop forever if the splitter returned an end ≤ pos
        // (degenerate input — pos has no \n or boundary).
        if end <= pos {
            end = floor_char_boundary(
                &content,
                (soft_target + (MAX_HARD_CHARS - MAX_CHUNK_CHARS)).min(content.len()),
            );
        }
        let sub_content = content[pos..end].to_string();
        let sub_spans = clip_spans(&spans, pos, end);
        out.push(SplitChunk {
            content: sub_content,
            spans: sub_spans,
        });
        // Advance past the boundary, leaving a small overlap so a fact
        // straddling the cut survives in the next sub-chunk too.
        // Snap the rewound `next_pos` to a char boundary too — the
        // overlap is measured in bytes, so subtracting blindly can
        // again land mid-char.
        let raw_next = end.saturating_sub(SPLIT_OVERLAP_CHARS);
        let next_pos = floor_char_boundary(&content, raw_next);
        if next_pos <= pos {
            // Overlap window pulled us back to or before pos — force
            // forward progress at the hard boundary.
            pos = end;
        } else {
            pos = next_pos;
        }
    }
    out
}

/// Locate the next preferred break point at or after `target`,
/// preferring (a) a `"\n\n"` paragraph boundary, (b) a single
/// `'\n'`. Caps the search at `MAX_HARD_CHARS - SOFT` chars past
/// `target` so we don't drag the soft cap arbitrarily far.
///
/// Callers must pass a `target` that is already on a UTF-8 char
/// boundary; this function slices `&s[target..hard]` directly.
fn next_soft_boundary(s: &str, target: usize) -> Option<usize> {
    let raw_hard = (target + (MAX_HARD_CHARS - MAX_CHUNK_CHARS)).min(s.len());
    let hard = floor_char_boundary(s, raw_hard);
    if target >= hard {
        return None;
    }
    let slice = &s[target..hard];
    if let Some(rel) = slice.find("\n\n") {
        return Some(target + rel + 2);
    }
    if let Some(rel) = slice.find('\n') {
        return Some(target + rel + 1);
    }
    None
}

/// Project the parent chunk's spans onto a sub-chunk's byte range.
/// A span survives if it overlaps `[sub_start, sub_end)`; its byte
/// range is clipped to the overlap and rebased to sub-chunk
/// coordinates (`0..sub_end-sub_start`).
fn clip_spans(parent_spans: &[TurnSpan], sub_start: usize, sub_end: usize) -> Vec<TurnSpan> {
    let mut out: Vec<TurnSpan> = Vec::new();
    for s in parent_spans {
        let (a, b) = s.byte_range;
        let lo = a.max(sub_start);
        let hi = b.min(sub_end);
        if lo >= hi {
            continue;
        }
        out.push(TurnSpan {
            attribution: s.attribution,
            timestamp: s.timestamp.clone(),
            byte_range: (lo - sub_start, hi - sub_start),
        });
    }
    out
}

impl Default for ThreadedTurnsChunker {
    fn default() -> Self {
        Self::new()
    }
}

impl Chunker for ThreadedTurnsChunker {
    fn chunk(&self, text: &str) -> Vec<TextChunk> {
        self.chunk_attributed(text)
            .into_iter()
            .map(|c| TextChunk {
                content: c.content,
                index: c.index,
            })
            .collect()
    }
}

fn turn_header_regex() -> &'static Regex {
    static CELL: OnceLock<Regex> = OnceLock::new();
    // Matches `### [YYYY-MM-DD HH:MM] sender` or
    // `### [unknown-time] sender`. Captures: 1 = timestamp content
    // inside the brackets; 2 = sender slug.
    CELL.get_or_init(|| Regex::new(r"(?m)^###\s+\[([^\]]+)\]\s+(user|assistant)\s*$").unwrap())
}

/// One `### [ts] sender` turn block parsed out of rendered conversation
/// text. Public so downstream read paths (e.g. the wrapped meshapp
/// artifact builder) reuse the one header grammar instead of
/// duplicating the regex.
#[derive(Debug)]
pub struct ParsedTurn {
    pub attribution: Attribution,
    /// `YYYY-MM-DD HH:MM` (UTC, as rendered by the extractor), or
    /// `None` for `[unknown-time]` headers.
    pub timestamp: Option<String>,
    /// The full block, header line included, trailing whitespace trimmed.
    pub block: String,
    /// Byte offset of the block's header within the text that was
    /// parsed. `text[..turns[0].byte_start]` is therefore the text that
    /// precedes every header — for a chunk cut out of the middle of a
    /// long turn, that leading text belongs to the PREVIOUS turn, and a
    /// caller totalling a turn's real extent needs the offset to say so.
    pub byte_start: usize,
}

/// Split rendered conversation text into its turn blocks. Returns an
/// empty vec when the text carries no turn headers.
pub fn parse_turns(text: &str) -> Vec<ParsedTurn> {
    let re = turn_header_regex();
    let captures: Vec<(usize, String, String)> = re
        .captures_iter(text)
        .map(|c| {
            let start = c.get(0).unwrap().start();
            let ts_raw = c.get(1).unwrap().as_str().to_string();
            let sender = c.get(2).unwrap().as_str().to_string();
            (start, ts_raw, sender)
        })
        .collect();

    if captures.is_empty() {
        return Vec::new();
    }

    let mut turns: Vec<ParsedTurn> = Vec::with_capacity(captures.len());
    for (i, (start, ts_raw, sender)) in captures.iter().enumerate() {
        let block_end = captures
            .get(i + 1)
            .map(|(s, _, _)| *s)
            .unwrap_or(text.len());
        let block = text[*start..block_end].trim_end().to_string();
        let attribution = match sender.as_str() {
            "user" => Attribution::User,
            "assistant" => Attribution::Assistant,
            _ => continue,
        };
        let timestamp = if ts_raw == "unknown-time" {
            None
        } else {
            Some(ts_raw.clone())
        };
        turns.push(ParsedTurn {
            attribution,
            timestamp,
            block,
            byte_start: *start,
        });
    }
    turns
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "### [2025-09-04 18:01] user\n\nWhat was our burn rate?\n\n### [2025-09-04 18:02] assistant\n\nAbout $312k last month.\n\n### [2025-09-04 18:10] user\n\nAnd runway?\n\n### [2025-09-04 18:11] assistant\n\n~14 months.";

    #[test]
    fn splits_into_two_pairs() {
        let chunks = ThreadedTurnsChunker::new().chunk(SAMPLE);
        assert_eq!(chunks.len(), 2);
    }

    #[test]
    fn first_pair_contains_question_and_answer() {
        let chunks = ThreadedTurnsChunker::new().chunk(SAMPLE);
        let first = &chunks[0].content;
        assert!(first.contains("burn rate"));
        assert!(first.contains("$312k"));
        assert!(first.contains("### [2025-09-04 18:01] user"));
        assert!(first.contains("### [2025-09-04 18:02] assistant"));
    }

    #[test]
    fn preserves_turn_headers_in_chunk_content() {
        let chunks = ThreadedTurnsChunker::new().chunk(SAMPLE);
        for chunk in &chunks {
            assert!(
                chunk.content.contains("### ["),
                "header missing from chunk: {}",
                chunk.content
            );
        }
    }

    #[test]
    fn dangling_user_emitted_alone() {
        let input = "### [2025-09-04 18:01] user\n\nQuestion with no reply.";
        let chunks = ThreadedTurnsChunker::new().chunk(input);
        assert_eq!(chunks.len(), 1);
        assert!(chunks[0].content.contains("Question with no reply"));
    }

    #[test]
    fn assistant_without_preceding_user_emitted_alone() {
        let input = "### [2025-09-04 18:01] assistant\n\nUnsolicited opener.\n\n### [2025-09-04 18:02] user\n\nQ\n\n### [2025-09-04 18:03] assistant\n\nA";
        let chunks = ThreadedTurnsChunker::new().chunk(input);
        assert_eq!(chunks.len(), 2);
        assert!(chunks[0].content.contains("Unsolicited"));
        assert!(chunks[1].content.contains("Q"));
        assert!(chunks[1].content.contains("A"));
    }

    #[test]
    fn empty_input_yields_no_chunks() {
        let chunks = ThreadedTurnsChunker::new().chunk("");
        assert!(chunks.is_empty());
    }

    #[test]
    fn text_without_turn_headers_degrades_to_single_chunk() {
        let chunks = ThreadedTurnsChunker::new().chunk("Just some prose with no turn markers.");
        assert_eq!(chunks.len(), 1);
        assert_eq!(chunks[0].content, "Just some prose with no turn markers.");
    }

    #[test]
    fn indices_increment_sequentially() {
        let chunks = ThreadedTurnsChunker::new().chunk(SAMPLE);
        for (i, c) in chunks.iter().enumerate() {
            assert_eq!(c.index, i);
        }
    }

    // ─── Attribution-surface tests ─────────────────────────────────

    #[test]
    fn attributed_pair_has_two_spans_user_then_assistant() {
        let chunks = ThreadedTurnsChunker::new().chunk_attributed(SAMPLE);
        assert_eq!(chunks.len(), 2);
        assert_eq!(chunks[0].spans.len(), 2);
        assert_eq!(chunks[0].spans[0].attribution, Attribution::User);
        assert_eq!(chunks[0].spans[1].attribution, Attribution::Assistant);
    }

    #[test]
    fn span_byte_ranges_slice_back_to_correct_authorship() {
        let chunks = ThreadedTurnsChunker::new().chunk_attributed(SAMPLE);
        let first = &chunks[0];
        let user_span = &first.spans[0];
        let assistant_span = &first.spans[1];
        let user_text = &first.content[user_span.byte_range.0..user_span.byte_range.1];
        let asst_text = &first.content[assistant_span.byte_range.0..assistant_span.byte_range.1];
        assert!(user_text.contains("burn rate"));
        assert!(
            !user_text.contains("$312k"),
            "user span leaked assistant text: {}",
            user_text
        );
        assert!(asst_text.contains("$312k"));
        assert!(
            !asst_text.contains("burn rate"),
            "assistant span leaked user text: {}",
            asst_text
        );
    }

    #[test]
    fn span_timestamps_parsed() {
        let chunks = ThreadedTurnsChunker::new().chunk_attributed(SAMPLE);
        let first = &chunks[0];
        assert_eq!(
            first.spans[0].timestamp.as_deref(),
            Some("2025-09-04 18:01")
        );
        assert_eq!(
            first.spans[1].timestamp.as_deref(),
            Some("2025-09-04 18:02")
        );
    }

    #[test]
    fn unknown_time_yields_none_timestamp() {
        let input = "### [unknown-time] user\n\nQ\n\n### [unknown-time] assistant\n\nA";
        let chunks = ThreadedTurnsChunker::new().chunk_attributed(input);
        assert_eq!(chunks[0].spans[0].timestamp, None);
        assert_eq!(chunks[0].spans[1].timestamp, None);
    }

    #[test]
    fn dangling_user_span_marked_user() {
