        let chunks = ThreadedTurnsChunker::new().chunk(&input);
        assert!(
            chunks.len() > 1,
            "oversized paired turn must split into multiple chunks (got {})",
            chunks.len()
        );
        for c in &chunks {
            assert!(
                c.content.len() <= MAX_HARD_CHARS,
                "split chunk overshot hard cap ({} > {}): {:?}",
                c.content.len(),
                MAX_HARD_CHARS,
                &c.content[..c.content.len().min(120)],
            );
        }
    }

    #[test]
    fn small_paired_turn_is_not_split() {
        // SAMPLE is well under the cap — splitter must be a no-op.
        let chunks = ThreadedTurnsChunker::new().chunk(SAMPLE);
        assert_eq!(chunks.len(), 2, "small pairs should not split");
    }

    #[test]
    fn split_subchunks_preserve_attribution_spans() {
        let user_body = "User says: ".to_string() + &"foo bar baz ".repeat(200);
        let assistant_body = "Reply: ".to_string() + &"qux quux corge ".repeat(200);
        let input = format!(
            "### [2025-09-04 18:01] user\n\n{user_body}\n\n### [2025-09-04 18:02] assistant\n\n{assistant_body}"
        );
        let chunks = ThreadedTurnsChunker::new().chunk_attributed(&input);
        assert!(chunks.len() > 1);
        for chunk in &chunks {
            // Each sub-chunk must carry at least one span — span
            // clipping is the load-bearing detail that keeps
            // attribution coherent across the split.
            assert!(
                !chunk.spans.is_empty(),
                "sub-chunk lost all attribution spans: {:?}",
                &chunk.content[..chunk.content.len().min(120)]
            );
            // Every span's byte range must be in-bounds of the
            // sub-chunk's content.
            for s in &chunk.spans {
                let (a, b) = s.byte_range;
                assert!(a <= b, "span byte_range inverted: {a:?}..{b:?}");
                assert!(
                    b <= chunk.content.len(),
                    "span byte_range overshoots sub-chunk content (end {} > len {})",
                    b,
                    chunk.content.len(),
                );
            }
        }
    }

    #[test]
    fn split_indices_remain_sequential() {
        let big = "lorem ipsum dolor sit amet ".repeat(400);
        let input = format!(
            "### [2025-09-04 18:01] user\n\n{big}\n\n### [2025-09-04 18:02] assistant\n\nshort reply"
        );
        let chunks = ThreadedTurnsChunker::new().chunk(&input);
        for (i, c) in chunks.iter().enumerate() {
            assert_eq!(c.index, i);
        }
    }

    #[test]
    fn split_handles_oversize_without_newlines() {
        // A blob with no newlines (worst case for the soft boundary
        // pass) must still split cleanly via the hard char-boundary.
        let blob = "x".repeat(6000);
        let input = format!(
            "### [2025-09-04 18:01] user\n\n{blob}\n\n### [2025-09-04 18:02] assistant\n\ny"
        );
        let chunks = ThreadedTurnsChunker::new().chunk(&input);
        assert!(chunks.len() > 1);
        for c in &chunks {
            assert!(c.content.len() <= MAX_HARD_CHARS);
        }
    }

    /// Pinned regression: the first real anthropic-export ingest
    /// panicked with `byte index 2979 is not a char boundary; it is
    /// inside '—' (bytes 2977..2980)`. Root cause was
    /// `pos + MAX_CHUNK_CHARS` landing inside the em-dash on the
    /// second loop iteration, then a `&content[target..hard]` slice
    /// panicking via `slice_error_fail`. Every position the splitter
    /// derives from byte arithmetic must now snap to a UTF-8 char
    /// boundary first (`floor_char_boundary`); this test enforces
    /// that by stuffing the input with em-dashes so the soft target
    /// + overlap rewind both stand a good chance of landing
    /// mid-glyph.
    #[test]
    fn split_handles_multibyte_glyph_on_soft_target() {
        // Body crafted so the byte position ~MAX_CHUNK_CHARS into
        // each turn lands inside a multi-byte char.
        let multibyte_run = "Let's dig in — there's an em-dash every line.\n".repeat(80);
        let extra = "—".repeat(400); // pure 3-byte chars
        let input = format!(
            "### [2026-03-28 20:20] user\n\n{multibyte_run}{extra}\n\n### [2026-03-28 20:21] assistant\n\nReply with more — and more —.\n"
        );
        // Pre-fix this panicked with `slice_error_fail` inside the
        // chunker; post-fix it must complete + every chunk must
        // round-trip as valid UTF-8.
        let chunks = ThreadedTurnsChunker::new().chunk(&input);
        assert!(
            chunks.len() > 1,
            "input must split: got {} chunks",
            chunks.len()
        );
        for c in &chunks {
            assert!(c.content.is_char_boundary(0));
            assert!(c.content.is_char_boundary(c.content.len()));
            assert!(
                c.content.len() <= MAX_HARD_CHARS,
                "chunk overshot hard cap: {} > {}",
                c.content.len(),
                MAX_HARD_CHARS
            );
            // is_char_boundary returns true on every valid UTF-8
            // index — confirm by re-parsing the &str.
            let _ = c.content.as_str();
        }
    }

    /// Stronger fuzz: a wall of em-dashes with no newlines forces
    /// the soft-boundary search to fail every time, exercising the
    /// hard-boundary fallback in a path full of multi-byte chars.
    #[test]
    fn split_handles_pure_multibyte_blob() {
        let blob = "—".repeat(3000); // 9000 bytes of 3-byte glyphs
        let input = format!(
            "### [2025-09-04 18:01] user\n\n{blob}\n\n### [2025-09-04 18:02] assistant\n\nack"
        );
        let chunks = ThreadedTurnsChunker::new().chunk(&input);
        assert!(chunks.len() > 1);
        for c in &chunks {
            assert!(c.content.len() <= MAX_HARD_CHARS);
            // All chars survived round-trip.
            for ch in c.content.chars() {
                let _ = ch;
            }
        }
    }
}

