                canonical_name: "Zossima".into(),
                aliases: vec![],
                entity_type: EntityType::Person,
                first_appearance: ChunkRef::new("sec_0001", None),
                description: "Monastery elder.".into(),
                defining_quote: None,
                salience: 1.0,
