            out.entities
                .iter()
                .map(|e| &e.canonical_name)
                .collect::<Vec<_>>()
        );
        let survivor = &out.entities[0];
        // The three loser spellings must surface as aliases so an
        // operator (or downstream Phase 5) can audit which forms got
        // folded together.
        for variant in [
