            }],
            evidence_invocations: vec![],
            oppositions: vec![OppositionSketch {
                left: "markets".into(),
                right: "regulation".into(),
                axis: "governance".into(),
                framing: "".into(),
                anchor: "markets vs regulation".into(),
            }],
