    }

    #[test]
    fn resolve_typed_extension_section_wraps_and_projects() {
        let resolved = resolve_typed_extension_section(
            argumentative_with_mechanism_and_opposition(),
            "chunk:42".into(),
            EnrichmentDepth::Extracted,
