        apply_citations_to_resolved(&mut resolved, &citations);

        assert_eq!(
            resolved.new_entities[0]
                .first_appearance
                .passage_preview
                .as_deref(),
            Some("Verbatim source sentence about spread pricing.")
        );
        assert_eq!(
            resolved.new_positions[0]
                .first_appearance
                .passage_preview
                .as_deref(),
