        roles.insert("investor".into(), "investment.from".into());
        roles.insert("customer".into(), "revenue.to".into());

        let findings = detect_role_overlap("invest_in_customer", &roles, &relationships);
        assert_eq!(findings.len(), 1, "got: {findings:?}");
