//! `IndexMeta.enrichment_requested` — the flag that makes the enrichment
//! health check reachable.
//!
//! **The thing being fixed.** Until 2026-08-07 this field was called
//! `enrichment_enabled`, was written in exactly one place
//! (`index/create.rs`, always `false`), and had no setter. Every corpus on
//! every machine therefore reported `false`, which made
//! `EnrichmentChecker`'s opening `if !info.enrichment_enabled { continue; }`
//! fire for every corpus, always — so `LowEnrichmentCoverage` and
//! `StaleEnrichment` were unreachable for all inputs. Full trace:
//! `docs/TRACE_ENRICHMENT_ENABLED_FLAG.md` §4.
//!
//! **What these tests pin.** The stamp happens at the ENTRY of ingest's
//! `'enrichment:` block, not at its exit. That distinction is the entire
//! design: a corpus whose enrichment *failed* must still report
//! `enrichment_requested == true`, because "was supposed to be enriched" is
//! the question the standing health surface needs answered. A success-only
//! stamp would leave exactly the failure case invisible, which is the defect.
//!
//! The two `break 'enrichment` early-outs (`investigation`, `atlas`) are the
//! other direction: those recipes are deliberately not field-model-enriched
//! at install time, so they must un-stamp rather than leave a standing
//! "unfinished enrichment" complaint against every such corpus.
//!
//! Delete `index.set_enrichment_requested(true)` from `engine/ingest.rs` and
//! `ingest_stamps_enrichment_requested_when_enrichment_produces_nothing`
//! fails.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use corpus_engine::{CorpusEngine, CorpusSpec, EmbedFn, Error};

// ─── Fixtures ────────────────────────────────────────────────

fn write_source(dir: &Path) -> PathBuf {
    let path = dir.join("source.txt");
    // Several paragraphs so the paragraph chunker produces >1 chunk and the
    // ingest reaches `build_indexes` (a zero-chunk ingest fails earlier and
    // never enters the enrichment block at all).
    let text = "The ledger opened on a Tuesday, which is the sort of detail \
                nobody records unless it matters later.\n\n\
                By Thursday the second column had been ruled twice, once in \
                pencil and once in something darker.\n\n\
                The auditor's note in the margin read: reconcile before the \
                quarter closes, and no later.\n\n\
                Nobody reconciled anything. The quarter closed on its own, \
                the way quarters do.\n";
    std::fs::write(&path, text).unwrap();
    path
}

/// A recipe with an optional `[enrichment]` block appended verbatim, so each
/// test states exactly the enrichment shape it is exercising.
fn write_recipe(recipes_dir: &Path, source: &Path, enrichment_block: &str) -> PathBuf {
    let recipe_path = recipes_dir.join("test_corpus.toml");
    let source_str = source.to_string_lossy();
    let toml = format!(
        r#"
[corpus]
id = "test_corpus"
name = "Test Corpus"
description = "enrichment_requested flag fixture"
license = "CC0"
mesh_sharing = false

[acquire]
type = "local_file"
path = "{source_str}"

[extract]
type = "plaintext"

[chunk]
type = "paragraph"
max_chars = 512
overlap_chars = 64

[index]
embedding_model = "test-mock"
embedding_dimensions = 8
{enrichment_block}
"#
    );
    std::fs::write(&recipe_path, toml).unwrap();
    recipe_path
}

fn working_embed_fn() -> EmbedFn {
    Arc::new(|_t: &str| Box::pin(async { Ok(vec![0.1_f32; 8]) }))
}

/// Inference that always errors — the stand-in for the real-world enrichment
/// failures this flag exists to keep visible (an unregistered domain, a dead
/// model slot, a mid-phase kill). The block is entered; nothing completes.
fn always_failing_inference_fn() -> corpus_engine::types::InferenceFn {
    Arc::new(|_prompt: &str, _schema: Option<&serde_json::Value>| {
        // `corpus_engine::Error` has no dedicated inference variant, so this
        // borrows the nearest one; only the message text is load-bearing.
        Box::pin(async {
            Err(Error::InvalidInput(
                "simulated enrichment-time inference outage".to_string(),
            ))
        })
    })
}

/// Read `enrichment_requested` straight off whichever `_corpus_meta.json` the
/// run left behind — canonical `<corpus>/` on success, or the partition
/// `<corpus>-partition-<node>/` when the ingest died before promotion. Reading
/// the raw JSON (rather than only the typed projection) is what makes the
/// on-disk contract, not just the in-memory struct, the thing under test.
fn meta_flag_on_disk(indexes_dir: &Path) -> (PathBuf, serde_json::Value) {
    let mut found = Vec::new();
    for entry in std::fs::read_dir(indexes_dir)
        .unwrap_or_else(|e| panic!("indexes dir {} unreadable: {e}", indexes_dir.display()))
        .flatten()
    {
        let meta = entry.path().join("_corpus_meta.json");
        if meta.exists() {
            found.push(meta);
        }
    }
    assert_eq!(
        found.len(),
        1,
        "expected exactly one index dir with a meta under {}, found {found:?}",
        indexes_dir.display()
    );
    let raw = std::fs::read_to_string(&found[0]).unwrap();
    let json: serde_json::Value = serde_json::from_str(&raw).unwrap();
    (found[0].clone(), json)
}

// ─── Tests ───────────────────────────────────────────────────

/// **The watched-to-fail case.** A recipe asks for field-model enrichment and
/// every inference call during enrichment fails. The corpus must record that
/// enrichment was requested, because that is the only thing that lets a
/// standing health check say "this corpus was supposed to be enriched and
/// isn't".
///
/// Note what the run does, because it is the reason the standing check
/// matters: the enrichment phases absorb a total inference outage and the
/// ingest returns `Ok` ("Ingestion complete — 1 chunks"). Nothing downstream
/// of the ingest call learns that enrichment produced nothing. The
/// `enrichment_requested` stamp is the only surviving trace that it was ever
/// supposed to happen.
///
/// Remove `index.set_enrichment_requested(true)` from the entry of the
/// `'enrichment:` block in `engine/ingest.rs` and this test fails on the
/// `enrichment_requested` assertions — the corpus goes back to reporting
/// `false`, which is the state that made `EnrichmentChecker` dead code.
#[tokio::test]
async fn ingest_stamps_enrichment_requested_when_enrichment_produces_nothing() {
    let dir = tempfile::tempdir().unwrap();
    let recipes_dir = dir.path().join("recipes");
    let indexes_dir = dir.path().join("indexes");
    std::fs::create_dir_all(&recipes_dir).unwrap();
    let source = write_source(dir.path());

    let recipe_path = write_recipe(
        &recipes_dir,
        &source,
        r#"
[enrichment]
enabled = true
type = "field_model"
domain = "philosophy"
"#,
    );

    let engine = CorpusEngine::new(recipes_dir, indexes_dir.clone(), working_embed_fn())
        .with_embedding_model("test-mock")
        .with_inference_fn(always_failing_inference_fn());

    engine
        .ingest(&CorpusSpec::RecipePath(recipe_path), None)
        .await
        .expect("ingest returns Ok — the enrichment phases swallow the outage");

    // Validate the instrument before the verdict (§18.4): the enrichment
    // block really was entered and really produced nothing. If a future
    // change made enrichment succeed here, the flag assertion below would
    // still pass while testing something else entirely.
    let index = engine
        .open_index_for_corpus("test_corpus")
        .await
        .expect("a completed ingest must be openable by corpus id");
    assert!(
        !index.has_field_model_tables().await,
        "the fixture must end UN-enriched — otherwise this is not the \
         requested-but-not-done state under test"
    );

    let (meta_path, meta) = meta_flag_on_disk(&indexes_dir);
    assert_eq!(
        meta.get("enrichment_requested").and_then(|v| v.as_bool()),
        Some(true),
        "the entry stamp must survive the failure — {} says {meta:#}",
        meta_path.display()
    );

    // And the typed projection agrees, which is the surface
    // `EnrichmentChecker` actually reads.
    let installed = engine.installed_indexes().await.unwrap();
    let info = installed
        .iter()
        .find(|i| i.corpus_id == "test_corpus")
        .expect("the corpus must be listed as installed");
    assert!(
        info.enrichment_requested,
        "IndexInfo::enrichment_requested must project the stamped meta"
    );
}

/// The control. No `[enrichment]` block means the block is never entered and
/// nothing is stamped — so a plain corpus never shows up in the enrichment
/// health check. Without this, a stamp accidentally moved outside the
/// enrichment block would make the checker complain about every corpus on the
/// machine, which is the opposite failure and just as useless.
#[tokio::test]
async fn a_recipe_without_enrichment_never_claims_it_was_requested() {
    let dir = tempfile::tempdir().unwrap();
    let recipes_dir = dir.path().join("recipes");
    let indexes_dir = dir.path().join("indexes");
    std::fs::create_dir_all(&recipes_dir).unwrap();
    let source = write_source(dir.path());
    let recipe_path = write_recipe(&recipes_dir, &source, "");

    let engine = CorpusEngine::new(recipes_dir, indexes_dir.clone(), working_embed_fn())
        .with_embedding_model("test-mock");

    engine
        .ingest(&CorpusSpec::RecipePath(recipe_path), None)
        .await
        .expect("a plain ingest must succeed");

    let (_, meta) = meta_flag_on_disk(&indexes_dir);
    assert_eq!(
        meta.get("enrichment_requested").and_then(|v| v.as_bool()),
        Some(false),
        "no [enrichment] block means nothing was requested"
    );
}

/// The `break 'enrichment` early-out direction. An `investigation` recipe is
/// enriched by an explicit later command (`sovereign enrich investigation
/// build <id>`), never at install — so install must not claim the request.
/// Stamping `true` here would make the health check report a standing,
/// permanent "unfinished enrichment" against every investigation corpus,
/// which is a false positive, not a finding.
#[tokio::test]
async fn an_investigation_recipe_takes_the_enrichment_request_back() {
    let dir = tempfile::tempdir().unwrap();
    let recipes_dir = dir.path().join("recipes");
    let indexes_dir = dir.path().join("indexes");
    std::fs::create_dir_all(&recipes_dir).unwrap();
    let source = write_source(dir.path());

    let recipe_path = write_recipe(
        &recipes_dir,
        &source,
        r#"
[enrichment]
enabled = true
type = "investigation"
"#,
    );

    let engine = CorpusEngine::new(recipes_dir, indexes_dir.clone(), working_embed_fn())
        .with_embedding_model("test-mock")
        // Inference is present so the block is ENTERED (the `None` arm skips
        // it entirely); it must never be called on this path.
        .with_inference_fn(always_failing_inference_fn());

    engine
        .ingest(&CorpusSpec::RecipePath(recipe_path), None)
        .await
        .expect("an investigation recipe must install cleanly — it skips install-time enrichment");

    let (_, meta) = meta_flag_on_disk(&indexes_dir);
    assert_eq!(
        meta.get("enrichment_requested").and_then(|v| v.as_bool()),
        Some(false),
        "the investigation early-out must un-stamp the entry request"
    );
}

/// **Back-compat.** Every `_corpus_meta.json` already on disk spells this key
/// `enrichment_enabled`. The `#[serde(alias = "enrichment_enabled")]` on
/// `IndexMeta` is what keeps those parsing, and this test proves it against a
/// real meta rather than a hand-written stub: ingest normally, rewrite the one
/// key back to its pre-rename spelling, and re-read through the same
/// `installed_indexes()` path production uses.
///
/// It also pins the harder half — an old meta that said `true` must still read
/// as `true`, not be silently defaulted to `false` by an unmatched key (§18.3:
/// absence is reported, never defaulted; here the key is present and must be
/// honoured).
#[tokio::test]
async fn a_pre_rename_meta_still_deserializes() {
    let dir = tempfile::tempdir().unwrap();
    let recipes_dir = dir.path().join("recipes");
    let indexes_dir = dir.path().join("indexes");
    std::fs::create_dir_all(&recipes_dir).unwrap();
    let source = write_source(dir.path());
    let recipe_path = write_recipe(&recipes_dir, &source, "");

    let engine = CorpusEngine::new(recipes_dir, indexes_dir.clone(), working_embed_fn())
        .with_embedding_model("test-mock");
    engine
        .ingest(&CorpusSpec::RecipePath(recipe_path), None)
        .await
        .expect("plain ingest must succeed");

    // Rewrite the real meta into its pre-rename shape: the key spelled the old
    // way, and set to `true` so a silent default-to-false is detectable.
    let (meta_path, mut meta) = meta_flag_on_disk(&indexes_dir);
    let obj = meta.as_object_mut().unwrap();
    obj.remove("enrichment_requested")
        .expect("the fresh meta must carry the NEW key — otherwise this test proves nothing");
    obj.insert("enrichment_enabled".into(), serde_json::Value::Bool(true));
    std::fs::write(&meta_path, serde_json::to_string_pretty(&meta).unwrap()).unwrap();

    let installed = engine.installed_indexes().await.unwrap();
    let info = installed
        .iter()
        .find(|i| i.corpus_id == "test_corpus")
        .expect("a pre-rename meta must still list as an installed corpus");
    assert!(
        info.enrichment_requested,
        "the serde alias must carry an old `enrichment_enabled: true` through \
         to `enrichment_requested`; a legacy meta that silently reads `false` \
         would re-blind the enrichment health check for every corpus \
         installed before the rename"
    );
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! End-to-end empirical validation of the prebuilt-snapshot restore
//! path against a real archive on disk.
//!
//! Marked `#[ignore]` so it only runs on demand — the test reads a
//! multi-GB local file. Invoke explicitly:
//!
//! ```bash
//! SNAPSHOT_PATH=~/.svrnmesh/snapshots/wikipedia-qwen-embedding-0.6b-2026-05-13.tar.zst \
//!   cargo test --release --package corpus-engine --test snapshot_restore_e2e \
//!     -- --ignored --nocapture restore_real_wikipedia_snapshot_as_sibling
//! ```
//!
//! What it proves:
//!   1. The on-disk .tar.zst archive parses end-to-end.
//!   2. The sha256 in the recipe's `[prebuilt]` block matches the
//!      bytes on disk.
//!   3. The restorer rewrites tar paths and patches
//!      `_corpus_meta.json::corpus_id` so the archive can be installed
//!      under a non-default corpus id without clobbering the original.
//!   4. The result has the expected on-disk layout (LanceDB chunks
//!      table, atlas subtree, meta file).

use corpus_engine::snapshot::restore_snapshot_archive;
use std::path::PathBuf;

const WIKIPEDIA_PREBUILT_SHA256: &str =
    "65fa045c95d6ffdaa92b7634ea95acb2d9d4bac6c9f6cd20bc831c098c10c6bd";
const TARGET_CORPUS_ID: &str = "wikipedia-prebuilt-test";

fn snapshot_path() -> Option<PathBuf> {
    std::env::var_os("SNAPSHOT_PATH").map(PathBuf::from)
}

#[test]
#[ignore]
fn restore_real_wikipedia_snapshot_as_sibling() {
    let Some(archive) = snapshot_path() else {
        panic!(
            "set SNAPSHOT_PATH to the local .tar.zst (e.g. \
             ~/.svrnmesh/snapshots/wikipedia-qwen-embedding-0.6b-2026-05-13.tar.zst)"
        );
    };
    assert!(archive.is_file(), "{} does not exist", archive.display());

    let restore_root = tempfile::tempdir().expect("create tmp dir for restore root");
    let restore_root = restore_root.path().to_path_buf();
    eprintln!("Restore root: {}", restore_root.display());

    let outcome = restore_snapshot_archive(
        &archive,
        &restore_root,
        TARGET_CORPUS_ID,
        Some(WIKIPEDIA_PREBUILT_SHA256),
        "qwen-embedding-0.6b",
        1024,
    )
    .expect("restore_snapshot_archive succeeded");

    // ── Manifest integrity ────────────────────────────────────
    assert_eq!(
        outcome.manifest.corpus_id, "wikipedia",
        "manifest preserves the archive's original id"
    );
    assert_eq!(outcome.manifest.embedding_model, "qwen-embedding-0.6b");
    assert_eq!(outcome.manifest.embedding_dimensions, 1024);
    assert_eq!(outcome.manifest.chunk_count, 1_847_442);

    // ── Path rewriting landed under target id ─────────────────
    let expected_index = restore_root.join("indexes").join(TARGET_CORPUS_ID);
    assert_eq!(outcome.index_dir, expected_index);
    assert!(outcome.index_dir.is_dir(), "index dir missing");
    assert!(
        !restore_root.join("indexes/wikipedia").exists(),
        "rename failed: archive corpus-id path was created instead of target's"
    );

    // ── Expected on-disk layout ───────────────────────────────
    assert!(outcome.index_dir.join("_corpus_meta.json").is_file());
    assert!(
        outcome.index_dir.join("chunks.lance").is_dir(),
        "LanceDB chunks table missing"
    );
    assert!(
        outcome.index_dir.join("atlas").is_dir(),
        "atlas subtree missing — published with atlas embedded under indexes/<id>/atlas/"
    );

    // ── _corpus_meta.json patched to target id ────────────────
    let meta: serde_json::Value = serde_json::from_slice(
        &std::fs::read(outcome.index_dir.join("_corpus_meta.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        meta.get("corpus_id").and_then(|v| v.as_str()),
        Some(TARGET_CORPUS_ID),
        "patch_meta_corpus_id did not run / produced wrong value"
    );
    assert_eq!(
        meta.get("embedding_model").and_then(|v| v.as_str()),
        Some("qwen-embedding-0.6b"),
        "embedding_model should be preserved across rename"
    );

    // ── No separate enrichment subtree expected for this snapshot ──
    // The wikipedia archive bundled the atlas under indexes/<id>/atlas/
    // rather than enrichment/<id>/, so atlas_included=false in the
    // manifest and enrichment_dir comes back None.
    assert!(
        outcome.enrichment_dir.is_none(),
        "this snapshot has atlas embedded in the index, not a separate enrichment subtree"
    );
    assert!(
        !restore_root
            .join("enrichment")
            .join(TARGET_CORPUS_ID)
            .exists(),
        "no enrichment subtree should be created for this archive"
    );

    // ── Bytes match HF reported size ──────────────────────────
    assert_eq!(
        outcome.archive_size_bytes, 8_386_497_983,
        "archive_size_bytes should match the bytes we sha-verified"
    );

    eprintln!(
        "\n✓ End-to-end restore validated.\n  index: {}\n  meta.corpus_id: {}\n  chunks_lance/: present\n  atlas/: present",
        outcome.index_dir.display(),
        TARGET_CORPUS_ID,
    );
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `cargo xtask env-gate` — the env-knob plane obeys `quality/env-flags.toml`.
//!
//! The registry is DECLARATION, not plumbing: `std::env::var` read sites stay
//! exactly where they are. This gate censuses them — Rust literals
//! (`env::var`/`var_os`/`set_var`/`remove_var`), the `svrnmesh_env` suffix
//! wrapper, and `${SOVEREIGN_*}` expansions/assignments in `scripts/` +
//! `.claude/hooks/` — and diffs the observed names against the declared map.
//! A NEW name that is neither registered, third-party-allowlisted, nor in the
//! legacy baseline fails the gate with the exact fix; the pre-existing debt
//! rides the shrink-only baseline (`quality/baselines/env_unregistered.txt`,
//! `--update-baseline` / `--tighten` — the uniform ratchet contract in
//! `common.rs`).
//!
//! `docs/ENV_FLAGS.md` is rendered from the registry and freshness-checked
//! here (regenerate: `--update-doc`) — same generated-doc contract as
//! `sovereign/docs/retrieval-pipeline.md`, with xtask as the renderer because
//! the source of truth is repo data, not crate code.
//!
//! `SVRNMESH_*` observations canonicalize to `SOVEREIGN_*`: the rebrand
//! mirror (`sovereign-contracts/src/rebrand.rs::promote_legacy_env`) makes
//! them one name. This census is also the rebrand bridge's deletion
//! predicate: the bridge can be dropped once zero sites read the legacy
//! prefix only.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use crate::common;

const REGISTRY_PATH: &str = "quality/env-flags.toml";
const BASELINE_FILE: &str = "env_unregistered.txt";
const DOC_PATH: &str = "docs/ENV_FLAGS.md";
const VALID_STATUSES: [&str; 4] = ["guard", "shipped", "experiment", "deprecated"];

pub fn run(args: &[String]) -> i32 {
    let flags = common::baseline_flags(args);
    let update_doc = args.iter().any(|a| a == "--update-doc");
    let root = common::repo_root();

    let registry = match load_registry(&root.join(REGISTRY_PATH)) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("env-gate: {REGISTRY_PATH}: {e}");
            return 1;
        }
    };

    let observed = census(&root);
    let baseline_path = common::baselines_dir(&root).join(BASELINE_FILE);
    let baseline = common::load_line_set(&baseline_path);

    let registered: BTreeSet<&str> = registry.flags.iter().map(|f| f.name.as_str()).collect();
    let unregistered: BTreeMap<&String, &Vec<String>> = observed
        .iter()
        .filter(|(name, _)| {
            !registered.contains(name.as_str()) && !registry.allowlist.contains(*name)
        })
        .collect();

    // ── Ratchet maintenance ─────────────────────────────────────────
    if flags.update {
        let set: BTreeSet<String> = unregistered.keys().map(|s| (*s).clone()).collect();
        if let Err(e) = common::write_line_set(
            &baseline_path,
            "env-gate",
            "observed env-var names not yet declared in quality/env-flags.toml",
            &set,
        ) {
            eprintln!("env-gate: {e}");
            return 1;
        }
        eprintln!(
            "env-gate: baseline updated — {} unregistered name(s) accepted as legacy debt",
            set.len()
        );
        return 0;
    }
    if flags.tighten {
        let kept: BTreeSet<String> = baseline
            .iter()
            .filter(|n| unregistered.contains_key(n))
            .cloned()
            .collect();
        let dropped = baseline.len() - kept.len();
        if let Err(e) = common::write_line_set(
            &baseline_path,
            "env-gate",
            "observed env-var names not yet declared in quality/env-flags.toml",
            &kept,
        ) {
            eprintln!("env-gate: {e}");
            return 1;
        }
        eprintln!(
            "env-gate: tightened — {dropped} name(s) left the baseline (registered or no longer read), {} remain",
            kept.len()
        );
        return 0;
    }

    // ── Generated doc ───────────────────────────────────────────────
    let doc_path = root.join(DOC_PATH);
    let rendered = render_doc(&registry);
    if update_doc {
        if let Err(e) = std::fs::write(&doc_path, &rendered) {
            eprintln!("env-gate: write {DOC_PATH}: {e}");
            return 1;
        }
        eprintln!("env-gate: wrote {DOC_PATH}");
        // fall through: still run the census checks below
    }

    // ── Checks ──────────────────────────────────────────────────────
    let mut failures = 0usize;

    let new_names: Vec<(&&String, &&Vec<String>)> = unregistered
        .iter()
        .filter(|(name, _)| !baseline.contains(**name))
        .collect();
    for (name, sites) in &new_names {
        failures += 1;
        eprintln!("env-gate: NEW unregistered env var `{name}`:");
        for site in sites.iter().take(3) {
            eprintln!("    {site}");
        }
        if sites.len() > 3 {
            eprintln!("    … and {} more site(s)", sites.len() - 3);
        }
    }
    if !new_names.is_empty() {
        eprintln!(
            "  Declare each in {REGISTRY_PATH} (a [[flag]] entry with cluster/default/purpose/status,\n  \
             or `third_party_allowlist` for vars owned by other software). To accept as legacy debt instead:\n  \
             cargo run -p xtask -- env-gate --update-baseline"
        );
    }

    let committed = std::fs::read_to_string(&doc_path).unwrap_or_default();
    if committed != rendered {
        failures += 1;
        eprintln!(
            "env-gate: {DOC_PATH} is stale — the registry changed. Regenerate:\n  \
             cargo run -p xtask -- env-gate --update-doc"
        );
    }

    // ── Summary ─────────────────────────────────────────────────────
    let now_registered = baseline
        .iter()
        .filter(|n| !unregistered.contains_key(n))
        .count();
    eprintln!(
        "env-gate: {} observed name(s) · {} registered · {} allowlisted · {} riding the baseline",
        observed.len(),
        registry.flags.len(),
        registry.allowlist.len(),
        baseline.len().saturating_sub(now_registered),
    );
    if now_registered > 0 {
        eprintln!(
            "env-gate: {now_registered} baseline name(s) are now registered or gone — bank the improvement:\n  \
             cargo run -p xtask -- env-gate --tighten"
        );
    }

    if failures == 0 {
        eprintln!("env-gate: OK");
        0
    } else {
        1
    }
}

// ─── Registry ───────────────────────────────────────────────────────

struct Registry {
    flags: Vec<FlagRow>,
    allowlist: BTreeSet<String>,
}

struct FlagRow {
    name: String,
    cluster: String,
    default: String,
    purpose: String,
    status: String,
    alias_of: Option<String>,
    shadows: Option<String>,
}

fn load_registry(path: &Path) -> Result<Registry, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read: {e}"))?;
    let value: toml::Value = text.parse().map_err(|e| format!("parse: {e}"))?;

    let allowlist: BTreeSet<String> = value
        .get("third_party_allowlist")
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default();

    let mut flags = Vec::new();
    let mut seen = BTreeSet::new();
    let empty = Vec::new();
    let entries = value
        .get("flag")
        .and_then(|v| v.as_array())
        .unwrap_or(&empty);
    for (i, entry) in entries.iter().enumerate() {
        let req = |key: &str| -> Result<String, String> {
            entry
                .get(key)
                .and_then(|v| v.as_str())
                .map(String::from)
                .ok_or_else(|| format!("[[flag]] #{}: missing `{key}`", i + 1))
        };
        let row = FlagRow {
            name: req("name")?,
            cluster: req("cluster")?,
            default: req("default")?,
            purpose: req("purpose")?,
            status: req("status")?,
            alias_of: entry
                .get("alias_of")
                .and_then(|v| v.as_str())
                .map(String::from),
            shadows: entry
                .get("shadows")
                .and_then(|v| v.as_str())
                .map(String::from),
        };
        if !VALID_STATUSES.contains(&row.status.as_str()) {
            return Err(format!(
                "flag `{}`: status `{}` is not one of {VALID_STATUSES:?}",
                row.name, row.status
            ));
        }
        if !seen.insert(row.name.clone()) {
            return Err(format!("flag `{}` declared twice", row.name));
        }
        flags.push(row);
    }
    // Alias targets must themselves be declared.
    for f in &flags {
        if let Some(target) = &f.alias_of {
            if !seen.contains(target) {
                return Err(format!(
                    "flag `{}`: alias_of `{target}` is not itself declared",
                    f.name
                ));
            }
        }
    }
    Ok(Registry { flags, allowlist })
}

// ─── Census ─────────────────────────────────────────────────────────

/// Observed canonical name -> `file:line` sites. `SVRNMESH_*` canonicalizes
/// to `SOVEREIGN_*` (one name, mirrored by the rebrand bridge).
// Static regex literals + guaranteed capture groups: a panic here is a
// programmer error in this file, not a runtime condition to handle.
#[allow(clippy::expect_used)]
fn census(root: &Path) -> BTreeMap<String, Vec<String>> {
    let rust_read =
        regex::Regex::new(r#"env::var(?:_os)?\s*\(\s*"((?:SOVEREIGN|SVRNMESH)_[A-Z0-9_]+)""#)
            .expect("rust_read regex");
    let rust_write =
        regex::Regex::new(r#"(?:set_var|remove_var)\s*\(\s*"((?:SOVEREIGN|SVRNMESH)_[A-Z0-9_]+)""#)
            .expect("rust_write regex");
    let rust_wrapper =
        regex::Regex::new(r#"svrnmesh_env\s*\(\s*"([A-Z0-9_]+)""#).expect("wrapper regex");
    let shell_read =
        regex::Regex::new(r"\$\{?((?:SOVEREIGN|SVRNMESH)_[A-Z0-9_]+)").expect("shell_read regex");
    let shell_write =
        regex::Regex::new(r"(?m)^\s*(?:export\s+)?((?:SOVEREIGN|SVRNMESH)_[A-Z0-9_]+)=")
            .expect("shell_write regex");

    let mut observed: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut record = |name: &str, file: &Path, offset: usize, content: &str| {
        let canonical = format!(
            "SOVEREIGN_{}",
            name.trim_start_matches("SOVEREIGN_")
                .trim_start_matches("SVRNMESH_")
        );
        let line = content[..offset].matches('\n').count() + 1;
        let rel = file.strip_prefix(root).unwrap_or(file);
        observed
            .entry(canonical)
            .or_default()
            .push(format!("{}:{line}", rel.display()));
    };

    for file in rust_files(root) {
        let Ok(content) = std::fs::read_to_string(&file) else {
            continue;
        };
        for re in [&rust_read, &rust_write] {
            for cap in re.captures_iter(&content) {
                let m = cap.get(1).expect("group 1");
                record(m.as_str(), &file, m.start(), &content);
            }
        }
        for cap in rust_wrapper.captures_iter(&content) {
            let m = cap.get(1).expect("group 1");
            let name = format!("SOVEREIGN_{}", m.as_str());
            record(&name, &file, m.start(), &content);
        }
    }

    for file in shell_files(root) {
        let Ok(content) = std::fs::read_to_string(&file) else {
            continue;
        };
        for re in [&shell_read, &shell_write] {
            for cap in re.captures_iter(&content) {
                let m = cap.get(1).expect("group 1");
                record(m.as_str(), &file, m.start(), &content);
            }
        }
    }

    observed
}

fn rust_files(root: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    walk(root, &mut |p| {
        if p.extension().is_some_and(|e| e == "rs") {
            out.push(p.to_path_buf());
        }
    });
    out
}

fn shell_files(root: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    for dir in [root.join("scripts"), root.join(".claude/hooks")] {
        walk(&dir, &mut |p| {
            if p.extension().is_some_and(|e| e == "sh") {
                out.push(p.to_path_buf());
            }
        });
    }
    out
}

fn walk(dir: &Path, root: &Path, scope: &common::SourceTree, f: &mut impl FnMut(&Path)) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if path.is_dir() {
            if scope.excludes_dir(&common::rel_path(&path, root)) {
                continue;
            }
            walk(&path, f);
        } else {
            f(&path);
        }
    }
}

// ─── Generated doc ──────────────────────────────────────────────────

fn render_doc(registry: &Registry) -> String {
    let mut md = String::from(
        "<!-- GENERATED FILE — do not edit by hand.\n\
         \x20    Source: quality/env-flags.toml (the declared env-knob registry)\n\
         \x20    Regenerate: cargo run -p xtask -- env-gate --update-doc -->\n\
         \n\
         # Environment-variable knobs — the declared registry\n\
         \n\
         One row per declared knob, grouped by subsystem cluster. Names use the\n\
         canonical `SOVEREIGN_` prefix; every one is mirrored to `SVRNMESH_*` by\n\
         the rebrand bridge (`sovereign-contracts/src/rebrand.rs`), so both\n\
         spellings work. `status` legend: **guard** = safety/kill-switch, keep;\n\
         **shipped** = default-on product behavior; **experiment** = A/B lever,\n\
         default-off unless noted; **deprecated** = scheduled for removal.\n\
         \n\
         The registry is enforced by `cargo run -p xtask -- env-gate`: a NEW env\n\
         var read anywhere in the workspace must be declared here (or in the\n\
         gate's third-party allowlist); pre-registry debt rides the shrink-only\n\
         baseline `quality/baselines/env_unregistered.txt`. The historical\n\
         dead-codepath survey lives in `docs/ENV_VAR_AUDIT.md`.\n",
    );

    let mut by_cluster: BTreeMap<&str, Vec<&FlagRow>> = BTreeMap::new();
    for f in &registry.flags {
        by_cluster.entry(f.cluster.as_str()).or_default().push(f);
    }
    for (cluster, mut rows) in by_cluster {
        rows.sort_by_key(|f| f.name.as_str());
        md.push_str(&format!(
            "\n## {cluster}\n\n| flag | default | status | purpose |\n|---|---|---|---|\n"
        ));
        for f in rows {
            let mut purpose = f.purpose.clone();
            if let Some(t) = &f.alias_of {
                purpose.push_str(&format!(" *(alias of `{t}`)*"));
            }
            if let Some(s) = &f.shadows {
                purpose.push_str(&format!(" *(shadows `SetupConfig.{s}`)*"));
            }
            md.push_str(&format!(
                "| `{}` | {} | {} | {} |\n",
                f.name, f.default, f.status, purpose
            ));
        }
    }
    md
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! layer-gate — Cargo-DECLARED dependency edges must obey the layer map
//! (`quality/ARCH_LAYERS.toml`), plus the crate fan-in ratchet.
//!
//! This is the deterministic half of dependency-direction enforcement: it
//! parses manifests only, runs in <1s, and needs no daemon. The code-intel
//! `arch_report` checks the same policy against SCIP-OBSERVED symbol
//! references (catching coupling that re-exports hide) — both halves share
//! the `arch-layers` parser/evaluator so they can't drift on semantics.
//!
//! Fan-in ratchet: `quality/baselines/fan_in.tsv` caps how many workspace
//! crates may depend on each tracked (god-)crate. One more dependent on
//! `corpus-engine` becomes a visible, reviewed baseline diff instead of
//! silent accretion.

use arch_layers::{DepEdge, DepKind};
use std::collections::{BTreeMap, BTreeSet};

use crate::common;
use crate::manifests;

/// Crates enter the fan-in baseline when first snapshotted at or above this
/// many dependents. (Below it, fan-in isn't the interesting signal.) 8, not
/// 9: sovereign-tools — the workspace's sharpest hub (fan-in 8 AND fan-out
/// 13) — must be inside the ratchet.
const FAN_IN_SEED_THRESHOLD: usize = 8;

pub fn run(args: &[String]) -> i32 {
    let root = common::repo_root();
    let flags = common::baseline_flags(args);
    let map_path = root.join("quality/ARCH_LAYERS.toml");
    let fan_in_path = common::baselines_dir(&root).join("fan_in.tsv");

    let map_text = match std::fs::read_to_string(&map_path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!(
                "error: cannot read {} ({e}).\n  The layer map is the dependency-direction \
                 contract — see ARCH_PRINCIPLES.md §8.",
                map_path.display()
            );
            return 1;
        }
    };
    let map = match arch_layers::parse(&map_text) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: {e}");
            return 1;
        }
    };

    let members = manifests::workspace_members(&root);
    let names: BTreeSet<String> = members.iter().map(|m| m.name.clone()).collect();
    let edges = manifests::internal_dep_edges(&root, &members);
    let fan_in = compute_fan_in(&edges);

    // ── Baseline maintenance modes ────────────────────────────────────────────
    if flags.update {
        let tracked: BTreeMap<String, usize> = if fan_in_path.exists() {
            // Keep the tracked SET stable; snapshot current counts for it.
            common::load_count_map(&fan_in_path)
                .keys()
                .map(|k| (k.clone(), fan_in.get(k).copied().unwrap_or(0)))
                .collect()
        } else {
            // First snapshot: seed with every crate at/above the threshold.
            fan_in
                .iter()
                .filter(|(_, &n)| n >= FAN_IN_SEED_THRESHOLD)
                .map(|(k, &n)| (k.clone(), n))
                .collect()
        };
        if let Err(e) = write_fan_in(&fan_in_path, &tracked) {
            eprintln!("error: {e}");
            return 1;
        }
        eprintln!(
            "wrote {} ({} crates fan-in-ratcheted)",
            fan_in_path.display(),
            tracked.len()
        );
        return 0;
    }
    if flags.tighten {
        let baseline = common::load_count_map(&fan_in_path);
        let tightened: BTreeMap<String, usize> = baseline
            .iter()
            .map(|(k, &cap)| (k.clone(), fan_in.get(k).copied().unwrap_or(0).min(cap)))
            .collect();
        if tightened == baseline {
            eprintln!(
                "layer-gate --tighten: fan-in baseline already tight ({} entries)",
                baseline.len()
            );
            return 0;
        }
        let lowered = tightened
            .iter()
            .filter(|(k, &v)| baseline.get(*k).is_some_and(|&b| v < b))
            .count();
        if let Err(e) = write_fan_in(&fan_in_path, &tightened) {
            eprintln!("error: {e}");
            return 1;
        }
        eprintln!(
            "layer-gate --tighten: {lowered} caps lowered → {}",
            fan_in_path.display()
        );
        return 0;
    }

    // ── Check mode ────────────────────────────────────────────────────────────
    let violations = arch_layers::evaluate(&map, &names, &edges);

    let baseline = common::load_count_map(&fan_in_path);
    let mut fan_in_fails: Vec<String> = Vec::new();
    for (name, &cap) in &baseline {
        let actual = fan_in.get(name).copied().unwrap_or(0);
        if actual > cap {
            fan_in_fails.push(format!(
                "fan-in of `{name}` grew {cap} → {actual}: one more crate now depends on \
                 this god-crate. Depend on a narrower crate instead, or accept the growth \
                 explicitly by re-baselining."
            ));
        }
    }

    // Dev-only upward edges are worth eyes but never enforcement.
    let dev_edges_up = edges.iter().filter(|e| e.kind == DepKind::Dev).count();

    eprintln!(
        "layer-gate: {} members, {} internal edges ({} dev, exempt; {} absent from the \
         default build) vs {} layers; {} back-of-house patterns; fan-in ratchet over {} crates",
        names.len(),
        edges.len(),
        dev_edges_up,
        map.layers.len(),
        baseline.len()
    );
    for v in &violations {
        eprintln!("  ✗ {}", v.describe());
    }
    for f in &fan_in_fails {
        eprintln!("  ✗ {f}");
    }
    if violations.is_empty() && fan_in_fails.is_empty() {
        eprintln!(
            "  ✓ every crate assigned, every edge points down or sideways, fan-in within caps"
        );
        0
    } else {
        eprintln!();
        eprintln!(
            "layer-gate FAILED ({} layer violations, {} fan-in). The layer map is the \
             dependency-direction contract — quality/ARCH_LAYERS.toml (ARCH_PRINCIPLES §8).",
            violations.len(),
            fan_in_fails.len()
        );
        eprintln!(
            "Layer/forbid violations: fix the edge or add a [[exception]] with a reason \
             (a reviewable policy diff). Stale exceptions: delete the entry."
        );
        eprintln!("{}", common::fix_footer("layer-gate"));
        1
    }
}

/// Distinct-dependent count per crate over Normal+Build edges (a dev-dep
/// can't leak into a shipped artifact, so it doesn't count as fan-in).
fn compute_fan_in(edges: &[DepEdge]) -> BTreeMap<String, usize> {
    let mut dependents: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    for e in edges {
        if e.kind == DepKind::Dev {
            continue;
        }
        dependents.entry(&e.to).or_default().insert(&e.from);
    }
    dependents
        .into_iter()
        .map(|(k, v)| (k.to_string(), v.len()))
        .collect()
}

fn write_fan_in(path: &std::path::Path, map: &BTreeMap<String, usize>) -> Result<(), String> {
    common::write_count_map(
        path,
        "layer-gate",
        "crate fan-in caps (distinct dependent workspace crates, normal+build deps)",
        map,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn edge(from: &str, to: &str, kind: DepKind) -> DepEdge {
        DepEdge {
            from: from.into(),
            to: to.into(),
            kind,
        }
    }

    #[test]
    fn fan_in_counts_distinct_dependents_and_ignores_dev() {
        let edges = vec![
            edge("a", "core", DepKind::Normal),
            edge("b", "core", DepKind::Normal),
            edge("b", "core", DepKind::Normal), // duplicate edge — still one dependent
            edge("c", "core", DepKind::Dev),    // dev — not fan-in
            edge("a", "other", DepKind::Build), // build — counts
        ];
        let f = compute_fan_in(&edges);
        assert_eq!(f.get("core"), Some(&2));
        assert_eq!(f.get("other"), Some(&1));
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `cargo xtask quality` — run every local gate, one summary table.
//!
//! The single entry point for "am I clean?" before/after a cleanup session.
//! Check-mode only: baseline mutations stay explicit per-gate
//! (`--update-baseline` / `--tighten`), so a habit-run can never silently
//! move a ratchet.
//!
//! Compile-coupled gates (lint-gate over clippy JSON, api-gate over rustdoc
//! JSON) are deliberately NOT here — they cost a build and run on their own
//! cadence (see .github/workflows/weekly.yml). This command stays sub-second.

use crate::{arch_gate, boundary_gate, docs_gate, env_gate, layer_gate, lock_gate};

pub fn run() -> i32 {
    let no_args: [String; 0] = [];
    let gates: &[(&str, &dyn Fn() -> i32)] = &[
        ("arch-gate", &|| arch_gate::run(&no_args)),
        ("docs-gate", &docs_gate::run),
        ("boundary-gate", &boundary_gate::run),
        ("layer-gate", &|| layer_gate::run(&no_args)),
        ("lock-gate", &|| lock_gate::run(&no_args)),
        ("env-gate", &|| env_gate::run(&no_args)),
    ];

    let mut results: Vec<(&str, Enforcement, i32)> = Vec::new();
    for (name, enforcement, gate) in gates {
        eprintln!("── {name} ────────────────────────────────────────────────");
        let code = gate();
        results.push((name, code));
        eprintln!();
    }

    eprintln!("── quality summary ─────────────────────────────────────────");
    let mut failed = 0;
    for (name, code) in &results {
        let verdict = if *code == 0 { "PASS" } else { "FAIL" };
        eprintln!("  {verdict}  {name}");
        if *code != 0 {
            failed += 1;
        }
    }
    if failed == 0 {
        eprintln!("  ✓ all {} gates green", results.len());
        0
    } else {
        eprintln!(
            "  ✗ {failed}/{} gates failing — each gate's output above ends with its fix command",
            results.len()
        );
        1
    }
}

