//! Client-owned connection state: the HOST_CONNECTION record (SQLite)
//! and the CREDENTIAL token (keychain).

pub mod keychain;
pub mod store;

pub use keychain::{CredentialStore, DevFileCredentialStore};
pub use store::HostConnection;

/// How a `HostConnection.tailnet_address` is interpreted. One kind
/// today; a future dial-by-key transport (iroh) adds its own without
/// reshaping the table — the address column is opaque per kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EndpointKind {
    /// MagicDNS name or overlay IP + port, reached as plain
    /// `http://<addr>` over the tailnet.
    Tailnet,
}

impl EndpointKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            EndpointKind::Tailnet => "tailnet",
        }
    }

    /// Loud on unknown kinds: a row written by a NEWER app build
    /// must fail visibly here, not be silently dialed as a tailnet
    /// address that can't work.
    pub fn parse(s: &str) -> crate::error::Result<Self> {
        match s {
            "tailnet" => Ok(EndpointKind::Tailnet),
            other => Err(crate::error::Error::Other(format!(
                "unknown host endpoint_kind '{other}' — this app build is too old for this host entry"
            ))),
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Shared application state managed by Tauri. Holds the SQLite cache
//! connection, the keychain-backed credential store, and helpers to
//! resolve the active host into an authed [`ApiClient`].

use std::sync::{Arc, Mutex};

use rusqlite::Connection;

use crate::connection::{store as conn_store, CredentialStore, HostConnection};
use crate::error::{Error, Result};
use crate::remote::ApiClient;

pub struct AppState {
    /// Single cache connection behind a mutex. Locked only for short,
    /// await-free critical sections (the stream path writes at
    /// completion without holding it across I/O).
    pub db: Arc<Mutex<Connection>>,
    /// Token store — OS keychain at ship time (dev-file placeholder now).
    pub credentials: Box<dyn CredentialStore>,
}

impl AppState {
    pub fn new(db: Connection, credentials: Box<dyn CredentialStore>) -> Self {
        Self {
            db: Arc::new(Mutex::new(db)),
            credentials,
        }
    }

    fn with_db<T>(&self, f: impl FnOnce(&Connection) -> Result<T>) -> Result<T> {
        let conn = self.db.lock().map_err(|_| Error::Other("db poisoned".into()))?;
        f(&conn)
    }

    pub fn active_host(&self) -> Result<HostConnection> {
        self.with_db(|c| conn_store::get_default(c))?
            .ok_or(Error::NoActiveHost)
    }

    /// Build an authed client for the active host. Reads the token from
    /// the keychain — never from SQLite.
    pub async fn active_client(&self) -> Result<ApiClient> {
        let host = self.active_host()?;
        let token = self
            .credentials
            .get_token(&host.id)?
            .ok_or(Error::Unauthenticated)?;
        self.client_for_host(&host, token).await
    }

    /// Transport seam: the host's `endpoint_kind` decides how its
    /// address becomes a dialable client. One arm today (tailnet →
    /// plain HTTP to the address); a future dial-by-key transport
    /// adds an arm instead of every caller assuming an IP address.
    /// Unknown kinds (rows written by a newer app build) fail loudly
    /// in `EndpointKind::parse`.
    fn client_for_host(host: &HostConnection, token: String) -> Result<ApiClient> {
        match crate::connection::EndpointKind::parse(&host.endpoint_kind)? {
            crate::connection::EndpointKind::Tailnet => {
                Ok(ApiClient::new(&host.tailnet_address, token))
            }
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Role layer — the counter-force structure on top of the
//! canonical primitives.
//!
//! A `Role` is a closed enum of agent invocation profiles. Each
//! role carries a `RoleProfile`: system prompt + allowed primitive
//! subset + sampling overrides + forced first tool. The agent loop
//! runs in one role at a time; transitions between roles happen at
//! call boundaries (each chat completion request uses the active
//! role's profile).
//!
//! Three roles in v1:
//!
//! - **Planner** — read state + emit chunked plan. No write/build
//!   access. Closes "Implementer holding the whole problem in
//!   attention."
//! - **Implementer** — write code against the plan. No build/smoke
//!   access. After every `write_file` (or `handoff_to_evaluator`),
//!   transition to Evaluator. Closes "Implementer iterates without
//!   verifying."
//! - **Evaluator** — verify state + decide next move. First call
//!   forced to `build` or `smoke`. No `write_file` access. Closes
//!   verify-discipline gap structurally.
//!
//! Plans live in `~/.claude/plans/role-layer-multilang.md`.

pub mod dossier;
pub mod model_map;
pub mod profile;
pub mod transition;

use serde::{Deserialize, Serialize};

pub use dossier::{RoleDossier, RoleDossierOutcome};
pub use model_map::RoleModelMap;
pub use profile::{
    profile_for, RoleProfile, SamplingOverrides, WorkdirScale, EVALUATOR_MUST_HANDOFF_SUBSET,
    EVALUATOR_TERMINATING_SUBSET, IMPLEMENTER_REWRITE_SUBSET,
};
pub use transition::{transition_after, TransitionTrigger};

/// Closed enum of agent roles. Adding a variant requires touching:
/// `profile::default_profile_for`, `transition::transition_after`,
/// `transition::initial_role`, and every site that matches on
/// `Role` exhaustively.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Role {
    Planner,
    Implementer,
    Evaluator,
}

impl Role {
    pub const fn id(&self) -> &'static str {
        match self {
            Role::Planner => "planner",
            Role::Implementer => "implementer",
            Role::Evaluator => "evaluator",
        }
    }

    pub fn from_id(id: &str) -> Option<Self> {
        match id {
            "planner" => Some(Role::Planner),
            "implementer" => Some(Role::Implementer),
            "evaluator" => Some(Role::Evaluator),
            _ => None,
        }
    }

    pub const fn all() -> &'static [Role] {
        &[Role::Planner, Role::Implementer, Role::Evaluator]
    }

    /// The role the agent loop starts in. Per the plan: Planner
    /// runs first so the Implementer inherits a chunked plan
    /// instead of holding the whole problem.
    pub const fn initial() -> Role {
        Role::Planner
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn role_ids_round_trip() {
        for r in Role::all() {
            assert_eq!(Role::from_id(r.id()), Some(*r));
        }
    }

    #[test]
    fn initial_is_planner() {
        assert_eq!(Role::initial(), Role::Planner);
    }
}

