    fn derive_title_handles_plain_text_fallback() {
        assert_eq!(
            derive_milestone_title("Plain text brief"),
            "Plain text brief"
        );
    }

    #[test]
    fn extract_id_and_title_em_dash_separator() {
        let md = "# atos-foo — Human Title\n\nbody";
        let (id, title) = extract_id_and_title(md).unwrap();
        assert_eq!(id, "atos-foo");
        assert_eq!(title, "Human Title");
    }

    #[test]
    fn extract_id_and_title_rejects_missing_heading() {
        let md = "body without heading";
        let err = extract_id_and_title(md).unwrap_err();
        assert!(matches!(err, Error::CharterParse(_)));
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Headless OCR install — hand the daemon's `LocalCorpusManager` an `OcrCtx`.
//!
//! # Why this file exists
//!
//! Everything needed to OCR a scanned PDF on a headless box was already in
//! the tree; the one missing link was a caller. `OcrCtx` is plain data,
//! `LocalCorpusManager::set_ocr_ctx` is a per-instance setter, and the
//! daemon already builds that manager (`bootstrap::setup_watched_folders`).
//! Only the desktop ever called the setter, and it resolved its assets from
//! three `AppHandle` bundle probes that do not exist off-desktop. This
//! module is the same install with the bundle probes replaced by
//! env-then-`data_dir` resolution.
//!
//! Without it, `svrn corpus watch --ocr` on a server registers the corpus
//! with `with_ocr: true` and then every scanned PDF lands in
//! `WatchedFolderState.failed_files` with the reason "OCR is enabled but the
//! daemon's OcrCtx isn't installed" (`watched/worker.rs`). Reported, not
//! silent — but for a litigation corpus, "reported" still means the
//! discovery never got indexed.
//!
//! # The seam is an env var, deliberately
//!
//! `PaddleEngine::from_ctx` resolves its models through
//! `paddle::models_root()`, which reads `SOVEREIGN_PADDLE_OCR_MODEL_DIR` and
//! otherwise falls back to a hardcoded `~/.svrnmesh/models/paddle-ocr` —
//! **not** rebrand-aware, so a `~/.svrnmesh` install misses it. `OcrCtx`
//! carries no model-path field, so pointing the engine at a staged asset
//! directory means setting that variable. We set it (as the desktop does)
//! rather than introducing a second resolution path for the same thing.
//!
//! # Glassbox
//!
//! Every exit from [`install_ocr_ctx`] logs, including the two silent ones:
//! the feature being compiled out, and the models not resolving. An operator
//! who turned OCR on in `corpus watch` and sees nothing happen must be able
//! to find out why from the daemon log alone.

use std::path::Path;
// Only the `ocr` arm and its path helpers build owned paths. Without the
// gate this is an unused-import warning in every default build, which is
// the kind of noise that trains a reader to ignore warnings.
#[cfg(feature = "ocr")]
use std::path::PathBuf;

use sovereign_tools::local_corpus::LocalCorpusManager;

/// Install an `OcrCtx` on `manager`, if this build has the `ocr` feature and
/// the PaddleOCR assets can be found.
///
/// `cleanup_model` must be a GGUF **file stem** the daemon's
/// `/v1/chat/completions` route can resolve (slots are registered under
/// their file stem) — never a slot alias like `"fast"`, which 503s. A wrong
/// value does not fail: the page keeps its raw un-polished OCR text with a
/// `<!-- raw OCR (cleanup unavailable) -->` marker, which is exactly the
/// kind of quality loss nobody reports. Hence the explicit warn below when
/// it arrives empty.
///
/// Never fatal. A daemon with no OCR is a supported posture; a daemon that
/// refuses to boot because an optional asset is missing is not.
pub(super) async fn install_ocr_ctx(
    manager: &LocalCorpusManager,
    data_dir: &Path,
    daemon_base_url: String,
    cleanup_model: String,
) {
    #[cfg(not(feature = "ocr"))]
    {
        // Bind the unused params so the no-op arm compiles identically to
        // the real one — a signature that drifts between cfgs is a build
        // break waiting for whoever first turns the feature on.
        let _ = (manager, data_dir, daemon_base_url, cleanup_model);
        tracing::info!(
            "ocr:unavailable reason=feature_not_compiled — this daemon was built \
             without `--features ocr`, so scanned PDFs in a `corpus watch --ocr` \
             folder will be reported as scanned_no_text rather than indexed"
        );
    }

    #[cfg(feature = "ocr")]
    {
        use sovereign_tools::local_corpus::ocr::paddle::DEFAULT_MODEL_ID;
        use sovereign_tools::local_corpus::ocr::{OcrCtx, OcrEngineKind};

        let roots = paddle_model_roots(
            data_dir,
            sovereign_tools::local_corpus::ocr::paddle::model_root_override(),
        );
        let Some(model_root) = roots
            .iter()
            .find(|root| model_set_complete(root, DEFAULT_MODEL_ID))
            .cloned()
        else {
            tracing::warn!(
                probed = ?roots,
                model_set = DEFAULT_MODEL_ID,
                "ocr:unavailable reason=models_not_found — none of the probed roots \
                 holds {DEFAULT_MODEL_ID}/{{det.onnx,rec.onnx,dict.txt}}. Stage them \
                 or set SOVEREIGN_PADDLE_OCR_MODEL_DIR; scanned PDFs stay unindexed \
                 until then"
            );
            return;
        };

        // The engine reads this on construction. Setting it here (rather
        // than teaching `models_root()` about `data_dir`) keeps one
        // resolution path for both the desktop and the daemon.
        std::env::set_var("SOVEREIGN_PADDLE_OCR_MODEL_DIR", &model_root);

        let pdfium_probes = pdfium_probes(data_dir, std::env::var("SOVEREIGN_PDFIUM_LIB").ok());
        let pdfium_lib_path = pdfium_probes.iter().find(|p| p.exists()).cloned();
        if pdfium_lib_path.is_none() {
            tracing::warn!(
                probed = ?pdfium_probes,
                "ocr:pdfium_not_staged — falling back to pdfium-render's bundled/system \
                 search. On an air-gapped box there is usually no system libpdfium, and \
                 without it no PDF can be rasterized, so OCR will produce nothing. Stage \
                 the library or set SOVEREIGN_PDFIUM_LIB"
            );
        }

        if cleanup_model.is_empty() {
            tracing::warn!(
                "ocr:cleanup_model_unset — no chat model is configured, so the OCR \
                 cleanup pass cannot run. Pages will carry raw recognizer output with a \
                 `<!-- raw OCR (cleanup unavailable) -->` marker"
            );
        }

        let ctx = OcrCtx {
            // Inert under `engine: Paddle`; `OcrCtx` has no Option for them.
            tesseract_bin: PathBuf::from("tesseract"),
            tessdata_dir: PathBuf::new(),
            pdfium_lib_path,
            daemon_base_url,
            cleanup_model,
            dpi: 300,
            tesseract_timeout_secs: 30,
            cleanup_timeout_secs: 30,
            engine: OcrEngineKind::Paddle,
        };
        tracing::info!(
            engine = "paddleocr",
            paddle_model_root = %model_root.display(),
            pdfium = ?ctx.pdfium_lib_path,
            cleanup_model = %ctx.cleanup_model,
            daemon_base_url = %ctx.daemon_base_url,
            "ocr:installed — `corpus watch --ocr` folders will read scanned PDFs"
        );
        manager.set_ocr_ctx(ctx).await;
    }
}

/// Candidate PaddleOCR model **roots**, in precedence order. A root holds
/// `<model_id>/` — not the model files themselves.
///
/// `data_dir` before `~/.svrnmesh` is the load-bearing ordering: a
/// rebranded install (`~/.svrnmesh`) has a `data_dir` the hardcoded
/// `paddle::models_root()` fallback would never look at.
///
/// The env override arrives as a parameter rather than being read here so
/// the precedence is a pure function of its inputs — testable without
/// mutating process-global state, which under a parallel test runner is not
/// a test but a race.
#[cfg(feature = "ocr")]
fn paddle_model_roots(data_dir: &Path, env_override: Option<PathBuf>) -> Vec<PathBuf> {
    let mut roots: Vec<PathBuf> = Vec::new();
    if let Some(env_path) = env_override {
        roots.push(PathBuf::from(env_path));
    }
    roots.push(data_dir.join("models").join("paddle-ocr"));
    roots.push(
        sovereign_contracts::rebrand::svrnmesh_root()
            .join("models")
            .join("paddle-ocr"),
    );
    roots
}

/// True only when all three files of a model set are present, so a `Some`
/// from the caller means "Paddle can run" rather than "a directory exists".
/// Discovering a missing `rec.onnx` per-document instead is the failure this
/// avoids.
#[cfg(feature = "ocr")]
fn model_set_complete(root: &Path, model_id: &str) -> bool {
    let set = root.join(model_id);
    set.join("det.onnx").is_file()
        && set.join("rec.onnx").is_file()
        && set.join("dict.txt").is_file()
}

/// Candidate `libpdfium` paths, in precedence order. All three platform
/// library names are probed at each root so a kit staged on one OS and
/// inspected on another still resolves.
#[cfg(feature = "ocr")]
fn pdfium_probes(data_dir: &Path, env_override: Option<String>) -> Vec<PathBuf> {
    const LIB_NAMES: [&str; 3] = ["libpdfium.so", "libpdfium.dylib", "pdfium.dll"];
    let mut probes: Vec<PathBuf> = Vec::new();
    if let Some(env_path) = env_override {
        probes.push(PathBuf::from(env_path));
    }
    let mut roots = vec![data_dir.join("lib"), data_dir.to_path_buf()];
    roots.push(sovereign_contracts::rebrand::svrnmesh_root().join("lib"));
    for root in &roots {
        for lib in LIB_NAMES {
            probes.push(root.join("pdfium").join(lib));
            probes.push(root.join(lib));
        }
    }
    probes
}

#[cfg(all(test, feature = "ocr"))]
mod tests {
    use super::*;

    /// The rebrand trap: `paddle::models_root()`'s own fallback is a
    /// hardcoded `~/.svrnmesh/models/paddle-ocr`, so a `~/.svrnmesh` install
    /// only finds staged models because `data_dir` is probed FIRST. Assert
    /// the ordering, not merely the membership.
    #[test]
    fn data_dir_root_outranks_the_hardcoded_home_fallback() {
        let data_dir = Path::new("/srv/svrnmesh");
        let roots = paddle_model_roots(data_dir, None);
        let staged = roots
            .iter()
            .position(|p| p == &data_dir.join("models").join("paddle-ocr"))
            .expect("data_dir root must be probed");
        // svrnmesh_root() is infallible and is now pushed unconditionally;
        // it must still come after the staged root.
        let fallback = sovereign_contracts::rebrand::svrnmesh_root()
            .join("models")
            .join("paddle-ocr");
        if let Some(at) = roots.iter().position(|p| p == &fallback) {
            assert!(
                staged < at,
                "data_dir root must outrank the hardcoded ~/.svrnmesh fallback"
            );
        }
    }

    /// A directory with two of three files must NOT resolve — the whole
    /// point of validating the set is that "OCR is available" is decided
    /// once at boot rather than per document.
    #[test]
    fn a_partial_model_set_does_not_resolve() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let root = tmp.path().join("models").join("paddle-ocr");
        let set = root.join("ppocr-en-v4v5");
        std::fs::create_dir_all(&set).expect("mkdir");
        std::fs::write(set.join("det.onnx"), b"x").expect("write det");
        std::fs::write(set.join("dict.txt"), b"x").expect("write dict");
        assert!(
            !model_set_complete(&root, "ppocr-en-v4v5"),
            "a set missing rec.onnx must not count as resolvable"
        );
        std::fs::write(set.join("rec.onnx"), b"x").expect("write rec");
        assert!(
            model_set_complete(&root, "ppocr-en-v4v5"),
            "a complete set must resolve"
        );
    }

    /// `SOVEREIGN_PDFIUM_LIB` is the documented override in the on-prem
    /// runbook; if it ever stopped being probed first, a staged-but-wrong
    /// library in `data_dir` would silently win.
    #[test]
    fn pdfium_env_override_is_probed_first() {
        let probes = pdfium_probes(
            Path::new("/srv/svrnmesh"),
            Some("/opt/libpdfium.so".to_string()),
        );
        assert_eq!(
            probes.first().map(PathBuf::as_path),
            Some(Path::new("/opt/libpdfium.so"))
        );
    }

    /// With no override, `data_dir` must still be probed ahead of `$HOME` —
    /// the same rebrand trap as the model root, for the library.
    #[test]
    fn pdfium_probes_data_dir_before_home() {
        let data_dir = Path::new("/srv/svrnmesh");
        let probes = pdfium_probes(data_dir, None);
        let staged = probes
            .iter()
            .position(|p| p == &data_dir.join("lib").join("libpdfium.so"))
            .expect("data_dir/lib must be probed");
        let fallback = sovereign_contracts::rebrand::svrnmesh_root()
            .join("lib")
            .join("libpdfium.so");
        if let Some(at) = probes.iter().position(|p| p == &fallback) {
            assert!(staged < at, "data_dir/lib must outrank ~/.svrnmesh/lib");
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Hot-reload inference provider factory — extracted from `daemon_cmd`
//! (§3.2). Rebuilds the embedded llama.cpp provider (wrapped in the
//! mesh-aware router) when the operator changes a model path at runtime.

use std::sync::Arc;

use async_trait::async_trait;
use sovereign_core::model_family::ModelFamily;
use sovereign_core::setup_config::SetupConfig;
use sovereign_core::traits::InferenceProvider;
use sovereign_inference::embedded::EmbeddedLlamaCpp;
use sovereign_mesh::admin_http::ProviderFactory;

/// Rebuilds the embedded llama.cpp provider from a fresh `SetupConfig`,
/// wrapped in the same `MeshInferenceProvider` used at cold start so
/// hot-reloads preserve mesh-aware model routing.
///
/// Hot-swapped into `EmbeddedDaemon::inference_provider` by the admin
/// reload handler when the user changes a `models.*` path in
/// `~/.svrnmesh/config.toml` (e.g. via the desktop Settings
/// panel's model picker). Keeps the model-loading side of the daemon
/// out of `sovereign-mesh`, which has no business knowing about GGUF.
pub(super) struct LlamaCppFactory {
    /// Same `EmbeddedDaemon` the cold-start path wraps the raw
    /// llama.cpp provider against. Held here so a hot-reload
    /// (operator changing the primary GGUF path while the daemon is
    /// running) produces a `MeshInferenceProvider` view of the new
    /// raw provider — without this, reload would drop the wrapper
    /// and `/v1/chat/completions` would silently start substituting
    /// for peer-only model names again.
    pub(super) daemon: Arc<sovereign_mesh::DeferredDaemon>,
}

#[async_trait]
impl ProviderFactory for LlamaCppFactory {
    async fn build_provider(
        &self,
        cfg: &SetupConfig,
    ) -> Result<Arc<dyn InferenceProvider>, String> {
        // Mirror the load parameters used by `run_daemon` on cold
        // start — the reload must not silently downgrade context
        // size or auto-gpu-layer behaviour. Pulls context size and
        // idle timeout from `cfg` for the same reason: a hot-reload
        // shouldn't drop the operator's tuned values.
        let provider = EmbeddedLlamaCpp::load_full_with_families(
            cfg.models.fast_path(),
            Some(&cfg.models.primary),
            Some(&cfg.models.embed),
            cfg.models.code.as_deref(),
            cfg.models.effective_context_size(),
            None,
            ModelFamily::Unknown,
            ModelFamily::Unknown,
            ModelFamily::Unknown,
            // code slot is Qwen3-Coder-30B-A3B-Instruct (the only code
            // GGUF we ship today). Pinning the family to Qwen3 picks up
            // Qwen's recommended sampling defaults — top_k=20 (vs the
            // Unknown fallback of 40), top_p=0.95, presence_penalty=1.5
            // — and the SystemPromptToken thinking control. Empirically
            // (2026-05-08 measurement) the Unknown defaults left the
            // sampler too permissive on long Rust emissions, contributing
            // to the character-drop pattern (`f3 2`, `Lat encyClass`).
            ModelFamily::Qwen3,
        )
        .map_err(|e| format!("reload: failed to load models: {e}"))?;
        // Keep a typed `Arc<EmbeddedLlamaCpp>` to fire
        // `start_idle_monitor` (inherent method), then upcast to
        // `Arc<dyn InferenceProvider>` so the wrapper can hold it.
        let raw_concrete = Arc::new(provider);
        raw_concrete.start_idle_monitor(cfg.daemon.primary_idle_secs);
        let raw: Arc<dyn InferenceProvider> = raw_concrete;

        // Wrap so a hot-reloaded daemon keeps its mesh-aware model
        // routing — same wrapper the cold-start path installs in
        // `run_daemon`. See the comment on the cold-start wiring
        // for why a bare `EmbeddedLlamaCpp` here would re-introduce
        // the silent-substitution bug.
        //
        // Hot-reload load-awareness invariant: the new MIP must
        // share the SAME `Arc<AtomicU32>` publisher as the old MIP
        // (held by AppState's OnceLock). Live `LocalTotalGuard`s
        // from the old MIP have already captured a clone of that
        // Arc and will continue to decrement it as their requests
        // drain. If we let the new MIP create a fresh publisher,
        // the old guards would write to an Arc nobody reads, and
        // gossip would see a counter that snaps to zero on reload
        // and stays there until new traffic flows. See
        // `sovereign/docs/MESH_LOAD_AWARENESS.md`.
        let app_state_opt = self.daemon.app_state().await;
        let mesh_provider = if let Some(state) = app_state_opt.as_ref() {
            match state.in_flight_publisher() {
                Some(publisher) => Arc::new(
                    sovereign_mesh::peer_inference::MeshInferenceProvider::with_peer_source_and_publisher(
                        raw,
                        Arc::clone(&self.daemon),
                        publisher,
                    ),
                ),
                // OnceLock not yet set means cold-start's spawned
                // task hasn't run; reload still installs the new
                // MIP, and the spawned task will install its
                // publisher when it next polls.
                None => Arc::new(sovereign_mesh::peer_inference::MeshInferenceProvider::new(
                    raw,
                    Arc::clone(&self.daemon),
                )),
            }
        } else {
            Arc::new(sovereign_mesh::peer_inference::MeshInferenceProvider::new(
                raw,
                Arc::clone(&self.daemon),
            ))
        };
        // Push current slot aliases into the freshly-built mesh
        // provider so a reload preserves the deferred-resolution
        // wiring. Mirrors the cold-start spawned task in
        // `run_daemon`; here we run inline because the daemon is
        // already in the Running state at reload time.
        if let Some(state) = app_state_opt {
            let snapshot = state.inner.slot_aliases.load();
            let map: std::collections::HashMap<String, String> = snapshot
                .iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect();
            if !map.is_empty() {
                mesh_provider.set_slot_aliases(map);
            }
        }
        // Route this node's primary turns into the mesh-hosted shared model, if
        // one is configured (SOVEREIGN_SHARED_MODEL_ID, from [shared_model]
        // model_id). Survives reload — the env is set once at daemon entry.
        if let Some(id) = std::env::var("SOVEREIGN_SHARED_MODEL_ID")
            .ok()
            .filter(|s| !s.trim().is_empty())
        {
            mesh_provider.set_shared_model_id(Some(id));
        }
        let routed: Arc<dyn InferenceProvider> = mesh_provider;
        Ok(routed)
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Daemon MCP tool-registry construction — extracted from `daemon_cmd`
//! (§3.2). Builds the code-intel + notes + work-atlas + lint/test
//! `ToolRegistry` and the merged in-memory SCIP graph it reads from.

use std::path::PathBuf;
use std::sync::Arc;

use corpus_engine::CorpusEngine;
use corpus_engine_notes::NoteStore;
use corpus_engine_watchers::{LintResultStore, TestResultStore};
use sovereign_core::ToolRegistry;

pub(super) async fn build_tool_registry(
    data_dir: &std::path::Path,
    engine: Arc<CorpusEngine>,
    notes: Arc<NoteStore>,
    lint_store: Arc<LintResultStore>,
    test_store: Arc<TestResultStore>,
    test_watcher: Option<Arc<corpus_engine_watchers::TestWatcher>>,
    watched_lint_scope: Option<String>,
    watched_test_scope: Option<String>,
    watcher_heartbeat: Arc<corpus_engine_watchers::WatcherHeartbeat>,
    workspace_dir: Option<PathBuf>,
    work_atlas_store: Arc<sovereign_work_atlas::WorkAtlasStore>,
    work_atlas_cfg: sovereign_work_atlas::WorkAtlasConfig,
    work_atlas_broadcaster: Arc<sovereign_work_atlas::tools::DeferredBroadcaster>,
    work_atlas_repo_root: Option<PathBuf>,
    work_atlas_repo_id: Option<String>,
    work_atlas_branch: Option<String>,
    solve_jobs: Arc<super::solve_http::SolveJobs>,
    // The shared merged SCIP graph. Created ONCE by the caller and handed to
    // BOTH these tools and the project reindexer, so the reindexer's live
    // updates (the tree-sitter overlay and full rebuilds) are visible to
    // symbols/callers/blast without a daemon restart. Before this was shared,
    // the tools read a frozen startup snapshot while the reindexer updated an
    // orphan graph nothing queried — the root of "always stale."
    merged_graph_handle: sovereign_tools::ScipGraphHandle,
) -> ToolRegistry {
    let indexes_dir = data_dir.join("indexes");

    // Tier 4 — shared tool-result cache. The daemon's registry
    // serves both HTTP API requests AND in-process Runtime calls;
    // per-conversation scoping in `CacheKey` keeps the slices
    // isolated even when two clients hit different conversations
    // simultaneously.
    let tool_cache = std::sync::Arc::new(sovereign_core::tool_result_cache::ToolResultCache::new());
    let mut tools = ToolRegistry::new().with_cache(std::sync::Arc::clone(&tool_cache));

    // Call-graph tools. Merge every `scip_graph.db` under the indexes
    // directory into a single in-memory graph, then register
    // find_callers / find_callees / blast_radius. Without this step
    // agents can't trace references through the daemon — project_serve
    // had these, the daemon didn't.
    //
    // The graph also backs `symbols`/exact-name lookup, so build it
    // BEFORE registering the code-intel tools below.
    // Use the caller-provided shared handle (see the param doc) rather than
    // building a private snapshot — that private snapshot never saw the
    // reindexer's updates and is the staleness this unification fixes.
    let graph_handle = merged_graph_handle;

    // Code intelligence — scoped to discovered corpora under indexes_dir.
    let health_checker = Arc::new(sovereign_tools::IndexHealthChecker::new(Arc::clone(
        &graph_handle,
    )));
    tools.register(Box::new(
        sovereign_tools::SymbolLookupTool::new(Arc::clone(&engine), Arc::clone(&graph_handle))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    tools.register(Box::new(
        sovereign_tools::CodeSearchTool::new(Arc::clone(&engine)).declared(),
    ))));
    tools.register(Box::new(sovereign_tools::RecentChangesTool::new(
        Arc::clone(&engine),
    )));
    tools.register(Box::new(
        sovereign_tools::FindCallersTool::new(Arc::clone(&engine), Arc::clone(&graph_handle))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    tools.register(Box::new(
        sovereign_tools::FindCalleesTool::new(Arc::clone(&engine), Arc::clone(&graph_handle))
            .with_health_checker(Arc::clone(&health_checker)),
    ));
    tools.register(Box::new(
        sovereign_tools::BlastRadiusTool::new(Arc::clone(&graph_handle))
            .with_health_checker(Arc::clone(&health_checker))
            .with_atlas(Arc::clone(&work_atlas_store)),
    ));
    // Capability map — derived "what the codebase does" overview. Resolves
    // the per-corpus SCIP graph itself (same indexes dir the runtime uses).
    tools.register(Box::new(sovereign_tools::CapabilityMapTool::new()));
    // Architecture observability (quality program) — the SCIP-observed half
    // of the layer-map story (arch_report) + the cheap persisted-posture
    // reader (arch_posture). The workspace root unlocks the declared-deps /
    // layer-map / filesystem sections and the posture freshness check.
    {
        let mut tool = sovereign_tools::ArchReportTool::new();
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_project_root(ws);
        }
        tools.register(Box::new(tool));
    }
    {
        let mut tool = sovereign_tools::ArchPostureTool::new();
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_project_root(ws);
        }
        tools.register(Box::new(tool));
    }

    // Deterministic land-value-tax analytics over parcel corpora
    // (e.g. sf-assessor-roll) — pre-cited figures for the "no
    // confabulated numbers" demo. Read-only; safe on the MCP surface.
    tools.register(Box::new(
        sovereign_tools::parcel_analytics::ParcelAnalyticsTool::new(Arc::clone(&engine)),
    ));
    // Typed SEC-filing figures with basis + accession, or first-class
    // refusals; declares the opt-in bare-numeral audit (FINANCIAL_CORPORA §6).
    tools.register(Box::new(sovereign_tools::sec_facts::SecFactsTool::new(
        Arc::clone(&engine),
    )));

    // ── Work atlas tools (Phase 2) ──────────────────────────────
    // Always registered so MCP clients see them even on a repo
    // without an origin remote — `declare_scope` rejects with an
    // actionable error in that case. `work_in_flight` is read-only
    // and works without an origin (it just returns what the daemon
    // has heard from peers).
    tools.register(Box::new(
        sovereign_work_atlas::tools::DeclareScopeTool::new(
            Arc::clone(&work_atlas_store),
            work_atlas_cfg.clone(),
            Arc::clone(&work_atlas_broadcaster)
                as Arc<dyn sovereign_work_atlas::tools::ClaimBroadcaster>,
            work_atlas_repo_root
                .clone()
                .unwrap_or_else(|| data_dir.to_path_buf()),
            work_atlas_repo_id.clone().unwrap_or_default(),
            work_atlas_branch.clone(),
        ),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::ReleaseScopeTool::new(
            Arc::clone(&work_atlas_store),
            Arc::clone(&work_atlas_broadcaster)
                as Arc<dyn sovereign_work_atlas::tools::ClaimBroadcaster>,
        ),
    ));
    tools.register(Box::new(
        sovereign_work_atlas::tools::WorkInFlightTool::new(Arc::clone(&work_atlas_store)),
    ));
    // Resource-commons read surface (order seat-resource-commons):
    // "is this shared resource taken?" — verdict over claims
    // INCLUDING expired ones, so UC-R3's "expired" (taker died) is
    // distinguishable from "released" (work finished).
    tools.register(Box::new(
        sovereign_work_atlas::tools::ResourceMayITool::new(Arc::clone(&work_atlas_store)),
    ));

    // ── Lint / test watcher tools ───────────────────────────────
    // Always registered so MCP clients see a stable tool list. When
    // no watcher is wired (workspace not resolved or sovereign.toml
    // empty), the tools report `never_run` / `watcher_active: false`
    // — accurate, not silently-missing.
    {
        let mut tool = sovereign_tools::LintStatusTool::new(Arc::clone(&lint_store))
            .with_heartbeat(Arc::clone(&watcher_heartbeat));
        if let Some(scope) = watched_lint_scope.clone() {
            tool = tool.with_watched_scope(scope);
        }
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_workspace_root(ws);
        }
        tools.register(Box::new(tool));
    }
    {
        let mut tool = sovereign_tools::DriftPostureTool::new();
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_workspace_root(ws);
        }
        tools.register(Box::new(tool));
    }
    // Findings half of the drift pair. `MCP_TOOLS_ALWAYS` declares
    // `drift_findings`, but the daemon previously registered only
    // `drift_posture` — so the tool was on the manifest yet absent from the
    // live surface (preflight FAIL: "declared but not served"). It reads the
    // canonical `~/.svrnmesh/drift` sidecar via its default `drift_dir`, so a
    // bare `::new()` is correct — mirroring the CapabilityFindingsTool
    // registration below (a posture/findings pair that was wired symmetrically).
    tools.register(Box::new(sovereign_tools::DriftFindingsTool::new()));
    // Code facts — the embed-free structural fact base (tree-sitter fn defs /
    // config construction-fields / string literals), read from
    // `<indexes_dir>/<corpus>/facts.json`. Read-only and model-free, so it never
    // contends with agent inference; every response is freshness-stamped.
    tools.register(Box::new(sovereign_tools::FactsTool::new(
        indexes_dir.clone(),
    )));
    // Capability-reconciliation freshness + findings — siblings to drift_*,
    // over the `enrich capability-reconcile` artifact.
    {
        let mut tool = sovereign_tools::CapabilityPostureTool::new();
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_workspace_root(ws);
        }
        tools.register(Box::new(tool));
    }
    tools.register(Box::new(sovereign_tools::CapabilityFindingsTool::new()));
    {
        let mut tool = sovereign_tools::BuildTool::new(Arc::clone(&lint_store))
            .with_heartbeat(Arc::clone(&watcher_heartbeat));
        if let Some(scope) = watched_lint_scope {
            tool = tool.with_watched_scope(scope);
        }
        tools.register(Box::new(tool));
    }
    tools.register(Box::new(sovereign_tools::GetLintOutputTool::new(
        Arc::clone(&lint_store),
    )));
    {
        let mut tool = sovereign_tools::TestStatusTool::new(Arc::clone(&test_store))
            .with_heartbeat(Arc::clone(&watcher_heartbeat));
        if let Some(scope) = watched_test_scope {
            tool = tool.with_watched_scope(scope);
        }
        tools.register(Box::new(tool));
    }
    tools.register(Box::new(sovereign_tools::GetRunOutputTool::new(
        Arc::clone(&test_store),
    )));
    // `run_tests` is only registered when there's a live test watcher
    // to dispatch into. Without it, agents calling `run_tests` would
    // get a confusing no-op; the absence is the honest signal.
    if let Some(ref w) = test_watcher {
        tools.register(Box::new(sovereign_tools::RunTestsTool::new(Arc::clone(w))));
    }

    // NOTE: knowledge_lookup (Tool-Mastery Phase 5) is wired in
    // chat_cmd/bootstrap.rs where the `inference` + `store`
    // handles are available. The daemon's MCP-only tool registry
    // intentionally does not expose it — the unified knowledge
    // envelope only makes sense inside an active chat
    // conversation (the consumer is the model's synthesis path,
    // not arbitrary MCP clients).

    // Session-orientation brief — the SessionStart hook's renderer on
    // the MCP surface. Threads the live work-atlas store so the
    // "Work in flight" section reflects what this daemon has heard
    // from peers, not a stale read-only snapshot. Registered without
    // a workspace too: it rejects at execute time with the same
    // actionable set-SOVEREIGN_WORKSPACE_DIR message the watcher
    // tools use, rather than being silently absent.
    {
        let mut tool = sovereign_tools::BriefingTool::new(Arc::clone(&notes))
            .with_atlas(Arc::clone(&work_atlas_store));
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_workspace_root(ws);
        }
        tools.register(Box::new(tool));
    }

    // Encode-time session-frame upsert (SESSION_CONTINUITY write-path
    // 1). Workspace optional — without it the frame just skips the
    // head_at_end/branch git stamps.
    {
        let mut tool = sovereign_tools::SessionStateTool::new();
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_workspace_root(ws);
        }
        tools.register(Box::new(tool));
    }

    // Notes tools work regardless of indexing state.
    tools.register(Box::new(sovereign_tools::WriteNoteTool::new(Arc::clone(
        &notes,
    ))));
    {
        // Workspace optional — without it the operational-anchors
        // registry loader falls back to SOVEREIGN_WORKSPACE_DIR, the
        // ~/.svrnmesh/workspace file, then an ascent from the cwd,
        // then the compiled-in floor (read_notes.rs).
        let mut tool = sovereign_tools::ReadNotesTool::new(Arc::clone(&notes));
        if let Some(ws) = workspace_dir.clone() {
            tool = tool.with_workspace_root(ws);
        }
        tools.register(Box::new(tool));
    }
    tools.register(Box::new(sovereign_tools::DeleteNoteTool::new(Arc::clone(
        &notes,
    ))));
    tools.register(Box::new(sovereign_tools::RetireNoteTool::new(Arc::clone(
        &notes,
    ))));
    tools.register(Box::new(sovereign_tools::SessionReflectionTool::new(
        Arc::clone(&notes),
    )));

    // ATOS step verification — runs verify commands with
    // hollow/untouched gates to catch silent agent no-ops.
    tools.register(Box::new(sovereign_tools::AtosVerifyTool::new()));

    // Project context — served from `indexes/project_docs.db` if a
    // project has been init'd. Absent on a bare-setup daemon; that's
    // fine, just one fewer tool.
    #[cfg(feature = "atos")]
    if let Ok(ds) =
        corpus_engine_notes::ProjectDocsStore::open(&indexes_dir.join("project_docs.db"))
    {
        tools.register(Box::new(sovereign_tools::ProjectContextTool::new(
            Arc::new(ds),
        )));
    }

    // Doc-path checker — no state dependency.
    tools.register(Box::new(sovereign_tools::CheckDocPathsTool::new()));

    // Wikipedia on-demand fetch — operates against the catalog corpus
    // installed on this daemon. Wired here so `svrn tools call
    // wikipedia_fetch --title=…` and the MCP /mcp surface can drive
    // catalog-hit → fetch end-to-end without a live chat session.
    tools.register(Box::new(sovereign_tools::WikipediaFetchTool::new(
        Arc::clone(&engine),
    )));

    // DESIGN.md structural signals — no state dependency; the tool
    // reads the DESIGN.md path argument at call time. No
    // `with_project_root` in the daemon context because the daemon
    // doesn't know which project the caller means. ATOS-gated.
    #[cfg(feature = "atos")]
    tools.register(Box::new(sovereign_tools::DesignSignalsExtractTool::new()));

    // B:P9d — the corpus/atlas plane (corpus_store, corpus_search, atlas_gaps,
    // atlas_tensions, + the document ExtractTool). `standard_registry` dropped
    // these when the studio bundle carved out corpus-engine (B:P5); the daemon
    // still links corpus-engine, so it registers them HERE to serve them over
    // `/mcp`, letting a corpus-engine-free studio client (B:P9e) run the shipped
    // notebook / summarize workflows remotely. Each is a bare unit struct that
    // opens its corpus/atlas (or document) from disk at call time, so no engine
    // handle is threaded in. `extract` resolves its `path` on THIS host's
    // filesystem — correct for a loopback client, a clean "file not found" for a
    // remote one (see `sovereign_tools::mcp_surface::MCP_TOOLS_ALWAYS`).
    for tool in sovereign_tools::workflow_corpus_tools() {
        tools.register(tool);
    }

    // SOLVE — the daemon-hosted TDD solver (docs/specs/SOLVE_UX.md).
    // Same job table as the /v1/solve/jobs HTTP surface, so MCP
    // agents and curl sessions see the same jobs.
    tools.register(Box::new(super::solve_tools::SolveTool(Arc::clone(
        &solve_jobs,
    ))));
    tools.register(Box::new(super::solve_tools::SolveStatusTool(Arc::clone(
        &solve_jobs,
    ))));
    tools.register(Box::new(super::solve_tools::SolveCancelTool(solve_jobs)));

    tools
}

/// Merge every per-corpus `scip_graph.db` under `indexes_dir` into a
/// single in-memory graph. Same idea as `project_cmd::load_merged_graph`
/// but without the operator-facing stdout printing, since the daemon
/// runs under launchd/systemd.
pub(super) async fn build_merged_scip_graph(
    indexes_dir: &std::path::Path,
) -> corpus_engine_scip::ScipGraph {
    let merged =
        corpus_engine_scip::ScipGraph::open_in_memory("merged").expect("in-memory ScipGraph");
    let Ok(entries) = std::fs::read_dir(indexes_dir) else {
        return merged;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let scip_path = path.join("scip_graph.db");
        if !scip_path.exists() {
            continue;
        }
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("?")
            .to_string();
        match merged.import_from_path(&scip_path).await {
            Ok((syms, refs)) => {
                if syms > 0 || refs > 0 {
                    tracing::info!(
                        corpus = %name,
                        symbols = syms,
                        references = refs,
                        "merged SCIP graph from corpus"
                    );
                }
            }
            Err(e) => {
                tracing::warn!(
                    corpus = %name,
                    error = %e,
                    "could not import SCIP graph — skipping"
                );
            }
        }
    }
    merged
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn setup --fim` — one-command inline-completion onboarding.
//!
//! The manual flow this replaces is seven steps in
//! `packages/vscode-sovereign/README.md`: download a coder GGUF,
//! download an embed GGUF, hand-write a `[models.edit]` block, restart
//! the daemon, curl a completion, build a `.vsix`, install it. Every
//! step has a failure mode that surfaces minutes later as "ghost text
//! doesn't appear", with nothing to tell the operator which rung
//! broke. This module runs the same seven steps and *verifies* them,
//! stopping at the first failure with the fix.
//!
//! Two design commitments, both load-bearing:
//!
//! **Consent before mutation.** [`build_plan`] decides everything —
//! model, quant, paths, which config keys change, what gets backed up
//! — and [`print_plan`] shows it, before a single byte is downloaded
//! or written. `--yes` skips the prompt, not the plan.
//!
//! **Lean mode.** `[models].primary` and `[models.edit].path` are set
//! to the SAME file, so `ModelsSection::fast_path()` (which falls
//! back to `primary` when `fast` is unset) equals the FIM path and
//! `EmbeddedLlamaCpp::install_edit_slot` takes its alias branch — one
//! copy of Mellum2 in RAM serving both chat and completions. The
//! alternative, a dedicated pinned `fim` slot beside a separate chat
//! primary, needs 7–13 GB of headroom on top of the primary; the
//! `high` (16.3 GB primary, 20–23 GB band) and `very_high` (20.5 GB
//! primary, ≥24 GB band) tiers have ~3.5 GB. That is measured against
//! `models.toml`, not assumed — see the FIM LADDER block there.

use std::io::{self, IsTerminal as _, Write as _};
use std::path::{Path, PathBuf};
use std::time::Duration;

use sovereign_core::models_manifest::SlotConfig;
use sovereign_inference::hardware::{self, HardwareProfile, ProfileName};
use sovereign_inference::setup_planner::{
    fim_rung_for_profile, fim_slot_for_rung, hf_download_url, next_fim_rung, resolve_slot, SlotKind,
};

use crate::setup_config::{DaemonSection, DataSection, EditSection, ModelsSection, SetupConfig};

use super::download::{download_silent, download_with_progress};
use super::Opts;

/// How long to wait for the daemon to answer after a restart. A cold
/// 7–13 GB mmap warmup is 30–60s on an SSD and materially longer on
/// a spinning disk or a cold page cache; the old 30s ceiling from
/// `finish::wait_for_daemon` would report a false failure on exactly
/// the machines this command targets.
const DAEMON_READY_TIMEOUT: Duration = Duration::from_secs(300);

/// Round-trip budget for the synthetic completion. Generous because
/// the first completion after a restart also pays prompt prefill on
/// a cold KV cache.
const COMPLETION_TIMEOUT: Duration = Duration::from_secs(90);

// ─── Plan ──────────────────────────────────────────────────────────

/// Everything decided before anything is mutated. Built by
/// [`build_plan`], printed by [`print_plan`], then executed. Keeping
/// it a value (rather than a sequence of side effects) is what makes
/// the consent screen honest: the plan the operator approves is the
/// plan that runs.
struct Plan {
    profile: ProfileName,
    /// Ladder rung name, e.g. `"q6_k"`.
    rung: String,
    /// Whether `rung` came from `--quant` rather than the hardware.
    rung_overridden: bool,
    slot: SlotConfig,
    models_dir: PathBuf,
    /// Destination for the Mellum2 GGUF — the file that becomes both
    /// `primary` and `fim.path`.
    model_path: PathBuf,
    /// Embed slot to download, `None` when a usable one already
    /// exists on disk (the daemon requires an embed model, but there
    /// is no reason to re-fetch one the operator already has).
    embed_download: Option<(SlotConfig, PathBuf)>,
    embed_path: PathBuf,
    /// The config we're about to change, when one exists.
    existing: Option<ExistingConfig>,
    config_path: PathBuf,
    backup_path: PathBuf,
    data_dir: PathBuf,
    client_port: u16,
}

/// The parts of a pre-existing config the plan needs to talk about
/// honestly: what we're replacing, and whether FIM was already set up.
struct ExistingConfig {
    primary: PathBuf,
    fim_path: Option<PathBuf>,
}

impl Plan {
    /// Total bytes we intend to fetch — `0` when everything needed is
    /// already on disk, which is the re-run case and worth saying out
    /// loud rather than implying a fresh multi-GB download.
    fn download_gb(&self) -> f64 {
        let mut gb = 0.0;
        if !file_is_present(&self.model_path) {
            gb += self.slot.size_gb;
        }
        if let Some((slot, path)) = &self.embed_download {
            if !file_is_present(path) {
                gb += slot.size_gb;
            }
        }
        gb
    }

    /// True when the config already points at exactly what we'd
    /// write. Drives "already configured" phrasing so a re-run
    /// doesn't claim credit for work it didn't do.
    fn already_lean_on_this_model(&self) -> bool {
        self.existing.as_ref().is_some_and(|e| {
            e.primary == self.model_path && e.fim_path.as_deref() == Some(self.model_path.as_path())
        })
    }
}

fn file_is_present(p: &Path) -> bool {
    p.metadata().map(|m| m.len() > 0).unwrap_or(false)
}

// ─── Entry point ───────────────────────────────────────────────────

pub(super) async fn run_fim_setup(opts: &Opts) -> i32 {
    println!();
    println!("  Sovereign Setup — inline completion");
    println!("  {}", "─".repeat(54));
    println!();

    let plan = match build_plan(opts).await {
        Ok(p) => p,
        Err(msg) => {
            eprintln!("error: {msg}");
            return 1;
        }
    };

    print_plan(&plan);

    if !confirm(opts) {
        println!();
        println!("  Nothing changed.");
        return 1;
    }

    // ── Download ──────────────────────────────────────────────────
    println!();
    if let Err(e) = std::fs::create_dir_all(&plan.models_dir) {
        eprintln!("error: cannot create {}: {e}", plan.models_dir.display());
        return 1;
    }
    if let Err(code) = download_models(&plan).await {
        return code;
    }

    // ── Config ────────────────────────────────────────────────────
    println!();
    if let Err(msg) = write_config(&plan) {
        eprintln!("error: {msg}");
        return 1;
    }

    // `daemon --setup-only --fim` runs INSIDE the daemon's own
    // first-boot path — the process that would serve these probes is
    // the one waiting for us to return. Restarting or probing here
    // would deadlock against a listener that hasn't bound yet.
    if opts.wizard_only {
        println!();
        println!("  \u{2713} Config written. The daemon will load it as it boots.");
        println!();
        println!("  Verify once it's up:  svrn setup --fim --yes");
        return 0;
    }

    // ── Daemon ────────────────────────────────────────────────────
    println!();
    if let Err(msg) = bring_daemon_up(&plan).await {
        eprintln!();
        eprintln!("  \u{2717} {msg}");
        eprintln!(
            "    Config is written and correct — this is a lifecycle problem, not a FIM one."
        );
        eprintln!("    Try:  svrn daemon run        # foreground, prints the load errors live");
        return 1;
    }

    // ── Verify ────────────────────────────────────────────────────
    println!();
    println!("  Verifying...");
    let verified = match verify(plan.client_port).await {
        Ok(v) => v,
        Err(msg) => {
            eprintln!();
            eprintln!("  \u{2717} {msg}");
            return 1;
        }
    };

    // ── Editor ────────────────────────────────────────────────────
    println!();
    let editor = if opts.skip_editor {
        EditorOutcome::Skipped
    } else {
        install_extension()
    };

    print_decision(&plan, &verified, &editor);
    0
}

// ─── Plan construction ─────────────────────────────────────────────

async fn build_plan(opts: &Opts) -> Result<Plan, String> {
    eprint!("  Detecting hardware... ");
    io::stderr().flush().ok();
    let hw = tokio::task::spawn_blocking(HardwareProfile::detect)
        .await
        .map_err(|e| format!("hardware detection panicked: {e}"))?;
    let profile = hardware::select_profile(&hw);
    println!(
        "{}, {:.0}GB {}memory",
        match &hw.gpu_name {
            Some(name) => name.clone(),
            None if hw.is_unified_memory => "Apple Silicon".to_string(),
            None => "CPU-only system".to_string(),
        },
        hw.system_ram_gb(),
        if hw.is_unified_memory { "unified " } else { "" }
    );

    let rung_overridden = opts.quant.is_some();
    let rung = opts
        .quant
        .clone()
        .unwrap_or_else(|| fim_rung_for_profile(&profile).to_string());
    // `parse_args` already rejected an unknown `--quant`, so a miss
    // here means the ladder and the manifest disagree — a build-time
    // bug, not operator error. Say which, so the report is useful.
    let slot = fim_slot_for_rung(&rung).ok_or_else(|| {
        format!(
            "FIM rung '{rung}' is not in the bundled manifest — \
             models.toml and setup_planner::FIM_RUNGS are out of sync"
        )
    })?;

    // Existing config decides the data dir and port; `--data-dir`
    // overrides; otherwise the standard root.
    let existing_cfg = SetupConfig::load().ok();
    let config_path = SetupConfig::default_path();
    let data_dir = opts
        .data_dir
        .clone()
        .or_else(|| existing_cfg.as_ref().map(|c| c.data.dir.clone()))
        .unwrap_or_else(sovereign_contracts::rebrand::svrnmesh_root);
    let client_port = existing_cfg
        .as_ref()
        .map(|c| c.daemon.client_port)
        .unwrap_or_else(|| DaemonSection::default().client_port);

    let models_dir = data_dir.join("models");
    let model_path = models_dir.join(&slot.file);

    // Embed: reuse whatever the operator already has rather than
    // re-downloading. The FIM path does not use the embed slot at
    // all — the daemon simply refuses to start without one.
    let existing_embed = existing_cfg
        .as_ref()
        .map(|c| c.models.embed.clone())
        .filter(|p| file_is_present(p));
    let (embed_download, embed_path) = match existing_embed {
        Some(p) => (None, p),
        None => {
            let embed_slot = resolve_slot(&profile, SlotKind::Embed).ok_or_else(|| {
                "bundled manifest has no embed slot for this hardware".to_string()
            })?;
            let path = models_dir.join(&embed_slot.file);
            (Some((embed_slot, path.clone())), path)
        }
    };

    let existing = existing_cfg.as_ref().map(|c| ExistingConfig {
        primary: c.models.primary.clone(),
        fim_path: c.models.edit.as_ref().map(|f| f.path.clone()),
    });

    Ok(Plan {
        profile,
        rung,
        rung_overridden,
        slot,
        models_dir,
        model_path,
        embed_download,
        embed_path,
        existing,
        backup_path: config_path.with_extension("toml.pre-fim"),
        config_path,
        data_dir,
        client_port,
    })
}

// ─── Consent ───────────────────────────────────────────────────────

fn print_plan(plan: &Plan) {
    let gb = plan.download_gb();
    println!();
    println!("  Plan — nothing has changed yet");
    println!();
    println!(
        "    Model    {} {} ({:.1} GB){}",
        plan.slot.base_name,
        plan.slot.quant,
        plan.slot.size_gb,
        if plan.rung_overridden {
            "  [--quant]"
        } else {
            ""
        }
    );
    println!("    From     {}", plan.slot.hf_url);
    println!("    To       {}", plan.model_path.display());
    println!();
    println!("    Serving  lean mode — this model becomes BOTH the chat");
    println!("             primary and the completion model, one copy in RAM.");
    match &plan.existing {
        Some(_) if plan.already_on_this_edit_model() => {
            println!();
            println!(
                "    Config   {} is already set up this way;",
                plan.config_path.display()
            );
            println!("             this run re-verifies it end to end.");
        }
        Some(e) => {
            println!();
            println!("    Config   {}", plan.config_path.display());
            println!(
                "               primary      {} \u{2192} {}",
                short(&e.primary),
                short(&plan.model_path)
            );
            println!("               fast         cleared (primary serves it)");
            println!(
                "               models.edit   {} \u{2192} {}",
                e.fim_path
                    .as_deref()
                    .map(short)
                    .unwrap_or_else(|| "(unset)".into()),
                short(&plan.model_path)
            );
            println!(
                "               embed        {} ({})",
                short(&plan.embed_path),
                if plan.embed_download.is_some() {
                    "downloaded — yours is missing"
                } else {
                    "unchanged"
                }
            );
            println!(
                "             Backed up first to {}",
                plan.backup_path.display()
            );
        }
        None => {
            println!();
            println!("    Config   {} (new)", plan.config_path.display());
        }
    }
    if gb > 0.0 {
        println!();
        println!("    Download {gb:.1} GB total");
    } else {
        println!();
        println!("    Download nothing — every file is already on disk");
    }
    println!();
    println!("    Then     start (or restart) the daemon, verify a real");
    println!("             completion, install the editor extension.");
}

fn short(p: &Path) -> String {
    p.file_name()
        .map(|f| f.to_string_lossy().into_owned())
        .unwrap_or_else(|| p.display().to_string())
}

fn confirm(opts: &Opts) -> bool {
    if opts.yes {
        return true;
    }
    if !io::stdin().is_terminal() {
        eprintln!();
        eprintln!("error: not a terminal, so there's nobody to ask.");
        eprintln!("       Re-run with --yes to accept the plan above.");
        return false;
    }
    println!();
    print!("  Proceed? [Y/n] ");
    io::stdout().flush().ok();
    let mut line = String::new();
    if io::stdin().read_line(&mut line).is_err() {
        return false;
    }
    matches!(line.trim().to_ascii_lowercase().as_str(), "" | "y" | "yes")
}

// ─── Execution ─────────────────────────────────────────────────────

async fn download_models(plan: &Plan) -> Result<(), i32> {
    println!("  Downloading...");
    println!();
    let label = format!("{} {}", plan.slot.base_name, plan.slot.quant);
    if let Err(e) = download_with_progress(
        &hf_download_url(&plan.slot),
        &plan.model_path,
        &label,
        plan.slot.size_gb,
    )
    .await
    {
        eprintln!("  \u{2717} {label}: {e}");
        eprintln!();
        eprintln!("    Nothing was written to your config — re-run when the download can succeed.");
        return Err(1);
    }

    if let Some((slot, path)) = &plan.embed_download {
        match download_silent(&hf_download_url(slot), path, slot.size_gb).await {
            Ok(()) => println!("    \u{2713} {} (embedder)", slot.file),
            Err(e) => {
                eprintln!("  \u{2717} embedder {}: {e}", slot.file);
                eprintln!();
                eprintln!("    The daemon requires an embed model to start, so this is fatal.");
                eprintln!("    Nothing was written to your config.");
                return Err(1);
            }
        }
    }
    Ok(())
}

fn write_config(plan: &Plan) -> Result<(), String> {
    let fim = EditSection {
        path: plan.model_path.clone(),
        // Defaults are deliberate, not laziness: 4096 ctx / 48 tokens
        // / temp 0.2 are the FIM defaults documented on `EditSection`,
        // and writing them explicitly would freeze today's values
        // into every user's config where a later tuning pass could
        // never reach them.
        context_size: None,
        max_tokens: None,
        temperature: None,
        max_prefix_chars: None,
        max_suffix_chars: None,
        next_edit_format: None,
    };

    let mut cfg = match SetupConfig::load() {
        Ok(existing) => {
            // Back up BEFORE mutating. Lean mode replaces the chat
            // primary; an operator who decides tomorrow that they
            // want their 35B back must not have to reconstruct the
            // rest of their config from memory.
            std::fs::copy(&plan.config_path, &plan.backup_path).map_err(|e| {
                format!(
                    "could not back up {} to {}: {e}",
                    plan.config_path.display(),
                    plan.backup_path.display()
                )
            })?;
            println!("    \u{2713} Backed up {}", plan.backup_path.display());
            existing
        }
        Err(_) => SetupConfig {
            compute: Default::default(),
            search: Default::default(),
            models: ModelsSection {
                primary: plan.model_path.clone(),
                fast: None,
                embed: plan.embed_path.clone(),
                code: None,
                context_size: None,
                fast_context_size: None,
                extra: std::collections::BTreeMap::new(),
                max_extras_memory_gb: None,
                primary_pool: None,
                edit: None,
            },
            daemon: DaemonSection::default(),
            data: DataSection {
                dir: plan.data_dir.clone(),
            },
            watched_folders: Default::default(),
            memory: Default::default(),
            iroh: Default::default(),
            shared_model: Default::default(),
            discovery: Default::default(),
            mcp_servers: Vec::new(),
        },
    };

    cfg.models.primary = plan.model_path.clone();
    // Clearing `fast` is what puts the daemon in alias mode:
    // `fast_path()` falls back to `primary`, which now equals
    // `fim.path`, so `install_edit_slot` serves completions from the
    // resident fast slot instead of loading a second copy. Leaving a
    // stale `fast` here would quietly cost a whole extra model.
    cfg.models.fast = None;
    cfg.models.embed = plan.embed_path.clone();
    cfg.models.edit = Some(fim);

    let path = cfg.save()?;
    println!("    \u{2713} Wrote {}", path.display());
    Ok(())
}

/// Get the daemon running the config we just wrote.
///
/// `restart` is NOT the universal answer here. With no daemon running
/// and no service registered, `restart_daemon` = stop + start, and its
/// stop leg falls through to the service manager, fails, and returns
/// non-zero *without ever starting anything* — which is exactly the
/// fresh-install case this command is built for. So: probe first,
/// restart only what is actually up.
async fn bring_daemon_up(plan: &Plan) -> Result<(), String> {
    let running =
        daemon_answers(plan.client_port).await || crate::daemon_cmd::read_daemon_pid().is_some();
    let verb = if running { "Restarting" } else { "Starting" };
    println!(
        "  {verb} the daemon (cold load of a {:.1} GB model takes a minute)...",
        plan.slot.size_gb
    );
    // No `--rpc-worker` here: the FIM setup path is configuring THIS node's own
    // completion slot, not offering its GPU to the mesh. Whatever the operator's
    // config says about serving still applies via the role translation.
    let rc = if running {
        crate::daemon_cmd::lifecycle::restart_daemon(&[]).await
    } else {
        crate::daemon_cmd::lifecycle::start_daemon(&[]).await
    };
    if rc == 0 {
        return Ok(());
    }
    Err(format!(
        "the daemon did not come up ({} exited {rc}).",
        verb.to_lowercase()
    ))
}

/// Cheap liveness probe — is anything serving on the client port?
async fn daemon_answers(port: u16) -> bool {
    let Ok(client) = reqwest::Client::builder()
        .timeout(Duration::from_secs(2))
        .build()
    else {
        return false;
    };
    client
        .get(format!("http://127.0.0.1:{port}/v1/models"))
        .send()
        .await
        .map(|r| r.status().is_success())
        .unwrap_or(false)
}

// ─── Verification ──────────────────────────────────────────────────

/// What the three rungs proved, for the final banner.
struct Verified {
    slot: String,
    model_id: String,
    /// `None` when this model's vocab carries no FIM markers — it
    /// serves next-edit but `/v1/completions` 503s. A supported
    /// arrangement, so it is reported rather than treated as a probe
    /// failure.
    fim_style: Option<String>,
    aliased_to_fast: bool,
    sample: String,
    ttft_ms: Option<u64>,
}

/// The same ladder the extension's `Diagnose Completion Setup`
/// command walks — daemon reachable, FIM slot live, real completion
/// round-trips — run here so `--fim` cannot report success on a
/// daemon that would 503 on the first keystroke.
async fn verify(port: u16) -> Result<Verified, String> {
    let client = reqwest::Client::builder()
        .timeout(COMPLETION_TIMEOUT)
        .build()
        .map_err(|e| format!("could not build an http client: {e}"))?;
    let base = format!("http://127.0.0.1:{port}");

    // 1. Daemon reachable.
    let deadline = std::time::Instant::now() + DAEMON_READY_TIMEOUT;
    let models_url = format!("{base}/v1/models");
    let mut up = false;
    while std::time::Instant::now() < deadline {
        if client
            .get(&models_url)
            .timeout(Duration::from_secs(3))
            .send()
            .await
            .map(|r| r.status().is_success())
            .unwrap_or(false)
        {
            up = true;
            break;
        }
        tokio::time::sleep(Duration::from_millis(750)).await;
    }
    if !up {
        return Err(format!(
            "daemon never answered on :{port} within {}s.\n    \
             The config is written; this is a startup failure.\n    \
             Run `svrn daemon run` to watch the load errors live.",
            DAEMON_READY_TIMEOUT.as_secs()
        ));
    }
    println!("    \u{2713} daemon reachable on :{port}");

    // 2. FIM slot installed. A null here means the marker probe
    //    refused the model — the one failure this whole command
    //    exists to make legible.
    let status: serde_json::Value = client
        .get(format!("{base}/status"))
        .send()
        .await
        .map_err(|e| format!("GET /status failed: {e}"))?
        .json()
        .await
        .map_err(|e| format!("GET /status returned unparseable JSON: {e}"))?;
    // Prefer the canonical key; fall back to the deprecated `fim`
    // mirror so this verification still works against a daemon binary
    // older than the lane split. The mirror is scheduled for removal —
    // when it goes, this fallback goes with it.
    let edit = status
        .pointer("/inference/edit")
        .or_else(|| status.pointer("/inference/fim"))
        .filter(|v| !v.is_null())
        .ok_or_else(|| {
            "the daemon is up but reports no editing slot (`inference.edit` is\n    \
             null). Check the daemon log's [edit_slot] lines; they name the model\n    \
             and the reason."
                .to_string()
        })?;
    let str_at = |k: &str| {
        edit.get(k)
            .and_then(|v| v.as_str())
            .unwrap_or("?")
            .to_string()
    };
    let aliased_to_fast = edit
        .get("aliased_to_fast")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let (slot, model_id) = (str_at("slot"), str_at("model_id"));
    // `fim_style` is now absent when the model carries no FIM markers.
    // That is a real, supported arrangement — next-edit serves and
    // `/v1/completions` 503s — so report it as such rather than
    // printing "?" and letting the operator assume a broken probe.
    match edit.get("fim_style").and_then(|v| v.as_str()) {
        Some(style) => {
            println!("    \u{2713} FIM slot live — {model_id} ({style}) on slot '{slot}'")
        }
        None => {
            println!("    \u{26a0} {model_id} on slot '{slot}' serves next-edit but NOT FIM —");
            println!("      its tokenizer carries no FIM markers, so /v1/completions will");
            println!("      503. Point [models.edit].path at a coder GGUF (Mellum2,");
            println!("      Qwen2.5-Coder) if you need inline completion.");
        }
    }
    if !aliased_to_fast {
        // Not fatal — completions work either way — but it means the
        // lean-mode invariant broke and the operator is paying for a
        // second resident copy without having asked to.
        println!("    \u{26a0} serving from a DEDICATED slot, not the shared fast slot —");
        println!("      lean mode didn't take. Two copies of the model are resident.");
    }

    // 3. A real completion. The synthetic case is deliberately one
    //    the model cannot get "right" by echoing: the answer has to
    //    come from the middle.
    let body = serde_json::json!({
        "prefix": "fn fibonacci(n: u32) -> u32 {\n    match n {\n        0 => 0,\n        1 => 1,\n        _ => ",
        "suffix": "\n    }\n}\n",
        "path": "probe.rs",
        "language": "rust",
        "debug": true,
    });
    let resp = client
        .post(format!("{base}/v1/completions"))
        .json(&body)
        .send()
        .await
        .map_err(|e| format!("POST /v1/completions failed: {e}"))?;
    let code = resp.status();
    let json: serde_json::Value = resp
        .json()
        .await
        .map_err(|e| format!("POST /v1/completions returned unparseable JSON: {e}"))?;
    if !code.is_success() {
        return Err(format!(
            "POST /v1/completions returned {code}: {}",
            json.get("error")
                .map(|e| e.to_string())
                .unwrap_or_else(|| json.to_string())
        ));
    }
    let text = json
        .pointer("/choices/0/text")
        .and_then(|v| v.as_str())
        .unwrap_or_default()
        .to_string();
    let ttft_ms = json
        .pointer("/sovereign_debug/timings_ms/ttft")
        .and_then(|v| v.as_u64());
    if text.trim().is_empty() {
        return Err(format!(
            "the completion round-tripped but came back empty \
             (stop_rule={}).\n    The slot is live, so this is a sampling / stop-rule \
             problem rather than a setup one.",
            json.pointer("/sovereign_debug/stop_rule")
                .and_then(|v| v.as_str())
                .unwrap_or("?")
        ));
    }
    println!(
        "    \u{2713} completion round-tripped ({} chars{})",
        text.len(),
        ttft_ms.map(|t| format!(", ttft {t}ms")).unwrap_or_default()
    );

    Ok(Verified {
        slot,
        model_id,
        fim_style: edit
            .get("fim_style")
            .and_then(|v| v.as_str())
            .map(str::to_string),
        aliased_to_fast,
        sample: text.lines().next().unwrap_or("").trim().to_string(),
        ttft_ms,
    })
}

// ─── Editor extension ──────────────────────────────────────────────

/// Where a user without a source checkout gets the `.vsix`. The extension
/// ships on the public shelf under its own `vscode-v*` tag stream (see
/// RELEASING.md). Same shelf as `update_cmd::REPO` — keep them in step.
///
/// This path matters more than it looks: anyone who installed from the CLI
/// tarball has no `packages/vscode-sovereign` to build from, so this banner
/// is the *only* instruction they get. It named a tag prefix that never
/// existed (`svrn-fim-*`) until 2026-07-29.
///
/// Deliberately the unfiltered list. GitHub's `?q=tag:vscode-v` releases
/// filter returns HTTP 200 with the release absent from the body (verified
/// 2026-07-29), so a "helpful" filtered link is an empty page — worse than
/// a list the reader can scan. There is no per-prefix `latest` pointer
/// either; `/releases/latest` is repo-global and belongs to the desktop app.
const VSIX_RELEASES_URL: &str = "https://github.com/alexsbryan/svrnmesh-releases/releases";

enum EditorOutcome {
    Installed {
        editor: String,
    },
    /// No editor CLI on PATH, or no extension sources to build from.
    /// Carries the reason so the banner can say what to do instead.
    Unavailable(String),
    Skipped,
}

/// Install the `svrn fim` extension into whichever VS Code-family
/// editor is on PATH. Best-effort by design: a failure here leaves a
/// fully working daemon, so it degrades to an instruction rather than
/// failing the command.
fn install_extension() -> EditorOutcome {
    let Some(editor) = find_editor() else {
        return EditorOutcome::Unavailable(
            "no VS Code-family CLI on PATH (looked for code, cursor, windsurf, codium)".into(),
        );
    };
    let Some(ext_dir) = find_extension_dir() else {
        return EditorOutcome::Unavailable(
            "extension sources not found (this build isn't running from a repo checkout)".into(),
        );
    };

    println!("  Installing the editor extension ({editor})...");

    let vsix = match existing_vsix(&ext_dir).or_else(|| build_vsix(&ext_dir)) {
        Some(v) => v,
        None => {
            return EditorOutcome::Unavailable(format!(
                "could not produce a .vsix in {}",
                ext_dir.display()
            ))
        }
    };

    match std::process::Command::new(&editor)
        .arg("--install-extension")
        .arg(&vsix)
        .arg("--force")
        .output()
    {
        Ok(out) if out.status.success() => {
            println!("    \u{2713} installed into {editor}");
            EditorOutcome::Installed { editor }
        }
        Ok(out) => EditorOutcome::Unavailable(format!(
            "{editor} --install-extension failed: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        )),
        Err(e) => EditorOutcome::Unavailable(format!("could not run {editor}: {e}")),
    }
}

fn find_editor() -> Option<String> {
    ["code", "cursor", "windsurf", "codium"]
        .into_iter()
        .find(|c| on_path(c))
        .map(str::to_string)
}

/// PATH scan rather than shelling out to `which` — one less external
/// dependency on a path that runs during onboarding, when the least
/// is known about the machine.
fn on_path(cmd: &str) -> bool {
    let Some(path) = std::env::var_os("PATH") else {
        return false;
    };
    let candidates: &[&str] = if cfg!(windows) {
        &[".cmd", ".exe", ""]
    } else {
        &[""]
    };
    std::env::split_paths(&path).any(|dir| {
        candidates
            .iter()
            .any(|ext| dir.join(format!("{cmd}{ext}")).is_file())
    })
}

/// Locate `packages/vscode-sovereign`. Checked against the working
/// directory first (the common case: an operator in the repo) and
/// then relative to the running binary, which covers
/// `target/debug/sovereign-cli-daemon` invoked from elsewhere.
fn find_extension_dir() -> Option<PathBuf> {
    const REL: &str = "packages/vscode-sovereign";
    let mut roots: Vec<PathBuf> = Vec::new();
    if let Ok(cwd) = std::env::current_dir() {
        roots.extend(cwd.ancestors().map(Path::to_path_buf));
    }
    if let Ok(exe) = std::env::current_exe() {
        roots.extend(exe.ancestors().map(Path::to_path_buf));
    }
    roots
        .into_iter()
        .map(|r| r.join(REL))
        .find(|p| p.join("package.json").is_file())
}

fn existing_vsix(dir: &Path) -> Option<PathBuf> {
    let mut found: Option<(std::time::SystemTime, PathBuf)> = None;
    for entry in std::fs::read_dir(dir).ok()?.flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("vsix") {
            continue;
        }
        let modified = entry.metadata().and_then(|m| m.modified()).ok()?;
        if found.as_ref().is_none_or(|(t, _)| modified > *t) {
            found = Some((modified, path));
        }
    }
    found.map(|(_, p)| p)
}

/// `npm install && npm run package`. Slow (tens of seconds) and
/// noisy, so it is announced; silent multi-minute stalls during
/// onboarding are how people conclude a tool has hung.
fn build_vsix(dir: &Path) -> Option<PathBuf> {
    if !on_path("npm") {
        return None;
    }
    println!("    building the extension (npm — this takes a moment)...");
    for args in [["install"].as_slice(), ["run", "package"].as_slice()] {
        let out = std::process::Command::new("npm")
            .args(args)
            .current_dir(dir)
            .output()
            .ok()?;
        if !out.status.success() {
            eprintln!(
                "    npm {} failed: {}",
                args.join(" "),
                String::from_utf8_lossy(&out.stderr).trim()
            );
            return None;
        }
    }
    existing_vsix(dir)
}

// ─── Final banner ──────────────────────────────────────────────────

/// The decision, the escape hatch, and the one upgrade worth trying —
/// in that order, and short. An operator who reads nothing else
/// should still know what changed on their machine and how to undo it.
fn print_decision(plan: &Plan, v: &Verified, editor: &EditorOutcome) {
    println!();
    println!("  {}", "─".repeat(54));
    println!("  \u{2713} Inline completion is live");
    println!();
    println!("  What we decided");
    println!(
        "    {} on {} hardware \u{2014} {}",
        v.model_id,
        profile_label(&plan.profile),
        if plan.rung_overridden {
            format!("{} because you asked for it", plan.slot.quant)
        } else {
            format!("{} picked for your hardware", plan.slot.quant)
        }
    );
    if v.aliased_to_fast {
        println!(
            "    Lean mode: it serves chat AND completions from slot '{}' \u{2014}",
            v.slot
        );
        println!("    one copy in RAM. Your previous chat model is no longer loaded.");
    } else {
        println!(
            "    Dedicated slot '{}' \u{2014} a second model is resident.",
            v.slot
        );
    }
    match &v.fim_style {
        Some(style) => {
            println!("    Style {style} \u{2014} probed from the vocab, not assumed.")
        }
        None => println!(
            "    No FIM markers in the vocab \u{2014} next-edit serves, \
             /v1/completions 503s."
        ),
    }
    if !v.sample.is_empty() {
        println!(
            "    Proof: it completed `_ =>` with `{}`{}.",
            truncate(&v.sample, 44),
            v.ttft_ms.map(|t| format!(" in {t}ms")).unwrap_or_default()
        );
    }

    println!();
    println!("  Swap the model");
    println!("    svrn setup --fim --quant <rung>     # mxfp4_moe | q4_k_m | q6_k | q8_0");
    // Deliberately NOT `svrn model set primary <file>`: in lean mode
    // primary and models.edit.path must move together, and `model set`
    // touches only one of them. A half-applied swap loads two models.
    println!("    (both primary and models.edit move together \u{2014} that's what keeps it lean)");
    if let Some((next_rung, next_slot)) = next_fim_rung(&plan.rung) {
        println!();
        println!("  Worth trying next");
        println!(
            "    svrn setup --fim --quant {next_rung}      # {} {} \u{2014} {:.1} GB, +{:.1} GB",
            next_slot.base_name,
            next_slot.quant,
            next_slot.size_gb,
            next_slot.size_gb - plan.slot.size_gb
        );
        println!("    Better completions if you have the memory; same model, finer quant.");
    }

    if plan.existing.is_some() {
        println!();
        println!("  Undo");
        println!(
            "    cp {} {}  &&  svrn daemon restart",
            plan.backup_path.display(),
            plan.config_path.display()
        );
    }

    println!();
    match editor {
        EditorOutcome::Installed { editor } => {
            println!("  Next: reload {editor}, open a code file, pause after a line.");
            println!("        Ghost text appears; Tab accepts. The status bar shows the model.");
        }
        EditorOutcome::Skipped => {
            println!("  Editor: skipped (--skip-editor). The daemon is serving completions");
            println!(
                "          at http://127.0.0.1:{}/v1/completions.",
                plan.client_port
            );
        }
        EditorOutcome::Unavailable(why) => {
            println!("  Editor: not installed \u{2014} {why}.");
            println!("          Completions are still being served at");
            println!(
                "            http://127.0.0.1:{}/v1/completions",
                plan.client_port
            );
            println!("          To get the extension: open the release shelf, pick the newest");
            println!("          `vscode-v*` release, download its `sovereign-fim-*.vsix`, then:");
            println!("            {VSIX_RELEASES_URL}");
            println!("            code --install-extension <downloaded>.vsix");
            println!("          From a source checkout you can build it instead:");
            println!("            cd packages/vscode-sovereign && npm install && npm run package");
        }
    }
}

fn profile_label(p: &ProfileName) -> &'static str {
    match p {
        ProfileName::CpuOnly => "cpu-only",
        ProfileName::LowMem => "low-memory",
        ProfileName::Default => "default-tier",
        ProfileName::High => "high-tier",
        ProfileName::VeryHigh => "very-high-tier",
    }
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        return s.to_string();
    }
    let head: String = s.chars().take(max.saturating_sub(1)).collect();
    format!("{head}\u{2026}")
}

