            rung: "q6_k".into(),
            rung_overridden: false,
            slot: slot("m.gguf", 10.88),
            models_dir: model.parent().unwrap().to_path_buf(),
            model_path: model,
            embed_download: None,
            embed_path: PathBuf::from("/models/embed.gguf"),
            existing,
            config_path: PathBuf::from("/cfg/config.toml"),
            backup_path: PathBuf::from("/cfg/config.toml.pre-fim"),
            data_dir: PathBuf::from("/cfg"),
            client_port: 9741,
        }
    }

    /// A re-run against files already on disk must not claim it is
    /// about to download 10.88 GB — the consent screen is only worth
    /// anything if its numbers are true.
    #[test]
    fn download_gb_is_zero_when_the_model_is_already_present() {
        let tmp = tempfile::tempdir().unwrap();
        let model = tmp.path().join("m.gguf");
        std::fs::write(&model, b"GGUF").unwrap();
        let plan = plan_with(model, None);
        assert_eq!(plan.download_gb(), 0.0);
    }

    #[test]
    fn download_gb_counts_a_missing_model() {
        let tmp = tempfile::tempdir().unwrap();
        let plan = plan_with(tmp.path().join("absent.gguf"), None);
        assert!((plan.download_gb() - 10.88).abs() < f64::EPSILON);
    }

    #[test]
    fn download_gb_counts_a_missing_embed_too() {
        let tmp = tempfile::tempdir().unwrap();
        let model = tmp.path().join("m.gguf");
        std::fs::write(&model, b"GGUF").unwrap();
        let mut plan = plan_with(model, None);
        let embed = tmp.path().join("e.gguf");
        plan.embed_download = Some((slot("e.gguf", 0.6), embed));
        assert!((plan.download_gb() - 0.6).abs() < 1e-9);
    }

    /// An empty file is not a model. `download_gguf` resumes from a
    /// `.part`, but a zero-byte final path is the signature of an
    /// interrupted move and must count as absent.
    #[test]
    fn zero_byte_files_count_as_absent() {
        let tmp = tempfile::tempdir().unwrap();
        let model = tmp.path().join("m.gguf");
        std::fs::write(&model, b"").unwrap();
        assert!(!file_is_present(&model));
    }

    #[test]
    fn already_configured_looks_only_at_the_edit_path() {
        let model = PathBuf::from("/models/m.gguf");
        let other = PathBuf::from("/models/other.gguf");

        let matching = plan_with(
            model.clone(),
            Some(ExistingConfig {
                primary: model.clone(),
                fim_path: Some(model.clone()),
            }),
        );
        assert!(matching.already_lean_on_this_model());

        // primary matches but FIM was never configured
        let half = plan_with(
            model.clone(),
            Some(ExistingConfig {
                primary: model.clone(),
                fim_path: None,
            }),
        );
        assert!(!half.already_lean_on_this_model());

        // FIM points somewhere else — the dedicated-slot arrangement
        let dedicated = plan_with(
            model.clone(),
            Some(ExistingConfig {
                primary: other,
                fim_path: Some(model),
            }),
        );
        assert!(!dedicated.already_lean_on_this_model());

        assert!(!plan_with(PathBuf::from("/models/m.gguf"), None).already_lean_on_this_model());
    }

    #[test]
    fn backup_path_sits_beside_the_config() {
        let cfg = PathBuf::from("/home/u/.sovereign/config.toml");
        assert_eq!(
            cfg.with_extension("toml.pre-fim"),
            PathBuf::from("/home/u/.sovereign/config.toml.pre-fim")
        );
    }

    #[test]
    fn truncate_keeps_short_strings_whole() {
        assert_eq!(truncate("abc", 10), "abc");
        assert_eq!(truncate("abcdefghij", 5), "abcd\u{2026}");
    }

    #[test]
    fn on_path_finds_a_real_executable_dir_entry() {
        // `sh` exists on every unix host the daemon supports; on
        // Windows the candidate-extension branch is what matters and
        // this assertion would be about a different binary, so scope
        // the test to unix.
        #[cfg(unix)]
        assert!(on_path("sh"), "expected sh on PATH");
        assert!(!on_path("definitely-not-a-real-binary-9f3a"));
    }

    #[test]
    fn existing_vsix_picks_the_newest() {
        let tmp = tempfile::tempdir().unwrap();
        let old = tmp.path().join("sovereign-fim-0.0.1.vsix");
        let new = tmp.path().join("sovereign-fim-0.1.0.vsix");
        std::fs::write(&old, b"old").unwrap();
        std::thread::sleep(std::time::Duration::from_millis(20));
        std::fs::write(&new, b"new").unwrap();
        std::fs::write(tmp.path().join("notes.txt"), b"ignore me").unwrap();
        assert_eq!(existing_vsix(tmp.path()), Some(new));
    }

    /// The no-source-checkout banner is the only install instruction a
    /// tarball user ever sees, and for months it pointed at a tag prefix
    /// (`svrn-fim-*`) that no release has ever used. Nothing failed loudly
    /// — the text just sent people hunting. Pin the shelf so a future edit
    /// can't quietly reintroduce a dead pointer.
    #[test]
    fn vsix_releases_url_points_at_the_public_shelf() {
        assert!(
            VSIX_RELEASES_URL.starts_with("https://github.com/alexsbryan/svrnmesh-releases"),
            "the .vsix must be sourced from the public shelf, not the private source repo: {VSIX_RELEASES_URL}"
        );
        assert!(
            VSIX_RELEASES_URL.ends_with("/releases"),
            "must be the unfiltered release list — GitHub's ?q=tag: filter renders an empty page: {VSIX_RELEASES_URL}"
        );
        assert!(
            !VSIX_RELEASES_URL.contains("svrn-fim"),
            "`svrn-fim-*` is not a real tag stream; the extension ships under `vscode-v*`"
        );
    }

    #[test]
    fn existing_vsix_is_none_when_there_are_none() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("package.json"), b"{}").unwrap();
        assert_eq!(existing_vsix(tmp.path()), None);
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! opencode config install/merge — extracted from `setup_cmd` (§3.2).
//! Writes or merges Sovereign's MCP server + provider into the user's
//! `~/.config/opencode/opencode.json` without clobbering other entries.

use std::path::{Path, PathBuf};

/// Outcome of attempting to install / update the opencode config.
/// Carries the path so the banner prints something actionable
/// instead of "ok".
#[derive(Debug)]
pub(super) enum OpencodeInstall {
    /// File didn't exist; we created it from scratch.
    Created(PathBuf),
    /// File existed; we merged Sovereign's MCP server + provider
    /// into the existing JSON without disturbing the user's other
    /// providers, models, skills, etc.
    MergedInto(PathBuf),
    /// File existed and already contained an entry pointing at our
    /// daemon — nothing to do.
    AlreadyConfigured(PathBuf),
}

fn opencode_config_path() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("opencode")
        .join("opencode.json")
}

/// Render the JSON snippet we'd write — used both to seed a new file
/// and to print as a fallback when writing fails.
pub(super) fn opencode_config_snippet(client_port: u16) -> String {
    let value = serde_json::json!({
        "mcp": {
            "servers": {
                "sovereign": {
                    "type": "http",
                    "url": format!("http://localhost:{client_port}/mcp")
                }
            }
        },
        "provider": {
            "commonwealth": {
                "npm": "@ai-sdk/openai-compatible",
                "options": {
                    "baseURL": format!("http://localhost:{client_port}/v1")
                }
            }
        }
    });
    serde_json::to_string_pretty(&value).unwrap_or_else(|_| String::new())
}

/// Install or merge our opencode entries into `~/.config/opencode/opencode.json`.
///
/// Behaviour matrix (decided so a re-run of `svrn setup` is
/// always safe and never clobbers third-party config):
///   - file missing               → create with our entries only.
///   - file present, no overlap   → merge: add `mcp.sovereign` and
///                                  `provider.commonwealth`, leave
///                                  leave everything else untouched.
///   - file present, our entries  → noop, return `AlreadyConfigured`.
///   - file present, parse error  → bail (the user has invalid JSON;
///                                  we shouldn't try to "fix" it).
pub(super) fn install_opencode_config(client_port: u16) -> Result<OpencodeInstall, String> {
    install_opencode_config_at(&opencode_config_path(), client_port)
}

pub(super) fn install_opencode_config_at(
    path: &Path,
    client_port: u16,
) -> Result<OpencodeInstall, String> {
    // Fresh install — easy path.
    if !path.exists() {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)
                .map_err(|e| format!("create {}: {e}", parent.display()))?;
        }
        std::fs::write(path, opencode_config_snippet(client_port))
            .map_err(|e| format!("write {}: {e}", path.display()))?;
        return Ok(OpencodeInstall::Created(path.to_path_buf()));
    }

    // Existing file — parse, merge our keys, write back.
    let raw = std::fs::read_to_string(path).map_err(|e| format!("read {}: {e}", path.display()))?;
    let mut cfg: serde_json::Value =
        serde_json::from_str(&raw).map_err(|e| format!("parse {}: {e}", path.display()))?;
    if !cfg.is_object() {
        return Err(format!(
            "{} is not a JSON object — refusing to overwrite",
            path.display()
        ));
    }

    let mcp_url = format!("http://localhost:{client_port}/mcp");
    let base_url = format!("http://localhost:{client_port}/v1");

    // Detect already-configured to give the user a "nothing to do"
    // banner instead of pretending we did work.
    let same_mcp = cfg
        .pointer("/mcp/servers/sovereign/url")
        .and_then(|v| v.as_str())
        == Some(mcp_url.as_str());
    let same_provider = cfg
        .pointer("/provider/commonwealth/options/baseURL")
        .and_then(|v| v.as_str())
        == Some(base_url.as_str());
    if same_mcp && same_provider {
        return Ok(OpencodeInstall::AlreadyConfigured(path.to_path_buf()));
    }

    // Walk into mcp.servers.sovereign and provider.commonwealth,
    // creating intermediate objects only as needed. Other keys at
    // each level are preserved verbatim.
    let obj = cfg.as_object_mut().expect("verified above");
    let mcp = obj
        .entry("mcp".to_string())
        .or_insert_with(|| serde_json::json!({}));
    let mcp_obj = mcp
        .as_object_mut()
        .ok_or_else(|| "`mcp` is not an object".to_string())?;
    let servers = mcp_obj
        .entry("servers".to_string())
        .or_insert_with(|| serde_json::json!({}));
    let servers_obj = servers
        .as_object_mut()
        .ok_or_else(|| "`mcp.servers` is not an object".to_string())?;
    servers_obj.insert(
        "sovereign".to_string(),
        serde_json::json!({ "type": "http", "url": mcp_url }),
    );

    let provider = obj
        .entry("provider".to_string())
        .or_insert_with(|| serde_json::json!({}));
    let provider_obj = provider
        .as_object_mut()
        .ok_or_else(|| "`provider` is not an object".to_string())?;
    provider_obj.insert(
        "commonwealth".to_string(),
        serde_json::json!({
            "npm": "@ai-sdk/openai-compatible",
            "options": { "baseURL": base_url }
        }),
    );

    let pretty =
        serde_json::to_string_pretty(&cfg).map_err(|e| format!("serialize merged config: {e}"))?;
    std::fs::write(path, pretty).map_err(|e| format!("write {}: {e}", path.display()))?;
    Ok(OpencodeInstall::MergedInto(path.to_path_buf()))
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Self-healing supervisor for the lint/test watcher coordinator.
//!
//! ## Why this exists
//!
//! The daemon used to start the [`WatcherCoordinator`] once and hold its
//! handle for the process lifetime. If the coordinator's loop task
//! panicked, or the OS `notify` watcher died, nothing noticed — the
//! daemon's one-shot `watcher_active` bool stayed `true` and the
//! `lint_status`/`test_status` tools kept serving an increasingly stale
//! result while asserting the watcher was live. The watcher "silently
//! went stale."
//!
//! The supervisor closes that gap from the other side of the
//! [`WatcherHeartbeat`]: it owns the coordinator handle, polls liveness
//! on an interval (the loop task finished, OR the heartbeat stopped
//! advancing), and rebuilds + restarts the coordinator when it finds it
//! dead. The same heartbeat the tools read for honesty, the supervisor
//! reads for recovery — one signal, two consumers.
//!
//! Restart is bounded by exponential backoff so a persistently-failing
//! start (e.g. a broken watch root) can't become a hot loop; between
//! attempts the heartbeat stays stale, so the tools honestly report
//! `watcher_dead` and callers fall back to a direct `cargo` run.

use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;

use corpus_engine::{BackgroundWatcher, CoordinatorHandle, WatcherCoordinator, WatcherHeartbeat};
use tokio::task::JoinHandle;

/// How often the monitor re-checks coordinator liveness.
const CHECK_INTERVAL: Duration = Duration::from_secs(15);

/// The monitor treats the coordinator as dead when the heartbeat hasn't
/// advanced within this window. Deliberately wider than the status
/// tools' 30s liveness window so the supervisor only acts on a
/// genuinely-stuck loop, never a merely-slow one — and so the tools flip
/// to `watcher_dead` *before* the supervisor restarts, never after.
const RESTART_STALE_WINDOW_SECS: u64 = 60;

/// Backoff bounds for restart attempts.
const INITIAL_BACKOFF: Duration = Duration::from_secs(2);
const MAX_BACKOFF: Duration = Duration::from_secs(120);

/// Owns everything needed to (re)build a coordinator so the monitor can
/// restart it without the daemon re-deriving the inputs.
pub struct WatcherSupervisor {
    watchers: Vec<Arc<dyn BackgroundWatcher>>,
    watch_paths: Vec<PathBuf>,
    debounce_ms: u64,
    heartbeat: Arc<WatcherHeartbeat>,
}

impl WatcherSupervisor {
    pub fn new(
        watchers: Vec<Arc<dyn BackgroundWatcher>>,
        watch_paths: Vec<PathBuf>,
        debounce_ms: u64,
        heartbeat: Arc<WatcherHeartbeat>,
    ) -> Self {
        Self {
            watchers,
            watch_paths,
            debounce_ms,
            heartbeat,
        }
    }

    /// Build and start one coordinator instance, sharing the supervisor's
    /// heartbeat so both this monitor and the status tools observe the
    /// same liveness.
    async fn start_once(&self) -> corpus_engine_watchers::Result<CoordinatorHandle> {
        let mut coordinator =
            WatcherCoordinator::new(self.debounce_ms).with_heartbeat(Arc::clone(&self.heartbeat));
        for w in &self.watchers {
            coordinator.register(Arc::clone(w));
        }
        coordinator.start(self.watch_paths.clone()).await
    }

    /// True iff `handle` is both running and stamping its heartbeat. A
    /// finished task is the fast signal for a panicked loop; a frozen
    /// heartbeat catches a loop that's alive-but-wedged.
    fn is_healthy(&self, handle: &CoordinatorHandle) -> bool {
        handle.is_alive() && self.heartbeat.is_live(RESTART_STALE_WINDOW_SECS)
    }

    /// Start the coordinator and spawn the monitor task. The returned
    /// [`JoinHandle`] must be held for the daemon's lifetime: dropping it
    /// aborts the monitor, which drops the live `CoordinatorHandle` and
    /// shuts the watcher down. Returns `None` only if there is nothing to
    /// watch (no registered watchers / no paths).
    pub fn spawn(self) -> Option<JoinHandle<()>> {
        if self.watchers.is_empty() || self.watch_paths.is_empty() {
            return None;
        }
        Some(tokio::spawn(async move {
            self.run().await;
        }))
    }

    async fn run(self) {
        // `None` means "no live coordinator right now" — the loop below
        // (re)starts it. This unifies cold start and restart-after-death.
        let mut current: Option<CoordinatorHandle> = None;
        let mut backoff = INITIAL_BACKOFF;

        loop {
            let needs_start = match &current {
                None => true,
                Some(h) => !self.is_healthy(h),
            };

            if needs_start {
                if current.is_some() {
                    tracing::error!(
                        "watcher coordinator is not healthy (task finished or heartbeat \
                         stale > {RESTART_STALE_WINDOW_SECS}s) — restarting"
                    );
                    // Drop the dead/wedged handle: its Drop aborts the old
                    // task and releases the notify watcher before we
                    // build a fresh one.
                    current = None;
                }
                match self.start_once().await {
                    Ok(handle) => {
                        tracing::info!(
                            watchers = self.watchers.len(),
                            "watcher coordinator (re)started by supervisor"
                        );
                        current = Some(handle);
                        backoff = INITIAL_BACKOFF;
                    }
                    Err(e) => {
                        tracing::error!(
                            error = %e,
                            backoff_secs = backoff.as_secs(),
                            "watcher coordinator start failed; retrying after backoff \
                             (status tools will report watcher_dead meanwhile)"
                        );
                        tokio::time::sleep(backoff).await;
                        backoff = (backoff * 2).min(MAX_BACKOFF);
                        continue;
                    }
                }
            }

            tokio::time::sleep(CHECK_INTERVAL).await;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use async_trait::async_trait;
    use corpus_engine_watchers::WatcherStatus;
    use std::path::Path;
    use std::sync::atomic::{AtomicUsize, Ordering};

    struct NoopWatcher {
        calls: Arc<AtomicUsize>,
    }

    #[async_trait]
    impl BackgroundWatcher for NoopWatcher {
        fn id(&self) -> &'static str {
            "noop"
        }
        fn description(&self) -> &'static str {
            "test no-op"
        }
        async fn on_files_changed(&self, _paths: Vec<PathBuf>) {
            self.calls.fetch_add(1, Ordering::SeqCst);
        }
        async fn current_status(&self) -> WatcherStatus {
            WatcherStatus::NeverRun
        }
    }

    fn tmp_dir(tag: &str) -> PathBuf {
        let p = std::env::temp_dir().join(format!("wsup_{tag}_{}", std::process::id()));
        std::fs::create_dir_all(&p).unwrap();
        p
    }

    /// No watchers / no paths → nothing to supervise, `spawn` returns None
    /// rather than spinning a monitor that can never start anything.
    #[test]
    fn spawn_returns_none_when_empty() {
        let hb = WatcherHeartbeat::new();
        let sup = WatcherSupervisor::new(vec![], vec![tmp_dir("empty")], 200, hb);
        assert!(sup.spawn().is_none());

        let hb2 = WatcherHeartbeat::new();
        let w: Arc<dyn BackgroundWatcher> = Arc::new(NoopWatcher {
            calls: Arc::new(AtomicUsize::new(0)),
        });
        let sup2 = WatcherSupervisor::new(vec![w], vec![], 200, hb2);
        assert!(sup2.spawn().is_none());
    }

    /// The supervisor starts the coordinator (heartbeat goes live) and the
    /// monitor keeps running. Holding the returned handle keeps it alive.
    #[tokio::test]
    async fn supervisor_starts_and_keeps_heartbeat_live() {
        let dir = tmp_dir("start");
        let hb = WatcherHeartbeat::new();
        let w: Arc<dyn BackgroundWatcher> = Arc::new(NoopWatcher {
            calls: Arc::new(AtomicUsize::new(0)),
        });
        let sup = WatcherSupervisor::new(vec![w], vec![dir.clone()], 200, Arc::clone(&hb));
        let monitor = sup.spawn().expect("supervisor should spawn");

        // Give the monitor a beat to run start_once.
        tokio::time::sleep(Duration::from_millis(150)).await;
        assert!(
            hb.is_live(30),
            "heartbeat must be live once supervisor starts"
        );

        monitor.abort();
        std::fs::remove_dir_all(&dir).ok();
    }

    /// `is_healthy` is false for a never-stamped heartbeat even if the
    /// task is alive — the wedged-loop case the old bool couldn't catch.
    #[tokio::test]
    async fn is_healthy_false_when_heartbeat_stale() {
        let dir = tmp_dir("health");
        // A supervisor whose heartbeat we control independently of any
        // coordinator: start a coordinator with a DIFFERENT heartbeat so
        // the supervisor's own heartbeat never advances.
        let sup_hb = WatcherHeartbeat::new(); // never stamped
        let coord_hb = WatcherHeartbeat::new();
        let w: Arc<dyn BackgroundWatcher> = Arc::new(NoopWatcher {
            calls: Arc::new(AtomicUsize::new(0)),
        });
        let sup = WatcherSupervisor::new(vec![w], vec![dir.clone()], 200, sup_hb);
        // Build a live handle bound to coord_hb (alive task, but the
        // supervisor's heartbeat is stale).
        let handle = WatcherCoordinator::new(200)
            .with_heartbeat(Arc::clone(&coord_hb))
            .start(vec![dir.clone()])
            .await
            .unwrap();
        assert!(handle.is_alive());
        assert!(
            !sup.is_healthy(&handle),
            "stale supervisor heartbeat must read unhealthy even with a live task"
        );
        let _ = Path::new(""); // silence unused import in some cfgs
        std::fs::remove_dir_all(&dir).ok();
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! A/B driver comparison: `diff`, `run-ab`, `probe-driver`.
//!
//! - **`atos diff <id>`** reads the per-run `atos_tool_events` for a
//!   given milestone and prints a per-tool side-by-side table so the
//!   operator can see how Claude Code and opencode approached the
//!   same problem.
//! - **`atos run-ab <id> --brief <path>`** is the write-amplifier:
//!   spawns each driver against the same milestone in sequence,
//!   then runs `diff` against the resulting runs.
//! - **`atos probe-driver`** is a standalone tool-use sanity check
//!   that POSTs a trivial function-calling request to
//!   `/v1/chat/completions` and reports whether the server emitted
//!   structured `tool_calls`. Used from `doctor` and from CI.

use sovereign_atos::AtosOrchestrator;

use super::args::parse_args;
use super::stores::open_orchestrator;

// ─── diff ────────────────────────────────────────────────────────────────────

pub(crate) async fn cmd_diff(args: &[String]) -> i32 {
    let (positional, flags) = split_args(args);
    let Some(feature_id) = positional.first().cloned() else {
        eprintln!("diff: missing <feature-id>");
        return 2;
    };
    let ordinal: Option<i64> = get_flag(&flags, "--ordinal").and_then(|s| s.parse::<i64>().ok());

    let orc = match open_orchestrator() {
        Ok(o) => o,
        Err(e) => {
            eprintln!("diff: {e}");
            return 1;
        }
    };

    let Some(feature) = orc.get_feature(&feature_id).await.ok().flatten() else {
        eprintln!("diff: feature '{feature_id}' not found");
        return 1;
    };
    let milestones = orc.list_milestones(&feature_id).await.unwrap_or_default();
    let target_milestone = match ordinal {
        Some(n) => milestones.iter().find(|m| m.ordinal == n).cloned(),
        None => milestones.last().cloned(),
    };
    let Some(milestone) = target_milestone else {
        eprintln!("diff: no milestones for feature '{feature_id}'");
        return 1;
    };

    let runs_all = orc.list_runs(&feature_id).await.unwrap_or_default();
    let runs: Vec<_> = runs_all
        .into_iter()
        .filter(|r| r.milestone_id == milestone.id)
        .collect();
    if runs.is_empty() {
        eprintln!(
            "diff: no runs for feature '{feature_id}' milestone {}",
            milestone.ordinal
        );
        return 1;
    }

    render_diff(&feature, &milestone, &runs, orc.features()).await;
    0
}

/// Count tool events per (tool_name, run_id) with a breakdown of
/// outcomes and parse errors. Keyed on `tool_name` so the diff view
/// can render one row per tool across drivers.
#[derive(Default, Debug)]
struct ToolCounts {
    after: usize,
    errors: usize,
    parse_errors: usize,
    total_duration_ms: i64,
}

async fn render_diff(
    feature: &corpus_engine_atos::FeatureRow,
    milestone: &corpus_engine_atos::MilestoneRow,
    runs: &[corpus_engine_atos::AtosRunRow],
    feature_store: &std::sync::Arc<corpus_engine_atos::FeatureStore>,
) {
    println!();
    println!("  ── atos diff ────────────────────────────────────────────────");
    println!("  Feature:   {}", feature.id);
    println!("  Milestone: {}", milestone.ordinal);
    println!("  Runs:");
    for r in runs {
        let duration = match (r.started_at, r.ended_at) {
            (s, Some(e)) => format!("{}s", e - s),
            _ => "in-flight".into(),
        };
        let verdict = match r.stop_passed {
            Some(true) => "PASS",
            Some(false) => "FAIL",
            None => "?",
        };
        println!(
            "    • {:9} [{}]  driver={:8}  duration={:>7}",
            &r.id[..r.id.len().min(8)],
            verdict,
            r.driver,
            duration
        );
    }

    // Aggregate per-driver counts. Multiple runs for the same driver
    // (e.g. retries) collapse into one column — what the operator
    // wants is "how does claude typically behave here vs opencode."
    use std::collections::BTreeMap;
    let mut per_driver: BTreeMap<String, BTreeMap<String, ToolCounts>> = BTreeMap::new();
    for run in runs {
        let events = feature_store
            .list_events_for_run(&run.id)
            .await
            .unwrap_or_default();
        let entry = per_driver.entry(run.driver.clone()).or_default();
        for e in events {
            let counts = entry.entry(e.tool_name.clone()).or_default();
            match e.phase.as_str() {
                "after" => {
                    counts.after += 1;
                    if matches!(e.outcome.as_deref(), Some("error")) {
                        counts.errors += 1;
                    }
                    if let Some(d) = e.duration_ms {
                        counts.total_duration_ms += d;
                    }
                }
                "parse_error" => {
                    counts.parse_errors += 1;
                }
                _ => {}
            }
        }
    }

    // Union of tool names across drivers, sorted for stable output.
    let mut all_tools: std::collections::BTreeSet<String> = Default::default();
    for m in per_driver.values() {
        for k in m.keys() {
            all_tools.insert(k.clone());
        }
    }

    // Drivers we print columns for, in a stable order (claude first
    // so it's the baseline column on the left).
    let drivers: Vec<&String> = {
        let mut v: Vec<&String> = per_driver.keys().collect();
        v.sort_by(|a, b| {
            // claude < opencode < any others alphabetically
            let rank = |s: &str| match s {
                "claude" => 0,
                "opencode" => 1,
                _ => 2,
            };
            rank(a).cmp(&rank(b)).then(a.cmp(b))
        });
        v
    };

    println!();
    println!("  Per-tool activity:");
    let mut header = String::from("    tool                    ");
    for d in &drivers {
        header.push_str(&format!("{:>10}", d));
    }
    header.push_str("   note");
    println!("{header}");
    println!(
        "    ─────────────────────── {}   ─────────────────────────────",
        "──────────".repeat(drivers.len())
    );

    for tool in &all_tools {
        let mut line = format!("    {:<24}", truncate(tool, 24));
        let mut counts: Vec<usize> = Vec::new();
        let mut parse_err_here = false;
        for d in &drivers {
            let c = per_driver
                .get(*d)
                .and_then(|m| m.get(tool))
                .map(|c| (c.after, c.parse_errors))
                .unwrap_or((0, 0));
            counts.push(c.0);
            if c.1 > 0 {
                parse_err_here = true;
            }
            if c.1 > 0 {
                line.push_str(&format!("{:>8}×e{}", c.0, c.1));
            } else {
                line.push_str(&format!("{:>10}", format!("{}×", c.0)));
            }
        }
        let note = classify_delta(&counts, parse_err_here);
        line.push_str(&format!("   {note}"));
        println!("{line}");
    }

    // Also surface a parse-error total so the operator sees it even
    // if no per-tool row has parse errors (they could land on a
    // tool the other driver didn't touch).
    let total_parse_errors: usize = per_driver
        .values()
        .flat_map(|m| m.values())
        .map(|c| c.parse_errors)
        .sum();
    if total_parse_errors > 0 {
        println!();
        println!(
            "  ⚠ {total_parse_errors} tool_call parse error(s) across all runs — \
             run `svrn atos diff {} --ordinal {} --verbose` (TODO) to inspect payloads.",
            feature.id, milestone.ordinal
        );
    }
}

fn truncate(s: &str, n: usize) -> String {
    if s.len() <= n {
        s.into()
    } else {
        format!("{}…", &s[..n.saturating_sub(1)])
    }
}

/// Heuristic annotation for the diff table. Kept simple and
/// iteration-friendly — this is the first lever we'll tune once we
/// have real comparison data.
fn classify_delta(counts: &[usize], parse_errors: bool) -> String {
    if parse_errors {
        return "parse failure (see above)".into();
    }
    if counts.len() < 2 {
        return String::new();
    }
    let max = counts.iter().copied().max().unwrap_or(0);
    let min = counts.iter().copied().min().unwrap_or(0);
    if max == 0 {
        return String::new();
    }
    if min == 0 {
        return "only one driver used this tool".into();
    }
    let ratio = max as f64 / min as f64;
    if ratio >= 3.0 && max - min >= 3 {
        "large delta — inspect".into()
    } else if max - min <= 2 {
        "close".into()
    } else {
        "moderate delta".into()
    }
}

// ─── run-ab ──────────────────────────────────────────────────────────────────

pub(crate) async fn cmd_run_ab(args: &[String]) -> i32 {
    let (positional, flags) = split_args(args);
    let Some(feature_id) = positional.first().cloned() else {
        eprintln!("run-ab: missing <feature-id>");
        return 2;
    };
    let Some(brief_path) = flags.value("brief").map(|s| s.to_string()) else {
        eprintln!("run-ab: --brief <path> is required");
        return 2;
    };
    let drivers_flag = get_flag(&flags, "--drivers").unwrap_or_else(|| "claude,opencode".into());
    let drivers: Vec<String> = drivers_flag
        .split(',')
        .map(|s| s.trim().to_string())
        .collect();
    if drivers.is_empty() {
        eprintln!("run-ab: --drivers cannot be empty");
        return 2;
    }
    // Read brief once up-front so a path typo fails fast.
    if let Err(e) = std::fs::read_to_string(&brief_path) {
        eprintln!("run-ab: read {brief_path}: {e}");
        return 1;
    }

    println!("run-ab: drivers = {}", drivers.join(", "));
    let mut all_passed = true;
    for (idx, d) in drivers.iter().enumerate() {
        println!();
        println!("── driver={d} ───────────────────────────────────────");
        // Both drivers attach to the same milestone so `atos diff`
        // shows a real side-by-side view. The first driver creates
        // the milestone; subsequent drivers reuse it.
        let mut start_args = vec![
            feature_id.clone(),
            "--brief".into(),
            brief_path.clone(),
            "--driver".into(),
            d.clone(),
        ];
        if idx > 0 {
            start_args.push("--reuse-last-milestone".into());
        }
        let rc = super::milestone::cmd_start_milestone(&start_args).await;
        if rc != 0 {
            eprintln!("run-ab: driver '{d}' exited non-zero ({rc})");
            all_passed = false;
        }
        let end_rc = super::milestone::cmd_end_milestone(std::slice::from_ref(&feature_id)).await;
        if end_rc != 0 {
            all_passed = false;
        }
    }

    println!();
    println!("── diff ──────────────────────────────────────────────");
    cmd_diff(&[feature_id]).await;

    if all_passed {
        0
    } else {
        1
    }
}

// ─── probe-driver ────────────────────────────────────────────────────────────

pub(crate) async fn cmd_probe_driver(args: &[String]) -> i32 {
    let (_positional, flags) = split_args(args);
    let url = get_flag(&flags, "--url")
        .unwrap_or_else(|| "http://localhost:9741/v1/chat/completions".to_string());

    let probe = serde_json::json!({
        "model": "probe",
        "messages": [
            {"role": "user", "content": "Call the ping tool with {} as args."}
        ],
        "tools": [{
            "type": "function",
            "function": {
                "name": "ping",
                "description": "Trivial probe tool.",
                "parameters": {
                    "type": "object",
                    "properties": {},
                    "required": []
                }
            }
        }],
        "tool_choice": "required",
        "max_tokens": 64,
        "stream": false
    });

    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(10))
        .build();
    let client = match client {
        Ok(c) => c,
        Err(e) => {
            eprintln!("probe-driver: reqwest init: {e}");
            return 1;
        }
    };

    println!("probe-driver: POST {url}");
    let res = client
        .post(&url)
        .header("Content-Type", "application/json")
        .body(probe.to_string())
        .send()
        .await;
    let body = match res {
        Ok(r) => {
            let status = r.status();
            match r.text().await {
                Ok(b) => {
                    println!("probe-driver: HTTP {}", status.as_u16());
                    if !status.is_success() {
                        println!("{b}");
                        return 1;
                    }
                    b
                }
                Err(e) => {
                    eprintln!("probe-driver: body read: {e}");
                    return 1;
                }
            }
        }
        Err(e) => {
            eprintln!("probe-driver: request failed: {e}");
            return 1;
        }
    };

    let parsed: serde_json::Value = match serde_json::from_str(&body) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("probe-driver: parse response: {e}");
            return 1;
        }
    };

    // Accept both the structured `tool_calls` field (what M2
    // introduces) and the fallback text-in-content form (pre-M2
    // servers). The structured form is the success case.
    let tool_calls = parsed
        .pointer("/choices/0/message/tool_calls")
        .and_then(|v| v.as_array());
    match tool_calls {
        Some(calls) if !calls.is_empty() => {
            println!(
                "probe-driver: PASS — server emitted {} structured tool_call(s)",
                calls.len()
            );
            // Print the first call so operators see what the model produced.
            if let Some(first) = calls.first() {
                println!("  {first}");
            }
            0
        }
        _ => {
            println!("probe-driver: FAIL — response did not include structured tool_calls.");
            println!(
                "  Full message: {}",
                parsed
                    .pointer("/choices/0/message")
                    .unwrap_or(&serde_json::Value::Null)
            );
            1
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! The flag surface of `svrn atos`, as data.
//!
//! The CLI sidesteps `clap` here because each subcommand has its own
//! flag shape and a clap-derived parser for the union would be more
//! machinery than payoff. Instead we split `args` into positional
//! arguments and `(name, value)` flag pairs once, then subcommands
//! pluck what they need via [`get_flag`].
//!
//! Boolean flags that don't consume the next token are listed in
//! [`BOOLEAN_FLAGS`]; everything else is treated as a value-taking
//! flag that consumes the following token.

use sovereign_cli_shared::args::{parse, ArgError, ArgSpec, Parsed};

/// Boolean flags that do not consume the next token as their value.
pub(super) const BOOLEAN_FLAGS: &[&str] = &[
    "no-driver",
    "reuse-last-milestone",
    "yes",
    "y",
    "red-team",
    "auto",
    "dry-run",
    "fresh-plan",
];

/// Split `args` into `(positional, flag_pairs)`. Value-taking flags
/// (e.g. `--title "foo"`) consume the following token. Boolean flags
/// listed in [`BOOLEAN_FLAGS`] stand alone and are recorded with an
/// empty value.
pub(super) fn split_args(args: &[String]) -> (Vec<String>, Vec<(String, String)>) {
    let mut positional = Vec::new();
    let mut flags = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if let Some(name) = arg.strip_prefix("--") {
            if BOOLEAN_FLAGS.contains(&name) {
                flags.push((name.to_string(), String::new()));
                i += 1;
            } else {
                let value = args.get(i + 1).cloned().unwrap_or_default();
                flags.push((name.to_string(), value));
                i += 2;
            }
        } else {
            positional.push(arg.clone());
            i += 1;
        }
    }
    (positional, flags)
}

/// Look up a flag's value. Accepts both `"--title"` and `"title"` for
/// the `name` argument so callers can stay readable.
pub(super) fn get_flag(flags: &[(String, String)], name: &str) -> Option<String> {
    let key = name.strip_prefix("--").unwrap_or(name);
    flags.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())
}

// Path helper kept for the stop-condition runner's future use (emit a
// diagnostic when the feature's stop cmd references a path that does
// not resolve relative to CWD).
#[allow(dead_code)]
pub(super) fn exists_on_path(p: &str) -> bool {
    Path::new(p).exists()
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Milestone lifecycle: `start-milestone`, `end-milestone`, `next`,
//! plus the auto-redteam spawn and the subprocess driver.
//!
//! Flow:
//!
//! 1. **`start-milestone`** or **`next`** (the seamless variant)
//!    opens an [`AtosRunRow`], spawns a driver subprocess with
//!    `SOVEREIGN_FEATURE_ID` / `ATOS_RUN_ID` / `ATOS_DRIVER` /
//!    `ATOS_MODE` exported, then closes the run with a placeholder
//!    verdict when the driver exits.
//! 2. **`end-milestone`** runs the stop condition, overwrites the
//!    placeholder with the real verdict, writes the per-milestone
//!    artifact, and — if the charter opted in and this is the final
//!    milestone — spawns an auto-redteam pass.
//!
//! The [`Driver`] enum names the two supported drivers; new ones get
//! added as variants rather than strings so the help text stays
//! honest.

use std::process::Stdio;

use corpus_engine_notes::NoteScope;
use sovereign_atos::{AtosOrchestrator, RunMode};

use super::args::parse_args;
use super::stores::open_orchestrator;

// ─── start-milestone ─────────────────────────────────────────────────────────

pub(crate) async fn cmd_start_milestone(args: &[String]) -> i32 {
    let (positional, flags) = split_args(args);
    let Some(id) = positional.first().cloned() else {
        eprintln!("start-milestone: missing <id>");
        return 2;
    };
    let brief_path = match flags.value("brief").map(|s| s.to_string()) {
        Some(p) => p,
        None => {
            eprintln!("start-milestone: --brief <path> is required");
            return 2;
        }
    };
    let brief_md = match std::fs::read_to_string(&brief_path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("start-milestone: read {brief_path}: {e}");
            return 1;
        }
    };
    let driver_flag = get_flag(&flags, "--driver");
    let no_driver = flags.iter().any(|(k, _)| k == "no-driver");
    // `--reuse-last-milestone` is set by `run-ab` so both A/B drivers
    // attach to the same milestone ordinal. Without this, each driver
    // spawn would increment the ordinal and `atos diff` would only
    // show one driver column.
    let reuse_last = flags.iter().any(|(k, _)| k == "reuse-last-milestone");
    // `--milestone-id <uuid>` lets `cmd_next` target a specific
    // charter-provisioned milestone without scanning or appending.
    // Takes precedence over --reuse-last-milestone.
    let milestone_id_override = get_flag(&flags, "--milestone-id");
    // `--red-team` opens the run in `mode=redteam` so reports and
    // teardown can exclude these runs from normal-progress gating.
    // Driver env gains `ATOS_MODE=redteam` so the opencode plugin
    // (M2.6) can restrict tool surface.
    let red_team = flags.iter().any(|(k, _)| k == "red-team");
    let run_mode = if red_team {
        RunMode::Redteam
    } else {
        RunMode::Normal
    };
    let driver = resolve_driver(driver_flag.as_deref()).await;

    let orc = match open_orchestrator() {
        Ok(o) => o,
        Err(e) => {
            eprintln!("start-milestone: {e}");
            return 1;
        }
    };

    if orc.get_feature(&id).await.ok().flatten().is_none() {
        eprintln!("start-milestone: feature '{id}' is not provisioned");
        return 1;
    }

    let milestone = if let Some(mid) = milestone_id_override.as_ref() {
        let list = orc.list_milestones(&id).await.unwrap_or_default();
        match list.into_iter().find(|m| &m.id == mid) {
            Some(m) => m,
            None => {
                eprintln!("start-milestone: --milestone-id {mid} not found on feature '{id}'");
                return 1;
            }
        }
    } else if reuse_last {
        let list = orc.list_milestones(&id).await.unwrap_or_default();
        match list.into_iter().last() {
            Some(m) => m,
            None => {
                eprintln!(
                    "start-milestone: --reuse-last-milestone but feature '{id}' has no milestones"
                );
                return 1;
            }
        }
    } else {
        let ordinal = match orc.next_ordinal(&id).await {
            Ok(n) => n,
            Err(e) => {
                eprintln!("start-milestone: next_ordinal: {e}");
                return 1;
            }
        };
        match orc.add_milestone(&id, ordinal, &brief_md).await {
            Ok(m) => m,
            Err(e) => {
                eprintln!("start-milestone: {e}");
                return 1;
            }
        }
    };
    let ordinal = milestone.ordinal;
    let _ = orc.mark_milestone_started(&milestone.id).await;

    // Open an atos_runs row so the driver subprocess's tool events
    // can be attributed back to this specific (feature, milestone,
    // driver) tuple. The id is exported via env so the opencode
    // plugin can pass it back to `record_atos_event`.
    let run = match orc
        .begin_run(&id, &milestone.id, driver.as_label(), run_mode)
        .await
    {
        Ok(r) => r,
        Err(e) => {
            eprintln!("start-milestone: open_run: {e}");
            return 1;
        }
    };

    println!(
        "start-milestone: feature='{id}' ordinal={ordinal} driver={} run_id={}",
        driver.as_label(),
        run.run_id
    );

    if no_driver {
        println!(
            "start-milestone: --no-driver set; milestone {} recorded without spawning a driver",
            milestone.id
        );
        return 0;
    }

    let spawn_result = driver.spawn(&id, &brief_md, &run.run_id, run_mode);
    let exit_code = match &spawn_result {
        Ok(status) => status.code().unwrap_or(-1),
        Err(_) => -1,
    };
    // stop_passed at this point is unknown — end-milestone will
    // actually run the stop condition. We provisionally close the
    // run here with stop_passed=false and stop_stdout=None so an
    // interrupted session isn't left dangling; end-milestone
    // overwrites when it lands.
    let _ = orc.close_run(&run.run_id, exit_code, false, None).await;
    match spawn_result {
        Ok(status) if status.success() => 0,
        Ok(status) => {
            eprintln!(
                "start-milestone: driver exited with {}",
                status.code().unwrap_or(-1)
            );
            1
        }
        Err(e) => {
            eprintln!("start-milestone: driver spawn failed: {e}");
            1
        }
    }
}

// ─── end-milestone ───────────────────────────────────────────────────────────

pub(crate) async fn cmd_end_milestone(args: &[String]) -> i32 {
    let (positional, flags) = split_args(args);
    let Some(id) = positional.first().cloned() else {
        eprintln!("end-milestone: missing <id>");
        return 2;
    };
    let ordinal_override: Option<i64> =
        get_flag(&flags, "--ordinal").and_then(|s| s.parse::<i64>().ok());

    let orc = match open_orchestrator() {
        Ok(o) => o,
        Err(e) => {
            eprintln!("end-milestone: {e}");
            return 1;
        }
    };
    let Some(feature) = orc.get_feature(&id).await.ok().flatten() else {
        eprintln!("end-milestone: feature '{id}' not provisioned");
        return 1;
    };

    let milestones = match orc.list_milestones(&id).await {
        Ok(m) => m,
        Err(e) => {
            eprintln!("end-milestone: list_milestones: {e}");
            return 1;
        }
    };
    // Pick the milestone tied to the most recent run. This matches
    // what `atos next` (and its M3.4 descendants) expect: after
    // start-milestone opens a run against milestone 1, end-milestone
    // must close THAT milestone even if milestone 2 exists in the
    // charter. The old `.last()` behavior silently closed the wrong
    // milestone on a two-milestone charter.
    //
    // A/B parity: multiple runs can attach to the same milestone
    // (`--milestone-id` / `--reuse-last-milestone`); picking the
    // most-recent run still resolves to the right ordinal.
    let all_runs = orc.list_runs(&id).await.unwrap_or_default();
    let target = match ordinal_override {
        Some(n) => milestones.iter().find(|m| m.ordinal == n).cloned(),
        None => {
            let latest_run = all_runs.iter().max_by_key(|r| r.started_at);
            match latest_run {
                Some(r) => milestones.iter().find(|m| m.id == r.milestone_id).cloned(),
                None => milestones.last().cloned(),
            }
        }
    };
    let Some(milestone) = target else {
        eprintln!("end-milestone: no milestone to close");
        return 1;
    };

    // Run the stop condition through the orchestrator. Library owns
    // the shell spawn + stdout capture + 8KB cap. Prefer the
    // milestone-scoped stop_condition (set by the charter
    // provisioner) and fall back to the feature-level one for M1/M2
    // features.
    let stop_outcome = match orc.run_milestone_stop_condition(&feature, &milestone).await {
        Ok(o) => o,
        Err(e) => {
            eprintln!("end-milestone: stop_condition spawn: {e}");
            return 1;
        }
    };
    let stop_passed = stop_outcome.passed;

    // Gather feature-scoped notes for the compliance report. Until
    // M3.6 migrates rendering into the library, we keep a direct
    // NoteStore read here — orc.notes() exposes the same handle.
    let filter = corpus_engine_notes::ScopeFilter {
        scopes: vec![NoteScope::Feature],
        feature_id: Some(id.clone()),
    };
    let feature_notes: Vec<serde_json::Value> = orc
        .notes()
        .read_notes_scoped(None, &[], &[], &[], 100, false, &filter)
        .await
        .map(|rows| {
            rows.into_iter()
                .map(|n| {
                    serde_json::json!({
                        "id": n.id,
                        "kind": n.kind,
                        "content": n.content,
                        "created_at": n.created_at,
                    })
                })
                .collect()
        })
        .unwrap_or_default();

    // Find the run for this milestone (A/B case allows multiple).
    // Pick the most recent that's still open OR the most recent
    // overall, and close it with the real verdict.
    let runs = orc.list_runs(&feature.id).await.unwrap_or_default();
    let target_run = runs
        .iter()
        .filter(|r| r.milestone_id == milestone.id)
        .rev()
        .find(|r| r.ended_at.is_none())
        .cloned()
        .or_else(|| {
            runs.iter()
                .rfind(|r| r.milestone_id == milestone.id)
                .cloned()
        });
    if let Some(run) = target_run.as_ref() {
        let _ = orc
            .close_run(
                &run.id,
                run.exit_code.map(|c| c as i32).unwrap_or(0),
                stop_passed,
                Some(stop_outcome.stdout.as_str()),
            )
            .await;
    }

    let report = serde_json::json!({
        "feature_id": feature.id,
        "ordinal": milestone.ordinal,
        "stop_condition": feature.stop_condition,
        "stop_passed": stop_passed,
        "note_count": feature_notes.len(),
        "notes": feature_notes,
        "run_id": target_run.as_ref().map(|r| r.id.clone()),
        "driver": target_run.as_ref().map(|r| r.driver.clone()),
    });
    let report_json = report.to_string();
    let _ = orc.mark_milestone_ended(&milestone.id, &report_json).await;

    if stop_passed {
        println!(
            "end-milestone: stop_condition PASSED for feature='{}' ordinal={}",
            feature.id, milestone.ordinal
        );
        // Artifact hook: render milestone-<n>.md. Best-effort —
        // failure to write the artifact should not fail the
        // milestone closure.
        match orc
            .render_and_write_report(
                &feature.id,
                sovereign_atos::ReportSection::Milestone(milestone.ordinal),
            )
            .await
        {
            Ok(path) => println!("end-milestone: wrote {}", path.display()),
            Err(e) => eprintln!(
                "end-milestone: render milestone-{}.md failed: {e}",
                milestone.ordinal
            ),
        }
        // Red-team runs always refresh the red-team.md artifact too,
        // in case this end-milestone closes a --red-team run.
        if let Some(run) = target_run.as_ref() {
            if run.mode == "redteam" {
                match orc
                    .render_and_write_report(&feature.id, sovereign_atos::ReportSection::RedTeam)
                    .await
                {
                    Ok(path) => println!("end-milestone: wrote {}", path.display()),
                    Err(e) => eprintln!("end-milestone: render red-team.md failed: {e}"),
                }
            }
        }

        // Auto red-team trigger — fires iff:
        // - feature.auto_redteam was set (charter opt-in);
        // - this is the final milestone (highest ordinal);
        // - the just-closed run was `mode=normal` (we don't recurse
        //   on red-team's own runs);
        // - no redteam run already fired for this milestone
        //   (idempotent on re-invocation).
        let final_ordinal = milestones.iter().map(|m| m.ordinal).max().unwrap_or(0);
        let just_run_was_normal = target_run
            .as_ref()
            .map(|r| r.mode == "normal")
            .unwrap_or(false);
        let redteam_already_fired = runs
            .iter()
            .any(|r| r.milestone_id == milestone.id && r.mode == "redteam");
        if feature.auto_redteam
            && milestone.ordinal == final_ordinal
            && just_run_was_normal
            && !redteam_already_fired
        {
            println!(
                "⚙ auto-redteam: charter opted in — spawning red-team pass for milestone {}…",
                milestone.ordinal
            );
            spawn_auto_redteam(&feature.id, &milestone.id, milestone.ordinal);
        }
        0
    } else {
        eprintln!(
            "end-milestone: stop_condition FAILED for feature='{}' ordinal={}",
            feature.id, milestone.ordinal
        );
        1
    }
}

/// Spawn a blocking red-team pass over `milestone_id` by re-invoking
/// this binary. We use `std::process::Command` (not `tokio::spawn`)
/// because Yara's stdout is the right surface: she sees the red-team
/// run live in her terminal, same as a normal `start-milestone`.
///
/// Failures are noisy (printed to stderr) but never block the caller's
/// exit code — the normal milestone already passed; a red-team
/// hiccup shouldn't turn that into a "the whole thing failed."
fn spawn_auto_redteam(feature_id: &str, milestone_id: &str, ordinal: i64) {
    let exe = match std::env::current_exe() {
        Ok(p) => p,
        Err(e) => {
            eprintln!("auto-redteam: current_exe: {e} — skipping");
            return;
        }
    };

    let status = std::process::Command::new(&exe)
        .args([
            "atos",
            "start-milestone",
            feature_id,
            "--red-team",
            "--milestone-id",
            milestone_id,
        ])
        .status();
    match status {
        Ok(s) if s.success() => {}
        Ok(s) => {
            eprintln!(
                "auto-redteam: start-milestone --red-team exited {}",
                s.code().unwrap_or(-1)
            );
            return;
        }
        Err(e) => {
            eprintln!("auto-redteam: start-milestone --red-team spawn failed: {e}");
            return;
        }
    }

    let ord_str = ordinal.to_string();
    let status = std::process::Command::new(&exe)
        .args(["atos", "end-milestone", feature_id, "--ordinal", &ord_str])
        .status();
    match status {
        Ok(s) if s.success() => {
            println!("⚙ auto-redteam: red-team run closed and red-team.md written.");
        }
        Ok(s) => {
            eprintln!(
                "auto-redteam: end-milestone exited {}",
                s.code().unwrap_or(-1)
            );
        }
        Err(e) => {
            eprintln!("auto-redteam: end-milestone spawn failed: {e}");
        }
    }
}

// ─── next (seamless handoff) ─────────────────────────────────────────────────

/// `svrn atos next [<feature-id>]` — the seamless-handoff entry
/// point. Finds the next unfinished milestone, prints a summary, asks
/// for driver confirmation, and spawns.
pub(crate) async fn cmd_next(args: &[String]) -> i32 {
    let (positional, flags) = split_args(args);
    let auto_yes = flags.iter().any(|(k, _)| k == "yes" || k == "y");
    let driver_flag = get_flag(&flags, "--driver");

    let feature_id = match positional.first().cloned() {
        Some(id) => id,
        None => match std::env::var("SOVEREIGN_FEATURE_ID") {
            Ok(id) if !id.is_empty() => id,
            _ => {
                eprintln!(
                    "next: missing <feature-id> and $SOVEREIGN_FEATURE_ID is unset.\n\
                     Pass a feature id or run inside an ATOS-launched driver session."
                );
                return 2;
            }
        },
    };

    let orc = match open_orchestrator() {
        Ok(o) => o,
        Err(e) => {
            eprintln!("next: {e}");
            return 1;
        }
    };
    let Some(feature) = orc.get_feature(&feature_id).await.ok().flatten() else {
        eprintln!("next: feature '{feature_id}' not found");
        return 1;
    };

    let Some(brief) = orc
        .next_milestone(&feature_id, RunMode::Normal)
        .await
        .unwrap_or(None)
    else {
        println!(
            "feature '{}' has no unfinished milestone — every ordinal has a passing run.",
            feature.id
        );
        println!("Run `svrn atos teardown {}` to wrap it up.", feature.id);
        return 0;
    };

    // Pre-spawn summary. Shows last milestone's status + what's next.
    let runs = orc.list_runs(&feature_id).await.unwrap_or_default();
    let milestones_all = orc.list_milestones(&feature_id).await.unwrap_or_default();
    let ordinal_of = |milestone_id: &str| -> Option<i64> {
        milestones_all
            .iter()
            .find(|m| m.id == milestone_id)
            .map(|m| m.ordinal)
    };
    let last_passed_ordinal = runs
        .iter()
        .filter(|r| r.mode == "normal" && r.stop_passed == Some(true))
        .filter_map(|r| ordinal_of(&r.milestone_id))
        .max();

    println!();
    println!("  ── atos next ────────────────────────────────────────────");
    println!("  Feature:        {} [{}]", feature.id, feature.state);
    if let Some(ord) = last_passed_ordinal {
        println!("  Last milestone: {} [PASS]", ord);
    } else {
        println!("  Last milestone: (none yet)");
    }
    println!(
        "  Next milestone: {} — {}",
        brief.milestone_ordinal, brief.milestone_title
    );
    if !brief.stop_condition.is_empty() {
        println!("  Stop condition: {}", brief.stop_condition);
    } else {
        println!("  Stop condition: (manual review — no shell command)");
    }
    println!();

    // Driver selection.
    let chosen_driver = match driver_flag.as_deref() {
        Some("claude") => "claude".to_string(),
        Some("opencode") => "opencode".to_string(),
        Some(other) => {
            eprintln!("next: unknown driver '{other}'");
            return 2;
        }
        None => {
            if auto_yes {
                "claude".to_string()
            } else {
                match prompt_driver_choice() {
                    Some(d) => d,
                    None => {
                        println!("aborted.");
                        return 0;
                    }
                }
            }
        }
    };

    // Delegate to start-milestone so the spawn/ledger path stays in
    // one place. We write the composed brief to a tempfile;
    // start-milestone reads it the usual way.
    let rendered = brief.render();
    let tmp = match write_brief_tempfile(&rendered) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("next: could not write tempfile: {e}");
            return 1;
        }
    };
    let start_args = vec![
        feature_id.clone(),
        "--brief".into(),
        tmp.clone(),
        "--driver".into(),
        chosen_driver,
        // `next` never creates a new milestone — milestones are
        // charter-driven; `--milestone-id` pins the run to the
        // exact one `next_milestone` picked.
        "--milestone-id".into(),
        brief.milestone_id.clone(),
    ];
    let rc = cmd_start_milestone(&start_args).await;
    // Best-effort tempfile cleanup; leaving one behind is harmless.
    let _ = std::fs::remove_file(&tmp);
    if rc != 0 {
        return rc;
    }

    // Close out the run by running the real stop_condition. We
    // dispatch through cmd_end_milestone for the same reason: one
    // implementation of end-milestone semantics.
    cmd_end_milestone(&[feature_id]).await
}

fn prompt_driver_choice() -> Option<String> {
    use std::io::Write;
    eprint!("  spawn driver? [y=claude / o=opencode / N=abort]: ");
    let _ = std::io::stderr().flush();
    let mut line = String::new();
    if std::io::stdin().read_line(&mut line).is_err() {
        return None;
    }
    match line.trim().to_lowercase().as_str() {
        "" | "n" | "no" => None,
        "y" | "yes" | "c" | "claude" => Some("claude".into()),
        "o" | "opencode" => Some("opencode".into()),
        other => {
            eprintln!("  unknown response '{other}' — aborting.");
            None
        }
    }
}

fn write_brief_tempfile(contents: &str) -> std::io::Result<String> {
    use std::io::Write;
    let mut path = std::env::temp_dir();
    path.push(format!(
        "atos-brief-{}.md",
        uuid::Uuid::new_v4().as_simple()
    ));
    let mut f = std::fs::File::create(&path)?;
    f.write_all(contents.as_bytes())?;
    Ok(path.to_string_lossy().into_owned())
}

// ─── Driver ──────────────────────────────────────────────────────────────────

enum Driver {
    Claude,
    Opencode,
}

impl Driver {
    fn as_label(&self) -> &'static str {
        match self {
            Self::Claude => "claude",
            Self::Opencode => "opencode",
        }
    }

    fn spawn(
        &self,
        feature_id: &str,
        brief_md: &str,
        run_id: &str,
        mode: RunMode,
    ) -> std::io::Result<std::process::ExitStatus> {
        let mode_str = mode.as_str();
        match self {
            // Claude Code speaks MCP over localhost today. The MCP
            // tool calls it issues already land in `tool_call_log`;
            // the ATOS_RUN_ID export is carried for a future Claude
            // wrapper that mirrors those into `atos_tool_events`.
            Self::Claude => std::process::Command::new("claude")
                .arg("--print")
                .arg(brief_md)
                .env("SOVEREIGN_FEATURE_ID", feature_id)
                .env("ATOS_RUN_ID", run_id)
                .env("ATOS_DRIVER", "claude")
                .env("ATOS_MODE", mode_str)
                .stdin(Stdio::inherit())
                .stdout(Stdio::inherit())
                .stderr(Stdio::inherit())
                .status(),
            // Opencode + the sovereign-atos plugin feed tool events
            // into `atos_tool_events` keyed by $ATOS_RUN_ID. The
            // plugin is what M2.6 ships.
            Self::Opencode => std::process::Command::new("opencode")
                .arg("run")
                .arg("--input")
                .arg("-")
                .env("SOVEREIGN_FEATURE_ID", feature_id)
                .env("ATOS_RUN_ID", run_id)
                .env("ATOS_DRIVER", "opencode")
                .env("ATOS_MODE", mode_str)
                .stdin(std::process::Stdio::piped())
                .stdout(Stdio::inherit())
                .stderr(Stdio::inherit())
                .spawn()
                .and_then(|mut child| {
                    if let Some(mut stdin) = child.stdin.take() {
                        use std::io::Write;
                        let _ = stdin.write_all(brief_md.as_bytes());
                    }
                    child.wait()
                }),
        }
    }
}

/// Pick a driver. Explicit --driver wins. Otherwise fall back to
/// Claude — the probe-based capability discovery is a future-work
/// item deferred in the original file and preserved here so the
/// refactor is behaviour-equivalent.
async fn resolve_driver(requested: Option<&str>) -> Driver {
    match requested {
        Some("opencode") => Driver::Opencode,
        Some("claude") | None => Driver::Claude,
        Some(other) => {
            eprintln!("atos: unknown driver '{other}', falling back to claude");
            Driver::Claude
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn atos replay` — reconstruct a historical commit as an
//! ATOS Runner task.
//!
//! Flow:
//!   1. Resolve the commit's parent SHA and verify both exist.
//!   2. Check out a fresh branch at the parent SHA.
//!   3. Ask the Fast slot to synthesize `DESIGN.md` + `CHARTER.md`
//!      from the commit message and diff — what the design WOULD have
//!      looked like before the commit.
//!   4. Hand off to `svrn atos run` with the synthesized artifacts
//!      in the workdir; the existing drive loop runs unchanged.
//!
//! After the loop terminates, `git diff <parent_sha>..<commit_sha>` is
//! the ground-truth comparison for the `sovereign-eval scope` analyzer
//! — a future `--score` flag wires this in.
//!
//! See `sovereign/docs/ATOS_RUNNER.md` § replay primitive.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

use super::args::{get_flag, split_args};

const DEFAULT_SYNTH_MODEL: &str = "commonwealth/primary";
const DEFAULT_DAEMON_URL: &str = "http://localhost:9741";
const SYNTH_MAX_TOKENS: u32 = 4096;
const SYNTH_TEMPERATURE: f32 = 0.0;
const SYNTH_SEED: u64 = 0xA705;
const SYNTH_TIMEOUT_SECS: u64 = 600;
/// Diffs above this size get truncated before being shown to the
/// synthesizer — the goal is intent recovery, not byte-perfect echo.
const MAX_DIFF_BYTES: usize = 64 * 1024;

pub async fn cmd_replay(args: &[String]) -> i32 {
    let (_positional, flags) = split_args(args);

    let commit = match flags.value("commit").map(|s| s.to_string()) {
        Some(s) => s,
        None => {
            eprintln!("atos replay: missing --commit <sha>");
            print_help();
            return 2;
        }
    };
    let workdir = match flags.value("workdir").map(|s| s.to_string()) {
        Some(s) => PathBuf::from(s),
        None => {
            eprintln!("atos replay: missing --workdir <path>");
            print_help();
            return 2;
        }
    };
    if !workdir.is_dir() {
        eprintln!(
            "atos replay: --workdir is not a directory: {}",
            workdir.display()
        );
        return 2;
    }

    let driver = get_flag(&flags, "--driver").unwrap_or_else(|| "opencode".to_string());
    let daemon_url =
        get_flag(&flags, "--daemon-url").unwrap_or_else(|| DEFAULT_DAEMON_URL.to_string());
    let synth_model =
        get_flag(&flags, "--synth-model").unwrap_or_else(|| DEFAULT_SYNTH_MODEL.to_string());
    let custom_branch = get_flag(&flags, "--branch-name");
    let dry_run = flags.iter().any(|(k, _)| k == "dry-run");
    let max_iters = get_flag(&flags, "--max-iters").unwrap_or_else(|| "8".to_string());

    println!("atos replay: workdir = {}", workdir.display());
    println!("  commit       = {commit}");
    println!("  driver       = {driver}");
    println!("  synth model  = {synth_model}");

    // ── 1. Resolve commit + parent SHA ───────────────────────────
    let commit_sha = match git_rev_parse(&workdir, &commit) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot resolve commit `{commit}`: {e}");
            return 1;
        }
    };
    let parent_sha = match git_rev_parse(&workdir, &format!("{commit_sha}^")) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot resolve parent of `{commit_sha}`: {e}");
            return 1;
        }
    };
    println!("  parent       = {parent_sha}");
    println!("  target       = {commit_sha}");

    // ── 2. Read commit message + diff BEFORE checking out ────────
    let commit_message = match git_commit_message(&workdir, &commit_sha) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot read commit message: {e}");
            return 1;
        }
    };
    let mut diff_text = match git_diff(&workdir, &parent_sha, &commit_sha) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot compute diff: {e}");
            return 1;
        }
    };
    let diff_truncated = diff_text.len() > MAX_DIFF_BYTES;
    if diff_truncated {
        diff_text.truncate(MAX_DIFF_BYTES);
        diff_text.push_str("\n... (diff truncated)\n");
    }
    let changed_files = match git_changed_files(&workdir, &parent_sha, &commit_sha) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("atos replay: cannot list changed files: {e}");
            return 1;
        }
    };
    println!(
        "  diff         = {} bytes ({} files){}",
        diff_text.len(),
        changed_files.len(),
        if diff_truncated { " [truncated]" } else { "" }
    );

    // ── 3. Check out a fresh branch at parent SHA ────────────────
    let branch_name = custom_branch.unwrap_or_else(|| {
        let short = &commit_sha[..7.min(commit_sha.len())];
        let stamp = chrono::Utc::now().format("%Y%m%d%H%M%S");
        format!("atos-replay-{short}-{stamp}")
    });
    if let Err(e) = git_checkout_new_branch(&workdir, &branch_name, &parent_sha) {
        eprintln!("atos replay: branch checkout failed: {e}");
        return 1;
    }
    println!("  branch       = {branch_name} @ {parent_sha}");

    // ── 4. Fast slot synthesizes DESIGN.md and CHARTER.md ────────
    let design_md = match synthesize_design(
        &daemon_url,
        &synth_model,
        &commit_message,
        &diff_text,
        &changed_files,
    )
    .await
    {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: design synthesis failed: {e}");
            return 1;
        }
    };
    let charter_md = match synthesize_charter(
        &daemon_url,
        &synth_model,
        &commit_message,
        &diff_text,
        &changed_files,
    )
    .await
    {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: charter synthesis failed: {e}");
            return 1;
        }
    };

    let design_path = workdir.join("DESIGN.md");
    let charter_path = workdir.join("CHARTER.md");
    if let Err(e) = std::fs::write(&design_path, &design_md) {
        eprintln!("atos replay: write {}: {e}", design_path.display());
        return 1;
    }
    if let Err(e) = std::fs::write(&charter_path, &charter_md) {
        eprintln!("atos replay: write {}: {e}", charter_path.display());
        return 1;
    }
    println!(
        "  design       = {} ({} bytes)",
        design_path.display(),
        design_md.len()
    );
    println!(
        "  charter      = {} ({} bytes)",
        charter_path.display(),
        charter_md.len()
    );

    // Snapshot the synthesized artifacts to the runs dir for triage.
    // The actual run-id is allocated by `cmd_run`, so write to a
    // sidecar keyed by branch_name; operators can correlate via the
    // branch name printed above.
    let sidecar = sovereign_root().join("replay-synth").join(&branch_name);
    let _ = std::fs::create_dir_all(&sidecar);
    let _ = std::fs::write(sidecar.join("DESIGN.md"), &design_md);
    let _ = std::fs::write(sidecar.join("CHARTER.md"), &charter_md);
    let _ = std::fs::write(sidecar.join("commit_message.txt"), &commit_message);
    let _ = std::fs::write(sidecar.join("diff.patch"), &diff_text);

    if dry_run {
        println!("\natos replay: --dry-run set — synthesized artifacts only, not spawning driver.");
        println!("  synth dir  = {}", sidecar.display());
        return 0;
    }

    // ── 5. Delegate to `svrn atos run` ──────────────────────
    let workdir_str = workdir.to_string_lossy().to_string();
    let run_args = vec![
        "--workdir".to_string(),
        workdir_str,
        "--driver".to_string(),
        driver,
        "--max-iters".to_string(),
        max_iters,
        "--daemon-url".to_string(),
        daemon_url,
    ];
    super::run::cmd_run(&run_args).await
}

// ─── Synthesis prompts ───────────────────────────────────────────

const DESIGN_SYNTH_SYSTEM: &str = "You are an architect drafting a DESIGN.md for a software change. \
Output ONLY the markdown body — no surrounding prose, no fences, no commentary. \
The document should describe what the change accomplishes, the load-bearing anchors (files / functions / interfaces affected), and the success conditions a reviewer would check. \
Write it as if BEFORE the change was implemented — describe intent, not what happened.";

const CHARTER_SYNTH_SYSTEM: &str = "You are drafting a CHARTER.md that constrains an agent implementing the change described. \
Output ONLY the markdown body — no surrounding prose, no fences, no commentary. \
Include a `**Stop condition:**` line whose value is a single shell command that mechanically verifies the change. \
Prefer a `cargo test` / `cargo check` invocation scoped to the affected crate(s) when tests changed; otherwise use `cargo check --workspace`. \
Include short subsections on scope, out-of-scope, and what the reviewer should reject.";

async fn synthesize_design(
    daemon_url: &str,
    model: &str,
    commit_message: &str,
    diff_text: &str,
    changed_files: &[String],
) -> Result<String, String> {
    let user_prompt =
        build_synth_user_prompt("DESIGN.md", commit_message, diff_text, changed_files);
    call_synth(daemon_url, model, DESIGN_SYNTH_SYSTEM, &user_prompt).await
}

async fn synthesize_charter(
    daemon_url: &str,
    model: &str,
    commit_message: &str,
    diff_text: &str,
    changed_files: &[String],
) -> Result<String, String> {
    let user_prompt =
        build_synth_user_prompt("CHARTER.md", commit_message, diff_text, changed_files);
    call_synth(daemon_url, model, CHARTER_SYNTH_SYSTEM, &user_prompt).await
}

fn build_synth_user_prompt(
    artifact: &str,
    commit_message: &str,
    diff_text: &str,
    changed_files: &[String],
) -> String {
    let files_list = if changed_files.is_empty() {
        "(none listed)".to_string()
    } else {
        changed_files
            .iter()
            .map(|f| format!("- {f}"))
            .collect::<Vec<_>>()
            .join("\n")
    };
    format!(
        "Draft a {artifact} that an agent could implement against this codebase to reproduce the change described below.\n\n\
         ## Commit message\n\n{commit_message}\n\n\
         ## Files changed\n\n{files_list}\n\n\
         ## Diff (may be truncated)\n\n```\n{diff_text}\n```\n"
    )
}

async fn call_synth(
    daemon_url: &str,
    model: &str,
    system: &str,
    user: &str,
) -> Result<String, String> {
    let url = format!("{}/v1/chat/completions", daemon_url.trim_end_matches('/'));
    let body = serde_json::json!({
        "model": model,
        "temperature": SYNTH_TEMPERATURE,
        "top_p": 1.0,
        "max_tokens": SYNTH_MAX_TOKENS,
        "seed": SYNTH_SEED,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": user},
        ],
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(SYNTH_TIMEOUT_SECS))
        .build()
        .map_err(|e| format!("build http client: {e}"))?;
    let resp = client
        .post(&url)
        .json(&body)
        .send()
        .await
        .map_err(|e| format!("POST /v1/chat/completions: {e}"))?;
    if !resp.status().is_success() {
        let status = resp.status();
        let text = resp.text().await.unwrap_or_default();
        return Err(format!(
            "daemon returned {status}: {}",
            text.chars().take(1024).collect::<String>()
        ));
    }
    let v: serde_json::Value = resp
        .json()
        .await
        .map_err(|e| format!("parse daemon response: {e}"))?;
    let content = v
        .pointer("/choices/0/message/content")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_string();
    if content.is_empty() {
        return Err("daemon returned empty content".into());
    }
    Ok(content)
}

// ─── Git helpers ─────────────────────────────────────────────────

fn git_rev_parse(workdir: &Path, refspec: &str) -> Result<String, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("rev-parse")
        .arg("--verify")
        .arg(refspec)
        .output()
        .map_err(|e| format!("spawn git: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

fn git_commit_message(workdir: &Path, sha: &str) -> Result<String, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("log")
        .arg("-1")
        .arg("--format=%B")
        .arg(sha)
        .output()
        .map_err(|e| format!("spawn git log: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

fn git_diff(workdir: &Path, base: &str, head: &str) -> Result<String, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("diff")
        .arg(format!("{base}..{head}"))
        .output()
        .map_err(|e| format!("spawn git diff: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

fn git_changed_files(workdir: &Path, base: &str, head: &str) -> Result<Vec<String>, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("diff")
        .arg("--name-only")
        .arg(format!("{base}..{head}"))
        .output()
        .map_err(|e| format!("spawn git diff --name-only: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout)
        .lines()
        .filter(|l| !l.trim().is_empty())
        .map(str::to_string)
        .collect())
}

fn git_checkout_new_branch(workdir: &Path, branch: &str, base_sha: &str) -> Result<(), String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("checkout")
        .arg("-b")
        .arg(branch)
        .arg(base_sha)
        .output()
        .map_err(|e| format!("spawn git checkout: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "git checkout -b {branch} {base_sha}: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    Ok(())
}

