//!   re-ingest (useful after a typed-extension prompt iteration).
//! - Run the pass on a corpus whose atoms.json predates the typed-
//!   extension wire-up (e.g. obsidian-vault on the v1→v2 transition).
//! - Smoke-test the orchestrator end-to-end against a running daemon
//!   from a one-line CLI invocation.
//!
//! Idempotent via the `atoms.meta.json` sidecar — a second invocation
//! with no upstream changes prints `status=SkippedManifestMatch` and
//! makes zero LLM calls.

use std::path::PathBuf;
use std::sync::Arc;

use sovereign_core::traits::InferenceProvider;
use sovereign_inference::remote::RemoteApiProvider;
use sovereign_store::sqlite::SqliteStateStore;
use sovereign_tools::typed_extension::{run_typed_extension, ExtractionStatus};

/// Daemon endpoint default. Overridable via `--endpoint <url>` so
/// peer-daemon or worker-pod invocations are possible from the same
/// CLI surface.
const DEFAULT_ENDPOINT: &str = "http://127.0.0.1:9741/v1";

/// Context window the OpenAI-shape RemoteApiProvider claims. The
/// typed-extension prompts cap at ~8K decode tokens; the daemon's
/// real model context is whatever the loaded slot reports. This is
/// just an advertised ceiling for the provider's capabilities surface.
const ADVERTISED_CONTEXT: u32 = 32_768;

pub async fn run(args: &[String]) -> i32 {
    let parsed = match parse_args(args) {
        Ok(p) => p,
        Err(msg) => {
            eprintln!("error: {msg}");
            print_help();
            return 2;
        }
    };
    if parsed.help {
        print_help();
        return 0;
    }

    // Resolve data dir → state db + atlas dir for this corpus.
    let data_dir = match resolve_data_dir() {
        Some(d) => d,
        None => {
            eprintln!("error: cannot resolve data_dir (set HOME or SOVEREIGN_DATA_DIR)");
            return 1;
        }
    };
    let db_path = data_dir.join("sovereign.db");
    let indexes_dir = data_dir.join("indexes");
    // Accept a display name or unique fragment, not just the raw id —
    // ids carry a hash suffix nobody should have to type.
    let corpus_id = match crate::corpus_resolve::resolve_corpus_id(&indexes_dir, &parsed.corpus_id)
    {
        Ok(id) => id,
        Err(msg) => {
            eprintln!("error: {msg}");
            return 1;
        }
    };
    let corpus_dir = match find_corpus_index_path(&indexes_dir, &corpus_id) {
        Some(p) => p,
        None => {
            eprintln!(
                "error: no installed index for corpus '{corpus_id}' under {}",
                indexes_dir.display()
            );
            return 1;
        }
    };
    let atlas_dir = corpus_dir.join("atlas");

    eprintln!("corpus:    {corpus_id}");
    eprintln!("state db:  {}", db_path.display());
    eprintln!("atlas dir: {}", atlas_dir.display());
    eprintln!("endpoint:  {}", parsed.endpoint);
    eprintln!();

    // Open the daemon's state DB read+write — the typed-extension pass
    // only reads (conv_skeletons / conv_raptor_nodes / vault_themes)
    // but SqliteStateStore::open opens read/write.
    let store = match SqliteStateStore::open(&db_path) {
        Ok(s) => Arc::new(s),
        Err(e) => {
            eprintln!("error: open {}: {e}", db_path.display());
            return 1;
        }
    };

    // Build a RemoteApiProvider against the daemon. model_id="" so the
    // daemon's OICP picker routes by latency_class (the pass requests
    // Speed::Slow per spec for precision).
    let inference: Arc<dyn InferenceProvider> = Arc::new(RemoteApiProvider::new(
        &parsed.endpoint,
        None,
        "",
        ADVERTISED_CONTEXT,
    ));

    // --force: drop the idempotency manifest so the pass re-extracts
    // even when RAPTOR/theme hashes are unchanged. The operator use
    // cases are prompt iteration and RUN-VARIANCE estimation (same
    // code + same inputs, fresh sampling) — extraction is stochastic
    // and ±1 axis moves on the bench are inside single-run noise.
    if parsed.force {
        let manifest = atlas_dir.join(sovereign_tools::typed_extension::MANIFEST_FILENAME);
        match std::fs::remove_file(&manifest) {
            Ok(()) => eprintln!("--force: removed {}", manifest.display()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => {
                eprintln!(
                    "error: --force could not remove {}: {e}",
                    manifest.display()
                );
                return 1;
            }
        }
    }

    let started = std::time::Instant::now();
    let report = match run_typed_extension(&corpus_id, &store, &inference, &atlas_dir).await {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: typed extension failed: {e}");
            return 1;
        }
    };
    let elapsed_ms = started.elapsed().as_millis();

    println!();
    println!("  status:         {:?}", report.status);
    println!("  pass A calls:   {}", report.pass_a_calls);
    println!("  pass B calls:   {}", report.pass_b_calls);
    println!("  elapsed:        {}ms", elapsed_ms);
    if !report.atoms_per_kind.is_empty() {
        println!("  atoms per kind:");
        // Stable render order matches the AXIS_CATALOG argumentative
        // entries (see corpus-engine/src/enrichment/atlas/axis_catalog.rs).
        for key in [
            "mechanism",
            "named_position",
            "evidence",
            "opposition",
            "concession",
        ] {
            let count = report.atoms_per_kind.get(key).copied().unwrap_or(0);
            println!("    {:<16} {}", key, count);
        }
    }
    if !report.soft_failures.is_empty() {
        println!(
            "  soft failures:  {} (extraction still wrote what succeeded)",
            report.soft_failures.len()
        );
        for failure in report.soft_failures.iter().take(5) {
            println!("    · {failure}");
        }
        if report.soft_failures.len() > 5 {
            println!("    · …and {} more", report.soft_failures.len() - 5);
        }
    }

    match report.status {
        ExtractionStatus::Wrote => 0,
        ExtractionStatus::WroteEmpty => {
            eprintln!(
                "  ⚠ wrote zero atoms across all five axes — confirm the corpus has \
                 RAPTOR leaves and the daemon model produces argumentative content"
            );
            0
        }
        ExtractionStatus::SkippedManifestMatch => 0,
        ExtractionStatus::SkippedNoInputs => {
            eprintln!(
                "  ⚠ no leaves or themes for this corpus — run `svrn enrich build` \
                 with the tiered pipeline first, or confirm the corpus has Ready conv_skeletons"
            );
            0
        }
    }
}

struct Args {
    corpus_id: String,
    endpoint: String,
    help: bool,
    force: bool,
}

fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut corpus_id: Option<String> = None;
    let mut endpoint = default_endpoint();
    let mut help = false;
    let mut force = false;
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        match a.as_str() {
            "--help" | "-h" => help = true,
            "--force" => force = true,
            "--endpoint" => match iter.next() {
                Some(v) => endpoint = v.clone(),
                None => return Err("--endpoint requires a URL".into()),
            },
            other if other.starts_with("--") => {
                return Err(format!("unknown flag: {other}"));
            }
            other => {
                if corpus_id.is_some() {
                    return Err(format!("unexpected positional argument: {other}"));
                }
                corpus_id = Some(other.to_string());
            }
        }
    }
    Ok(Args {
        corpus_id: corpus_id.unwrap_or_default(),
        endpoint,
        help,
        force,
    })
}

fn print_help() {
    println!(
        "svrn atlas typed-extension <corpus> [--endpoint <url>]\n\
         \n\
         Run the tiered typed-extension LLM pass over an already-built corpus's\n\
         RAPTOR leaves + vault_themes. Writes atoms.json + atoms.meta.json into\n\
         the corpus's atlas/ dir.\n\
         \n\
         <corpus>          Corpus id (must already be installed in the indexes dir).\n\
         --endpoint <url>  Daemon OpenAI-shape endpoint. Default: {endpoint_default}\n\
         --force           Drop the idempotency manifest first — re-extract with\n\
                           unchanged inputs (prompt iteration / run-variance checks).\n\
         \n\
         Idempotent: re-running with no upstream changes prints SkippedManifestMatch\n\
         and makes zero LLM calls. Triggers Slow-slot decode on the daemon (per spec\n\
         §'Open design questions' #3).",
    );
}

fn resolve_data_dir() -> Option<PathBuf> {
    Some(sovereign_contracts::rebrand::data_dir())
}

fn find_corpus_index_path(indexes_dir: &std::path::Path, corpus_id: &str) -> Option<PathBuf> {
    // Canonical path: <indexes>/<corpus_id>. Accept either modern
    // (`_corpus_meta.json` present) or legacy (literary-built corpora
    // without the modern install meta file but with an `atlas/`
    // directory the typed-extension pass can write into).
    let canonical = indexes_dir.join(corpus_id);
    if canonical.is_dir()
        && (canonical.join("_corpus_meta.json").is_file() || canonical.join("atlas").is_dir())
    {
        return Some(canonical);
    }
    let entries = std::fs::read_dir(indexes_dir).ok()?;
    let prefix = format!("{corpus_id}-partition-");
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if name.starts_with(&prefix) && !name.contains('.') {
            return Some(entry.path());
        }
    }
    None
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! The item as it lands: the header block, the store path, and identity.
//!
//! A backlog item IS a notes-store todo carrying `related_entity=backlog`
//! and a header block. There is no backlog store — `scripts/co-backlog.py`
//! reads that same store and ranks it, and the ordering is derived at
//! every read, so an insert here is an O(1) append with nothing to
//! re-index (the priority-queue contract, order backlog-insert-system).

use std::path::{Path, PathBuf};

use corpus_engine_notes::{Note, NoteScope, NoteSource, NoteStore};

use super::ruler::Ruler;
use super::score::Score;

/// The test override, spelled exactly as `scripts/co-backlog.py` spells
/// it (`notes_db_path()`). One name for one path, across two languages.
pub const DB_ENV: &str = "CO_BACKLOG_NOTES_DB";
/// The registered per-user data root (`quality/env-flags.toml`).
pub const DATA_DIR_ENV: &str = "SOVEREIGN_DATA_DIR";

/// The store, NEVER discovered from cwd (invariant 0f8abed1).
///
/// A cwd-sensitive resolver answers confidently from the wrong store:
/// measured on this host, the same query from the repo root and from
/// `$HOME` hit different databases — 68 notes versus 6811 — and exited 0
/// both times. So the path is named, in the same precedence
/// `co-backlog.py` uses, and the verb prints what it resolved.
pub fn notes_db_path(explicit: Option<&Path>) -> PathBuf {
    if let Some(p) = explicit {
        return p.to_path_buf();
    }
    if let Ok(v) = std::env::var(DB_ENV) {
        if !v.is_empty() {
            return PathBuf::from(v);
        }
    }
    if let Ok(v) = std::env::var(DATA_DIR_ENV) {
        if !v.is_empty() {
            return PathBuf::from(v).join("notes.db");
        }
    }
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
    home.join(".sovereign").join("notes.db")
}

/// Everything a producer supplies. Filling this in is the whole job of
/// the verb; the ruler decides the numbers.
pub struct Draft<'a> {
    pub text: &'a str,
    pub objective: Option<&'a str>,
    /// Producer identity, from essence (ARCH §7.5) — a lane name, not a
    /// counter or a row id. A repeat filing under the same key UPDATES
    /// the item it already filed.
    pub key: Option<&'a str>,
    pub producer: &'a str,
    pub score: Option<&'a Score>,
}

/// The header block, rendered in the ruler's declared key order.
///
/// Key ORDER comes from `quality/backlog-ruler.toml`'s `header_keys`, so
/// a key added to the format appears in one file and both languages
/// follow — the Rust writer here and the Python parser that reads it.
pub fn render_header(draft: &Draft<'_>, ruler: &Ruler) -> String {
    let mut fields: Vec<(&str, String)> = Vec::new();
    fields.push((
        "Objective",
        draft
            .objective
            .unwrap_or("unstated — filed without an anchor")
            .to_string(),
    ));
    match draft.score {
        Some(s) => {
            // Only when the model gave one. An empty Title would parse
            // as a malformed header and is worse than no Title at all,
            // which the page handles by falling back to the item's own
            // first sentence.
            if !s.title.trim().is_empty() {
                fields.push(("Title", s.title.trim().to_string()));
            }
            fields.push(("Value", s.value_line(ruler)));
            fields.push(("Cost", format!("{} (session-chunks)", s.cost)));
            fields.push(("Approach", s.approach.trim().to_string()));
        }
        None => {
            // --no-score. The absence is written down, not left blank:
            // an item with no Value renders unscored and sorts last,
            // which is the honest place for it (ARCH §18.3).
            fields.push(("Approach", "unknown — needs a design pass".to_string()));
        }
    }
    if let Some(k) = draft.key {
        fields.push(("Key", k.to_string()));
    }
    fields.push(("Producer", draft.producer.to_string()));
    if let Some(s) = draft.score {
        // The stamp that keeps this unvetted. co-backlog.py's vet()
        // treats its PRESENCE as disqualifying, so a machine-drafted
        // item cannot become pullable by looking complete — a person
        // clears the stamp, and that clearing IS the review.
        fields.push(("Scored-by", s.scored_by.clone()));
    }

    let order: Vec<&str> = ruler
        .format
        .header_keys
        .iter()
        .map(|s| s.as_str())
        .collect();
    let mut lines = Vec::new();
    for key in &order {
        if let Some((_, v)) = fields.iter().find(|(k, _)| k == key) {
            lines.push(format!("{key}: {v}"));
        }
    }
    // Anything the ruler does not declare would be parsed as malformed
    // by the renderer, so it is a bug here, not something to emit and
    // hope about.
    debug_assert!(
        fields.iter().all(|(k, _)| order.contains(k)),
        "emitting a header key the ruler does not declare"
    );
    lines.join("\n")
}

/// The full note body: header block, blank line, then the producer's own
/// words, verbatim. The item's text is never summarized — the score is a
/// draft over it, not a replacement for it.
pub fn render_body(draft: &Draft<'_>, ruler: &Ruler) -> String {
    let mut body = render_header(draft, ruler);
    body.push_str("\n\n");
    if let Some(s) = draft.score {
        body.push_str(&format!(
            "Scored against value ruler v{} ({}) by {}.",
            ruler.version,
            ruler.path.display(),
            s.scored_by
        ));
        if let Some(from) = s.capped_from {
            body.push_str(&format!(
                " The model scored {from}; the ruler's top level requires a \
                 measurement attached and the item text quoted none, so it was \
                 capped to {}.",
                s.value
            ));
        } else if !s.measurement.trim().is_empty() {
            body.push_str(&format!(
                " Measurement quoted from the item text: {}.",
                s.measurement.trim()
            ));
        }
        body.push_str(
            " This is a DRAFT: it renders greyed and cannot be pulled until a \
             person reviews it and clears `Scored-by:`.\n\n",
        );
    } else {
        body.push_str(
            "Filed unscored (--no-score). It has no Value line, so it sorts \
             last and cannot be pulled until someone scores it.\n\n",
        );
    }
    body.push_str(draft.text.trim());
    body.push('\n');
    body
}

/// The `Key:` line of an item body, if it has one. Reads the header
/// block only — the leading run of lines before the first blank — for
/// the same reason the renderer's parser does: prose that happens to
/// contain "Key:" is prose.
pub fn key_of(body: &str) -> Option<String> {
    body.split("\n\n")
        .next()?
        .lines()
        .find_map(|l| l.trim().strip_prefix("Key:").map(|v| v.trim().to_string()))
        .filter(|v| !v.is_empty())
}

/// Where an insert landed, so the verb can say which one happened.
#[derive(Debug)]
pub enum Landed {
    Filed { id: String },
    Updated { id: String, replaced: String },
}

/// File the item, or update the one this key already filed.
///
/// Identity is the producer's `Key` and nothing else (ARCH §7.5): a
/// repeat filing supersedes its predecessor rather than adding a
/// duplicate, so a CI lane that fails nightly leaves one item, not
/// thirty. With no key, every call files a new item — the caller is a
/// person, and people do not want their second thought to eat their
/// first.
pub async fn land(
    db: &Path,
    draft: &Draft<'_>,
    ruler: &Ruler,
    create: bool,
) -> Result<Landed, String> {
    if !db.exists() && !create {
        // Opening would CREATE an empty store. A fresh store at a wrong
        // path is the silent failure this whole path exists to avoid, so
        // absence is refused rather than papered over (ARCH §18.3).
        return Err(format!(
            "no notes store at {} — refusing to create one, because a fresh \
             store at the wrong path looks exactly like a working one. Name \
             the right store with --db, or set {DB_ENV}. If you really are \
             starting a new backlog here, say so with --create.",
            db.display()
        ));
    }
    let store = NoteStore::open(db).map_err(|e| format!("cannot open {}: {e}", db.display()))?;
    let body = render_body(draft, ruler);
    // A fixed session id, not a new env knob: the producer is already
    // recorded on the item's `Producer:` line, and an unregistered env
    // read would have to earn a row in quality/env-flags.toml to say
    // less than the header already does.
    let session_id = "backlog-add";

    let existing: Option<Note> = match draft.key {
        None => None,
        Some(k) => store
            .read_notes_by_related_entity("backlog", &["todo"])
            .await
            .map_err(|e| format!("cannot read the backlog from {}: {e}", db.display()))?
            .into_iter()
            .filter(|r| key_of(&r.content).as_deref() == Some(k))
            // Newest wins if a key somehow has more than one live item;
            // the older ones are left alone rather than mass-retired.
            .max_by(|a, b| a.created_at.cmp(&b.created_at)),
    };

    let id = store
        .write_note_with_source(
            "todo",
            &body,
            Vec::new(),
            Vec::new(),
            session_id,
            NoteScope::Global,
            None,
            Some("backlog"),
            NoteSource::Agent,
            existing.as_ref().map(|r| r.id.as_str()),
        )
        .await
        .map_err(|e| format!("the write failed: {e}"))?;

    match existing {
        None => Ok(Landed::Filed { id }),
        Some(prev) => {
            store
                .retire_by_id(
                    &prev.id,
                    &format!("superseded by {id}: same producer key, re-filed"),
                )
                .await
                .map_err(|e| {
                    format!(
                        "filed {id}, but could not retire the item it replaces ({}): {e}. \
                         The backlog now shows BOTH — retire {} by hand.",
                        prev.id, prev.id
                    )
                })?;
            Ok(Landed::Updated {
                id,
                replaced: prev.id,
            })
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::backlog_cmd::score::parse;

    fn ruler() -> Ruler {
        Ruler::load(None).expect("the repo's own ruler must load")
    }

    fn a_score(ruler: &Ruler) -> Score {
        let mut s = parse(
            r#"{"value":4,"axis":"A","rationale":"A Grounded: cuts wrong-accepts",
                "approach":"extend the existing holdings gate","cost":"S",
                "measurement":""}"#,
            ruler,
        )
        .unwrap();
        s.scored_by = "commonwealth/primary".to_string();
        s
    }

    #[test]
    fn every_emitted_key_is_one_the_ruler_declares() {
        // The cross-language contract: this Rust writes the header and
        // scripts/co-backlog.py parses it, treating an unrecognized key
        // as MALFORMED. So every key emitted here must be in the ruler's
        // declared list — which is also the list the parser reads.
        let r = ruler();
        let s = a_score(&r);
        for draft in [
            Draft {
                text: "t",
                objective: Some("o"),
                key: Some("bench-lane:retrieval-prod"),
                producer: "svrn backlog add",
                score: Some(&s),
            },
            Draft {
                text: "t",
                objective: None,
                key: None,
                producer: "svrn backlog add",
                score: None,
            },
        ] {
            let header = render_header(&draft, &r);
            for line in header.lines() {
                let key = line.split(':').next().unwrap();
                assert!(
                    r.format.header_keys.iter().any(|k| k == key),
                    "emitted key {key:?} is not declared in {}",
                    r.path.display()
                );
            }
        }
    }

    #[test]
    fn the_title_heads_the_header_and_only_when_the_model_gave_one() {
        let r = ruler();
        let mut s = a_score(&r);
        s.title = "Stop the holdings gate accepting absent evidence".to_string();
        let header = render_header(
            &Draft {
                text: "t",
                objective: Some("o"),
                key: None,
                producer: "svrn backlog add",
                score: Some(&s),
            },
            &r,
        );
        assert!(
            header.starts_with("Title: Stop the holdings gate accepting absent evidence\n"),
            "the title is the first header line a reader meets: {header}"
        );

        // An empty title emits NO key. A `Title:` with nothing after it
        // would parse as a malformed header line on the page, which is
        // worse than the renderer's own first-sentence fallback.
        s.title = "   ".to_string();
        let header = render_header(
            &Draft {
                text: "t",
                objective: Some("o"),
                key: None,
                producer: "svrn backlog add",
                score: Some(&s),
            },
            &r,
        );
        assert!(!header.contains("Title:"), "{header}");
    }

    #[test]
    fn a_scored_item_carries_the_stamp_that_keeps_it_unvetted() {
        let r = ruler();
        let s = a_score(&r);
        let body = render_body(
            &Draft {
                text: "the raw item text",
                objective: Some("native grounding H0"),
                key: None,
                producer: "svrn backlog add",
                score: Some(&s),
            },
            &r,
        );
        assert!(body.contains("Scored-by: commonwealth/primary"), "{body}");
        assert!(
            body.contains("Value: 4 — A Grounded: cuts wrong-accepts"),
            "{body}"
        );
        assert!(
            body.contains("the raw item text"),
            "the item's own words survive"
        );
    }

    #[test]
    fn an_unscored_item_carries_no_stamp_and_no_value() {
        let r = ruler();
        let body = render_body(
            &Draft {
                text: "the raw item text",
                objective: None,
                key: None,
                producer: "svrn backlog add",
                score: None,
            },
            &r,
        );
        assert!(!body.contains("Scored-by:"), "{body}");
        assert!(
            !body.contains("Value:"),
            "an unscored item must not claim a value"
        );
    }

    #[test]
    fn the_key_is_read_from_the_header_not_from_the_prose() {
        assert_eq!(
            key_of("Objective: o\nKey: bench-lane:foo\n\nprose\nKey: not-this\n"),
            Some("bench-lane:foo".to_string())
        );
        assert_eq!(key_of("Objective: o\n\nprose\nKey: not-this\n"), None);
        assert_eq!(key_of("Objective: o\nKey:   \n\nprose"), None);
    }

    #[tokio::test]
    async fn an_absent_store_is_refused_not_created() {
        let dir = tempfile::tempdir().unwrap();
        let missing = dir.path().join("nope").join("notes.db");
        let r = ruler();
        let err = land(
            &missing,
            &Draft {
                text: "t",
                objective: None,
                key: None,
                producer: "test",
                score: None,
            },
            &r,
            false,
        )
        .await
        .expect_err("an absent store must refuse");
        assert!(err.contains("refusing to create"), "{err}");
        assert!(!missing.exists(), "refusing must not leave a store behind");
    }

    #[tokio::test]
    async fn a_repeat_key_updates_instead_of_duplicating() {
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("notes.db");
        NoteStore::open(&db).unwrap(); // the store exists; land() refuses otherwise
        let r = ruler();
        let draft = |text: &'static str| Draft {
            text,
            objective: Some("o"),
            key: Some("bench-lane:retrieval-prod"),
            producer: "sovereign-ci-bench.sh",
            score: None,
        };

        let first = land(&db, &draft("failed once"), &r, false).await.unwrap();
        let first_id = match first {
            Landed::Filed { id } => id,
            Landed::Updated { .. } => panic!("the first filing cannot be an update"),
        };

        let second = land(&db, &draft("failed again"), &r, false).await.unwrap();
        match second {
            Landed::Updated { replaced, .. } => assert_eq!(replaced, first_id),
            Landed::Filed { .. } => panic!("a repeat key must update, not duplicate"),
        }

        // And the backlog holds ONE live item, carrying the newer text.
        let store = NoteStore::open(&db).unwrap();
        let live = store
            .read_notes_by_related_entity("backlog", &["todo"])
            .await
            .unwrap();
        assert_eq!(live.len(), 1, "a repeat filing must not leave two items");
        assert!(live[0].content.contains("failed again"));
    }

    #[tokio::test]
    async fn a_different_key_files_a_second_item() {
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("notes.db");
        NoteStore::open(&db).unwrap();
        let r = ruler();
        for key in ["bench-lane:a", "bench-lane:b"] {
            land(
                &db,
                &Draft {
                    text: "t",
                    objective: Some("o"),
                    key: Some(key),
                    producer: "test",
                    score: None,
                },
                &r,
                false,
            )
            .await
            .unwrap();
        }
        let store = NoteStore::open(&db).unwrap();
        let live = store
            .read_notes_by_related_entity("backlog", &["todo"])
            .await
            .unwrap();
        assert_eq!(live.len(), 2, "two lanes are two items");
    }

    #[tokio::test]
    async fn no_key_means_every_filing_is_its_own_item() {
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("notes.db");
        NoteStore::open(&db).unwrap();
        let r = ruler();
        for _ in 0..2 {
            land(
                &db,
                &Draft {
                    text: "a person filing twice",
                    objective: Some("o"),
                    key: None,
                    producer: "test",
                    score: None,
                },
                &r,
                false,
            )
            .await
            .unwrap();
        }
        let store = NoteStore::open(&db).unwrap();
        let live = store
            .read_notes_by_related_entity("backlog", &["todo"])
            .await
            .unwrap();
        assert_eq!(live.len(), 2, "without a key, nothing is superseded");
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Per-phase resource accounting for bench-driven ingest/enrichment.
//!
//! The enrichment pipeline (skeleton, GLiNER, RAPTOR tree) has no
//! token/call ledger of its own — the only resource signal the benches
//! historically recorded was wall-clock. That confounds "the model got
//! faster" with "the pipeline did less work", which is exactly the
//! distinction a tuning experiment needs.
//!
//! [`MeteredInference`] is a transparent decorator over any
//! `InferenceProvider`: every `complete`/`complete_batch` records the
//! call count, prompt/completion token split, and provider-reported
//! latency into the [`ResourceLedger`]; every `embed*` call records
//! text counts and wall time. Streaming calls are counted (no usage
//! metadata flows on the plain stream surface) — the enrichment path
//! under measurement is non-streaming, so this is a completeness
//! backstop, not a gap in the numbers.
//!
//! Buckets are keyed by a phase label the harness sets at pipeline
//! state transitions (`ledger.set_phase("building_skeleton")`). The
//! ingest pipeline is sequential, so attributing calls to the phase
//! that is live when they complete is exact.

use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::time::Instant;

use async_trait::async_trait;
use futures::Stream;
use serde::{Deserialize, Serialize};

use sovereign_core::error::Result;
use sovereign_core::traits::{ComputeChildStatus, InferenceProvider, ResidentSlot};
use sovereign_core::types::{
    CompletionRequest, CompletionResponse, EditSlotInfo, ProviderCapabilities, Speed, StreamFrame,
};

/// Accumulated resource counters for one pipeline phase.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct PhaseBucket {
    /// Non-streaming LLM completions (includes each request inside a
    /// `complete_batch`).
    pub llm_calls: u64,
    /// Streaming LLM calls — counted only; usage isn't reported on the
    /// plain stream surface.
    pub llm_stream_calls: u64,
    /// LLM calls that returned an error.
    pub llm_errors: u64,
    /// Prompt-side tokens across all completions in this phase.
    pub prompt_tokens: u64,
    /// Completion-side tokens. Falls back to
    /// `tokens_used - prompt_tokens` when the provider doesn't report
    /// the split.
    pub completion_tokens: u64,
    /// Wall-clock spent inside `complete`/`complete_batch`, ms.
    pub llm_wall_ms: u64,
    /// Embedding calls (an `embed_batch` counts once here…)
    pub embed_calls: u64,
    /// …and its text count lands here.
    pub embed_texts: u64,
    /// Wall-clock spent inside `embed*`, ms.
    pub embed_wall_ms: u64,
    /// Rerank calls forwarded through the decorator.
    pub rerank_calls: u64,
}

impl PhaseBucket {
    fn add(&mut self, other: &PhaseBucket) {
        self.llm_calls += other.llm_calls;
        self.llm_stream_calls += other.llm_stream_calls;
        self.llm_errors += other.llm_errors;
        self.prompt_tokens += other.prompt_tokens;
        self.completion_tokens += other.completion_tokens;
        self.llm_wall_ms += other.llm_wall_ms;
        self.embed_calls += other.embed_calls;
        self.embed_texts += other.embed_texts;
        self.embed_wall_ms += other.embed_wall_ms;
        self.rerank_calls += other.rerank_calls;
    }

    fn is_empty(&self) -> bool {
        self.llm_calls == 0
            && self.llm_stream_calls == 0
            && self.llm_errors == 0
            && self.embed_calls == 0
            && self.rerank_calls == 0
    }
}

/// One phase's row in the serialized report.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PhaseResources {
    pub phase: String,
    #[serde(flatten)]
    pub bucket: PhaseBucket,
}

/// One metered call, logged individually.
///
/// The phase buckets answer "how much work did this phase do"; they
/// cannot answer "which call family inside the phase is expensive"
/// — several unrelated call families share a phase label (the window
/// skeleton and the RAPTOR tree both run under `building_skeleton`),
/// and a summed `llm_wall_ms` over concurrent calls is not a duration.
/// The per-call log restores both: `start_ms` reconstructs the real
/// concurrency picture, and `prompt_head` identifies the call family
/// without needing a new phase label for every prompt site.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CallRecord {
    /// `"llm"` or `"embed"`.
    pub kind: String,
    /// Phase label live when the call was issued.
    pub phase: String,
    /// Call start, ms since ledger construction (≈ attach). With
    /// `wall_ms` this gives the true overlap structure of a phase.
    pub start_ms: u64,
    pub wall_ms: u64,
    #[serde(default, skip_serializing_if = "is_zero")]
    pub prompt_tokens: u64,
    #[serde(default, skip_serializing_if = "is_zero")]
    pub completion_tokens: u64,
    /// Texts submitted (embed calls only).
    #[serde(default, skip_serializing_if = "is_zero")]
    pub embed_texts: u64,
    /// First ~64 chars of the prompt, whitespace-collapsed — the call
    /// family fingerprint. Empty for embeds.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub prompt_head: String,
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub model: String,
}

fn is_zero(v: &u64) -> bool {
    *v == 0
}

/// Whitespace-collapsed prompt prefix used as the call-family key.
fn prompt_fingerprint(prompt: &str) -> String {
    let collapsed = prompt.split_whitespace().collect::<Vec<_>>().join(" ");
    collapsed.chars().take(64).collect()
}

/// The serialized ledger: ordered per-phase rows + totals + every
/// model id that actually served a metered call (mesh routing can
/// attribute calls to a peer's model — surfacing that is the point).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResourceReport {
    pub phases: Vec<PhaseResources>,
    pub totals: PhaseBucket,
    pub models_seen: Vec<String>,
    /// Per-call detail in completion order. See [`CallRecord`] — this is
    /// what makes "which call family owns this phase's wall clock"
    /// answerable after the fact instead of by re-running with eprintln.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub calls: Vec<CallRecord>,
}

impl ResourceReport {
    /// Fixed-width table for stderr + the markdown report. Empty
    /// phases (label set but no calls landed) are skipped.
    pub fn render_table(&self) -> String {
        use std::fmt::Write as _;
        let mut s = String::new();
        let _ = writeln!(
            s,
            "{:<22} {:>6} {:>8} {:>12} {:>12} {:>9} {:>7} {:>9} {:>9}",
            "phase",
            "calls",
            "streams",
            "prompt_tok",
            "compl_tok",
            "llm_s",
            "embeds",
            "texts",
            "embed_s",
        );
        for row in self.phases.iter().filter(|r| !r.bucket.is_empty()) {
            let b = &row.bucket;
            let _ = writeln!(
                s,
                "{:<22} {:>6} {:>8} {:>12} {:>12} {:>9.1} {:>7} {:>9} {:>9.1}",
                row.phase,
                b.llm_calls,
                b.llm_stream_calls,
                b.prompt_tokens,
                b.completion_tokens,
                b.llm_wall_ms as f64 / 1000.0,
                b.embed_calls,
                b.embed_texts,
                b.embed_wall_ms as f64 / 1000.0,
            );
        }
        let t = &self.totals;
        let _ = writeln!(
            s,
            "{:<22} {:>6} {:>8} {:>12} {:>12} {:>9.1} {:>7} {:>9} {:>9.1}",
            "TOTAL",
            t.llm_calls,
            t.llm_stream_calls,
            t.prompt_tokens,
            t.completion_tokens,
            t.llm_wall_ms as f64 / 1000.0,
            t.embed_calls,
            t.embed_texts,
            t.embed_wall_ms as f64 / 1000.0,
        );
        if t.llm_errors > 0 {
            let _ = writeln!(s, "⚠ {} LLM call(s) errored", t.llm_errors);
        }
        if !self.models_seen.is_empty() {
            let _ = writeln!(s, "models: {}", self.models_seen.join(", "));
        }
        s
    }

    /// Roll the per-call log up by call family (phase + prompt
    /// fingerprint) and render it in first-call order.
    ///
    /// This is the table that says *where the wall clock actually went*.
    /// `window` is elapsed from the family's first call start to its
    /// last call's end — a real duration, unlike the phase bucket's
    /// `llm_wall_ms`, which sums concurrent calls and routinely exceeds
    /// the run length. `p_tok/call` and `c_tok/call` separate
    /// prefill-bound families from decode-bound ones.
    pub fn render_call_families(&self) -> String {
        use std::fmt::Write as _;
        if self.calls.is_empty() {
            return String::new();
        }
        // (phase, head) -> aggregate, in first-appearance order.
        let mut order: Vec<(String, String)> = Vec::new();
        let mut agg: Vec<FamilyAgg> = Vec::new();
        for c in &self.calls {
            let key = (c.phase.clone(), c.prompt_head.clone());
            let idx = match order.iter().position(|k| *k == key) {
                Some(i) => i,
                None => {
                    order.push(key);
                    agg.push(FamilyAgg::new(&c.kind));
                    agg.len() - 1
                }
            };
            agg[idx].absorb(c);
        }
        let mut s = String::new();
        let _ = writeln!(
            s,
            "{:<20} {:>5} {:>10} {:>10} {:>8} {:>8} {:>8}  {}",
            "phase", "n", "p_tok/call", "c_tok/call", "med_s", "window", "start", "call family",
        );
        for (i, (phase, head)) in order.iter().enumerate() {
            let a = &agg[i];
            let label = if a.kind == "embed" {
                format!("<embed {} texts>", a.embed_texts)
            } else if head.is_empty() {
                "<no prompt>".to_string()
            } else {
                head.chars().take(52).collect()
            };
            let _ = writeln!(
                s,
                "{:<20} {:>5} {:>10} {:>10} {:>8.1} {:>8.1} {:>8.1}  {}",
                phase,
                a.n,
                a.prompt_tokens / a.n.max(1),
                a.completion_tokens / a.n.max(1),
                a.median_wall_ms() as f64 / 1000.0,
                (a.last_end_ms.saturating_sub(a.first_start_ms)) as f64 / 1000.0,
                a.first_start_ms as f64 / 1000.0,
                label,
            );
        }
        s
    }
}

/// Accumulator behind [`ResourceReport::render_call_families`].
struct FamilyAgg {
    kind: String,
    n: u64,
    prompt_tokens: u64,
    completion_tokens: u64,
    embed_texts: u64,
    first_start_ms: u64,
    last_end_ms: u64,
    walls: Vec<u64>,
}

impl FamilyAgg {
    fn new(kind: &str) -> Self {
        Self {
            kind: kind.to_string(),
            n: 0,
            prompt_tokens: 0,
            completion_tokens: 0,
            embed_texts: 0,
            first_start_ms: u64::MAX,
            last_end_ms: 0,
            walls: Vec::new(),
        }
    }

    fn absorb(&mut self, c: &CallRecord) {
        self.n += 1;
        self.prompt_tokens += c.prompt_tokens;
        self.completion_tokens += c.completion_tokens;
        self.embed_texts += c.embed_texts;
        self.first_start_ms = self.first_start_ms.min(c.start_ms);
        self.last_end_ms = self.last_end_ms.max(c.start_ms + c.wall_ms);
        self.walls.push(c.wall_ms);
    }

    fn median_wall_ms(&self) -> u64 {
        if self.walls.is_empty() {
            return 0;
        }
        let mut w = self.walls.clone();
        w.sort_unstable();
        w[w.len() / 2]
    }
}

#[derive(Default)]
struct LedgerInner {
    /// Ordered (phase, bucket) — Vec keeps first-set-phase ordering so
    /// the report reads in pipeline order.
    phases: Vec<(String, PhaseBucket)>,
    current: String,
    models_seen: Vec<String>,
    calls: Vec<CallRecord>,
}

impl LedgerInner {
    fn bucket(&mut self) -> &mut PhaseBucket {
        // Split borrow dance: find index first, then index mutably.
        let cur = self.current.clone();
        if let Some(i) = self.phases.iter().position(|(p, _)| *p == cur) {
            &mut self.phases[i].1
        } else {
            self.phases.push((cur, PhaseBucket::default()));
            &mut self.phases.last_mut().expect("just pushed").1
        }
    }
}

/// Shared, phase-labelled resource accumulator. Cheap to clone the
/// `Arc`; all mutation is behind one short-hold `Mutex` (the metered
/// calls are seconds-long; the lock hold is nanoseconds).
pub struct ResourceLedger {
    inner: Mutex<LedgerInner>,
    /// Zero point for `CallRecord::start_ms` — ledger construction,
    /// which the harness does immediately before attach.
    origin: Instant,
}

impl ResourceLedger {
    pub fn new() -> Self {
        Self {
            inner: Mutex::new(LedgerInner {
                phases: Vec::new(),
                current: "setup".to_string(),
                models_seen: Vec::new(),
                calls: Vec::new(),
            }),
            origin: Instant::now(),
        }
    }

    /// Ms since ledger construction — the `start_ms` clock.
    fn now_ms(&self) -> u64 {
        self.origin.elapsed().as_millis() as u64
    }

    fn push_call(&self, rec: CallRecord) {
        if let Ok(mut g) = self.inner.lock() {
            g.calls.push(rec);
        }
    }

    /// Switch the attribution bucket. Idempotent per label — calls
    /// after a repeated label accumulate into the same bucket.
    pub fn set_phase(&self, phase: &str) {
        if let Ok(mut g) = self.inner.lock() {
            g.current = phase.to_string();
        }
    }

    fn record_completion(
        &self,
        prompt: &str,
        resp: &CompletionResponse,
        start_ms: u64,
        wall_ms: u64,
    ) {
        let rec = if let Ok(mut g) = self.inner.lock() {
            let model = resp.model_id.clone();
            if !model.is_empty() && !g.models_seen.contains(&model) {
                g.models_seen.push(model);
            }
            let phase = g.current.clone();
            let completion = resp
                .completion_tokens
                .map(u64::from)
                .unwrap_or_else(|| (resp.tokens_used.saturating_sub(resp.prompt_tokens)) as u64);
            let b = g.bucket();
            b.llm_calls += 1;
            b.prompt_tokens += resp.prompt_tokens as u64;
            b.completion_tokens += completion;
            b.llm_wall_ms += wall_ms;
            Some(CallRecord {
                kind: "llm".to_string(),
                phase,
                start_ms,
                wall_ms,
                prompt_tokens: resp.prompt_tokens as u64,
                completion_tokens: completion,
                embed_texts: 0,
                prompt_head: prompt_fingerprint(prompt),
                model: resp.model_id.clone(),
            })
        } else {
            None
        };
        if let Some(rec) = rec {
            self.push_call(rec);
        }
    }

    fn record_llm_error(&self, wall_ms: u64) {
        if let Ok(mut g) = self.inner.lock() {
            let b = g.bucket();
            b.llm_errors += 1;
            b.llm_wall_ms += wall_ms;
        }
    }

    fn record_stream_call(&self) {
        if let Ok(mut g) = self.inner.lock() {
            g.bucket().llm_stream_calls += 1;
        }
    }

    fn record_embed(&self, texts: u64, start_ms: u64, wall_ms: u64) {
        let rec = if let Ok(mut g) = self.inner.lock() {
            let phase = g.current.clone();
            let b = g.bucket();
            b.embed_calls += 1;
            b.embed_texts += texts;
            b.embed_wall_ms += wall_ms;
            Some(CallRecord {
                kind: "embed".to_string(),
                phase,
                start_ms,
                wall_ms,
                prompt_tokens: 0,
                completion_tokens: 0,
                embed_texts: texts,
                prompt_head: String::new(),
                model: String::new(),
            })
        } else {
            None
        };
        if let Some(rec) = rec {
            self.push_call(rec);
        }
    }

    fn record_rerank(&self) {
        if let Ok(mut g) = self.inner.lock() {
            g.bucket().rerank_calls += 1;
        }
    }

    pub fn snapshot(&self) -> ResourceReport {
        let g = self.inner.lock().expect("ledger lock poisoned");
        let phases: Vec<PhaseResources> = g
            .phases
            .iter()
            .map(|(p, b)| PhaseResources {
                phase: p.clone(),
                bucket: b.clone(),
            })
            .collect();
        let mut totals = PhaseBucket::default();
        for row in &phases {
            totals.add(&row.bucket);
        }
        let mut calls = g.calls.clone();
        calls.sort_by_key(|c| c.start_ms);
        ResourceReport {
            phases,
            totals,
            models_seen: g.models_seen.clone(),
            calls,
        }
    }
}

/// Transparent metering decorator. Forwards every trait method to the
/// wrapped provider (so mesh-aware overrides keep working) and records
/// usage into the shared ledger.
pub struct MeteredInference {
    inner: Arc<dyn InferenceProvider>,
    ledger: Arc<ResourceLedger>,
}

impl MeteredInference {
    pub fn new(inner: Arc<dyn InferenceProvider>, ledger: Arc<ResourceLedger>) -> Self {
        Self { inner, ledger }
    }
}

#[async_trait]
impl InferenceProvider for MeteredInference {
    async fn complete(&self, request: &CompletionRequest) -> Result<CompletionResponse> {
        let start_ms = self.ledger.now_ms();
        let start = Instant::now();
        let result = self.inner.complete(request).await;
        let wall_ms = start.elapsed().as_millis() as u64;
        match &result {
            Ok(resp) => self
                .ledger
                .record_completion(&request.prompt, resp, start_ms, wall_ms),
            Err(_) => self.ledger.record_llm_error(wall_ms),
        }
        result
    }

    async fn complete_batch(
        &self,
        requests: &[CompletionRequest],
    ) -> Result<Vec<CompletionResponse>> {
        let start_ms = self.ledger.now_ms();
        let start = Instant::now();
        let result = self.inner.complete_batch(requests).await;
        let wall_ms = start.elapsed().as_millis() as u64;
        match &result {
            Ok(responses) => {
                // Attribute the batch's wall time to its first response;
                // per-response provider latency is already in each row.
                for (i, resp) in responses.iter().enumerate() {
                    let prompt = requests.get(i).map(|r| r.prompt.as_str()).unwrap_or("");
                    self.ledger.record_completion(
                        prompt,
                        resp,
                        start_ms,
                        if i == 0 { wall_ms } else { 0 },
                    );
                }
            }
            Err(_) => self.ledger.record_llm_error(wall_ms),
        }
        result
    }

    async fn complete_stream(
        &self,
        request: &CompletionRequest,
    ) -> Result<Pin<Box<dyn Stream<Item = Result<String>> + Send>>> {
        self.ledger.record_stream_call();
        self.inner.complete_stream(request).await
    }

    async fn complete_stream_with_id(
        &self,
        request: &CompletionRequest,
    ) -> Result<(Pin<Box<dyn Stream<Item = Result<String>> + Send>>, String)> {
        self.ledger.record_stream_call();
        self.inner.complete_stream_with_id(request).await
    }

    async fn complete_stream_with_finish(
        &self,
        request: &CompletionRequest,
    ) -> Result<Pin<Box<dyn Stream<Item = StreamFrame> + Send>>> {
        self.ledger.record_stream_call();
        self.inner.complete_stream_with_finish(request).await
    }

    async fn complete_stream_with_id_and_finish(
        &self,
        request: &CompletionRequest,
    ) -> Result<(Pin<Box<dyn Stream<Item = StreamFrame> + Send>>, String)> {
        self.ledger.record_stream_call();
        self.inner.complete_stream_with_id_and_finish(request).await
    }

    async fn embed(&self, text: &str) -> Result<Vec<f32>> {
        let start_ms = self.ledger.now_ms();
        let start = Instant::now();
        let result = self.inner.embed(text).await;
        self.ledger
            .record_embed(1, start_ms, start.elapsed().as_millis() as u64);
        result
    }

    async fn embed_batch(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        let start_ms = self.ledger.now_ms();
        let start = Instant::now();
        let result = self.inner.embed_batch(texts).await;
        self.ledger.record_embed(
            texts.len() as u64,
            start_ms,
            start.elapsed().as_millis() as u64,
        );
        result
    }

    async fn embed_query(&self, query: &str) -> Result<Vec<f32>> {
        let start_ms = self.ledger.now_ms();
        let start = Instant::now();
        let result = self.inner.embed_query(query).await;
        self.ledger
            .record_embed(1, start_ms, start.elapsed().as_millis() as u64);
        result
    }

    async fn rerank_batch(&self, query: &str, docs: &[String]) -> Result<Vec<f32>> {
        self.ledger.record_rerank();
        self.inner.rerank_batch(query, docs).await
    }

