    eprintln!("  --daemon <url>           Daemon base URL (default http://localhost:9741).");
    eprintln!("  --calibrate              Score the judge against the hand-labeled situatedness");
    eprintln!("                           bank; gates on sensitivity/specificity >= 0.85.");
