// SPDX-License-Identifier: AGPL-3.0-or-later
//! Situated-lane judging loop.
//!
//! No generation happens here — see [`super::transcripts`] for why. The loop
//! is: for each banked probe, bind the criteria its question type calls for,
//! judge each one against the response the production turn produced, and
//! aggregate through the shared rubric core.

use std::time::Instant;

use sovereign_inference::remote::RemoteApiProvider;

use super::criteria::{self, Vocabulary};
use super::report::{ProbeReport, SituatedRun};
use super::transcripts::Transcript;
use crate::bench_cmd::rubric::judge::{self, CriterionVerdict};
use crate::bench_cmd::rubric::score::{aggregate, score_item, CriterionOutcome};

pub struct RunOptions {
    pub daemon_base: String,
    pub judge_model: String,
    pub judge_trials: u8,
    pub subject_model: String,
    pub transcripts_path: String,
    pub criteria_path: String,
    pub transcripts_skipped: usize,
}

pub async fn run(
    transcripts: &[Transcript],
    vocab: &Vocabulary,
    opts: &RunOptions,
) -> Result<SituatedRun, String> {
    let v1 = format!("{}/v1", opts.daemon_base.trim_end_matches('/'));
    let judge_provider = RemoteApiProvider::new(&v1, None, &opts.judge_model, 16384);

    if opts.subject_model == opts.judge_model {
        eprintln!(
            "bench situated: WARNING — judge model equals the model under test ({}); \
             self-judging conflates the rater with the rated (ARCH_PRINCIPLES §7.6). \
             Pin a different --judge-model for comparable scores.",
            opts.judge_model
        );
    }

    let mut probes: Vec<ProbeReport> = Vec::with_capacity(transcripts.len());
    for (idx, t) in transcripts.iter().enumerate() {
        let bound = criteria::bind(vocab, &t.id, t.qtype);
        eprintln!(
            "bench situated: [{}/{}] {} ({}, {} criteria)",
            idx + 1,
            transcripts.len(),
            t.id,
            t.qtype.label(),
            bound.len()
        );

        let started = Instant::now();
        let judged_text = t.judged_text();
        let mut outcomes = Vec::with_capacity(bound.len());
        for c in &bound {
            // STRUCTURAL criteria are READ from what the production gate
            // decided, never re-derived by the judge. `cites_a_source` is the
            // whole reason this branch exists: the gate resolves the
            // chunk→section join and knows exactly how many locators it
            // released, while a judge can only squint at the prose. Measured
            // 2026-08-05 on the saltgrass compound bank, the judged version
            // scored 3 real citations as 1 — it credited the one answer that
            // did NOT disclose a gap and declined both that did, because a
            // trailing "the passages do not answer X" distracted it, and it
            // stayed wrong under --judge-trials 3, so this was a stable bias
            // and not noise. The answer it rewarded was also the fabricating
            // one. A criterion that pays for fabrication and fines disclosure
            // cannot measure situatedness, and no rewording fixes a decider
            // that is downstream of the fact (§10.6).
            //
            // Only criteria whose truth the gate actually OWNS belong here.
            // Everything else stays judged — "is the gap statement specific",
            // "is this padded", "does it lecture" are genuine judgements the
            // system holds no answer to.
            if c.key == "cites_a_source" {
                let verdict = match t.cites_a_source() {
                    Some(cited) => CriterionVerdict {
                        verdict: Some(if cited {
                            judge::Ballot::Yes
                        } else {
                            judge::Ballot::No
                        }),
                        evidence: format!(
                            "structural: gate released {} located quote(s)",
                            t.citation_located.unwrap_or(0)
                        ),
                        // One "trial" — the gate's own decision. Recorded as a
                        // trial so the per-criterion table reads uniformly, and
                        // it is deterministic, so --judge-trials cannot move it.
                        trials_yes: u32::from(cited),
                        trials_no: u32::from(!cited),
                        trials_failed: 0,
                    },
                    // ONLY a transcript banked before the gate persisted the
                    // count lands here — a turn that abstained or took the
                    // legacy ladder writes 0, which is a miss, not an unknown.
                    // Scored as could-not-judge so an old transcript cannot
                    // manufacture a regression it never had (§18.3).
                    None => CriterionVerdict {
                        verdict: None,
                        evidence: "structural: transcript predates the gate's located-quote count"
                            .to_string(),
                        trials_yes: 0,
                        trials_no: 0,
                        trials_failed: 0,
                    },
                };
                outcomes.push(CriterionOutcome {
                    criterion_id: c.id.clone(),
                    dimension: c.dimension.clone(),
                    weight: c.weight,
                    verdict,
                });
                eprint!("=");
                continue;
            }
            // An empty response is could-not-judge on every criterion, not a
            // zero: nothing was observed, so nothing may be scored.
            let verdict = if t.is_judgeable() {
                judge::judge_criterion(
                    &judge_provider,
                    &judged_text,
                    &c.text,
                    Some(&opts.judge_model),
                    opts.judge_trials,
                )
                .await
            } else {
                CriterionVerdict {
                    verdict: None,
                    evidence: "no visible response to judge".to_string(),
                    trials_yes: 0,
                    trials_no: 0,
                    trials_failed: 0,
                }
            };
            outcomes.push(CriterionOutcome {
                criterion_id: c.id.clone(),
                dimension: c.dimension.clone(),
                weight: c.weight,
                verdict,
            });
            eprint!(".");
        }
        eprintln!();
        let judge_ms_total = started.elapsed().as_millis() as u64;

        let could_not_judge = outcomes
            .iter()
            .filter(|o| o.verdict.verdict.is_none())
            .count();
        let score = score_item(&outcomes);
        match score {
            Some(s) => eprintln!(
                "  score {s:.1}  (judge {:.1}s)",
                judge_ms_total as f64 / 1000.0
            ),
            None => eprintln!("  score n/a — every criterion could-not-judge"),
        }
        probes.push(ProbeReport {
            probe_id: t.id.clone(),
            qtype: t.qtype.label().to_string(),
            score,
            criteria: outcomes,
            could_not_judge,
            response: t.answer.clone(),
            gate_action: t.gate_action.clone(),
            judge_ms_total,
        });
    }

    let aggregate = aggregate(&probes);
    Ok(SituatedRun {
        started_at_unix: chrono::Utc::now().timestamp(),
        subject_model: opts.subject_model.clone(),
        judge_model: opts.judge_model.clone(),
        judge_trials: opts.judge_trials.max(1),
        transcripts_path: opts.transcripts_path.clone(),
        criteria_path: opts.criteria_path.clone(),
        criteria_version: vocab.meta.version,
        criteria_status: vocab.meta.status.clone(),
        transcripts_skipped: opts.transcripts_skipped,
        probes,
        aggregate,
    })
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn bench uap run|diagnose` — disposition-classification bench
//! for the `uap-blue-book` corpus. The classification analog of
//! `svrn bench enron` (entity resolution).
//!
//! `run` classifies each case's disposition via the daemon chat model
//! (schema-constrained to the era-possible category set), scores against
//! the frozen `gold_labels.jsonl` via
//! `sovereign_eval::disposition_score`, and persists the outcome.
//!
//! Two policies:
//!   - `baseline` — raw case narrative only (the floor).
//!   - `tuned` — narrative + the case's extracted observation features
//!     (shape / location). Both apply the date-conditioned era mask to
//!     the grammar enum, since predicting "Starlink" for a 1952 case is
//!     never legitimate — the mask is a correctness floor, not the tuning
//!     lever. The tuning lever is the feature context.
//!
//! Split discipline (reused verbatim from the Enron bench): the runner
//! refuses to score `holdout` without `--unseal-holdout`, which burns a
//! counter in `peek_budget.json`.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::time::Duration;

use serde::{Deserialize, Serialize};
use sovereign_eval::disposition_bench::{
    load_fixture_cases, FixtureCase, GoldLabels, PeekBudget, Split,
};
use sovereign_eval::disposition_score::{score_with_axis, DispositionReport, Labeling};
use sovereign_eval::disposition_taxonomy::{era_mask, era_mask_union, year_of};

use corpus_engine::enrichment::pipeline::types::ChatPrompt;

use sovereign_cli_shared::help::{self, Help, HelpSection};

const HELP: Help = Help {
    command: "svrn bench uap",
    summary: "Disposition-classification bench over the uap-blue-book corpus.",
    sections: &[
        HelpSection::Usage(
            "svrn bench uap run --corpus uap-blue-book --split {train|test|holdout} [--policy {baseline|tuned}] [--base-url <url>] [--no-strip-disposition-tail] [--unseal-holdout] [--bench-dir <path>] [--out <path>]",
        ),
        HelpSection::Subcommands(&[
            ("run", "Classify each case's disposition and score against the frozen gold labels."),
            ("diagnose", "Glass-box: confusion matrix + per-category P/R/F1 + worst over-confused pairs (tuned policy)."),
        ]),
        HelpSection::Notes(
            "Reads case narratives from <bench-dir>/fixtures/cases.jsonl and gold \
             from <bench-dir>/gold_labels.jsonl. Classifies via the daemon at \
             --base-url (default http://127.0.0.1:9741), constraining the label \
             set to the era-possible categories per case date. baseline = raw \
             narrative; tuned = narrative + extracted features. The synthetic \
             fixture states the disposition in prose; --no-strip-disposition-tail \
             keeps that sentence (default strips it so the baseline isn't trivial).",
        ),
    ],
};

const BENCH_ID: &str = "uap-disposition";
const DEFAULT_BASE_URL: &str = "http://127.0.0.1:9741";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Policy {
    Baseline,
    Tuned,
}

impl Policy {
    fn parse(s: &str) -> Option<Self> {
        match s {
            "baseline" | "floor" => Some(Policy::Baseline),
            "tuned" => Some(Policy::Tuned),
            _ => None,
        }
    }
    fn as_str(&self) -> &'static str {
        match self {
            Policy::Baseline => "baseline",
            Policy::Tuned => "tuned",
        }
    }
}

#[derive(Debug)]
struct Args {
    corpus: String,
    split: Split,
    policy: Policy,
    unseal_holdout: bool,
    bench_dir: PathBuf,
    out: Option<PathBuf>,
    base_url: String,
    strip_disposition_tail: bool,
    max_tokens: u32,
}

fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut corpus: Option<String> = None;
    let mut split: Option<Split> = None;
    let mut policy = Policy::Baseline;
    let mut unseal_holdout = false;
    let mut bench_dir: Option<PathBuf> = None;
    let mut out: Option<PathBuf> = None;
    let mut base_url: Option<String> = None;
    let mut strip_disposition_tail = true;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--corpus" => {
                i += 1;
                corpus = Some(
                    args.get(i)
                        .ok_or_else(|| "--corpus requires a value".to_string())?
                        .clone(),
                );
            }
            "--split" => {
                i += 1;
                let v = args
                    .get(i)
                    .ok_or_else(|| "--split requires a value".to_string())?;
                split = Some(match v.as_str() {
                    "train" => Split::Train,
                    "test" => Split::Test,
                    "holdout" => Split::Holdout,
                    other => return Err(format!("unknown split: {other}")),
                });
            }
            "--policy" => {
                i += 1;
                let v = args
                    .get(i)
                    .ok_or_else(|| "--policy requires a value".to_string())?;
                policy = Policy::parse(v)
                    .ok_or_else(|| format!("unknown policy: {v}; expected baseline|tuned"))?;
            }
            "--unseal-holdout" => unseal_holdout = true,
            "--no-strip-disposition-tail" => strip_disposition_tail = false,
            "--bench-dir" => {
                i += 1;
                bench_dir = Some(PathBuf::from(
                    args.get(i)
                        .ok_or_else(|| "--bench-dir requires a value".to_string())?,
                ));
            }
            "--out" => {
                i += 1;
                out = Some(PathBuf::from(
                    args.get(i)
                        .ok_or_else(|| "--out requires a value".to_string())?,
                ));
            }
            "--base-url" => {
                i += 1;
                base_url = Some(
                    args.get(i)
                        .ok_or_else(|| "--base-url requires a value".to_string())?
                        .clone(),
                );
            }
            "--help" | "-h" => {
                help::print(&HELP);
                return Err("__HELP__".into());
            }
            other => return Err(format!("unknown flag: {other}")),
        }
        i += 1;
    }
    let corpus = corpus.unwrap_or_else(|| "uap-blue-book".to_string());
    let split = split.ok_or_else(|| "--split is required".to_string())?;
    Ok(Args {
        corpus,
        split,
        policy,
        unseal_holdout,
        bench_dir: bench_dir.unwrap_or_else(default_bench_dir),
        out,
        base_url: base_url.unwrap_or_else(default_base_url),
        strip_disposition_tail,
        max_tokens: 64,
    })
}

fn default_bench_dir() -> PathBuf {
    if let Ok(cwd) = std::env::current_dir() {
        let candidate = cwd.join("sovereign/bench/uap");
        if candidate.exists() {
            return candidate;
        }
        if let Some(parent) = cwd.parent() {
            let candidate = parent.join("sovereign/bench/uap");
            if candidate.exists() {
                return candidate;
            }
        }
    }
    PathBuf::from("sovereign/bench/uap")
}

use sovereign_core::time::unix_now as now_secs;

fn git_head_short() -> Option<String> {
    std::process::Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
}

// ── outcome record ───────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
struct UapBenchOutcome {
    schema_version: u32,
    bench_id: String,
    policy_kind: String,
    split: String,
    corpus: String,
    model_id: String,
    captured_ts_unix: i64,
    accuracy: f64,
    macro_f1: f64,
    n_aligned: usize,
    era_axis: Vec<String>,
    confusion_matrix: serde_json::Value,
    per_category: serde_json::Value,
    source: String,
    delta_from_baseline_accuracy: Option<f64>,
    notes: String,
}

// ── entry ────────────────────────────────────────────────────────────

pub async fn cmd_uap(args: &[String]) -> i32 {
    let Some(first) = args.first() else {
        help::print(&HELP);
        return 2;
    };
    match first.as_str() {
        "run" => match cmd_run(&args[1..]).await {
            Ok(code) => code,
            Err(e) if e == "__HELP__" => 0,
            Err(e) => {
                eprintln!("error: {e}");
                2
            }
        },
        "diagnose" => match cmd_diagnose(&args[1..]).await {
            Ok(code) => code,
            Err(e) if e == "__HELP__" => 0,
            Err(e) => {
                eprintln!("error: {e}");
                2
            }
        },
        "--help" | "-h" => {
            help::print(&HELP);
            0
        }
        other => {
            eprintln!("unknown subcommand: {other}");
            help::print(&HELP);
            2
        }
    }
}

/// Shared classification pass: classify every gold case in the split,
/// returning (predicted labeling, model_id, gold labeling, era axis).
async fn classify_split(
    parsed: &Args,
) -> Result<(Labeling, String, Labeling, Vec<String>), String> {
    // Gold.
    let gold_path = parsed.bench_dir.join("gold_labels.jsonl");
    let gold = GoldLabels::load(&gold_path)
        .map_err(|e| format!("loading {}: {e}", gold_path.display()))?;
    let gold_labeling = gold.as_gold_labeling(parsed.split);
    if gold_labeling.is_empty() {
        return Err(format!(
            "no gold cases in split '{}' (or all sealed) at {}",
            parsed.split.as_str(),
            gold_path.display()
        ));
    }

    // Fixture narratives, keyed by case_id.
    let cases_path = parsed.bench_dir.join("fixtures/cases.jsonl");
    let cases = load_fixture_cases(&cases_path)
        .map_err(|e| format!("loading {}: {e}", cases_path.display()))?;
    let by_id: BTreeMap<String, FixtureCase> =
        cases.into_iter().map(|c| (c.case_id.clone(), c)).collect();

    // Era axis for the split (union of case years).
    let years: Vec<i32> = gold_labeling
        .keys()
        .filter_map(|id| by_id.get(id))
        .filter_map(|c| year_of(&c.date))
        .collect();
    let axis = era_mask_union(years);

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(600))
        .build()
        .map_err(|e| format!("http client: {e}"))?;

    let mut predicted: Labeling = Labeling::new();
    let mut model_id = String::new();
    let mut case_ids: Vec<&String> = gold_labeling.keys().collect();
    case_ids.sort();
    for case_id in case_ids {
        let Some(case) = by_id.get(case_id) else {
            // No narrative — can't classify; mark insufficient.
            predicted.insert(case_id.clone(), "INSUFFICIENT_DATA".to_string());
            continue;
        };
        let year = year_of(&case.date).unwrap_or(2024);
        let allowed = era_mask(year);
        let prompt = build_prompt(case, &allowed, parsed.policy, parsed.strip_disposition_tail);
        match run_chat(&client, &parsed.base_url, &prompt, parsed.max_tokens).await {
            Ok(resp) => {
                if model_id.is_empty() {
                    model_id = resp.model.clone();
                }
                let cat = parse_category(&resp.content).unwrap_or_else(|| {
                    eprintln!(
                        "  warn: {case_id}: could not parse category from response: {}",
                        resp.content.chars().take(120).collect::<String>()
                    );
                    "INSUFFICIENT_DATA".to_string()
                });
                predicted.insert(case_id.clone(), cat);
            }
            Err(e) => {
                eprintln!("  warn: {case_id}: classify failed: {e}");
                predicted.insert(case_id.clone(), "INSUFFICIENT_DATA".to_string());
            }
        }
    }

    Ok((predicted, model_id, gold_labeling, axis))
}

fn build_prompt(
    case: &FixtureCase,
    allowed: &[String],
    policy: Policy,
    strip_tail: bool,
) -> ChatPrompt {
    let narrative = if strip_tail {
        strip_disposition_sentence(&case.narrative)
    } else {
        case.narrative.clone()
    };
    let system = "You are adjudicating a historical UAP case into exactly one \
                  disposition category. Decide the single best category from the \
                  allowed list. Return JSON only."
        .to_string();
    let mut user = String::new();
    if policy == Policy::Tuned {
        // Tuned policy: inject the extracted observation features.
        user.push_str("Extracted features:\n");
        if let Some(shape) = &case.shape {
            user.push_str(&format!("- observed shape: {shape}\n"));
        }
        if let Some(loc) = &case.location {
            user.push_str(&format!("- location: {loc}\n"));
        }
        user.push('\n');
    }
    user.push_str("Case narrative:\n");
    user.push_str(&narrative);
    user.push_str(&format!(
        "\n\nAllowed categories: {}.\nRespond as JSON: {{\"category\": \"<one of the allowed>\"}}.",
        allowed.join(", ")
    ));

    let schema = serde_json::json!({
        "type": "object",
        "properties": {
            "category": { "type": "string", "enum": allowed }
        },
        "required": ["category"],
        "additionalProperties": false
    });
    ChatPrompt::new(system, user).with_response_schema("uap_disposition", schema)
}

/// Strip a trailing "Disposition: X." sentence so the synthetic fixture
/// doesn't hand the classifier its own answer.
fn strip_disposition_sentence(narrative: &str) -> String {
    // Case-insensitive: find the last "Disposition:" and cut from there.
    let lower = narrative.to_ascii_lowercase();
    if let Some(idx) = lower.rfind("disposition:") {
        narrative[..idx].trim_end().to_string()
    } else {
        narrative.to_string()
    }
}

fn parse_category(content: &str) -> Option<String> {
    // Strip think/code fences defensively, then parse {"category": "..."}.
    let cleaned = content
        .trim()
        .trim_start_matches("```json")
        .trim_start_matches("```");
    let cleaned = cleaned.split("```").next().unwrap_or(cleaned).trim();
    let v: serde_json::Value = serde_json::from_str(cleaned).ok()?;
    v.get("category")?.as_str().map(|s| s.to_string())
}

// ── run ──────────────────────────────────────────────────────────────

async fn cmd_run(args: &[String]) -> Result<i32, String> {
    let parsed = parse_args(args)?;

    // Holdout gate (reused discipline).
    if parsed.split.requires_unseal() && !parsed.unseal_holdout {
        return Err(format!(
            "refusing to run the '{}' split without --unseal-holdout (peek-budget gated)",
            parsed.split.as_str()
        ));
    }
    if parsed.split.requires_unseal() && parsed.unseal_holdout {
        let budget_path = parsed
            .bench_dir
            .join("baselines")
            .join(BENCH_ID)
            .join("peek_budget.json");
        let mut budget = PeekBudget::load(&budget_path).map_err(|e| format!("peek budget: {e}"))?;
        let n = budget.burn(
            "--unseal-holdout from `svrn bench uap run`",
            git_head_short(),
        );
        budget
            .save(&budget_path)
            .map_err(|e| format!("peek budget save: {e}"))?;
        eprintln!(
            "⚠ holdout unsealed; peek #{n} recorded in {}",
            budget_path.display()
        );
    }

    let (predicted, model_id, gold, axis) = classify_split(&parsed).await?;
    let report = score_with_axis(&predicted, &gold, &axis);

    print_summary(&parsed, &model_id, &report);

    // Delta vs baseline.
    let baseline_path = parsed
        .bench_dir
        .join("baselines")
        .join(BENCH_ID)
        .join("baseline.json");
    let delta = compute_delta_from_baseline(&baseline_path, report.accuracy);

    // Persist.
    let out_path = parsed.out.clone().unwrap_or_else(|| {
        let name = match parsed.policy {
            Policy::Baseline => "baseline.json",
            Policy::Tuned => "latest.json",
        };
        parsed.bench_dir.join("baselines").join(BENCH_ID).join(name)
    });
    let outcome = UapBenchOutcome {
        schema_version: 1,
        bench_id: BENCH_ID.to_string(),
        policy_kind: parsed.policy.as_str().to_string(),
        split: parsed.split.as_str().to_string(),
        corpus: parsed.corpus.clone(),
        model_id,
        captured_ts_unix: now_secs(),
        accuracy: report.accuracy,
        macro_f1: report.macro_f1,
        n_aligned: report.n_aligned,
        era_axis: report.confusion_matrix.categories.clone(),
        confusion_matrix: serde_json::to_value(&report.confusion_matrix).unwrap_or_default(),
        per_category: serde_json::to_value(&report.per_category).unwrap_or_default(),
        source: "fixture".to_string(),
        delta_from_baseline_accuracy: delta,
        notes: format!(
            "Written by `svrn bench uap run`. Narrative source: fixture cases.jsonl. \
             n_aligned={} — small-N fixture, read per-category F1 with the support column.",
            report.n_aligned
        ),
    };
    if let Some(parent) = out_path.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("mkdir {}: {e}", parent.display()))?;
    }
    let json = serde_json::to_string_pretty(&outcome).map_err(|e| format!("serialize: {e}"))?;
    std::fs::write(&out_path, json).map_err(|e| format!("write {}: {e}", out_path.display()))?;
    println!("\nwrote outcome → {}", out_path.display());

    Ok(0)
}

fn compute_delta_from_baseline(baseline_path: &Path, accuracy: f64) -> Option<f64> {
    let text = std::fs::read_to_string(baseline_path).ok()?;
    let v: serde_json::Value = serde_json::from_str(&text).ok()?;
    let base = v.get("accuracy")?.as_f64()?;
    Some(accuracy - base)
}

fn print_summary(parsed: &Args, model_id: &str, report: &DispositionReport) {
    println!("svrn bench uap — {}", parsed.policy.as_str());
    println!("  corpus:    {}", parsed.corpus);
    println!("  split:     {}", parsed.split.as_str());
    println!(
        "  model:     {}",
        if model_id.is_empty() {
            "(none)"
        } else {
            model_id
        }
    );
    println!("  cases:     {} aligned", report.n_aligned);
    println!("  accuracy:  {:.3}", report.accuracy);
    println!("  macro-F1:  {:.3}", report.macro_f1);
    if !report.unmatched_gold.is_empty() {
        println!("  unmatched gold:      {}", report.unmatched_gold.len());
    }
    if !report.unmatched_predicted.is_empty() {
        println!(
            "  unmatched predicted: {}",
            report.unmatched_predicted.len()
        );
    }
    println!("\n  per-category (P / R / F1 / support):");
    for pc in &report.per_category {
        if pc.support == 0 {
            continue;
        }
        println!(
            "    {:<18} {:.2} / {:.2} / {:.2}  (n={})",
            pc.category, pc.precision, pc.recall, pc.f1, pc.support
        );
    }
}

// ── diagnose ─────────────────────────────────────────────────────────

async fn cmd_diagnose(args: &[String]) -> Result<i32, String> {
    let mut parsed = parse_args(args)?;
    // Diagnose always runs the tuned policy so its numbers match a
    // tuned `run`.
    parsed.policy = Policy::Tuned;

    let (predicted, model_id, gold, axis) = classify_split(&parsed).await?;
    let report = score_with_axis(&predicted, &gold, &axis);

    println!("svrn bench uap diagnose — tuned");
    let model_disp = if model_id.is_empty() {
        "(none)"
    } else {
        model_id.as_str()
    };
    println!(
        "  corpus: {}  split: {}  model: {}",
        parsed.corpus,
        parsed.split.as_str(),
        model_disp
    );
    println!(
        "  accuracy: {:.3}  macro-F1: {:.3}  ({} cases)\n",
        report.accuracy, report.macro_f1, report.n_aligned
    );

    // Confusion matrix grid (gold rows × predicted cols), restricted to
    // categories that actually appear (support>0 or any prediction).
    let cm = &report.confusion_matrix;
    let active: Vec<usize> = (0..cm.categories.len())
        .filter(|&i| {
            let row: usize = cm.matrix[i].iter().sum();
            let col: usize = cm.matrix.iter().map(|r| r[i]).sum();
            row + col > 0
        })
        .collect();
    println!("  confusion matrix (gold ↓ × predicted →):");
    print!("    {:<18}", "");
    for &j in &active {
        print!("{:>6}", short(&cm.categories[j]));
    }
    println!();
    for &i in &active {
        print!("    {:<18}", cm.categories[i]);
        for &j in &active {
            print!("{:>6}", cm.matrix[i][j]);
        }
        println!();
    }

    // Worst over-confused pairs (off-diagonal cells, descending).
    let mut confusions: Vec<(String, String, usize)> = Vec::new();
    for (i, row) in cm.matrix.iter().enumerate() {
        for (j, &cell) in row.iter().enumerate() {
            if i != j && cell > 0 {
                confusions.push((cm.categories[i].clone(), cm.categories[j].clone(), cell));
            }
        }
    }
    confusions.sort_by(|a, b| b.2.cmp(&a.2));
    if !confusions.is_empty() {
        println!("\n  worst confusions (gold → predicted):");
        for (g, p, n) in confusions.iter().take(8) {
            println!("    {g} → {p}  ({n})");
        }
    }

    println!("\n  per-category (P / R / F1 / support):");
    for pc in &report.per_category {
        if pc.support == 0 {
            continue;
        }
        println!(
            "    {:<18} {:.2} / {:.2} / {:.2}  (n={})",
            pc.category, pc.precision, pc.recall, pc.f1, pc.support
        );
    }
    Ok(0)
}

/// Abbreviate a category token for the matrix header (first 5 chars).
fn short(cat: &str) -> String {
    cat.chars().take(5).collect()
}

// ── daemon chat (copied from the atlas bench's run_chat) ──────────────

#[derive(Debug, Deserialize)]
struct ChatChoice {
    message: ChatMessage,
    #[serde(default)]
    #[allow(dead_code)]
    finish_reason: Option<String>,
}

#[derive(Debug, Deserialize)]
struct ChatMessage {
    content: String,
}

#[derive(Debug, Deserialize)]
struct ChatResponseEnvelope {
    #[serde(default)]
    model: String,
    choices: Vec<ChatChoice>,
}

struct ChatResponse {
    model: String,
    content: String,
}

async fn run_chat(
    client: &reqwest::Client,
    base_url: &str,
    prompt: &ChatPrompt,
    max_tokens: u32,
) -> Result<ChatResponse, String> {
    let url = format!("{}/v1/chat/completions", base_url);
    let mut body = serde_json::json!({
        "model": "",
        "messages": [
            { "role": "system", "content": prompt.system },
            { "role": "user", "content": prompt.user },
        ],
        "temperature": 0.0,
        "max_tokens": max_tokens,
        "stream": false,
    });
    if let Some(schema) = prompt.response_schema.as_ref() {
        let name = prompt
            .response_schema_name
            .as_deref()
            .unwrap_or("response_schema");
        if let Some(obj) = body.as_object_mut() {
            obj.insert(
                "response_format".into(),
                serde_json::json!({
                    "type": "json_schema",
                    "json_schema": { "name": name, "schema": schema, "strict": true }
                }),
            );
        }
    }
    let resp = client
        .post(&url)
        .json(&body)
        .send()
        .await
        .map_err(|e| format!("send: {e}"))?;
    let status = resp.status();
    let text = resp.text().await.map_err(|e| format!("body read: {e}"))?;
    if !status.is_success() {
        return Err(format!("daemon HTTP {status}: {text}"));
    }
    let env: ChatResponseEnvelope = serde_json::from_str(&text)
        .map_err(|e| format!("response not JSON: {e} — body: {text}"))?;
    let choice = env
        .choices
        .into_iter()
        .next()
        .ok_or_else(|| "response had zero choices".to_string())?;
    Ok(ChatResponse {
        model: env.model,
        content: choice.message.content,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn a(args: &[&str]) -> Vec<String> {
        args.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn parse_minimum_args_defaults() {
        let p = parse_args(&a(&["--split", "train"])).unwrap();
        assert_eq!(p.corpus, "uap-blue-book");
        assert_eq!(p.split, Split::Train);
        assert_eq!(p.policy, Policy::Baseline);
        assert!(p.strip_disposition_tail);
        assert_eq!(p.base_url, default_base_url());
    }

    #[test]
    fn unknown_split_rejected() {
        assert!(parse_args(&a(&["--split", "weekday"])).is_err());
    }

    #[test]
    fn policy_aliases_parse() {
        assert_eq!(Policy::parse("baseline"), Some(Policy::Baseline));
        assert_eq!(Policy::parse("tuned"), Some(Policy::Tuned));
        assert_eq!(Policy::parse("nonsense"), None);
    }

    #[test]
    fn holdout_without_unseal_is_rejected_by_gate() {
        // The gate lives in cmd_run; here we just assert the flag parses.
        let p = parse_args(&a(&["--split", "holdout"])).unwrap();
        assert!(p.split.requires_unseal());
        assert!(!p.unseal_holdout);
    }

    #[test]
    fn strip_disposition_sentence_removes_tail() {
        let n = "Witnesses saw a light. Disposition: AIRCRAFT.";
        assert_eq!(strip_disposition_sentence(n), "Witnesses saw a light.");
        let no_tail = "Witnesses saw a light.";
        assert_eq!(strip_disposition_sentence(no_tail), no_tail);
    }

    #[test]
    fn parse_category_handles_fences() {
        assert_eq!(
            parse_category(r#"{"category": "BALLOON"}"#).as_deref(),
            Some("BALLOON")
        );
        assert_eq!(
            parse_category("```json\n{\"category\": \"HOAX\"}\n```").as_deref(),
            Some("HOAX")
        );
        assert_eq!(parse_category("not json").as_deref(), None);
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Daemon-backed Runtime bootstrap for `svrn chat`.
//!
//! Mirrors `sovereign-desktop::state::bootstrap` — same StateStore,
//! CorpusEngine, tools, mesh-knowledge wiring — but the
//! `InferenceProvider` is a `SplitInferenceProvider` that delegates
//! chat completions to the daemon's chat model and embeddings to the
//! daemon's embed model over HTTP. No embedded llama.cpp, no Tauri.
//!
//! Rationale
//! ---------
//! The desktop's Attach mode is the architectural template we want:
//! "the daemon already owns the model, talk to it over HTTP". The
//! desktop currently still loads local weights even in Attach mode
//! (historical quirk); this CLI does what Attach *should* do — pure
//! HTTP.
//!
//! The split-provider dance is required because `RemoteApiProvider`
//! uses a single `model_id` for both `/chat/completions` AND
//! `/embeddings`. Sending a chat model to the embeddings endpoint
//! returns non-embedding shapes (or errors). We keep two instances
//! and route by method.

use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;

use async_trait::async_trait;

use sovereign_core::conv_tiered::ConvTieredReader;
use sovereign_core::error::{Error, Result};
use sovereign_core::runtime::Runtime;
use sovereign_core::traits::{ApprovalChannel, InferenceProvider, StateStore};
use sovereign_core::types::*;
use sovereign_core::SkillRegistry;
use sovereign_runtime_recipe::{LaneWarmth, RecipeInputs, RecipeProgress, RerankWiring};
// Re-exported (not just `use`d) so the other CLI modules that referenced the
// formerly-local `chat_cmd::bootstrap::SplitInferenceProvider` (raptor,
// recipe_cmd) keep resolving after it was promoted to sovereign-inference.
pub use sovereign_inference::remote::SplitInferenceProvider;
use sovereign_store::sqlite::SqliteStateStore;

use crate::chat_cmd::config::ChatGlobals;

/// Bundle of everything the chat subcommands need from bootstrap.
/// Carries `Arc<Runtime>` plus the handles required to persist turns
/// (the store) and browse prior conversations.
pub struct ChatSession {
    pub runtime: Arc<Runtime>,
    pub store: Arc<dyn StateStore>,
    pub corpus_engine: Arc<corpus_engine::CorpusEngine>,
    pub inference: Arc<dyn InferenceProvider>,
    pub daemon_base: String,
    /// Resolved embed model id (e.g. `Qwen3-Embedding-0.6B-Q8_0`).
    /// Surfaced so cache layers (atlas embeddings, future per-corpus
    /// vector caches) can key on the active model and invalidate when
    /// the operator swaps it.
    pub embed_model: String,
    /// The per-process atlas-grounding manager (the same Arc installed
    /// on `runtime` as its `AtlasContextProvider`). Exposed so a
    /// measurement harness can `warm_one(corpus)` its sealed corpus —
    /// `build_session` only loads already-cached atlases
    /// (`init_from_cache`), so a freshly-enriched corpus contributes 0
    /// contexts until something warms it. Warming this Arc is visible to
    /// `runtime` because they share it.
    pub atlas_mgr: Arc<sovereign_tools::atlas_context_manager::AtlasContextManager>,
}

/// Build a `Runtime` backed by the daemon over HTTP.
///
/// Fails fast if the daemon isn't answering — there's no recovery
/// path a retry could fix, and a partially-initialized Runtime
/// pointing at a dead endpoint would produce confusing errors deep
/// in retrieval. The caller should exit with a hint.
pub async fn build_session(globals: &ChatGlobals) -> Result<ChatSession> {
    build_session_with_skills(globals, SkillRegistry::new()).await
}

/// Build a daemon-backed `ChatSession` with a caller-supplied
/// `SkillRegistry`. The default `build_session` passes an empty
/// registry — chat-as-chat doesn't need skills loaded. The Tier-B
/// voice eval harness (`svrn voice eval`) supplies a registry
/// pre-populated with the relational skills (inner-work,
/// personal-assistant) and pre-activates the per-scenario one so
/// the runtime's `primary_skill_register()` resolves to
/// `Relational` and the witness-voice contract gets prepended.
pub async fn build_session_with_skills(
    globals: &ChatGlobals,
    skills: SkillRegistry,
) -> Result<ChatSession> {
    // 1. Probe the daemon before we touch anything else. A fast fail
    //    here prints a clean "start the daemon" message instead of
    //    the cryptic timeout from the first real request.
    let base = globals.daemon_base.clone();
    let v1 = format!("{base}/v1");
    probe_or_bail(&base, globals.bearer.as_deref()).await?;

    // 2. Resolve model IDs. Preference order:
    //       a) explicit `--chat-model` / `--embed-model` flag,
    //       b) the daemon's `SetupConfig.models.*` filename stems
    //          — this is what the daemon actually loaded, and the
    //          daemon advertises those IDs on `/v1/models`,
    //       c) fallback: probe `/v1/models` and pick the first
    //          chat- and first embed-shaped entries.
    //    The historical (c)-only path picked non-deterministically
    //    between a locally-loaded `qwen-embedding-0.6b` (1024-dim)
    //    and a mesh-peer-advertised `Qwen3-Embedding-0.6B-Q8_0`
    //    whose dimensionality didn't match any installed corpus —
    //    silently downgrading every retrieval to FTS-only. Reading
    //    the config directly removes that race.
    let (chat_model, embed_model) = resolve_model_ids(&v1, globals).await?;
    eprintln!("Daemon: {base}");
    eprintln!("Chat model:  {chat_model}");
    eprintln!("Embed model: {embed_model}");

    // B:P9a — prefer the daemon's own OICP capabilities manifest for the chat
    // slot's context window (v0.4 §7) and the embed slot's query-instruction
    // prefix (§4), so `Runtime`'s budget-aware compaction sees the host's REAL
    // window (e.g. 32768) instead of the historical 8192 approximation. On a
    // v0.3 host that doesn't serve `/oicp/v1/capabilities`, fall back to 8192 +
    // the `DEFAULT_MANIFEST`-derived prefix (the prior behavior, bit-identical).
    let inference: Arc<dyn InferenceProvider> = Arc::new(
        match sovereign_inference::remote::fetch_manifest(&base, globals.bearer.clone()).await {
            Some(manifest) => SplitInferenceProvider::from_manifest(
                &v1,
                &manifest,
                chat_model,
                embed_model.clone(),
            ),
            None => SplitInferenceProvider::new(
                &v1,
                chat_model,
                embed_model.clone(),
                8192,
                sovereign_core::models_manifest::DEFAULT_MANIFEST
                    .embed_query_instruction(&embed_model),
            ),
        },
    );

    // 3. Open the state store. Creating the data dir on the fly is
    //    safe — mirrors the desktop's behaviour and means a first
    //    `svrn chat` against a fresh home directory doesn't
    //    stumble on a missing folder.
    std::fs::create_dir_all(&globals.data_dir)
        .map_err(|e| Error::Serialization(format!("create {:?}: {e}", globals.data_dir)))?;
    let db_path = globals.data_dir.join("sovereign.db");
    eprintln!("Database:    {}", db_path.display());
    let store_concrete = Arc::new(
        SqliteStateStore::open(&db_path)
            .map_err(|e| Error::Serialization(format!("open db {:?}: {e}", db_path)))?,
    );
    let store: Arc<dyn StateStore> = store_concrete.clone();

    // 4. Build the CorpusEngine. The desktop (`state.rs`) hardcodes
    //    `~/.svrnmesh/{recipes,indexes}` regardless of `config.data.dir` —
    //    that field governs the state DB only, not corpus storage. Matching
    //    that convention means this CLI sees the same corpora the desktop
    //    just ingested.
    //
    //    If a user passed `--data-dir` explicitly they almost
    //    certainly meant to override BOTH paths; honour that by
    //    using `<data_dir>/indexes` when `--data-dir` was given.
    //    Otherwise stick to the hardcoded well-known path.
    let dotsovereign = sovereign_contracts::rebrand::svrnmesh_root();
    let (recipes_dir, indexes_dir): (PathBuf, PathBuf) = if globals.data_dir_explicit {
        (
            globals.data_dir.join("recipes"),
            globals.data_dir.join("indexes"),
        )
    } else {
        (dotsovereign.join("recipes"), dotsovereign.join("indexes"))
    };
    eprintln!("Indexes:     {}", indexes_dir.display());
    let embed_fn = sovereign_tools::corpus::inference_to_embed_fn(Arc::clone(&inference));
    let inference_fn = sovereign_tools::corpus::inference_to_inference_fn(Arc::clone(&inference));
    // The engine's `expected_embedding_model` flows into
    // `_corpus_meta.json` at ingest time and into shard-consistency
    // checks. The CLI doesn't ingest during chat, but if any tool
    // path later triggers an ingest (e.g. watcher-driven reindex
    // through the same engine), it must match what the desktop
    // would have written.
    let corpus_engine = Arc::new(
        corpus_engine::CorpusEngine::new(recipes_dir, indexes_dir.clone(), embed_fn)
            .with_embedding_model(&embed_model)
            .with_inference_fn(inference_fn),
    );

    // 5. Session-level overrides. `govern ask` sets custom instructions to its
    //    governance answering rules; ordinary chat leaves them None
    //    (byte-identical prompt to before).
    let mut inference_config = InferenceConfig::default();
    if let Some(t) = globals.temperature {
        inference_config.temperature = t;
        eprintln!("Temperature: {t} (override)");
    }
    if let Some(n) = globals.max_tokens {
        inference_config.max_tokens = n;
        eprintln!("Max tokens: {n} (override)");
    }
    if globals.custom_instructions.is_some() {
        inference_config.custom_instructions = globals.custom_instructions.clone();
    }

    // 6. Tool-Mastery Layer 3 — NoteStore for the per-conversation
    //    `tool_decision` write hook. Same path the daemon uses, so the chat
    //    REPL and bench surfaces share one outcome log.
    let notes_path = globals.data_dir.join("notes.db");
    let note_store = match corpus_engine_notes::NoteStore::open(&notes_path) {
        Ok(s) => Some(Arc::new(s)),
        Err(e) => {
            eprintln!(
                "warn: NoteStore open failed at {} ({e}); tool-decision \
                 writes will no-op this session",
                notes_path.display()
            );
            None
        }
    };

    // ── The shared recipe ────────────────────────────────────────────────
    //
    // Tools, the router classifier stack, the planner and the enrichment lane
    // used to be ~450 lines right here, and the desktop and the server each
    // had their own copy. `sovereign-runtime-recipe` is the one of them
    // (TOPOLOGY.md §10 phase 5c); what stays above is only what a host is the
    // sole thing able to answer — which daemon to talk to, which models it
    // loaded, where this invocation's data root is.
    let skills = Arc::new(skills);
    let common = sovereign_runtime_recipe::common_parts(
        RecipeInputs {
            inference: Arc::clone(&inference),
            store: Arc::clone(&store),
            // The same `SqliteStateStore` handle already opened above also
            // impls `ConvTieredReader` (spec CONV_TIERED_PORT.md).
            conv_tiered: Some(Arc::clone(&store_concrete) as Arc<dyn ConvTieredReader>),
            corpus_engine: Arc::clone(&corpus_engine),
            // Cloned: `tool_bundles` below borrows the same handle for
            // `knowledge_lookup`'s notes channel. One store, two readers.
            note_store: note_store.clone(),
            skills: Arc::clone(&skills),
            // Chat turns don't trigger confirmations in the normal path; a
            // yes-only stub keeps a stray approval request from deadlocking a
            // one-shot CLI.
            approval: Arc::new(AutoApprove) as Arc<dyn ApprovalChannel>,
            inference_config,
            indexes_dir: indexes_dir.clone(),
            embed_model: embed_model.clone(),
            // The families this surface's turn registry carries. Shell is
            // present because an interactive CLI runs as the invoking user,
            // in the directory they invoked it from, for the length of one
            // command they are watching.
            tool_bundles: {
                let mut b = sovereign_runtime_recipe::baseline_bundles(
                    sovereign_runtime_recipe::BaselineDeps {
                        store: &store,
                        inference: &inference,
                        corpus_engine: &corpus_engine,
                        // The same handle passed to `note_store` below — the
                        // notes evidence channel and the tool-decision write
                        // hook read one store, not two.
                        note_store: note_store.as_ref(),
                        web: sovereign_tools::bundles::WebReach::Granted(
                            sovereign_core::egress::search_client()
                                .expect("egress boundary search client build"),
                        ),
                        // `svrn chat` has no operator switch for it; the
                        // user-in-loop escalation card is still there.
                        escalation: sovereign_tools::bundles::WebEscalation::Disabled,
                    },
                );
                b.push(Box::new(sovereign_tools::bundles::WikipediaTools::new(
                    Arc::clone(&corpus_engine),
                )));
                b.push(Box::new(sovereign_tools::bundles::ShellTools));
                b
            },
            // No settings panel on this host, so nothing to consult: every
            // family composed above registers.
            switches: sovereign_runtime_recipe::ToolSwitches::Ungoverned,
            // No config file of its own: the canonical `[[mcp_servers]]` array
            // is the whole declaration on this host.
            mcp_extra: Vec::new(),
            // A one-shot answering one question would rather wait once than
            // answer it with less. Byte-identical to the behaviour this
            // function had when the recipe was inline.
            warmth: LaneWarmth::Eager,
            // The provider here is a `SplitInferenceProvider` over HTTP and
            // does not support rerank, so a standalone slot is the only way
            // this surface gets a cross-encoder at all.
            rerank: RerankWiring::Standalone,
        },
        &Banner,
    )
    .await;

    // Mesh knowledge client. Talks to the daemon's `/v1/mesh` — when no mesh
    // is running, reqwest gets ECONNREFUSED on the first call and retrieval
    // falls through to local-only. Safe to install unconditionally (same
    // policy as the desktop). A host input, not part of the recipe: inside the
    // daemon this is a loopback call to itself and dissolves (§3.5).
    let mesh_knowledge: Option<Arc<dyn sovereign_core::traits::MeshKnowledgeSource>> =
        match sovereign_mesh::knowledge_client::MeshKnowledgeClient::new(&base) {
            Ok(c) => Some(Arc::new(c)),
            Err(_) => None,
        };

    // Named absences, written as a diff against the recipe's baseline. `svrn
    // chat` genuinely has no compaction worker, no landscape-digest provider,
    // no sensitivity oracle, no principal resolver and no folder-metadata
    // oracle. Narration is a real gap here (the CLI renders none); it is
    // written down rather than being invisible, which is what it was for the
    // whole life of the builder surface.
    let runtime = sovereign_runtime_recipe::commission(sovereign_core::RuntimeParts {
        mesh_knowledge,
        routing_events: Arc::new(sovereign_core::traits::NoOpRoutingEventSink),
        ..common.parts
    });

    Ok(ChatSession {
        runtime,
        store,
        corpus_engine,
        inference,
        daemon_base: base,
        embed_model,
        atlas_mgr: common.atlas_context,
    })
}

/// The CLI's boot banner. `svrn chat` prints the recipe's progress lines to
/// stderr, one per line, exactly as it did when the recipe was inline here —
/// a daemon commissioning the same `Runtime` traces them instead.
struct Banner;

impl RecipeProgress for Banner {
    fn note(&self, line: &str) {
        eprintln!("{line}");
    }
}

/// GET `/v1/models` with a 2s timeout. Any non-200 aborts bootstrap
/// with a clear remediation hint — the alternative is cryptic
/// "connection refused" errors minutes later, mid-retrieval.
async fn probe_or_bail(base: &str) -> Result<()> {
    let url = format!("{base}/v1/models");
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(2))
        .build()
        .map_err(|e| Error::Serialization(format!("http client build: {e}")))?;
    match client.get(&url).send().await {
        Ok(r) if r.status().is_success() => Ok(()),
        Ok(r) => Err(Error::Serialization(format!(
            "daemon at {base} returned {} from /v1/models. \
             Is it really a svrn daemon? Try `svrn doctor`.",
            r.status()
        ))),
        Err(_) => Err(Error::Serialization(format!(
            "daemon unreachable at {base}. \
             Start it with `svrn daemon run`, or pass --daemon <url>."
        ))),
    }
}

/// Resolve `(chat_model_id, embed_model_id)` against the daemon.
/// See the call-site comment in `build_session` for the preference
/// order — explicit flag → SetupConfig stem → `/v1/models` probe.
async fn resolve_model_ids(v1: &str, globals: &ChatGlobals) -> Result<(String, String)> {
    // (a) Explicit flags short-circuit everything.
    if let (Some(c), Some(e)) = (&globals.chat_model, &globals.embed_model) {
        return Ok((c.clone(), e.clone()));
    }

    // (b) SetupConfig filename stems. The daemon loads
    //     `config.models.embed` and advertises it on `/v1/models`
    //     under its filename stem (e.g. `qwen-embedding-0.6b.gguf`
    //     → `qwen-embedding-0.6b`). Preferring the stem over
    //     `/v1/models` iteration means we always reach the
    //     *local* slot, never a mesh-peer advertisement, and the
    //     answer is stable across invocations.
    let from_config = chat_and_embed_stems_from_config();
    let mut chat_found = globals
        .chat_model
        .clone()
        .or_else(|| from_config.as_ref().and_then(|s| s.chat.clone()));
    let mut embed_found = globals
        .embed_model
        .clone()
        .or_else(|| from_config.as_ref().and_then(|s| s.embed.clone()));
    if let (Some(c), Some(e)) = (chat_found.as_ref(), embed_found.as_ref()) {
        return Ok((c.clone(), e.clone()));
    }

    // (c) Fallback: probe `/v1/models`. Used when SetupConfig is
    //     absent (fresh install, dev without setup) or when it
    //     lacks one of the two slots.
    let url = format!("{v1}/models");
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(5))
        .build()
        .map_err(|e| Error::Serialization(format!("http client build: {e}")))?;
    let resp = client
        .get(&url)
        .send()
        .await
        .map_err(|e| Error::Serialization(format!("GET {url}: {e}")))?;
    if !resp.status().is_success() {
        return Err(Error::Serialization(format!(
            "GET {url} returned {}",
            resp.status()
        )));
    }
    let v: serde_json::Value = resp
        .json()
        .await
        .map_err(|e| Error::Serialization(format!("parse /v1/models: {e}")))?;
    let arr = v
        .get("data")
        .and_then(|d| d.as_array())
        .ok_or_else(|| Error::Serialization("/v1/models: no `data` array".into()))?;
    for m in arr {
        let Some(id) = m.get("id").and_then(|s| s.as_str()) else {
            continue;
        };
        let lower = id.to_lowercase();
        let is_embed = lower.contains("embedding") || lower.contains("-embed");
        if is_embed {
            if embed_found.is_none() {
                embed_found = Some(id.to_string());
            }
        } else if chat_found.is_none() {
            chat_found = Some(id.to_string());
        }
    }

    match (chat_found, embed_found) {
        (Some(c), Some(e)) => Ok((c, e)),
        (None, _) => Err(Error::Serialization(
            "daemon lists no chat models — check `svrn setup` and the primary/fast slots".into(),
        )),
        (_, None) => Err(Error::Serialization(
            "daemon lists no embedding model — retrieval will fail. Set `[models] embed` in \
             ~/.svrnmesh/config.toml or pass --embed-model."
                .into(),
        )),
    }
}

/// Filename-stem extraction for `SetupConfig.models.{primary,embed}`.
/// The daemon advertises these on `/v1/models` using exactly the
/// file stem (`qwen-embedding-0.6b.gguf` → `qwen-embedding-0.6b`),
/// so returning those stems gives us the stable local-model IDs
/// without any `/v1/models` round-trip.
struct ConfigModelStems {
    chat: Option<String>,
    embed: Option<String>,
}

fn chat_and_embed_stems_from_config() -> Option<ConfigModelStems> {
    let cfg = sovereign_core::setup_config::SetupConfig::load().ok()?;
    Some(ConfigModelStems {
        chat: cfg
            .models
            .primary
            .file_stem()
            .and_then(|s| s.to_str())
            .map(|s| s.to_string()),
        embed: cfg
            .models
            .embed
            .file_stem()
            .and_then(|s| s.to_str())
            .map(|s| s.to_string()),
    })
}

/// Approval channel that silently yes-answers everything. Chat never
/// hits the ask-user path in practice; this prevents a surprise
/// deadlock in a one-shot CLI invocation.
struct AutoApprove;

#[async_trait]
impl ApprovalChannel for AutoApprove {
    async fn request_approval(&self, _step: &Step, _preview: &ActionPreview) -> Result<bool> {
        Ok(true)
    }

    async fn ask_user(&self, _question: &str) -> Result<String> {
        Ok(String::new())
    }

    fn emit_progress(&self, _step: &Step, _output: &StepOutput) {}
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn claim` — CLI surface for the work atlas.
//!
//! DAEMON-FIRST: the daemon's work-atlas store is the one peers,
//! gossip, and CodeWatcher observations share, so every subcommand
//! calls the daemon's MCP tools when it answers. The in-process
//! repo-local `.sovereign/mesh.db` is a FALLBACK for daemon-down
//! operation only, and says so loudly — a claim written there is
//! invisible to every other process. (The previous header claimed the
//! daemon and CLI share that file; they never did — the daemon's
//! store is in-memory. Root-caused 2026-07-31.)
//!
//! Output is human-readable by default; `--format json` mirrors
//! `svrn tools` for scripting.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use commonwealth_state::MeshStore;
use uuid::Uuid;

use sovereign_cli_shared::mcp_client::{daemon_tool_call, DaemonCallError};
use sovereign_work_atlas::{
    model::{AgentKind, Privacy},
    resolve_repo_id, ClaimRecord, ScopeMatch, SessionIdentity, WorkAtlasConfig, WorkAtlasStore,
};

/// Outcome of the daemon-first attempt for one subcommand.
enum DaemonFirst {
    /// The daemon answered; here is the tool's JSON payload.
    Payload(serde_json::Value),
    /// No daemon — caller proceeds against the repo-local store.
    Fallback,
    /// The daemon answered and REJECTED the call. Do not fall back:
    /// retrying a rejected write against a store nobody reads would
    /// manufacture a success.
    Fail(i32),
}

async fn daemon_first(tool: &str, args: serde_json::Value) -> DaemonFirst {
    match daemon_tool_call(tool, args).await {
        Ok(v) => DaemonFirst::Payload(v),
        Err(DaemonCallError::Tool(msg)) => {
            eprintln!("claim: daemon rejected {tool}: {msg}");
            DaemonFirst::Fail(1)
        }
        Err(DaemonCallError::Unreachable(_)) => {
            eprintln!(
                "warning: daemon unreachable — using the repo-local store. Records here are \
                 NOT visible to the daemon, MCP peers, or the mesh; re-declare once the \
                 daemon is back if coordination matters."
            );
            DaemonFirst::Fallback
        }
    }
}

pub async fn run(args: &[String]) -> i32 {
    let Some((sub, rest)) = args.split_first() else {
        print_help();
        return 2;
    };
    match sub.as_str() {
        "help" | "--help" | "-h" => {
            print_help();
            0
        }
        "check" => run_check(rest).await,
        "list" => run_list(rest).await,
        "release" => run_release(rest).await,
        // Resource-commons verbs (order seat-resource-commons): the
        // seat-side helpers over the claims rail.
        "may-i" => run_may_i(rest).await,
        "take" => run_take(rest).await,
        // `svrn claim <symbol> --intent <text>` — the bare form.
        // No leading subcommand keyword.
        scope => run_declare(scope, rest, None).await,
    }
}

fn print_help() {
    eprintln!(
        "svrn claim — coordinate work with other agents on this mesh\n\
         \n\
         Usage:\n  \
           sovereign claim <symbol-or-path> --intent <text> [--ttl <seconds>]\n  \
           sovereign claim check <symbol-or-path>\n  \
           sovereign claim list [--mine|--all]\n  \
           sovereign claim release <claim-id>\n  \
           sovereign claim may-i <resource-scope>\n  \
           sovereign claim take <resource-scope> --intent <text> [--ttl <seconds>]\n  \
         \n\
         Resource-commons verbs (order seat-resource-commons):\n  \
           may-i  One call: is this shared resource taken right now? Verdicts\n  \
                  held / expired / free. `expired` means someone took it and\n  \
                  never released (their work may have died); `free` means never\n  \
                  claimed or explicitly released. Never blocks.\n  \
           take   Claim a shared resource before touching it. Scope convention\n  \
                  `daemon:<node>:<action>` (e.g. `daemon:BeefyMac:restart`);\n  \
                  default TTL 30 min, override with --ttl. Release with\n  \
                  `sovereign claim release <claim-id>`.\n  \
         \n\
         Flags:\n  \
           --format json   Emit JSON instead of human-readable output.\n  \
         \n\
         See sovereign/docs/WORK_ATLAS.md for the full model.\n"
    );
}

/// Declare a claim. `default_ttl` fills in when `--ttl` is absent —
/// `Some` for the resource-commons `take` verb (the convention's 30
/// minutes), `None` for the bare form (the store config's default).
async fn run_declare(scope: &str, rest: &[String], default_ttl: Option<u64>) -> i32 {
    let mut intent: Option<String> = None;
    let mut ttl_seconds: Option<u64> = None;
    let mut format_json = false;
    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--intent" => {
                if i + 1 >= rest.len() {
                    eprintln!("claim: --intent requires a value");
                    return 2;
                }
                intent = Some(rest[i + 1].clone());
                i += 2;
            }
            "--ttl" => {
                if i + 1 >= rest.len() {
                    eprintln!("claim: --ttl requires a seconds value");
                    return 2;
                }
                ttl_seconds = rest[i + 1].parse().ok();
                if ttl_seconds.is_none() {
                    eprintln!("claim: --ttl must be a positive integer");
                    return 2;
                }
                i += 2;
            }
            "--format" => {
                format_json = i + 1 < rest.len() && rest[i + 1] == "json";
                i += 2;
            }
            other => {
                eprintln!("claim: unknown flag '{other}'");
                return 2;
            }
        }
    }
    let Some(intent_s) = intent else {
        eprintln!("claim: --intent <text> is required");
        return 2;
    };
    if intent_s.trim().is_empty() {
        eprintln!("claim: intent must not be empty");
        return 2;
    }

    let ttl_seconds = ttl_seconds.or(default_ttl);
    let mut args = serde_json::json!({ "symbols": [scope], "intent": intent_s });
    if let Some(ttl) = ttl_seconds {
        args["ttl_seconds"] = ttl.into();
    }
    match daemon_first("declare_scope", args).await {
        DaemonFirst::Payload(p) => {
            if format_json {
                println!("{}", serde_json::to_string_pretty(&p).unwrap_or_default());
            } else {
                let claim_id = p["claim_id"].as_str().unwrap_or("?");
                println!(
                    "claimed {scope}\n  id:       {}\n  intent:   {}\n  expires:  {}\n  release with: sovereign claim release {}",
                    claim_id,
                    p["intent"].as_str().unwrap_or(&intent_s),
                    p["ttl_expires_at"].as_u64().unwrap_or(0),
                    claim_id,
                );
            }
            return 0;
        }
        DaemonFirst::Fail(code) => return code,
        DaemonFirst::Fallback => {}
    }

    let ctx = match open_atlas() {
        Ok(c) => c,
        Err(code) => return code,
    };
    let ttl = ctx.config.clamp_ttl(ttl_seconds);
    let identity = SessionIdentity {
        node_id: ctx.store.node_id(),
        // CLI synthetic — one ambient human session per workstation
        // for Phase 1 (Phase 2 supersedes with CodeWatcher idle-gap).
        agent_session_token: Some(format!("cli:{}", ctx.store.node_id())),
        repo_id: ctx.repo_id.clone(),
    };
    let session = match ctx.store.ensure_session(
        identity,
        ctx.config.node.default_privacy_enum(),
        AgentKind::Human,
        ctx.repo_root.clone(),
        ctx.current_branch.clone(),
    ) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("claim: open session: {e}");
            return 1;
        }
    };
    let now = now_secs();
    let claim = ClaimRecord {
        claim_id: Uuid::new_v4(),
        session_id: session.session_id,
        intent: intent_s.trim().to_string(),
        symbol_refs: vec![sovereign_work_atlas::SymbolRef {
            scip_symbol: None,
            file_path: PathBuf::from(scope),
            scip_was_fresh: false,
        }],
        declared_at: now,
        ttl_expires_at: now.saturating_add(ttl),
        // Fix 1 (commons-fluency): attribution rides the claim.
        node_id: Some(ctx.store.node_id()),
        // Fix 3b (commons-fluency): the origin never sets a receipt.
        received_at: None,
    };
    if let Err(e) = ctx.store.put_claim(session.privacy, &claim) {
        eprintln!("claim: write: {e}");
        return 1;
    }

    if format_json {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "claim_id":       claim.claim_id.to_string(),
                "session_id":     claim.session_id.to_string(),
                "ttl_expires_at": claim.ttl_expires_at,
                "intent":         claim.intent,
                "scope":          scope,
            }))
            .unwrap()
        );
    } else {
        println!(
            "claimed {scope}\n  id:       {}\n  intent:   {}\n  ttl:      {}s (expires {})\n  session:  {}\n  release with: sovereign claim release {}",
            claim.claim_id,
            claim.intent,
            ttl,
            claim.ttl_expires_at,
            claim.session_id,
            claim.claim_id,
        );
    }
    0
}

async fn run_check(rest: &[String]) -> i32 {
    let mut format_json = false;
    let mut scope: Option<String> = None;
    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--format" => {
                format_json = i + 1 < rest.len() && rest[i + 1] == "json";
                i += 2;
            }
            other if !other.starts_with("--") && scope.is_none() => {
                scope = Some(other.to_string());
                i += 1;
            }
            other => {
                eprintln!("claim check: unknown argument '{other}'");
                return 2;
            }
        }
    }
    let Some(scope) = scope else {
        eprintln!("claim check: scope required");
        return 2;
    };

    match daemon_first(
        "work_in_flight",
        serde_json::json!({ "scope": scope, "match_mode": "symbol", "include_self": true }),
    )
    .await
    {
        DaemonFirst::Payload(p) => {
            let claims = p["claims"].as_array().cloned().unwrap_or_default();
            if format_json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(
                        &serde_json::json!({ "scope": scope, "live": claims })
                    )
                    .unwrap_or_default()
                );
            } else if claims.is_empty() {
                println!("no live claims on {scope}");
            } else {
                let now = now_secs();
                println!("live claims on {scope}:");
                for c in &claims {
                    println!(
                        "  {}  intent: {}  expires-in: {}s",
                        c["claim_id"].as_str().unwrap_or("?"),
                        c["intent"].as_str().unwrap_or("?"),
                        c["ttl_expires_at"]
                            .as_u64()
                            .unwrap_or(0)
                            .saturating_sub(now),
                    );
                }
            }
            return 0;
        }
        DaemonFirst::Fail(code) => return code,
        DaemonFirst::Fallback => {}
    }

    let ctx = match open_atlas() {
        Ok(c) => c,
        Err(code) => return code,
    };
    let claims = match ctx.store.list_claims_for_scope(&scope, ScopeMatch::Symbol) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("claim check: {e}");
            return 1;
        }
    };
    let now = now_secs();
    let live: Vec<&ClaimRecord> = claims.iter().filter(|c| c.ttl_expires_at >= now).collect();

    if format_json {
        let claims_json: Vec<_> = live
            .iter()
            .map(|c| {
                serde_json::json!({
                    "claim_id":       c.claim_id.to_string(),
                    "session_id":     c.session_id.to_string(),
                    "intent":         c.intent,
                    "ttl_expires_at": c.ttl_expires_at,
                })
            })
            .collect();
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "scope":  scope,
                "live":   claims_json,
            }))
            .unwrap()
        );
    } else if live.is_empty() {
        println!("no live claims on {scope}");
    } else {
        println!("live claims on {scope}:");
        for c in &live {
            println!(
                "  {}  intent: {}  expires-in: {}s",
                c.claim_id,
                c.intent,
                c.ttl_expires_at.saturating_sub(now)
            );
        }
    }
    // Historical-prior: git co-evolution. Clearly labeled per §9 of
    // the spec — never confused with live activity.
    if !format_json {
        println!(
            "\n(historical-prior — not live activity; git co-evolution lookup deferred to Phase 2)"
        );
    }
    0
}

async fn run_list(rest: &[String]) -> i32 {
    let mut mine = false;
    let mut format_json = false;
    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--mine" => {
                mine = true;
                i += 1;
            }
            "--all" => {
                mine = false;
                i += 1;
            }
            "--format" => {
                format_json = i + 1 < rest.len() && rest[i + 1] == "json";
                i += 2;
            }
            other => {
                eprintln!("claim list: unknown argument '{other}'");
                return 2;
            }
        }
    }
    match daemon_first(
        "work_in_flight",
        serde_json::json!({ "scope": "", "match_mode": "file", "include_self": true }),
    )
    .await
    {
        DaemonFirst::Payload(p) => {
            let now = now_secs();
            let my_node = sovereign_mesh::persist::resolve_self_node_id(
                &sovereign_cli_shared::dirs::sovereign_root(),
            )
            .to_string();
            let claims: Vec<serde_json::Value> = p["claims"]
                .as_array()
                .cloned()
                .unwrap_or_default()
                .into_iter()
                .filter(|c| !mine || c["node_id"].as_str() == Some(my_node.as_str()))
                .collect();
            if format_json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&claims).unwrap_or_default()
                );
            } else if claims.is_empty() {
                println!("no live claims{}", if mine { " (yours)" } else { "" });
            } else {
                for c in &claims {
                    let target = c["scopes"][0].as_str().unwrap_or("<no-scope>");
                    println!(
                        "{}  {}  intent: {}  expires-in: {}s  node: {}",
                        c["claim_id"].as_str().unwrap_or("?"),
                        target,
                        c["intent"].as_str().unwrap_or("?"),
                        c["ttl_expires_at"]
                            .as_u64()
                            .unwrap_or(0)
                            .saturating_sub(now),
                        c["node_id"].as_str().unwrap_or("?"),
                    );
                }
            }
            return 0;
        }
        DaemonFirst::Fail(code) => return code,
        DaemonFirst::Fallback => {}
    }

    let ctx = match open_atlas() {
        Ok(c) => c,
        Err(code) => return code,
    };
    let now = now_secs();
    // "Mine" = this workstation's node. The old token-string match
    // (`cli:<node>`) missed sessions created by any other surface
    // (tools-path sessions carry no token), which made `--mine`
    // return empty against your own live claims.
    let me_node = ctx.store.node_id();

    let mut rows: Vec<(ClaimRecord, Option<String>)> = Vec::new();
    for privacy in [Privacy::Public, Privacy::Private] {
        let claims = match ctx.store.scan_claims(privacy) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("claim list: scan {}: {e}", privacy.id());
                return 1;
            }
        };
        for c in claims {
            if c.ttl_expires_at < now {
                continue;
            }
            let session = ctx.store.get_session(c.session_id).ok().flatten();
            if mine {
                let is_mine = session
                    .as_ref()
                    .map(|s| s.node_id == me_node)
                    .unwrap_or(false);
                if !is_mine {
                    continue;
                }
            }
            let node = session.as_ref().map(|s| s.node_id.to_string());
            rows.push((c, node));
        }
    }
    rows.sort_by_key(|(c, _)| std::cmp::Reverse(c.declared_at));

    if format_json {
        let json: Vec<_> = rows
            .iter()
            .map(|(c, node)| {
                serde_json::json!({
                    "claim_id":       c.claim_id.to_string(),
                    "session_id":     c.session_id.to_string(),
                    "intent":         c.intent,
                    "ttl_expires_at": c.ttl_expires_at,
                    "node_id":        node,
                })
            })
            .collect();
        println!("{}", serde_json::to_string_pretty(&json).unwrap());
    } else if rows.is_empty() {
        println!("no live claims{}", if mine { " (yours)" } else { "" });
    } else {
        for (c, node) in &rows {
            let target = c
                .symbol_refs
                .first()
                .map(|s| s.file_path.to_string_lossy().to_string())
                .unwrap_or_else(|| "<no-scope>".into());
            println!(
                "{}  {}  intent: {}  expires-in: {}s  node: {}",
                c.claim_id,
                target,
                c.intent,
                c.ttl_expires_at.saturating_sub(now),
                node.as_deref().unwrap_or("?")
            );
        }
    }
    0
}

async fn run_release(rest: &[String]) -> i32 {
    let mut format_json = false;
    let mut claim_id_str: Option<String> = None;
    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--format" => {
                format_json = i + 1 < rest.len() && rest[i + 1] == "json";
                i += 2;
            }
            other if !other.starts_with("--") && claim_id_str.is_none() => {
                claim_id_str = Some(other.to_string());
                i += 1;
            }
            other => {
                eprintln!("claim release: unknown argument '{other}'");
                return 2;
            }
        }
    }
    let Some(s) = claim_id_str else {
        eprintln!("claim release: claim-id required");
        return 2;
    };
    let claim_id = match Uuid::parse_str(&s) {
        Ok(id) => id,
        Err(_) => {
            eprintln!("claim release: invalid uuid '{s}'");
            return 2;
        }
    };

    match daemon_first(
        "release_scope",
        serde_json::json!({ "claim_id": claim_id.to_string() }),
    )
    .await
    {
        DaemonFirst::Payload(p) => {
            let released = p["released"].as_bool().unwrap_or(true);
            if format_json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&serde_json::json!({ "released": released }))
                        .unwrap_or_default()
                );
            } else if released {
                println!("released {claim_id}");
            } else {
                println!("no claim {claim_id} (already released or expired)");
            }
            return 0;
        }
        DaemonFirst::Fail(code) => return code,
        DaemonFirst::Fallback => {}
    }

    let ctx = match open_atlas() {
        Ok(c) => c,
        Err(code) => return code,
    };
    let released = match ctx.store.release_claim(claim_id) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("claim release: {e}");
            return 1;
        }
    };
    if format_json {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({ "released": released })).unwrap()
        );
    } else if released {
        println!("released {claim_id}");
    } else {
        println!("no claim {claim_id} (already released or expired)");
    }
    0
}

// ── Resource-commons verbs (order seat-resource-commons) ────────────────

/// `claim take <scope> --intent <text> [--ttl <seconds>]` — claim a
/// shared resource before touching it (the order's "I am taking it"
/// half of UC-R2). Thin wrapper over the declare path with the
/// resource-convention TTL default (30 min) — one implementation of
/// the declare logic, one of the default (§10.6).
async fn run_take(rest: &[String]) -> i32 {
    // The first positional is the scope; the flags pass through to
    // run_declare, which must not see it (its parser rejects
    // non-flag leftovers).
    let mut scope: Option<String> = None;
    let mut passthrough: Vec<String> = Vec::with_capacity(rest.len());
    for a in rest {
        if !a.starts_with("--") && scope.is_none() {
            scope = Some(a.clone());
        } else {
            passthrough.push(a.clone());
        }
    }
    let Some(scope) = scope else {
        eprintln!("claim take: resource-scope required (e.g. daemon:BeefyMac:restart)");
        return 2;
    };
    run_declare(
        &scope,
        &passthrough,
        Some(sovereign_work_atlas::tools::DEFAULT_RESOURCE_TTL_SECS),
    )
    .await
}

/// `claim may-i <scope>` — the one-call answer to "is this shared
/// resource serving someone else right now?" (UC-R2's question half,
/// and UC-R3's negative control: `expired` vs `free`).
async fn run_may_i(rest: &[String]) -> i32 {
    let mut format_json = false;
    let mut scope: Option<String> = None;
    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--format" => {
                format_json = i + 1 < rest.len() && rest[i + 1] == "json";
                i += 2;
            }
            other if !other.starts_with("--") && scope.is_none() => {
                scope = Some(other.to_string());
                i += 1;
            }
            other => {
                eprintln!("claim may-i: unknown argument '{other}'");
                return 2;
            }
        }
    }
    let Some(scope) = scope else {
        eprintln!("claim may-i: resource-scope required (e.g. daemon:BeefyMac:restart)");
        return 2;
    };

    match daemon_first("resource_may_i", serde_json::json!({ "scope": scope })).await {
        DaemonFirst::Payload(p) => {
            let verdict = p["verdict"].as_str().unwrap_or("free");
            let claims = p["claims"].as_array().cloned().unwrap_or_default();
            render_may_i(&scope, verdict, &claims, format_json);
            return 0;
        }
        DaemonFirst::Fail(code) => return code,
        DaemonFirst::Fallback => {
            // Refuse, don't substitute: the verdict's whole value is
            // the expired-vs-free distinction over PEER claims, which
            // only the daemon's store holds. A repo-local read could
            // only see this machine's records and a "free" would be a
            // false free — the seat would act on a lie (§18.3: absence
            // is reported, never defaulted).
            eprintln!(
                "claim may-i: daemon unreachable — no honest verdict possible. Peer claims \
                 live in the daemon's work-atlas store, which is down; a local read cannot \
                 distinguish 'expired' from 'released' for the mesh. Re-run when the daemon \
                 is up."
            );
            return 1;
        }
    }
}

fn render_may_i(scope: &str, verdict: &str, claims: &[serde_json::Value], format_json: bool) {
    if format_json {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "scope":   scope,
                "verdict": verdict,
                "claims":  claims,
            }))
            .unwrap_or_default()
        );
        return;
    }
    match verdict {
        "held" => {
            println!("held — {scope} is taken:");
            for c in claims {
                let who = c["node_id"].as_str().unwrap_or("?");
                let mine = if c["node_is_self"].as_bool().unwrap_or(false) {
                    " (yours)"
                } else {
                    ""
                };
                println!(
                    "  {}  intent: {}  {}s left  node: {}{}",
                    c["claim_id"].as_str().unwrap_or("?"),
                    c["intent"].as_str().unwrap_or("?"),
                    c["seconds_remaining"].as_u64().unwrap_or(0),
                    who,
                    mine,
                );
            }
            println!("  release with: sovereign claim release <claim-id>");
        }
        "expired" => {
            let ago = claims
                .iter()
                .map(|c| c["expired_seconds_ago"].as_u64().unwrap_or(0))
                .max()
                .unwrap_or(0);
            println!(
                "expired — claim(s) on {scope} abandoned {ago}s ago (TTL outlived, never \
                 released; the work may have died mid-run):"
            );
            for c in claims {
                println!(
                    "  {}  intent: {}  node: {}",
                    c["claim_id"].as_str().unwrap_or("?"),
                    c["intent"].as_str().unwrap_or("?"),
                    c["node_id"].as_str().unwrap_or("?"),
                );
            }
        }
        _ => {
            println!(
                "free — no claim on {scope} (never taken, or explicitly released = the \
                 work finished)"
            );
        }
    }
}

// ── Atlas open / context ────────────────────────────────────────────────

struct CliCtx {
    store: Arc<WorkAtlasStore>,
    config: WorkAtlasConfig,
    repo_root: PathBuf,
    repo_id: String,
    current_branch: Option<String>,
}

fn open_atlas() -> Result<CliCtx, i32> {
    let cwd = match std::env::current_dir() {
        Ok(p) => p,
        Err(e) => {
            eprintln!("claim: cwd: {e}");
            return Err(1);
        }
    };
    let (repo_root, repo_id) = match resolve_repo_id(&cwd) {
        Ok(pair) => pair,
        Err(e) => {
            eprintln!("claim: {e}");
            return Err(1);
        }
    };
    let sovereign_dir = repo_root.join(".sovereign");
    let _ = std::fs::create_dir_all(&sovereign_dir);
    let mesh_path = sovereign_dir.join("mesh.db");
    let mesh = match MeshStore::open(&mesh_path) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("claim: mesh open {}: {e}", mesh_path.display());
            return Err(1);
        }
    };
    // Identity from the ROOT data dir with the daemon's precedence
    // (node_id file → mesh.json → generate). The previous hardcoded
    // `~/.svrnmesh/indexes` minted a SECOND node id for this
    // workstation (2026-07-31).
    let node_id = sovereign_mesh::persist::resolve_self_node_id(
        &sovereign_cli_shared::dirs::sovereign_root(),
    );
    let store = Arc::new(WorkAtlasStore::new(Arc::new(mesh), node_id));

    let cfg_path = sovereign_contracts::rebrand::work_atlas_toml();
    let config = WorkAtlasConfig::load_or_default(&cfg_path).unwrap_or_else(|e| {
        eprintln!("claim: config load failed ({e}); using defaults");
        WorkAtlasConfig::defaults()
    });

    let current_branch = git_current_branch(&repo_root);
    Ok(CliCtx {
        store,
        config,
        repo_root,
        repo_id,
        current_branch,
    })
}

fn git_current_branch(repo_root: &Path) -> Option<String> {
    let out = std::process::Command::new("git")
        .arg("-C")
        .arg(repo_root)
        .args(["rev-parse", "--abbrev-ref", "HEAD"])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if s.is_empty() || s == "HEAD" {
        None
    } else {
        Some(s)
    }
}

